-- ============================================================
-- 圣经全文（新译本，神名已按公开发布本还原为「耶和华」）· 数据文件 6/6
-- 第二版：可覆盖第一版（冲突时更新经文）。已运行过第一版的直接运行本版即可。
-- 本文件 5068 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '路加福音', 42, 24, 28, '他们走近要去的村子，他好像还要往前行，'),
('CNV', '路加福音', 42, 24, 29, '他们强留他说：“天晚了，太阳下山了，请与我们同住吧！”他就进去与他们同住。'),
('CNV', '路加福音', 42, 24, 30, '到了吃饭的时候，他拿起饼来，感谢了，擘开递给他们，'),
('CNV', '路加福音', 42, 24, 31, '他们的眼睛开了，才认出是耶稣来；他却从他们面前不见了。'),
('CNV', '路加福音', 42, 24, 32, '他们彼此说：“在路上他对我们说话，给我们解释圣经的时候，我们的心不是火热的吗？”'),
('CNV', '路加福音', 42, 24, 33, '他们就立时起来回耶路撒冷去。在那里遇见十一个使徒和跟他们聚在一起的人，'),
('CNV', '路加福音', 42, 24, 34, '说：“主果然复活了，已经向西门显现了。”'),
('CNV', '路加福音', 42, 24, 35, '两个人就把在路上的事，和擘饼的时候他们怎样认出耶稣来的事，都述说了一遍。'),
('CNV', '路加福音', 42, 24, 36, '正说这话的时候，耶稣亲自站在他们当中，说：“愿你们平安。”'),
('CNV', '路加福音', 42, 24, 37, '他们非常惊怕，以为看见了灵。'),
('CNV', '路加福音', 42, 24, 38, '他说：“你们为什么惊慌，为什么心里疑惑呢？'),
('CNV', '路加福音', 42, 24, 39, '你们看我的手、我的脚，就知道我是谁。摸我看看，灵没有骨，没有肉；你们看，我是有的。”'),
('CNV', '路加福音', 42, 24, 40, '说了这话，就把手和脚给他们看。'),
('CNV', '路加福音', 42, 24, 41, '他们欢喜到不敢相信，并且很惊奇。耶稣说：“你们这里有什么吃的没有？”'),
('CNV', '路加福音', 42, 24, 42, '他们就给了他一片烧鱼。'),
('CNV', '路加福音', 42, 24, 43, '他接过来，在他们面前吃了。'),
('CNV', '路加福音', 42, 24, 44, '主对他们说：“这就是我从前与你们同在的时候，对你们说过的话：摩西的律法、先知书和诗篇上所记关于我的一切事，都必定应验。”'),
('CNV', '路加福音', 42, 24, 45, '于是他开他们的心窍，使他们明白圣经；'),
('CNV', '路加福音', 42, 24, 46, '又说：“经上这样记着：基督必须受害，第三天从死人中复活。'),
('CNV', '路加福音', 42, 24, 47, '人要奉他的名，传讲悔改与赦罪的道，从耶路撒冷起，直传到万国。'),
('CNV', '路加福音', 42, 24, 48, '你们就是这些事的见证。'),
('CNV', '路加福音', 42, 24, 49, '我要使我父的应许临到你们身上，你们当在城里等候，直到得着从上面来的能力。”'),
('CNV', '路加福音', 42, 24, 50, '主带他们出去，到了伯大尼附近，举手给他们祝福。'),
('CNV', '路加福音', 42, 24, 51, '正在祝福的时候，他就离开他们，被接到天上去了。'),
('CNV', '路加福音', 42, 24, 52, '他们就敬拜他，欢欢喜喜地回到耶路撒冷，'),
('CNV', '路加福音', 42, 24, 53, '常常在殿里称颂神。'),
('CNV', '约翰福音', 43, 1, 1, '太初有道，道与神同在，道就是神。'),
('CNV', '约翰福音', 43, 1, 2, '这道太初与神同在。'),
('CNV', '约翰福音', 43, 1, 3, '万有是藉着他造的；凡被造的，没有一样不是藉着他造的。'),
('CNV', '约翰福音', 43, 1, 4, '在他里面有生命（有些抄本第3、4节或译：“万有是藉着他造的，没有一样不是藉着他造的；凡被造的，都在他里面有生命……”），这生命就是人的光。'),
('CNV', '约翰福音', 43, 1, 5, '光照在黑暗中，黑暗不能胜过光。'),
('CNV', '约翰福音', 43, 1, 6, '有一个人，名叫约翰，是神所差来的。'),
('CNV', '约翰福音', 43, 1, 7, '他来是要作见证，就是为光作见证，使众人藉着他可以相信。'),
('CNV', '约翰福音', 43, 1, 8, '他不是那光，而是要为那光作见证。'),
('CNV', '约翰福音', 43, 1, 9, '那光来到世界，是普照世人的真光。'),
('CNV', '约翰福音', 43, 1, 10, '他在世界，世界也是藉着他造的，世界却不认识他。'),
('CNV', '约翰福音', 43, 1, 11, '他到自己的地方来，自己的人却不接受他。'),
('CNV', '约翰福音', 43, 1, 12, '凡接受他的，就是信他名的人，他就赐给他们权利，成为神的儿女。'),
('CNV', '约翰福音', 43, 1, 13, '他们不是从血统生的，不是从肉身的意思生的，也不是从人意生的，而是从神生的。'),
('CNV', '约翰福音', 43, 1, 14, '道成了肉身，住在我们中间，满有恩典和真理。我们见过他的荣光，正是从父而来的独生子的荣光。'),
('CNV', '约翰福音', 43, 1, 15, '约翰为他作见证，大声说：“这一位就是我所说的：‘那在我以后来的，位分比我高，因为他本来是在我以前的。’”'),
('CNV', '约翰福音', 43, 1, 16, '从他的丰盛里我们都领受了，而且恩上加恩。'),
('CNV', '约翰福音', 43, 1, 17, '律法是藉着摩西颁布的，恩典和真理却是藉着耶稣基督而来的。'),
('CNV', '约翰福音', 43, 1, 18, '从来没有人见过神，只有在父怀里的独生子把他彰显出来。'),
('CNV', '约翰福音', 43, 1, 19, '以下是约翰的见证：犹太人从耶路撒冷派祭司和利未人到约翰那里，问他：“你是谁？”'),
('CNV', '约翰福音', 43, 1, 20, '约翰并不否认，坦白地承认说：“我不是基督。”'),
('CNV', '约翰福音', 43, 1, 21, '他们又问：“那么你是谁？是以利亚吗？”他说：“我不是。”“是那位先知吗？”他回答：“不是。”'),
('CNV', '约翰福音', 43, 1, 22, '于是他们再问：“你是谁？好让我们回覆派我们来的人。你说你自己是谁？”'),
('CNV', '约翰福音', 43, 1, 23, '他说：“我就是在旷野呼喊者的声音：‘修直主的路！’正如以赛亚先知所说的。”'),
('CNV', '约翰福音', 43, 1, 24, '这些人是法利赛人派来的。'),
('CNV', '约翰福音', 43, 1, 25, '他们问约翰：“你既然不是基督，不是以利亚，也不是那位先知，那么你为什么施洗呢？”'),
('CNV', '约翰福音', 43, 1, 26, '约翰回答：“我是用水施洗，但有一位站在你们中间，是你们不认识的；'),
('CNV', '约翰福音', 43, 1, 27, '他是在我以后来的，我就是给他解鞋带也不配。”'),
('CNV', '约翰福音', 43, 1, 28, '这些事发生在约旦河东的伯大尼，约翰施洗的地方。'),
('CNV', '约翰福音', 43, 1, 29, '第二天，约翰见耶稣迎面而来，就说：“看哪，神的羊羔，是除去世人的罪孽的！'),
('CNV', '约翰福音', 43, 1, 30, '这一位就是我所说的：‘有一个人，是在我以后来的，位分比我高，因为他本来是在我以前的。’'),
('CNV', '约翰福音', 43, 1, 31, '我本来不认识他，但为了要把他显明给以色列人，因此我来用水施洗。”'),
('CNV', '约翰福音', 43, 1, 32, '约翰又作见证说：“我曾看见圣灵，好像鸽子从天上降下来，停留在他的身上。'),
('CNV', '约翰福音', 43, 1, 33, '我本来不认识他，但那差我来用水施洗的对我说：‘你看见圣灵降下来，停留在谁身上，谁就是用圣灵施洗的。’'),
('CNV', '约翰福音', 43, 1, 34, '我看见了，就作见证说：‘这就是神的儿子。’”'),
('CNV', '约翰福音', 43, 1, 35, '过了一天，约翰和他的两个门徒又站在那里。'),
('CNV', '约翰福音', 43, 1, 36, '约翰看见耶稣走过的时候，就说：“看哪，神的羊羔！”'),
('CNV', '约翰福音', 43, 1, 37, '那两个门徒听见他的话，就跟从了耶稣。'),
('CNV', '约翰福音', 43, 1, 38, '耶稣转过身来，看见他们跟着，就问：“你们要什么？”他们说：“拉比，你在哪里住？”（“拉比”的意思就是“老师”。）'),
('CNV', '约翰福音', 43, 1, 39, '他说：“你们来看吧！”于是他们就去看他所住的地方。那一天他们就和耶稣住在一起；那时大约是下午四点钟。'),
('CNV', '约翰福音', 43, 1, 40, '听了约翰的话而跟从耶稣的那两个人，一个是西门．彼得的弟弟安得烈。'),
('CNV', '约翰福音', 43, 1, 41, '他先找到自己的哥哥西门，告诉他：“我们遇见弥赛亚了！”（“弥赛亚”的意思就是“基督”。）'),
('CNV', '约翰福音', 43, 1, 42, '安得烈就带他到耶稣那里。耶稣定睛看着他，说：“你是约翰的儿子西门，你要称为矶法。”（“矶法”翻译出来就是“彼得”。）'),
('CNV', '约翰福音', 43, 1, 43, '再过一天，耶稣决定往加利利去；他遇见腓力，就对他说：“来跟从我！”'),
('CNV', '约翰福音', 43, 1, 44, '腓力是伯赛大人，与安得烈和彼得同乡。'),
('CNV', '约翰福音', 43, 1, 45, '腓力找到拿但业，告诉他：“摩西在律法书上所写的，和众先知所记的那位，我们已经遇见了，他就是约瑟的儿子拿撒勒人耶稣。”'),
('CNV', '约翰福音', 43, 1, 46, '拿但业说：“拿撒勒还能出什么好的吗？”腓力说：“你来看！”'),
('CNV', '约翰福音', 43, 1, 47, '耶稣看见拿但业向他走过来，就论到他说：“看哪，这的确是个以色列人，他心里没有诡诈。”'),
('CNV', '约翰福音', 43, 1, 48, '拿但业问他：“你怎么认识我呢？”耶稣回答：“腓力还没有招呼你，你在无花果树下的时候，我就看见你了。”'),
('CNV', '约翰福音', 43, 1, 49, '拿但业说：“拉比，你是神的儿子，你是以色列的王！”'),
('CNV', '约翰福音', 43, 1, 50, '耶稣说：“因为我告诉你‘我看见你在无花果树下’，你就信了吗？你还要看见比这些更大的事。”'),
('CNV', '约翰福音', 43, 1, 51, '又对他说：“我实实在在告诉你们，你们要看见天开了，神的众使者在人子的身上，上去下来。”'),
('CNV', '约翰福音', 43, 2, 1, '第三天，在加利利的迦拿有婚筵，耶稣的母亲在那里；'),
('CNV', '约翰福音', 43, 2, 2, '耶稣和门徒也被邀请参加婚筵。'),
('CNV', '约翰福音', 43, 2, 3, '酒用尽了，耶稣的母亲对他说：“他们没有酒了。”'),
('CNV', '约翰福音', 43, 2, 4, '耶稣说：“母亲（“母亲”原文作“妇人”），我跟你有什么关系呢？我的时候还没有到。”'),
('CNV', '约翰福音', 43, 2, 5, '他母亲告诉仆人说：“他吩咐你们什么，就作什么。”'),
('CNV', '约翰福音', 43, 2, 6, '在那里有六口石缸，每口可盛两三桶水，是为犹太人行洁净礼用的。'),
('CNV', '约翰福音', 43, 2, 7, '耶稣吩咐仆人：“把缸都倒满水！”他们就倒满了，直到缸口。'),
('CNV', '约翰福音', 43, 2, 8, '耶稣又吩咐他们：“现在舀出来，送给筵席的总管！”他们就送去了。'),
('CNV', '约翰福音', 43, 2, 9, '总管尝了那水变的酒，不知道是从哪里来的，只有舀水的仆人知道。总管就叫新郎来，'),
('CNV', '约翰福音', 43, 2, 10, '对他说：“人人都是先摆上好酒，等到亲友喝够了，才摆上次等的，你倒把好酒留到现在。”'),
('CNV', '约翰福音', 43, 2, 11, '这是耶稣所行的第一件神迹，是在加利利的迦拿行的。他显出了自己的荣耀，他的门徒就信了他。'),
('CNV', '约翰福音', 43, 2, 12, '这事以后，耶稣和母亲、弟弟、门徒，都下到迦百农去，在那里住了没有几天。'),
('CNV', '约翰福音', 43, 2, 13, '犹太人的逾越节近了，耶稣就上耶路撒冷去。'),
('CNV', '约翰福音', 43, 2, 14, '他在圣殿的外院里看见有卖牛羊鸽子的，和坐在那里兑换银钱的，'),
('CNV', '约翰福音', 43, 2, 15, '就用绳索做了一条鞭子，把众人连牛带羊都从外院赶出去，倒掉兑换银钱的人的钱，推翻他们的桌子；'),
('CNV', '约翰福音', 43, 2, 16, '又对卖鸽子的说：“把这些东西搬出去，不要把我父的殿当作巿场。”'),
('CNV', '约翰福音', 43, 2, 17, '他的门徒就想起经上记着：“我为你的殿心中迫切，如同火烧。”'),
('CNV', '约翰福音', 43, 2, 18, '犹太人就问他：“你可以显什么神迹给我们看，证明你有权作这些事呢？”'),
('CNV', '约翰福音', 43, 2, 19, '耶稣回答：“你们拆毁这殿，我三天之内要把它建造起来。”'),
('CNV', '约翰福音', 43, 2, 20, '犹太人说：“这殿建了四十六年，你三天之内就能把它建造起来吗？”'),
('CNV', '约翰福音', 43, 2, 21, '但耶稣所说的殿，就是他的身体。'),
('CNV', '约翰福音', 43, 2, 22, '所以当耶稣从死人中复活以后，门徒想起了他说过这话，就信了圣经和耶稣所说的话。'),
('CNV', '约翰福音', 43, 2, 23, '耶稣在耶路撒冷过逾越节的时候，许多人看见他所行的神迹，就信了他的名。'),
('CNV', '约翰福音', 43, 2, 24, '耶稣却不信任他们，因为他知道所有的人，'),
('CNV', '约翰福音', 43, 2, 25, '也不需要谁指证人是怎样的，因为他知道人心里存的是什么。'),
('CNV', '约翰福音', 43, 3, 1, '有一个法利赛人，名叫尼哥德慕，是犹太人的官长。'),
('CNV', '约翰福音', 43, 3, 2, '他夜间来到耶稣那里，对他说：“拉比，我们知道你是从神那里来的教师，因为如果没有神同在，你所行的这些神迹，就没有人能行。”'),
('CNV', '约翰福音', 43, 3, 3, '耶稣回答：“我实实在在告诉你，人若不重生，就不能见神的国。”'),
('CNV', '约翰福音', 43, 3, 4, '尼哥德慕说：“人老了，怎能重生呢？难道他能再进母腹生出来吗？”'),
('CNV', '约翰福音', 43, 3, 5, '耶稣回答：“我实实在在告诉你，人若不是从水和圣灵生的，就不能进神的国。'),
('CNV', '约翰福音', 43, 3, 6, '从肉身生的就是肉身，从灵生的就是灵。'),
('CNV', '约翰福音', 43, 3, 7, '你不要因为我对你说‘你们必须重生’而感到希奇。'),
('CNV', '约翰福音', 43, 3, 8, '风随意而吹，你听见它的响声，却不知道它从哪里来，往哪里去；凡从圣灵生的，也是这样。”'),
('CNV', '约翰福音', 43, 3, 9, '尼哥德慕说：“怎能有这事呢？”'),
('CNV', '约翰福音', 43, 3, 10, '耶稣说：“你是以色列人的教师，还不明白这事吗？'),
('CNV', '约翰福音', 43, 3, 11, '我实实在在告诉你，我们知道的，才讲论；见过的，就作证，然而你们却不接受我们的见证。'),
('CNV', '约翰福音', 43, 3, 12, '我对你们讲地上的事，你们尚且不信，如果讲天上的事，怎能相信呢？'),
('CNV', '约翰福音', 43, 3, 13, '除了那从天上降下来的人子（有些抄本作“除了那从天上降下来仍旧在天上的人子”），没有人升过天。'),
('CNV', '约翰福音', 43, 3, 14, '摩西在旷野怎样把铜蛇举起，人子也必照样被举起来，'),
('CNV', '约翰福音', 43, 3, 15, '使所有信他的人都得永生。'),
('CNV', '约翰福音', 43, 3, 16, '“神爱世人，甚至把他的独生子赐给他们，叫一切信他的，不至灭亡，反得永生。'),
('CNV', '约翰福音', 43, 3, 17, '因为神差他的儿子到世上来，不是要定世人的罪，而是要使世人藉着他得救。'),
('CNV', '约翰福音', 43, 3, 18, '信他的，不被定罪；不信的，罪已经定了，因为他不信神独生子的名。'),
('CNV', '约翰福音', 43, 3, 19, '光来到世上，世人因为自己的行为邪恶，不爱光倒爱黑暗，定他们罪的原因，就在这里。'),
('CNV', '约翰福音', 43, 3, 20, '凡作恶的都恨光，不来接近光，免得他的恶行暴露出来。'),
('CNV', '约翰福音', 43, 3, 21, '凡行真理的，就来接近光，好显明他所作的都是靠着神而作的。”'),
('CNV', '约翰福音', 43, 3, 22, '这事以后，耶稣和门徒来到犹太地，他和他们住在那里，并且施洗。'),
('CNV', '约翰福音', 43, 3, 23, '约翰也在靠近撒冷的艾嫩施洗，因为那里水多；众人都去受洗。'),
('CNV', '约翰福音', 43, 3, 24, '那时约翰还没有入狱。'),
('CNV', '约翰福音', 43, 3, 25, '约翰的门徒和一个犹太人为洁净礼发生辩论。'),
('CNV', '约翰福音', 43, 3, 26, '他们来到约翰那里，对他说：“拉比，你看，从前和你在约旦河东，你为他作见证的那一位，他也在施洗，众人都到他那里去了。”'),
('CNV', '约翰福音', 43, 3, 27, '约翰回答：“除了从天上赐下来给他的，人就不能得到什么。'),
('CNV', '约翰福音', 43, 3, 28, '你们自己可以为我作证：我曾说，我不是基督，不过是奉差遣作他的先锋的。'),
('CNV', '约翰福音', 43, 3, 29, '娶新娘的是新郎。新郎的好友站在那里听着，听见新郎的声音就非常喜乐。因此，我这喜乐满溢了！'),
('CNV', '约翰福音', 43, 3, 30, '他必兴旺，我必衰微。'),
('CNV', '约翰福音', 43, 3, 31, '“那从天上来的，是在万有之上；从地上来的，是属于地，所讲的也是属于地。那从天上来的，是超越万有之上。'),
('CNV', '约翰福音', 43, 3, 32, '他把所见所闻的见证出来，可是没有人接受他的见证。'),
('CNV', '约翰福音', 43, 3, 33, '那接受他的见证的，就确认神是真的。'),
('CNV', '约翰福音', 43, 3, 34, '神所差来的那一位讲神的话，因为神把圣灵无限地赐给他。'),
('CNV', '约翰福音', 43, 3, 35, '父爱子，已经把万有交在他手里。'),
('CNV', '约翰福音', 43, 3, 36, '信子的，有永生；不信从子的，必不得见永生，神的震怒却常在他身上。”'),
('CNV', '约翰福音', 43, 4, 1, '主知道法利赛人听见他收门徒和施洗比约翰更多（'),
('CNV', '约翰福音', 43, 4, 2, '其实不是耶稣亲自施洗，而是他的门徒施洗），'),
('CNV', '约翰福音', 43, 4, 3, '就离开了犹太，再往加利利去。'),
('CNV', '约翰福音', 43, 4, 4, '他必须经过撒玛利亚。'),
('CNV', '约翰福音', 43, 4, 5, '于是到了撒玛利亚的一座城，名叫叙加；这城靠近雅各给他儿子约瑟的那块地。'),
('CNV', '约翰福音', 43, 4, 6, '在那里有雅各井。耶稣因为旅途疲倦了，就坐在井旁；那时大约正午。'),
('CNV', '约翰福音', 43, 4, 7, '有一个撒玛利亚妇人来打水。耶稣对她说：“请给我水喝。”'),
('CNV', '约翰福音', 43, 4, 8, '那时，他的门徒都进城买食物去了。'),
('CNV', '约翰福音', 43, 4, 9, '撒玛利亚妇人对耶稣说：“你是犹太人，怎么向我，一个撒玛利亚妇人要水喝呢？”（原来犹太人和撒玛利亚人不相往来。）'),
('CNV', '约翰福音', 43, 4, 10, '耶稣回答她：“你若知道神的恩赐，和对你说‘请给我水喝’的是谁，你必早已求他，他也必早把活水赐给你了。”'),
('CNV', '约翰福音', 43, 4, 11, '妇人说：“先生，你没有打水的器具，井又深，你从哪里得活水呢？'),
('CNV', '约翰福音', 43, 4, 12, '我们的祖先雅各把这口井留给我们，他自己和子孙以及牲畜都喝这井的水，难道你比他还大吗？”'),
('CNV', '约翰福音', 43, 4, 13, '耶稣回答：“凡喝这水的，还要再渴；'),
('CNV', '约翰福音', 43, 4, 14, '人若喝我所赐的水，就永远不渴。我所赐的水要在他里面成为涌流的泉源，直涌到永生。”'),
('CNV', '约翰福音', 43, 4, 15, '妇人说：“先生，请把这水赐给我，使我不渴，也不用来这里打水。”'),
('CNV', '约翰福音', 43, 4, 16, '耶稣说：“你去，叫你的丈夫，然后回到这里来。”'),
('CNV', '约翰福音', 43, 4, 17, '妇人对他说：“我没有丈夫。”耶稣说：“你说‘没有丈夫’是不错的。'),
('CNV', '约翰福音', 43, 4, 18, '你以前有五个丈夫，现在有的并不是你的丈夫；你说这话是真的。”'),
('CNV', '约翰福音', 43, 4, 19, '妇人说：“先生，我看出你是先知。'),
('CNV', '约翰福音', 43, 4, 20, '我们的祖先在这山上敬拜神，而你们却说，敬拜的地方必须在耶路撒冷。”'),
('CNV', '约翰福音', 43, 4, 21, '耶稣说：“妇人，你应当信我，时候将到，那时你们敬拜父，不在这山上，也不在耶路撒冷。'),
('CNV', '约翰福音', 43, 4, 22, '你们敬拜你们所不知道的，我们却敬拜我们所知道的，因为救恩是从犹太人出来的。'),
('CNV', '约翰福音', 43, 4, 23, '然而时候将到，现在就是了，那靠着圣灵按着真理敬拜父的，才是真正敬拜的人；因为父在寻找这样敬拜他的人。'),
('CNV', '约翰福音', 43, 4, 24, '神是灵，敬拜他的必须靠着圣灵按着真理敬拜他。”'),
('CNV', '约翰福音', 43, 4, 25, '妇人说：“我知道那称为基督的弥赛亚要来；他来了，要把一切都告诉我们。”'),
('CNV', '约翰福音', 43, 4, 26, '耶稣说：“我这现在跟你说话的就是他。”'),
('CNV', '约翰福音', 43, 4, 27, '正在这时候，门徒回来了，见耶稣和一个妇人说话，就很希奇；但是没有人问：“你要什么？”或说：“你为什么跟她说话？”'),
('CNV', '约翰福音', 43, 4, 28, '那妇人撇下了她的水罐，进到城里去，对众人说：'),
('CNV', '约翰福音', 43, 4, 29, '“你们来，看看一个人，他把我所作的一切都说出来，难道这人就是基督吗？”'),
('CNV', '约翰福音', 43, 4, 30, '众人就出城，往耶稣那里去。'),
('CNV', '约翰福音', 43, 4, 31, '当时，门徒对耶稣说：“拉比，请吃。”'),
('CNV', '约翰福音', 43, 4, 32, '耶稣说：“我有食物吃，是你们所不知道的。”'),
('CNV', '约翰福音', 43, 4, 33, '门徒就彼此说：“难道有人拿东西给他吃了吗？”'),
('CNV', '约翰福音', 43, 4, 34, '耶稣说：“我的食物就是遵行差我来者的旨意，并且完成他的工作。'),
('CNV', '约翰福音', 43, 4, 35, '你们不是说‘还有四个月才到收获的时候’吗？我告诉你们，举目向田观看，庄稼已经熟了，可以收割了。'),
('CNV', '约翰福音', 43, 4, 36, '收割的人得到工资，也积储五谷直到永生，使撒种的和收割的一同快乐。'),
('CNV', '约翰福音', 43, 4, 37, '‘这人撒种，那人收割’，这话是真的。'),
('CNV', '约翰福音', 43, 4, 38, '我派你们去收割你们所没有劳苦的；别人劳苦，你们却享受他们劳苦的成果。”'),
('CNV', '约翰福音', 43, 4, 39, '因着那妇人作见证的话：“他把我所作的一切都说出来了”，那城里就有许多撒玛利亚人信了耶稣。'),
('CNV', '约翰福音', 43, 4, 40, '于是他们来到耶稣那里，求他和他们同住，耶稣就在那里住了两天。'),
('CNV', '约翰福音', 43, 4, 41, '因着耶稣的话，信他的人就更多了。'),
('CNV', '约翰福音', 43, 4, 42, '他们就对那妇人说：“现在我们信，不再是因为你的话，而是因为我们亲自听见了，知道这位真是世人的救主。”'),
('CNV', '约翰福音', 43, 4, 43, '两天之后，耶稣离开那里，往加利利去。'),
('CNV', '约翰福音', 43, 4, 44, '耶稣自己说过：“先知在本乡是不受尊敬的。”'),
('CNV', '约翰福音', 43, 4, 45, '耶稣到了加利利的时候，加利利人都欢迎他，因为他们曾经上耶路撒冷去过节，见过他所行的一切。'),
('CNV', '约翰福音', 43, 4, 46, '耶稣又到了加利利的迦拿，就是他变水为酒的地方。有一个大臣，他的儿子在迦百农患病。'),
('CNV', '约翰福音', 43, 4, 47, '他听见耶稣从犹太到了加利利，就来见他，求他下去医治他的儿子，因为他的儿子快要死了。'),
('CNV', '约翰福音', 43, 4, 48, '耶稣对他说：“你们若看不见神迹奇事，总是不肯信。”'),
('CNV', '约翰福音', 43, 4, 49, '大臣说：“先生，求你趁我的孩子还没有死就下去吧！”'),
('CNV', '约翰福音', 43, 4, 50, '耶稣告诉他：“回去吧，你的儿子好了。”那人信耶稣对他说的话，就回去了。'),
('CNV', '约翰福音', 43, 4, 51, '正下去的时候，他的仆人迎着他走来，说他的孩子好了。'),
('CNV', '约翰福音', 43, 4, 52, '他就向仆人查问孩子是什么时候好转的。他们告诉他：“昨天下午一点钟，热就退了。”'),
('CNV', '约翰福音', 43, 4, 53, '这父亲就知道，那正是耶稣告诉他“你的儿子好了”的时候，他自己和全家就信了。'),
('CNV', '约翰福音', 43, 4, 54, '这是耶稣从犹太回到加利利以后所行的第二件神迹。'),
('CNV', '约翰福音', 43, 5, 1, '这些事以后，到了犹太人的一个节期，耶稣就上耶路撒冷去。'),
('CNV', '约翰福音', 43, 5, 2, '在耶路撒冷靠近羊门有一个水池，希伯来话叫作毕士大，池边有五条走廊。'),
('CNV', '约翰福音', 43, 5, 3, '在那里躺着许多病人，有瞎眼的、瘸腿的和瘫痪的。（有些抄本有以下一段：“他们等候水动，'),
('CNV', '约翰福音', 43, 5, 4, '因为有主的使者按时下去搅动池水，水动之后，谁先下去，无论什么病，必得痊愈。”）'),
('CNV', '约翰福音', 43, 5, 5, '那里有一个人，病了三十八年。'),
('CNV', '约翰福音', 43, 5, 6, '耶稣看见他躺着，知道他病了很久，就问他：“你要痊愈吗？”'),
('CNV', '约翰福音', 43, 5, 7, '病人回答：“先生，水动的时候，没有人把我放在池里；自己想去的时候，总是给别人抢先。”'),
('CNV', '约翰福音', 43, 5, 8, '耶稣对他说：“起来，拿着你的褥子走吧。”'),
('CNV', '约翰福音', 43, 5, 9, '那人立刻痊愈，就拿起褥子走了。那天正是安息日。'),
('CNV', '约翰福音', 43, 5, 10, '因此犹太人对那医好了的人说：“今天是安息日，你拿着褥子是不可以的。”'),
('CNV', '约翰福音', 43, 5, 11, '他却回答：“那使我痊愈的对我说：‘拿起你的褥子走吧’。”'),
('CNV', '约翰福音', 43, 5, 12, '他们就问：“那对你说‘拿起来走吧’的是谁？”'),
('CNV', '约翰福音', 43, 5, 13, '那医好了的人不知道他是谁，因为那里人很多，耶稣已经避开了。'),
('CNV', '约翰福音', 43, 5, 14, '后来，耶稣在殿里遇见那人，对他说：“你已经痊愈了，不可再犯罪，免得招来更大的祸患。”'),
('CNV', '约翰福音', 43, 5, 15, '那人就去告诉犹太人，使他痊愈的就是耶稣。'),
('CNV', '约翰福音', 43, 5, 16, '从此犹太人就迫害耶稣，因为他常常在安息日作这些事。'),
('CNV', '约翰福音', 43, 5, 17, '耶稣却对他们说：“我父作工直到现在，我也作工。”'),
('CNV', '约翰福音', 43, 5, 18, '因此犹太人就更想杀耶稣，因为他不但破坏安息日，而且称神为自己的父，把自己与神当作平等。'),
('CNV', '约翰福音', 43, 5, 19, '耶稣又对他们说：“我实实在在告诉你们，子靠着自己不能作什么，只能作他看见父所作的；因为父所作的事，子也照样作。'),
('CNV', '约翰福音', 43, 5, 20, '父爱子，把自己所作的一切指示给他看，还要把比这些更大的事指示给他看，使你们惊奇。'),
('CNV', '约翰福音', 43, 5, 21, '父怎样叫死人复活，使他们得生命，子也照样随自己的意思使人得生命。'),
('CNV', '约翰福音', 43, 5, 22, '父不审判人，却已经把审判的权柄完全交给子，'),
('CNV', '约翰福音', 43, 5, 23, '使所有的人尊敬子好像尊敬父一样。不尊敬子的，就是不尊敬那差他来的父。'),
('CNV', '约翰福音', 43, 5, 24, '我实实在在告诉你们，那听见我的话又信那差我来的，就有永生，不被定罪，而是已经出死入生了。'),
('CNV', '约翰福音', 43, 5, 25, '我实实在在告诉你们，时候将到，现在就是了，死人要听见神儿子的声音，听见的人就要活了。'),
('CNV', '约翰福音', 43, 5, 26, '就如父是生命的源头，照样他也使子成为生命的源头，'),
('CNV', '约翰福音', 43, 5, 27, '并且把执行审判的权柄赐给他，因为他是人子。'),
('CNV', '约翰福音', 43, 5, 28, '你们不要把这事看作希奇，因为时候将到，那时所有在坟墓里的都要听见他的声音，'),
('CNV', '约翰福音', 43, 5, 29, '并且都要出来；行善的复活得生命，作恶的复活被定罪。'),
('CNV', '约翰福音', 43, 5, 30, '“我靠着自己不能作什么，我怎样听见，就怎样审判。我的审判是公义的，因为我不寻求自己的意思，只求那差我来者的旨意。'),
('CNV', '约翰福音', 43, 5, 31, '我若为自己作证，我的见证就不真。'),
('CNV', '约翰福音', 43, 5, 32, '然而另有一位为我作证的，我知道他为我作的见证是真的。'),
('CNV', '约翰福音', 43, 5, 33, '你们曾经派人到约翰那里，他为真理作过见证。'),
('CNV', '约翰福音', 43, 5, 34, '我不接受从人而来的见证，但我说这些事，是要你们得救。'),
('CNV', '约翰福音', 43, 5, 35, '约翰是一盏点亮的灯，你们情愿暂时在他的光中欢乐。'),
('CNV', '约翰福音', 43, 5, 36, '但我有比约翰更大的见证，因为父赐给我要我完成的工作，就是我所要作的，证明我是父所差来的。'),
('CNV', '约翰福音', 43, 5, 37, '差我来的父亲自为我作了见证。他的声音，你们从没有听过；他的容貌，你们从没有见过；'),
('CNV', '约翰福音', 43, 5, 38, '他的道，你们也不放在心里，因为你们不信他所差来的那一位。'),
('CNV', '约翰福音', 43, 5, 39, '你们研究圣经，因为你们认为圣经中有永生，其实为我作证的就是这圣经，'),
('CNV', '约翰福音', 43, 5, 40, '然而你们却不肯到我这里来得生命。'),
('CNV', '约翰福音', 43, 5, 41, '“我不接受从人而来的称赞；'),
('CNV', '约翰福音', 43, 5, 42, '我知道你们心里没有神的爱。'),
('CNV', '约翰福音', 43, 5, 43, '我奉我父的名而来，你们不接待我；如果有别人以自己的名义而来，你们倒接待他。'),
('CNV', '约翰福音', 43, 5, 44, '你们彼此接受称赞，却不寻求从独一的神而来的称赞，怎么能信呢？'),
('CNV', '约翰福音', 43, 5, 45, '不要以为我要向父控告你们，有一位控告你们的，就是你们所仰赖的摩西。'),
('CNV', '约翰福音', 43, 5, 46, '你们若信摩西，也必信我，因为他所写的书曾论及我。'),
('CNV', '约翰福音', 43, 5, 47, '你们若不信他所写的，怎能信我的话呢？”'),
('CNV', '约翰福音', 43, 6, 1, '这些事以后，耶稣渡过加利利海，就是提比里亚海。'),
('CNV', '约翰福音', 43, 6, 2, '有一大群人，因为看见了他在病人身上所行的神迹，就跟随了他。'),
('CNV', '约翰福音', 43, 6, 3, '耶稣上了山，同门徒坐在那里。'),
('CNV', '约翰福音', 43, 6, 4, '那时犹太人的逾越节近了。'),
('CNV', '约翰福音', 43, 6, 5, '耶稣举目观看，见一大群人向他走过来，就对腓力说：“我们从哪里买饼给这些人吃呢？”'),
('CNV', '约翰福音', 43, 6, 6, '他说这话，是要试验腓力，因他自己早已知道要怎样作。'),
('CNV', '约翰福音', 43, 6, 7, '腓力回答：“就算二百银币买的饼，每人分一点，也是不够的。”'),
('CNV', '约翰福音', 43, 6, 8, '有一个门徒，就是西门．彼得的弟弟安得烈，对耶稣说：'),
('CNV', '约翰福音', 43, 6, 9, '“这里有个小孩子，带着五个大麦饼、两条鱼；只是分给这么多人，有什么用呢？”'),
('CNV', '约翰福音', 43, 6, 10, '耶稣吩咐他们：“你们叫众人坐下。”原来那地方的草很多，众人就坐下，单是男人的数目约有五千。'),
('CNV', '约翰福音', 43, 6, 11, '耶稣拿起饼来，祝谢了，就分给坐着的人；分鱼也是这样，都是随着他们所要的。'),
('CNV', '约翰福音', 43, 6, 12, '他们吃饱了之后，耶稣对门徒说：“把剩下的零碎收拾起来，免得浪费。”'),
('CNV', '约翰福音', 43, 6, 13, '门徒就把众人吃剩那五个大麦饼的零碎收拾起来，装满了十二个篮子。'),
('CNV', '约翰福音', 43, 6, 14, '众人看见耶稣所行的神迹，就说：“这真是那要到世上来的先知。”'),
('CNV', '约翰福音', 43, 6, 15, '耶稣知道群众要来强迫他作王，就独自又退到山上去了。'),
('CNV', '约翰福音', 43, 6, 16, '到了晚上，他的门徒下到海边去。'),
('CNV', '约翰福音', 43, 6, 17, '他们上了船，要渡海往迦百农去。那时天已经黑了，耶稣还没有到他们那里。'),
('CNV', '约翰福音', 43, 6, 18, '忽然海上起了狂风，波浪翻腾。'),
('CNV', '约翰福音', 43, 6, 19, '门徒摇橹约行了五六公里，看见耶稣在海面上行走，渐渐靠近船，就害怕起来。'),
('CNV', '约翰福音', 43, 6, 20, '耶稣对他们说：“是我，不要怕。”'),
('CNV', '约翰福音', 43, 6, 21, '他们这才把他接上船，船就立刻到了他们要去的地方。'),
('CNV', '约翰福音', 43, 6, 22, '第二天，站在海那边的群众，看见只有一只小船留在那里，并且知道耶稣没有和他的门徒一同上船，门徒是自己去的；'),
('CNV', '约翰福音', 43, 6, 23, '不过有几只从提比里亚来的船停在那里，靠近他们在主祝谢以后吃饼的地方。'),
('CNV', '约翰福音', 43, 6, 24, '群众见耶稣和门徒都不在那里，就上船往迦百农去找耶稣。'),
('CNV', '约翰福音', 43, 6, 25, '他们在对岸找到了耶稣，就问他：“拉比，你几时到这里来的？”'),
('CNV', '约翰福音', 43, 6, 26, '耶稣回答：“我实实在在告诉你们，你们找我，不是因为看见了神迹，而是因为吃了饼又吃饱了。'),
('CNV', '约翰福音', 43, 6, 27, '不要为那必朽坏的食物操劳，却要为那存到永生的食物操劳，就是人子所要赐给你们的，因为人子是父神所印证的。”'),
('CNV', '约翰福音', 43, 6, 28, '众人又问他：“我们应该作什么，才算是作神的工作呢？”'),
('CNV', '约翰福音', 43, 6, 29, '耶稣回答：“信神所差来的，就是作神的工了。”'),
('CNV', '约翰福音', 43, 6, 30, '于是他们就说：“你要行什么神迹，让我们看了就信你呢？你到底能作什么呢？'),
('CNV', '约翰福音', 43, 6, 31, '我们的祖宗在旷野吃过吗哪，正如经上所记：‘他把从天上来的食物赐给他们吃。’”'),
('CNV', '约翰福音', 43, 6, 32, '耶稣对他们说：“我实实在在告诉你们，不是摩西把那从天上来的食物赐给你们，而是我父把天上来的真食物赐给你们；'),
('CNV', '约翰福音', 43, 6, 33, '因为神的食物就是从天上降下来，把生命赐给世人的那一位。”'),
('CNV', '约翰福音', 43, 6, 34, '他们对耶稣说：“主啊，求你常把这食物赐给我们。”'),
('CNV', '约翰福音', 43, 6, 35, '耶稣说：“我就是生命的食物，到我这里来的，必定不饿；信我的，永远不渴。'),
('CNV', '约翰福音', 43, 6, 36, '但我告诉你们，你们虽然见了我，还是不信。'),
('CNV', '约翰福音', 43, 6, 37, '凡是父赐给我的人，必到我这里来；到我这里来的，我决不丢弃他，'),
('CNV', '约翰福音', 43, 6, 38, '因为我从天上降下来，不是要行自己的意思，而是要行那差我来者的旨意。'),
('CNV', '约翰福音', 43, 6, 39, '那差我来者的旨意就是：他所赐给我的人，我连一个也不失落，并且在末日我要使他们复活。'),
('CNV', '约翰福音', 43, 6, 40, '因为我父的旨意，是要使所有看见了子而信的人有永生，并且在末日我要使他们复活。”'),
('CNV', '约翰福音', 43, 6, 41, '犹太人因为耶稣说“我是从天上降下来的食物”，就纷纷议论他。'),
('CNV', '约翰福音', 43, 6, 42, '他们说：“这不是约瑟的儿子耶稣吗？他的父母我们不都认识吗？他现在怎么说‘我是从天上降下来的’呢？”'),
('CNV', '约翰福音', 43, 6, 43, '耶稣回答：“你们不要彼此议论。'),
('CNV', '约翰福音', 43, 6, 44, '如果不是差我来的父吸引人，就没有人能到我这里来；到我这里来的，在末日我要使他复活。'),
('CNV', '约翰福音', 43, 6, 45, '先知书上记着：‘众人都必受神的教导。’凡听见从父那里来的教训而又学习的，必到我这里来。'),
('CNV', '约翰福音', 43, 6, 46, '这不是说有人见过父；只有从神那里来的那一位，他才见过父。'),
('CNV', '约翰福音', 43, 6, 47, '我实实在在告诉你们，信的人有永生。'),
('CNV', '约翰福音', 43, 6, 48, '我就是生命的食物，'),
('CNV', '约翰福音', 43, 6, 49, '你们的祖宗在旷野吃过吗哪，还是死了。'),
('CNV', '约翰福音', 43, 6, 50, '这是从天上降下来的食物，使人吃了就不死。'),
('CNV', '约翰福音', 43, 6, 51, '我就是从天上降下来生命的食物，人若吃了这食物，就必活到永远。我要赐的食物就是我的肉，是为了世人的生命而赐的。”'),
('CNV', '约翰福音', 43, 6, 52, '于是，犹太人彼此争论，说：“这个人怎能把他的肉给我们吃呢？”'),
('CNV', '约翰福音', 43, 6, 53, '耶稣就对他们说：“我实实在在告诉你们，你们若不吃人子的肉，不喝人子的血，就没有生命在你们里面。'),
('CNV', '约翰福音', 43, 6, 54, '吃我肉、喝我血的，就有永生，在末日我要使他复活；'),
('CNV', '约翰福音', 43, 6, 55, '因为我的肉是真正的食物，我的血是真正的饮料。'),
('CNV', '约翰福音', 43, 6, 56, '吃我肉、喝我血的人，就住在我里面，我也住在他里面。'),
('CNV', '约翰福音', 43, 6, 57, '正如永活的父差遣了我，我也因父活着；照样，吃我肉的人也必因我而活。'),
('CNV', '约翰福音', 43, 6, 58, '这就是从天上降下来的食物，不像吗哪，你们的祖宗吃过，还是死了；吃这食物的，必活到永远。”'),
('CNV', '约翰福音', 43, 6, 59, '这些话是耶稣在迦百农会堂里教导人的时候说的。'),
('CNV', '约翰福音', 43, 6, 60, '他的门徒中，有许多人听了，就说：“这话很难，谁能接受呢？”'),
('CNV', '约翰福音', 43, 6, 61, '耶稣心里知道门徒为了这事议论纷纷，就对他们说：“这话使你们动摇吗？'),
('CNV', '约翰福音', 43, 6, 62, '如果你们看见人子升到他原来所在的地方，又怎样呢？'),
('CNV', '约翰福音', 43, 6, 63, '使人活的是灵，肉体是无济于事的。我对你们所说的话是灵、是生命。'),
('CNV', '约翰福音', 43, 6, 64, '然而你们中间却有不信的人。”原来从起初耶稣就知道那些不信的是谁，那要把他出卖的又是谁。'),
('CNV', '约翰福音', 43, 6, 65, '耶稣跟着说：“所以我对你们说过，如果不是父所赐的，没有人能到我这里来。”'),
('CNV', '约翰福音', 43, 6, 66, '从此，他的门徒中有许多人退去了，不再与他同行。'),
('CNV', '约翰福音', 43, 6, 67, '于是耶稣对十二门徒说：“你们也想离去吗？”'),
('CNV', '约翰福音', 43, 6, 68, '西门．彼得回答：“主啊，你有永生之道，我们还跟从谁呢？'),
('CNV', '约翰福音', 43, 6, 69, '我们已经相信，并且知道你是神的圣者。”'),
('CNV', '约翰福音', 43, 6, 70, '耶稣说：“我不是拣选了你们十二个人吗？但你们中间有一个是魔鬼。”'),
('CNV', '约翰福音', 43, 6, 71, '耶稣这话是指着加略人西门的儿子犹大说的，因为他虽然是十二门徒之一，却要出卖耶稣。'),
('CNV', '约翰福音', 43, 7, 1, '这事以后，耶稣周游加利利，不愿在犹太往来，因为犹太人想要杀他。'),
('CNV', '约翰福音', 43, 7, 2, '犹太人的住棚节快到了，'),
('CNV', '约翰福音', 43, 7, 3, '耶稣的弟弟就对他说：“你应当离开这里上犹太去，好让你的门徒也可以看见你所行的事；'),
('CNV', '约翰福音', 43, 7, 4, '因为没有人想引人注目，却在暗处行事的。你既然行这些事，就应该向世人显明自己。”'),
('CNV', '约翰福音', 43, 7, 5, '原来连他的弟弟也不信他。'),
('CNV', '约翰福音', 43, 7, 6, '耶稣就对他们说：“我的时候还没有到，你们的时候却常常是方便的。'),
('CNV', '约翰福音', 43, 7, 7, '世人不能恨你们，却憎恨我，因为我指证他们的行为是邪恶的。'),
('CNV', '约翰福音', 43, 7, 8, '你们上去过节吧！我现在不上去过这个节，因为我的时机还没有成熟。”'),
('CNV', '约翰福音', 43, 7, 9, '他说了这些话以后，仍然住在加利利。'),
('CNV', '约翰福音', 43, 7, 10, '然而，他的弟弟上去过节以后，他也上去过节，不是公开地去，却是暗中地去。'),
('CNV', '约翰福音', 43, 7, 11, '过节的时候，犹太人寻找耶稣，说：“那人在哪里呢？”'),
('CNV', '约翰福音', 43, 7, 12, '群众因他纷纷议论，有的说：“他是好人。”有的说：“不，他是欺骗众人的。”'),
('CNV', '约翰福音', 43, 7, 13, '但没有人敢公开讲论他，因为怕犹太人。'),
('CNV', '约翰福音', 43, 7, 14, '节期当中，耶稣上圣殿去教导人。'),
('CNV', '约翰福音', 43, 7, 15, '犹太人就希奇，说：“这个人没有学过，怎会通晓经书呢？”'),
('CNV', '约翰福音', 43, 7, 16, '耶稣说：“我的教训不是我自己的，而是出于那差我来的。'),
('CNV', '约翰福音', 43, 7, 17, '人若愿意遵行神的旨意，就会知道这教训是出于神，还是我凭着自己的意思说的。'),
('CNV', '约翰福音', 43, 7, 18, '那凭着自己的意思说的，是求自己的荣誉；但那寻求差他来者的荣耀的，才是真诚的人，在他里面没有不义。'),
('CNV', '约翰福音', 43, 7, 19, '摩西不是曾经把律法传给你们吗？你们竟然没有一个人遵行律法。你们为什么想要杀我呢？”'),
('CNV', '约翰福音', 43, 7, 20, '群众回答：“你是鬼附的，谁想要杀你呢？”'),
('CNV', '约翰福音', 43, 7, 21, '耶稣说：“我行了一件事，你们都以为希奇。'),
('CNV', '约翰福音', 43, 7, 22, '摩西曾经把割礼传给你们（其实割礼不是从摩西开始的，而是从列祖开始的），因此，你们在安息日也给人行割礼。'),
('CNV', '约翰福音', 43, 7, 23, '如果人在安息日行割礼，为的是要遵守摩西的律法，那么我在安息日使一个人全身健康，你们就向我生气吗？'),
('CNV', '约翰福音', 43, 7, 24, '不要按外貌判断人，总要公公平平地判断人。”'),
('CNV', '约翰福音', 43, 7, 25, '当时，有些耶路撒冷人说：“这不是他们想要杀的人吗？'),
('CNV', '约翰福音', 43, 7, 26, '你看，他还在公开地讲话，竟然没有人对他说什么，难道官长们真的认为这个人就是基督吗？'),
('CNV', '约翰福音', 43, 7, 27, '可是我们知道这个人是从哪里来的，只是基督来的时候，没有人知道他是从哪里来的！”'),
('CNV', '约翰福音', 43, 7, 28, '当时耶稣在殿里教导人，大声说：“你们以为认识我，也知道我从哪里来，其实我不是凭着自己的意思来的，但那差我来的是真实的，你们却不认识他。'),
('CNV', '约翰福音', 43, 7, 29, '然而我认识他，因为我从他那里来，也是他差我来的。”'),
('CNV', '约翰福音', 43, 7, 30, '于是他们想逮捕他，只是没有人下手，因为他的时候还没有到。'),
('CNV', '约翰福音', 43, 7, 31, '群众中有许多人信了他。他们说：“基督来的时候，他所行的神迹，能比这人所行的更多吗？”'),
('CNV', '约翰福音', 43, 7, 32, '法利赛人听见群众纷纷议论这些关于耶稣的事，祭司长和法利赛人就派差役去逮捕耶稣。'),
('CNV', '约翰福音', 43, 7, 33, '于是耶稣说：“我跟你们在一起的时候不多了，我要回到那差我来的那里去。'),
('CNV', '约翰福音', 43, 7, 34, '你们要寻找我，却找不着；我所在的地方，你们是不能去的。”'),
('CNV', '约翰福音', 43, 7, 35, '犹太人彼此说：“这个人要到哪里去，使我们找不着他呢？难道他要到散居在希腊人中的犹太人那里，去教导希腊人吗？'),
('CNV', '约翰福音', 43, 7, 36, '他说‘你们要寻找我，却找不着；我所在的地方，你们是不能去的’这话，是什么意思呢？”'),
('CNV', '约翰福音', 43, 7, 37, '节期的最后一天，就是最隆重的那一天，耶稣站着高声说：“人若渴了，可以到我这里来喝！'),
('CNV', '约翰福音', 43, 7, 38, '信我的人，就像圣经所说的，从他的腹中要涌流出活水的江河来。”'),
('CNV', '约翰福音', 43, 7, 39, '他这话是指着信他的人要接受圣灵说的；那时圣灵还没有降临，因为耶稣还没有得着荣耀。'),
('CNV', '约翰福音', 43, 7, 40, '群众中有人听了这些话，就说：“这真是‘那位先知’！”'),
('CNV', '约翰福音', 43, 7, 41, '另有人说：“他是基督。”还有人说：“基督是从加利利出来的吗？'),
('CNV', '约翰福音', 43, 7, 42, '圣经不是说基督是大卫的后裔，是从大卫本乡伯利恒出来的吗？”'),
('CNV', '约翰福音', 43, 7, 43, '群众因为耶稣的缘故，就起了纷争。'),
('CNV', '约翰福音', 43, 7, 44, '他们中间有人想逮捕耶稣，只是没有人下手。'),
('CNV', '约翰福音', 43, 7, 45, '差役回到祭司长和法利赛人那里。他们就问差役：“你们为什么没有把他带来？”'),
('CNV', '约翰福音', 43, 7, 46, '差役回答：“从来没有人像他这样讲话的！”'),
('CNV', '约翰福音', 43, 7, 47, '法利赛人说：“连你们也受了欺骗吗？'),
('CNV', '约翰福音', 43, 7, 48, '官长或法利赛人中间有谁是信他的呢？'),
('CNV', '约翰福音', 43, 7, 49, '至于这群不明白律法的人，他们是可咒诅的。”'),
('CNV', '约翰福音', 43, 7, 50, '他们当中有一个人，就是以前来见耶稣的尼哥德慕，对他们说：'),
('CNV', '约翰福音', 43, 7, 51, '“如果不先听取他本人的口供，查明他所作的事，我们的律法怎能把他定罪呢？”'),
('CNV', '约翰福音', 43, 7, 52, '他们回答：“你也是从加利利出来的吗？你去考查一下，就知道先知是不会从加利利兴起的。”'),
('CNV', '约翰福音', 43, 7, 53, '于是各人都回家去了。（后期抄本才加上7:53~8:11）'),
('CNV', '约翰福音', 43, 8, 1, '耶稣往橄榄山去。'),
('CNV', '约翰福音', 43, 8, 2, '黎明的时候，他又到圣殿去，众人都来到他那里，他就坐下教导他们。'),
('CNV', '约翰福音', 43, 8, 3, '经学家和法利赛人带了一个行淫时被抓到的妇人来，叫她站在中间，'),
('CNV', '约翰福音', 43, 8, 4, '就对耶稣说：“先生，这妇人是正在犯奸淫的时候被抓到的。'),
('CNV', '约翰福音', 43, 8, 5, '摩西在律法上吩咐我们把这样的妇人用石头打死，你怎样说呢？”'),
('CNV', '约翰福音', 43, 8, 6, '他们说这话是要试探耶稣，要找把柄来控告他。耶稣却弯下身，用指头在地上写字。'),
('CNV', '约翰福音', 43, 8, 7, '他们不住地问耶稣，他就挺起身来，说：“你们中间谁是没有罪的，他就可以先拿起石头打她。”'),
('CNV', '约翰福音', 43, 8, 8, '于是又弯下身在地上写字。'),
('CNV', '约翰福音', 43, 8, 9, '他们听了这话，就从年老的开始，一个一个地都离开了，留下的只有耶稣和那个还站在那里的妇人。'),
('CNV', '约翰福音', 43, 8, 10, '耶稣挺起身来，问她：“妇人，他们在哪里？没有人定你的罪吗？”'),
('CNV', '约翰福音', 43, 8, 11, '她说：“主啊！没有。”耶稣说：“我也不定你的罪。走吧，从现在起不要再犯罪了。”'),
('CNV', '约翰福音', 43, 8, 12, '耶稣又对众人说：“我是世界的光，跟从我的，必定不在黑暗里走，却要得着生命的光。”'),
('CNV', '约翰福音', 43, 8, 13, '法利赛人对他说：“你为自己作证，你的见证不是真实的。”'),
('CNV', '约翰福音', 43, 8, 14, '耶稣回答：“即使我为自己作证，我的见证还是真实的，因为我知道我从哪里来，往哪里去，但你们却不知道我从哪里来，往哪里去。'),
('CNV', '约翰福音', 43, 8, 15, '你们按着外貌判断人，我却不判断人。'),
('CNV', '约翰福音', 43, 8, 16, '即使我判断人，我的判断也是正确的，因为我不是独自一人，而是差我来的父和我在一起。'),
('CNV', '约翰福音', 43, 8, 17, '你们的律法上也写着：‘两个人的见证才是真的。’'),
('CNV', '约翰福音', 43, 8, 18, '我为自己作证，差我来的父也为我作证。”'),
('CNV', '约翰福音', 43, 8, 19, '他们问：“你的父在哪里？”耶稣回答：“你们不认识我，也不认识我的父；如果你们认识我，也就认识我的父了。”'),
('CNV', '约翰福音', 43, 8, 20, '这些话是耶稣在殿里教导人的时候，在银库的院中说的。当时没有人逮捕他，因为他的时候还没有到。'),
('CNV', '约翰福音', 43, 8, 21, '耶稣又对他们说：“我要去了，你们要寻找我，并且要在自己的罪中死亡；我去的地方，你们不能到。”'),
('CNV', '约翰福音', 43, 8, 22, '于是犹太人说：“他说‘我去的地方，你们不能到’，难道他要自杀吗？”'),
('CNV', '约翰福音', 43, 8, 23, '耶稣说：“你们是从地上来的，我是从天上来的；你们属这世界，我却不属这世界，'),
('CNV', '约翰福音', 43, 8, 24, '所以我对你们说，你们要在自己的罪中死亡；你们若不信我就是‘那一位’，就要在自己的罪中死亡。”'),
('CNV', '约翰福音', 43, 8, 25, '他们就问：“你是谁？”耶稣说：“我不是从起初就告诉你们吗？'),
('CNV', '约翰福音', 43, 8, 26, '关于你们，我有许多事要说，要判断；但那差我来的是真实的，我从他那里听见的，就告诉世人。”'),
('CNV', '约翰福音', 43, 8, 27, '他们不明白耶稣是对他们讲论父的事。'),
('CNV', '约翰福音', 43, 8, 28, '所以耶稣说：“你们举起了人子以后，必定知道我就是‘那一位’，并且知道我不凭着自己作什么事；我说的这些话，是照着父所教导我的。'),
('CNV', '约翰福音', 43, 8, 29, '那差我来的和我同在，他没有留下我独自一人，因为我常作他喜悦的事。”'),
('CNV', '约翰福音', 43, 8, 30, '耶稣说这些话的时候，就有许多人信了他。'),
('CNV', '约翰福音', 43, 8, 31, '于是耶稣对信了他的犹太人说：“你们若持守我的道，就真是我的门徒了；'),
('CNV', '约翰福音', 43, 8, 32, '你们必定认识真理，真理必定使你们自由。”'),
('CNV', '约翰福音', 43, 8, 33, '他们说：“我们是亚伯拉罕的后裔，从来没有被谁奴役过，你怎么说‘你们必得自由’呢？”'),
('CNV', '约翰福音', 43, 8, 34, '耶稣说：“我实实在在告诉你们，凡犯罪的都是罪的奴隶。'),
('CNV', '约翰福音', 43, 8, 35, '奴隶不能永远住在家里，唯有儿子才可以永远住在家里。'),
('CNV', '约翰福音', 43, 8, 36, '所以，神的儿子若使你们自由，你们就真的得自由了。'),
('CNV', '约翰福音', 43, 8, 37, '我知道你们是亚伯拉罕的后裔；但你们想杀我，因为你们心里不能容纳我的道。'),
('CNV', '约翰福音', 43, 8, 38, '我所说的，是我在父那里看见的；但你们所作的，却是从你们的父那里听见的。”'),
('CNV', '约翰福音', 43, 8, 39, '他们说：“我们的祖宗是亚伯拉罕。”耶稣说：“你们若是亚伯拉罕的子孙，就必作亚伯拉罕所作的。'),
('CNV', '约翰福音', 43, 8, 40, '现在我把从神那里听见的真理告诉了你们，你们竟然想杀我，这不是亚伯拉罕所作的。'),
('CNV', '约翰福音', 43, 8, 41, '你们要作的，正是你们的父要作的。”他们说：“我们不是从淫乱生的；我们只有一位父，就是神。”'),
('CNV', '约翰福音', 43, 8, 42, '耶稣说：“如果神是你们的父，你们就必爱我，因为我是从神那里来的；我已经来到这里。我不是凭着自己来的，而是神差了我来。'),
('CNV', '约翰福音', 43, 8, 43, '你们为什么不明白我的话呢？因为我的道你们听不进去。'),
('CNV', '约翰福音', 43, 8, 44, '你们是出于你们的父魔鬼，喜欢按着你们的父的私欲行事。他从起初就是杀人的凶手，不守真理，因为他心里没有真理。他说谎是出于本性，因为他本来就是说谎者，也是说谎的人的父。'),
('CNV', '约翰福音', 43, 8, 45, '我讲真理，你们却因此不信我。'),
('CNV', '约翰福音', 43, 8, 46, '你们中间有谁能指证我有罪呢？我既然讲真理，你们为什么不信我呢？'),
('CNV', '约翰福音', 43, 8, 47, '出于神的，就听神的话；你们不听，因为你们不是出于神的。”'),
('CNV', '约翰福音', 43, 8, 48, '犹太人对耶稣说：“我们说你是撒玛利亚人，并且是鬼附的，不是很对吗？”'),
('CNV', '约翰福音', 43, 8, 49, '耶稣回答：“我不是鬼附的。我尊敬我的父，你们却侮辱我。'),
('CNV', '约翰福音', 43, 8, 50, '我不求自己的荣耀，但有一位是为我求荣耀，并且是审判人的。'),
('CNV', '约翰福音', 43, 8, 51, '我实实在在告诉你们，人若遵守我的道，必定永远不见死亡。”'),
('CNV', '约翰福音', 43, 8, 52, '犹太人对他说：“现在我们知道你的确是鬼附的。亚伯拉罕死了，先知们也死了，你还说‘人若遵守我的道，必定永远不尝死味’，'),
('CNV', '约翰福音', 43, 8, 53, '难道你比我们的祖宗亚伯拉罕还大吗？他死了，先知们也死了；你把自己当作什么人呢？”'),
('CNV', '约翰福音', 43, 8, 54, '耶稣回答：“如果我荣耀自己，我的荣耀就算不得什么；那使我得荣耀的是我的父，就是你们说是你们的神的那一位。'),
('CNV', '约翰福音', 43, 8, 55, '可是你们不认识他，我却认识他。如果我说我不认识他，我就像你们一样是说谎的；然而我认识他，也遵守他的道。'),
('CNV', '约翰福音', 43, 8, 56, '你们的祖宗亚伯拉罕，因为可以看见我的日子就欢喜，既然看见了，他就很快乐。”'),
('CNV', '约翰福音', 43, 8, 57, '犹太人对他说：“你还不到五十岁，怎会见过亚伯拉罕呢？”'),
('CNV', '约翰福音', 43, 8, 58, '耶稣说：“我实实在在告诉你们，亚伯拉罕出生以前，我已经存在了。”'),
('CNV', '约翰福音', 43, 8, 59, '于是他们拿起石头要打他。耶稣却躲起来，从殿里出去了。'),
('CNV', '约翰福音', 43, 9, 1, '耶稣走路的时候，看见一个生下来就瞎眼的人。'),
('CNV', '约翰福音', 43, 9, 2, '他的门徒问他：“拉比，这人生下来就瞎眼，是谁犯了罪？是他呢，还是他的父母呢？”'),
('CNV', '约翰福音', 43, 9, 3, '耶稣回答：“不是他犯了罪，也不是他的父母犯了罪，而是要在他身上彰显神的作为。'),
('CNV', '约翰福音', 43, 9, 4, '趁着白昼，我们必须作那差我来者的工；黑夜一到，就没有人能作工了。'),
('CNV', '约翰福音', 43, 9, 5, '我在世上的时候，是世界的光。”'),
('CNV', '约翰福音', 43, 9, 6, '说了这话，就吐唾沫在地上，用唾沫和了一点泥，把泥抹在瞎子的眼睛上，'),
('CNV', '约翰福音', 43, 9, 7, '对他说：“你去西罗亚池洗一洗吧。”（西罗亚就是“奉差遣”的意思。）于是他就去了，洗完了，走的时候，就看见了。'),
('CNV', '约翰福音', 43, 9, 8, '那时，邻居和以前常常见他讨饭的人说：“这不是那一向坐着讨饭的人吗？”'),
('CNV', '约翰福音', 43, 9, 9, '有的说：“是他。”有的说：“不是他，只是像他。”他自己说：“是我。”'),
('CNV', '约翰福音', 43, 9, 10, '他们就问他：“你的眼睛是怎样开的呢？”'),
('CNV', '约翰福音', 43, 9, 11, '他回答：“那名叫耶稣的人和了一点泥，抹在我的眼上，对我说：‘你去西罗亚池洗一洗吧。’我去一洗，就看见了。”'),
('CNV', '约翰福音', 43, 9, 12, '他们说：“那人在哪里？”他说：“我不知道。”'),
('CNV', '约翰福音', 43, 9, 13, '他们就把那个从前瞎眼的人带到法利赛人那里。'),
('CNV', '约翰福音', 43, 9, 14, '耶稣和了泥开他眼睛的那一天，正是安息日。'),
('CNV', '约翰福音', 43, 9, 15, '法利赛人又问他是怎样可以看见的。他告诉他们：“耶稣把泥抹在我的眼上，我一洗就看见了。”'),
('CNV', '约翰福音', 43, 9, 16, '有几个法利赛人说：“那个人不是从神那里来的，因为他不守安息日。”另外有些人说：“一个罪人怎能行这样的神迹呢？”他们就起了纷争。'),
('CNV', '约翰福音', 43, 9, 17, '他们再对瞎子说：“他既然开了你的眼睛，你说他是什么人？”他说：“他是个先知。”'),
('CNV', '约翰福音', 43, 9, 18, '犹太人不信他从前是瞎眼，现在才能看见的，于是把他的父母叫来，'),
('CNV', '约翰福音', 43, 9, 19, '问他们：“这是你们所说那生下来就瞎眼的儿子吗？现在他怎么又能看见呢？”'),
('CNV', '约翰福音', 43, 9, 20, '他的父母回答：“我们知道他是我们的儿子，生下来就瞎眼；'),
('CNV', '约翰福音', 43, 9, 21, '现在他是怎样可以看见的，我们不知道；谁开了他的眼睛，我们也不知道。你们问他吧；他已经长大成人，可以替自己讲话了。”'),
('CNV', '约翰福音', 43, 9, 22, '他的父母这样说，是因为怕犹太人，原来犹太人已经定好了，不论谁承认耶稣是基督，就要把那人赶出会堂。'),
('CNV', '约翰福音', 43, 9, 23, '因此他的父母说：“他已经长大成人，你们问他吧。”'),
('CNV', '约翰福音', 43, 9, 24, '于是法利赛人第二次把那从前瞎眼的人叫来，对他说：“你应当归荣耀给神，我们知道这人是个罪人。”'),
('CNV', '约翰福音', 43, 9, 25, '那人回答：“他是不是个罪人，我不知道；我只知道一件事，就是我本来是瞎眼的，现在能看见了。”'),
('CNV', '约翰福音', 43, 9, 26, '他们就问：“他向你作了什么呢？他怎样开了你的眼睛呢？”'),
('CNV', '约翰福音', 43, 9, 27, '他回答：“我已经告诉你们，但是你们不听；为什么现在又想听呢？你们也想成为他的门徒吗？”'),
('CNV', '约翰福音', 43, 9, 28, '他们就骂他，说：“你才是他的门徒，我们是摩西的门徒。'),
('CNV', '约翰福音', 43, 9, 29, '我们知道神曾对摩西说话；只是这个人，我们不知道他从哪里来。”'),
('CNV', '约翰福音', 43, 9, 30, '那人对他们说：“这就奇怪了，他开了我的眼睛，你们竟然不知道他从哪里来。'),
('CNV', '约翰福音', 43, 9, 31, '我们知道神不听罪人的祈求，只听那敬畏神，遵行他旨意的人。'),
('CNV', '约翰福音', 43, 9, 32, '自古以来，没有人听过生下来就是瞎眼的，有人可以开他们的眼睛。'),
('CNV', '约翰福音', 43, 9, 33, '这人若不是从神那里来的，他就不能作什么。”'),
('CNV', '约翰福音', 43, 9, 34, '他们说：“你的确是在罪中生的，还敢教训我们吗？”就把他赶出去。'),
('CNV', '约翰福音', 43, 9, 35, '耶稣听见他们把他赶出去，后来遇见他的时候，就对他说：“你信人子吗？”'),
('CNV', '约翰福音', 43, 9, 36, '他说：“先生，谁是人子，好让我信他呢？”'),
('CNV', '约翰福音', 43, 9, 37, '耶稣说：“你已经见过他，现在跟你说话的就是他。”'),
('CNV', '约翰福音', 43, 9, 38, '那人说：“主啊，我信。”就向他下拜。'),
('CNV', '约翰福音', 43, 9, 39, '耶稣说：“我到这世上来是为了审判，使那看不见的能够看见，能看见的反而成了瞎眼的。”'),
('CNV', '约翰福音', 43, 9, 40, '有些和耶稣在一起的法利赛人听了这话，就说：“难道我们也是瞎眼的吗？”'),
('CNV', '约翰福音', 43, 9, 41, '耶稣对他们说：“如果你们是瞎眼的，就没有罪了；但现在你们说‘我们能看见’，所以你们还是有罪的。”'),
('CNV', '约翰福音', 43, 10, 1, '“我实实在在告诉你们，那不从门进羊圈，倒从别处爬进去的，那人就是贼，就是强盗；'),
('CNV', '约翰福音', 43, 10, 2, '那从门进去的，才是羊的牧人。'),
('CNV', '约翰福音', 43, 10, 3, '看门的给他开门，羊也听他的声音；他按著名字呼叫自己的羊，领它们出来。'),
('CNV', '约翰福音', 43, 10, 4, '他把自己的羊全都领出来以后，就走在前头，羊也跟随他，因为认得他的声音。'),
('CNV', '约翰福音', 43, 10, 5, '它们决不会跟随陌生人，反而逃避他，因为不认得陌生人的声音。”'),
('CNV', '约翰福音', 43, 10, 6, '耶稣对他们说了这个譬喻，他们却不明白他所说的是什么。'),
('CNV', '约翰福音', 43, 10, 7, '于是耶稣又说：“我实实在在告诉你们，我就是羊的门。'),
('CNV', '约翰福音', 43, 10, 8, '所有在我以先来的，都是贼和强盗；羊却不听从他们。'),
('CNV', '约翰福音', 43, 10, 9, '我就是门，如果有人藉着我进来，就必定得救，并且可以出、可以入，也可以找到草场。'),
('CNV', '约翰福音', 43, 10, 10, '贼来了，不过是要偷窃、杀害、毁坏；我来了，是要使羊得生命，并且得的更丰盛。'),
('CNV', '约翰福音', 43, 10, 11, '我是好牧人，好牧人为羊舍命。'),
('CNV', '约翰福音', 43, 10, 12, '那作雇工不是牧人的，羊也不是自己的，他一见狼来，就把羊撇下逃跑，狼就抓住羊群，把他们驱散了；'),
('CNV', '约翰福音', 43, 10, 13, '因为他是个雇工，对羊群漠不关心。'),
('CNV', '约翰福音', 43, 10, 14, '我是好牧人，我认识我的羊，我的羊也认识我，'),
('CNV', '约翰福音', 43, 10, 15, '好像父认识我，我也认识父一样；并且我为羊舍命。'),
('CNV', '约翰福音', 43, 10, 16, '我还有别的羊，不在这羊圈里；我必须把它们领来，它们也要听我的声音，并且要合成一群，归于一个牧人。'),
('CNV', '约翰福音', 43, 10, 17, '父爱我，因为我把生命舍去，好再把它取回来。'),
('CNV', '约翰福音', 43, 10, 18, '没有人能夺去我的生命，是我自己舍去的。我有权把生命舍去，也有权把它取回来；这是我从我的父所领受的命令。”'),
('CNV', '约翰福音', 43, 10, 19, '犹太人因着这些话又起了纷争。'),
('CNV', '约翰福音', 43, 10, 20, '他们当中有许多人说：“他是鬼附的，他发疯了；为什么要听他呢？”'),
('CNV', '约翰福音', 43, 10, 21, '另外有人说：“这话不是鬼附的人所说的。鬼怎能使瞎子的眼睛开了呢？”'),
('CNV', '约翰福音', 43, 10, 22, '在耶路撒冷，献殿节到了，那时是冬天。'),
('CNV', '约翰福音', 43, 10, 23, '耶稣在殿的所罗门廊上走过，'),
('CNV', '约翰福音', 43, 10, 24, '犹太人围着他，对他说：“你使我们心里悬疑不定，要到几时呢？如果你是基督，就公开地告诉我们吧！”'),
('CNV', '约翰福音', 43, 10, 25, '耶稣对他们说：“我已经告诉你们，你们却不相信；我奉我父的名所作的事，可以为我作证。'),
('CNV', '约翰福音', 43, 10, 26, '只是你们不信，因为你们不是我的羊。'),
('CNV', '约翰福音', 43, 10, 27, '我的羊听我的声音，我也认识他们，他们也跟随我。'),
('CNV', '约翰福音', 43, 10, 28, '我赐给他们永生，他们永不灭亡，谁也不能把他们从我手里夺去。'),
('CNV', '约翰福音', 43, 10, 29, '那位把羊群赐给我的父比一切都大，也没有人能把他们从我父的手里夺去。'),
('CNV', '约翰福音', 43, 10, 30, '我与父原为一。”'),
('CNV', '约翰福音', 43, 10, 31, '犹太人又拿起石头要打他。'),
('CNV', '约翰福音', 43, 10, 32, '耶稣对他们说：“我把许多从父那里来的善事显给你们看，你们因哪一件要用石头打我呢？”'),
('CNV', '约翰福音', 43, 10, 33, '犹太人对他说：“我们不是因为善事用石头打你，而是因为你说了僭妄的话；又因为你是个人，竟然把自己当作神。”'),
('CNV', '约翰福音', 43, 10, 34, '耶稣说：“你们的律法上不是写着‘我说你们是神’吗？'),
('CNV', '约翰福音', 43, 10, 35, '圣经是不能废除的，如果那些承受神的道的人，神尚且称他们是神，'),
('CNV', '约翰福音', 43, 10, 36, '那么父所分别为圣又差到世上来的，他自称是神的儿子，你们就说他说了僭妄神的话吗？'),
('CNV', '约翰福音', 43, 10, 37, '我若不作我父的事，你们就不必信我；'),
('CNV', '约翰福音', 43, 10, 38, '我若作了，你们纵然不信我，也应当信这些事，好使你们确实知道，我父是在我里面，我也在父里面。”'),
('CNV', '约翰福音', 43, 10, 39, '他们又要逮捕耶稣，他却从他们的手中逃脱了。'),
('CNV', '约翰福音', 43, 10, 40, '耶稣又往约旦河东去，到约翰从前施洗的地方，住在那里。'),
('CNV', '约翰福音', 43, 10, 41, '许多人到他那里去，说：“约翰没有行过一件神迹，但约翰指着这人所说的一切话，都是真实的。”'),
('CNV', '约翰福音', 43, 10, 42, '在那里就有许多人信了耶稣。'),
('CNV', '约翰福音', 43, 11, 1, '有一个患病的人，名叫拉撒路，住在伯大尼，就是马利亚和她姊姊马大的村庄。'),
('CNV', '约翰福音', 43, 11, 2, '这马利亚就是后来用香膏抹主，并且用头发把主的脚擦干的那人；患病的拉撒路是她的兄弟。'),
('CNV', '约翰福音', 43, 11, 3, '姊妹二人派人到耶稣那里去，说：“主啊，你所爱的人病了。”'),
('CNV', '约翰福音', 43, 11, 4, '耶稣听见，就说：“这病不至于死，而是为了神的荣耀，使神的儿子因此得到荣耀。”'),
('CNV', '约翰福音', 43, 11, 5, '耶稣向来爱马大和她的妹妹马利亚，以及拉撒路。'),
('CNV', '约翰福音', 43, 11, 6, '他听说拉撒路病了，仍然在原来的地方住了两天，'),
('CNV', '约翰福音', 43, 11, 7, '然后对门徒说：“我们再到犹太去吧。”'),
('CNV', '约翰福音', 43, 11, 8, '门徒对他说：“拉比，近来犹太人要拿石头打你，你还到那里去吗？”'),
('CNV', '约翰福音', 43, 11, 9, '耶稣说：“白昼不是有十二小时吗？人若在白昼行走，就不会跌倒，因为他看见这世上的光；'),
('CNV', '约翰福音', 43, 11, 10, '人若在夜间行走，就会跌倒，因为他没有光。”'),
('CNV', '约翰福音', 43, 11, 11, '耶稣说完了这些话，跟着又对他们说：“我们的朋友拉撒路睡了，我要去唤醒他。”'),
('CNV', '约翰福音', 43, 11, 12, '门徒说：“主啊，如果他睡了，就会好过来的。”'),
('CNV', '约翰福音', 43, 11, 13, '其实耶稣是指着拉撒路的死说的，门徒却以为他是指正常的睡眠说的。'),
('CNV', '约翰福音', 43, 11, 14, '于是，耶稣公开地告诉他们：“拉撒路死了。'),
('CNV', '约翰福音', 43, 11, 15, '我为你们欢喜，因为我不在那里，是要使你们相信。现在我们到他那里去吧。”'),
('CNV', '约翰福音', 43, 11, 16, '那称为“双生子”（“双生子”原文作“低土马”）的多马，对其他的门徒说：“我们也去跟他一同死吧！”'),
('CNV', '约翰福音', 43, 11, 17, '耶稣到了，知道拉撒路在坟墓里已经四天了。'),
('CNV', '约翰福音', 43, 11, 18, '伯大尼靠近耶路撒冷，相距约有三公里。'),
('CNV', '约翰福音', 43, 11, 19, '有许多犹太人来到马大和马利亚那里，为了拉撒路的死来安慰她们。'),
('CNV', '约翰福音', 43, 11, 20, '马大听见耶稣来了，就去迎接他，马利亚却仍然坐在家里。'),
('CNV', '约翰福音', 43, 11, 21, '马大对耶稣说：“主啊，如果你早在这里，我的兄弟就不会死了！'),
('CNV', '约翰福音', 43, 11, 22, '就是现在，我也知道无论你向神求什么，神必赐给你。”'),
('CNV', '约翰福音', 43, 11, 23, '耶稣对她说：“你的兄弟必会复活。”'),
('CNV', '约翰福音', 43, 11, 24, '马大说：“我知道在末日复活的时候，他必会复活。”'),
('CNV', '约翰福音', 43, 11, 25, '耶稣说：“我就是复活和生命；信我的人，虽然死了，也要活着。'),
('CNV', '约翰福音', 43, 11, 26, '所有活着又信我的人，必定永远不死，你信这话吗？”'),
('CNV', '约翰福音', 43, 11, 27, '她说：“主啊，我信；我已经信了，你是基督，是神的儿子，是那要到世上来的。”'),
('CNV', '约翰福音', 43, 11, 28, '马大说了这些话，就回去叫她妹妹马利亚，暗暗地说：“老师来了，他叫你。”'),
('CNV', '约翰福音', 43, 11, 29, '马利亚一听见，就急忙起来，到耶稣那里去。'),
('CNV', '约翰福音', 43, 11, 30, '那时，耶稣还没有进入村子，仍然在马大迎接他的地方。'),
('CNV', '约翰福音', 43, 11, 31, '那些在房子里和马利亚在一起安慰她的犹太人，见她匆忙地起来出去，就跟着她，以为她要到坟墓那里去哭。'),
('CNV', '约翰福音', 43, 11, 32, '马利亚来到耶稣那里，一看见他，就俯伏在他脚前，说：“主啊，如果你早在这里，我的兄弟就不会死了！”'),
('CNV', '约翰福音', 43, 11, 33, '耶稣看见她在哭，和她一同来的犹太人也在哭，就心里激动，难过起来，'),
('CNV', '约翰福音', 43, 11, 34, '说：“你们把他安放在哪里？”他们说：“主啊，请来看。”'),
('CNV', '约翰福音', 43, 11, 35, '耶稣哭了。'),
('CNV', '约翰福音', 43, 11, 36, '于是犹太人说：“你看，他多么爱这个人！”'),
('CNV', '约翰福音', 43, 11, 37, '他们中间有人说：“他既然开了瞎子的眼睛，难道不能使这个人不死吗？”'),
('CNV', '约翰福音', 43, 11, 38, '耶稣又再心里激动，来到坟墓前面。那坟墓是一个洞穴，洞口有块石头堵住。'),
('CNV', '约翰福音', 43, 11, 39, '耶稣说：“把这块石头挪开！”死者的姊姊马大对他说：“主啊，已经四天了，他必定臭了。”'),
('CNV', '约翰福音', 43, 11, 40, '耶稣说：“我不是对你说过‘如果你信，就必定看见神的荣耀’吗？”'),
('CNV', '约翰福音', 43, 11, 41, '于是他们把石头挪开。耶稣举目向天，说：“父啊，我感谢你，因为你垂听了我，'),
('CNV', '约翰福音', 43, 11, 42, '我知道你常常听我，但我说这话，是为了周围站着的群众，叫他们信是你差了我来。”'),
('CNV', '约翰福音', 43, 11, 43, '说了这话，就大声呼喊：“拉撒路，出来！”'),
('CNV', '约翰福音', 43, 11, 44, '那死了的人就出来，他的手脚都缠着布，脸上裹着巾。耶稣说：“解开他，让他走！”'),
('CNV', '约翰福音', 43, 11, 45, '有许多到马利亚那里去的犹太人，看见了耶稣所作的事，就信了他。'),
('CNV', '约翰福音', 43, 11, 46, '但他们中间有些人到法利赛人那里去，把耶稣所作的事都告诉他们。'),
('CNV', '约翰福音', 43, 11, 47, '于是祭司长和法利赛人召开公议会，说：“这个人行了许多神迹，我们怎么办呢？'),
('CNV', '约翰福音', 43, 11, 48, '我们若让他这样，所有的人都会信他，罗马人就会来，夺取我们的圣地，除灭我们的民族。”'),
('CNV', '约翰福音', 43, 11, 49, '他们当中有一位该亚法，是那年作大祭司的，对他们说：“你们什么都不知道，'),
('CNV', '约翰福音', 43, 11, 50, '也不去想想，一个人代替人民死，免得整个民族灭亡，这对你们是有益的。”'),
('CNV', '约翰福音', 43, 11, 51, '他说这话不是由于自己，而是因为他是那年的大祭司，所以预言耶稣要替犹太民族死；'),
('CNV', '约翰福音', 43, 11, 52, '不但替犹太民族死，也要把散居各地的神的儿女招聚成为一体。'),
('CNV', '约翰福音', 43, 11, 53, '从那天起，他们就想杀害耶稣。'),
('CNV', '约翰福音', 43, 11, 54, '因此，耶稣不再在犹太人中间公开活动，却离开那里，到旷野附近的地方去；到了一座名叫以法莲的城，就和门徒住在那里。'),
('CNV', '约翰福音', 43, 11, 55, '犹太人的逾越节快到了，有许多人在过节前从各乡上耶路撒冷去，要在那里洁净自己。'),
('CNV', '约翰福音', 43, 11, 56, '他们到处寻找耶稣，站在圣殿里的时候，彼此说：“你们认为怎样？他不会来过节吧？”'),
('CNV', '约翰福音', 43, 11, 57, '祭司长和法利赛人早已下了命令：如果有人知道耶稣在哪里，就要前来报告，好去逮捕他。'),
('CNV', '约翰福音', 43, 12, 1, '逾越节前六天，耶稣到了伯大尼，就是拉撒路所住的地方；耶稣曾经使这拉撒路从死人中复活。'),
('CNV', '约翰福音', 43, 12, 2, '有人在那里为耶稣预备了筵席。马大在那里侍候，拉撒路也和一些人与耶稣一同吃饭。'),
('CNV', '约翰福音', 43, 12, 3, '马利亚拿了半公斤珍贵纯正的哪哒香膏，抹耶稣的脚，又用自己的头发去擦；屋里就满了香膏的香气。'),
('CNV', '约翰福音', 43, 12, 4, '耶稣的一个门徒，就是那要出卖他的加略人犹大，说：'),
('CNV', '约翰福音', 43, 12, 5, '“为什么不把这香膏卖三百银币，周济穷人呢？”'),
('CNV', '约翰福音', 43, 12, 6, '他说这话，并不是因为他关怀穷人，而是因为他是个贼，又带着钱囊，常取其中所存的。'),
('CNV', '约翰福音', 43, 12, 7, '耶稣就说：“由她吧，这香膏是她留下来为我安葬的日子用的。'),
('CNV', '约翰福音', 43, 12, 8, '你们常常有穷人跟你们在一起，却不常有我。”'),
('CNV', '约翰福音', 43, 12, 9, '有一大群犹太人知道耶稣在那里，就都来了，然而他们不单是为了耶稣的缘故，也是要看看耶稣使他从死人中复活的拉撒路。'),
('CNV', '约翰福音', 43, 12, 10, '于是祭司长想把拉撒路也杀掉，'),
('CNV', '约翰福音', 43, 12, 11, '因为有许多犹太人为了拉撒路的缘故，离开他们，信了耶稣。'),
('CNV', '约翰福音', 43, 12, 12, '第二天，有一大群上来过节的人，听见耶稣要来耶路撒冷，'),
('CNV', '约翰福音', 43, 12, 13, '就拿着棕树枝出去迎接他，欢呼说：“和散那，奉主名来的以色列王，是应当称颂的！”'),
('CNV', '约翰福音', 43, 12, 14, '耶稣找到一头小驴，就骑在上面，正如经上所记的：'),
('CNV', '约翰福音', 43, 12, 15, '“锡安的居民哪，不要惧怕；看哪，你的王来了，他骑着小驴来了。”'),
('CNV', '约翰福音', 43, 12, 16, '门徒起初不明白这些事，可是到耶稣得了荣耀以后，他们才想起这些话是指着他说的，并且人们果然向他这样行了。'),
('CNV', '约翰福音', 43, 12, 17, '那些和耶稣在一起，看见他叫拉撒路从坟墓出来，又使他从死人中复活的群众，都为这事作见证。'),
('CNV', '约翰福音', 43, 12, 18, '群众因为听见他行了这神迹，就去迎接他。'),
('CNV', '约翰福音', 43, 12, 19, '于是法利赛人彼此说：“你们看，你们都是徒劳无功，世人都去跟随他了！”'),
('CNV', '约翰福音', 43, 12, 20, '上去过节作礼拜的人中，有些是希腊人。'),
('CNV', '约翰福音', 43, 12, 21, '他们来到加利利的伯赛大人腓力那里，请求他，说：“先生，我们想见耶稣。”'),
('CNV', '约翰福音', 43, 12, 22, '腓力去告诉安得烈，安得烈就和腓力去告诉耶稣。'),
('CNV', '约翰福音', 43, 12, 23, '耶稣对他们说：“人子得荣耀的时候到了！'),
('CNV', '约翰福音', 43, 12, 24, '我实实在在告诉你们，一粒麦子若不落在地里死了，仍旧是一粒；如果死了，就结出许多果实来。'),
('CNV', '约翰福音', 43, 12, 25, '爱惜自己生命的，就丧掉生命；在这世上恨恶自己生命的，必会保全生命到永远。'),
('CNV', '约翰福音', 43, 12, 26, '如果有人服事我，就应当跟从我；我在哪里，服事我的人也会在哪里；如果有人服事我，我父必尊重他。'),
('CNV', '约翰福音', 43, 12, 27, '“我现在心里烦乱，我应该说什么呢？说‘父啊，救我脱离这时刻’吗？然而我正是为了这个缘故来的，要面对这时刻。'),
('CNV', '约翰福音', 43, 12, 28, '父啊，愿你荣耀你的名！”当时有声音从天上来，说：“我已经荣耀了我的名，还要再荣耀。”'),
('CNV', '约翰福音', 43, 12, 29, '站在旁边的群众听见了，就说：“打雷了。”另外有人说：“有天使对他说话。”'),
('CNV', '约翰福音', 43, 12, 30, '耶稣说：“这声音不是为了我，而是为了你们发出的。'),
('CNV', '约翰福音', 43, 12, 31, '现在是这世界受审判的时候了，现在这世界的王要被赶出去。'),
('CNV', '约翰福音', 43, 12, 32, '我若从地上被举起来，就要吸引万人归向我。”'),
('CNV', '约翰福音', 43, 12, 33, '他说这话，是指着自己将要怎样死说的。'),
('CNV', '约翰福音', 43, 12, 34, '于是群众对他说：“我们从律法上知道基督是永远常存的，你怎么说‘人子必须被举起来’呢？这人子是谁呢？”'),
('CNV', '约翰福音', 43, 12, 35, '耶稣说：“光在你们中间的时间不多了。你们应当趁着有光的时候行走，免得黑暗追上你们。在黑暗中行走的人，不知道往哪里去。'),
('CNV', '约翰福音', 43, 12, 36, '你们应当趁着有光的时候信从这光，使你们成为光明的儿女。”耶稣说完了这些话，就离开他们隐藏起来。'),
('CNV', '约翰福音', 43, 12, 37, '耶稣在他们面前行了许多神迹，但是他们仍然不信他。'),
('CNV', '约翰福音', 43, 12, 38, '这是要应验以赛亚先知所说的话：“主啊，我们所传的，有谁信呢？主的膀臂向谁显露呢？”'),
('CNV', '约翰福音', 43, 12, 39, '他们不能相信，因为以赛亚又说：'),
('CNV', '约翰福音', 43, 12, 40, '“神使他们瞎了眼，硬了心，免得他们眼睛看见，心里明白而回转过来；我就医好他们。”'),
('CNV', '约翰福音', 43, 12, 41, '以赛亚说这些话，是因为看见了他的荣耀，就指着他说的。'),
('CNV', '约翰福音', 43, 12, 42, '虽然这样，官长当中也有许多人信了耶稣。但是因为法利赛人的缘故，他们不敢公开承认，免得被赶出会堂；'),
('CNV', '约翰福音', 43, 12, 43, '因为他们爱来自人的荣耀，过于爱来自神的荣耀。'),
('CNV', '约翰福音', 43, 12, 44, '耶稣大声说：“信我的，不单是信我，也是信那差我来的。'),
('CNV', '约翰福音', 43, 12, 45, '看见我的，就是看见那差我来的。'),
('CNV', '约翰福音', 43, 12, 46, '我是光，我到世上来，叫所有信我的不住在黑暗里。'),
('CNV', '约翰福音', 43, 12, 47, '人若听见我的话却不遵守的，我不审判他，因为我来不是要审判世人，而是要拯救世人。'),
('CNV', '约翰福音', 43, 12, 48, '弃绝我又不接受我的话的人，自有审判他的。我所讲的道在末日要定他的罪；'),
('CNV', '约翰福音', 43, 12, 49, '因为我没有凭着自己说话，而是差我来的父给了我命令，要我说什么，讲什么。'),
('CNV', '约翰福音', 43, 12, 50, '我知道他的命令就是永生。所以，我所讲的，正是父吩咐我要我讲的。”'),
('CNV', '约翰福音', 43, 13, 1, '逾越节以前，耶稣知道自己离开这世界回到父那里去的时候到了。他既然爱世上属于自己的人，就爱他们到底。'),
('CNV', '约翰福音', 43, 13, 2, '吃晚饭的时候（魔鬼已经把出卖耶稣的意念放在西门的儿子加略人犹大的心里），'),
('CNV', '约翰福音', 43, 13, 3, '耶稣知道父已经把万有交在他手中，并且知道自己从神而来，又要回到神那里去，'),
('CNV', '约翰福音', 43, 13, 4, '就起身离席，脱去外衣，拿一条手巾束腰。'),
('CNV', '约翰福音', 43, 13, 5, '然后他倒了一盆水，洗门徒的脚，并且用束腰的手巾擦干。'),
('CNV', '约翰福音', 43, 13, 6, '轮到西门．彼得，彼得就说：“主啊，你要洗我的脚吗？”'),
('CNV', '约翰福音', 43, 13, 7, '耶稣回答：“我所作的，你现在不知道，以后就会明白。”'),
('CNV', '约翰福音', 43, 13, 8, '彼得说：“不行，你千万不可洗我的脚！”耶稣说：“如果我不洗你，你就与我没有关系了。”'),
('CNV', '约翰福音', 43, 13, 9, '西门．彼得说：“主啊，那就不单洗我的脚，连我的手和头都洗吧！”'),
('CNV', '约翰福音', 43, 13, 10, '耶稣说：“洗过澡的人，全身都洁净，只需要洗脚就可以了。你们是洁净的，但不是人人都是这样。”'),
('CNV', '约翰福音', 43, 13, 11, '原来耶稣知道谁要出卖他，所以他说“你们不是人人都是洁净的”。'),
('CNV', '约翰福音', 43, 13, 12, '耶稣洗完了门徒的脚，就穿上外衣，再坐下来，对他们说：“我给你们作的，你们明白吗？'),
('CNV', '约翰福音', 43, 13, 13, '你们称呼我‘老师，主’，你们说得对，我本来就是。'),
('CNV', '约翰福音', 43, 13, 14, '我是主，是老师，尚且洗你们的脚，你们也应当彼此洗脚。'),
('CNV', '约翰福音', 43, 13, 15, '我作了你们的榜样，是要你们也照着我所作的去行。'),
('CNV', '约翰福音', 43, 13, 16, '我实实在在告诉你们，仆人不能大过主人，奉差遣的也不能大过差他的人。'),
('CNV', '约翰福音', 43, 13, 17, '你们既然知道这些事，如果去实行，就有福了。'),
('CNV', '约翰福音', 43, 13, 18, '我这话不是指着你们全体说的；我认识我所拣选的人，但是经上的话：‘那吃我饭的，用他的脚踢我’，必须应验。'),
('CNV', '约翰福音', 43, 13, 19, '现在，事情还没有发生，我就告诉你们，使你们到时可以信我就是‘那一位’。'),
('CNV', '约翰福音', 43, 13, 20, '我实实在在告诉你们，那接待我所差遣的，就是接待我；接待我的，就是接待那差我来的。”'),
('CNV', '约翰福音', 43, 13, 21, '耶稣说了这话，心里很难过，就明明地说：“我实实在在告诉你们，你们中间有一个人要出卖我。”'),
('CNV', '约翰福音', 43, 13, 22, '门徒面面相看，不知道他是指着谁说的。'),
('CNV', '约翰福音', 43, 13, 23, '门徒中有一个人，是耶稣所爱的，侧身挨近耶稣（“侧身挨近耶稣”原文作“在耶稣的胸怀里”）。'),
('CNV', '约翰福音', 43, 13, 24, '西门．彼得向他示意，叫他问耶稣是指着谁说的。'),
('CNV', '约翰福音', 43, 13, 25, '于是那个门徒贴近耶稣的胸怀，问他：“主啊，是谁呢？”'),
('CNV', '约翰福音', 43, 13, 26, '耶稣回答：“我蘸一小块饼给谁，谁就是了。”于是他蘸了一小块饼，递给加略人西门的儿子犹大。'),
('CNV', '约翰福音', 43, 13, 27, '犹大接过饼以后，撒但就进入他的心。耶稣对他说：“你要作的，快去作吧。”'),
('CNV', '约翰福音', 43, 13, 28, '在座的人，没有一个知道耶稣为什么对犹大说这话。'),
('CNV', '约翰福音', 43, 13, 29, '犹大是管钱的，所以有人以为耶稣叫他去买过节用的东西，或是吩咐他拿点东西去周济穷人。'),
('CNV', '约翰福音', 43, 13, 30, '犹大吃了饼，立刻就出去；那时是黑夜了。'),
('CNV', '约翰福音', 43, 13, 31, '他出去以后，耶稣就说：“现在人子得了荣耀，神也在人子身上得了荣耀，'),
('CNV', '约翰福音', 43, 13, 32, '（神既然在人子身上得了荣耀，）（有些抄本无此句）也要在自己身上荣耀人子，并且要立刻荣耀他。'),
('CNV', '约翰福音', 43, 13, 33, '孩子们啊，我跟你们在一起的时候不多了。你们要寻找我，但是我对犹太人说过，现在也照样对你们说：‘我去的地方，是你们不能去的。’'),
('CNV', '约翰福音', 43, 13, 34, '我给你们一条新命令，就是要你们彼此相爱；我怎样爱你们，你们也要怎样彼此相爱。'),
('CNV', '约翰福音', 43, 13, 35, '如果你们彼此相爱，众人就会认出你们是我的门徒了。”'),
('CNV', '约翰福音', 43, 13, 36, '西门．彼得对耶稣说：“主啊，你往哪里去？”耶稣回答：“我去的地方，你现在不能跟着我去，但后来却要跟着我去。”'),
('CNV', '约翰福音', 43, 13, 37, '彼得说：“主啊，为什么我现在不能跟着你去？为了你，我舍命也愿意！”'),
('CNV', '约翰福音', 43, 13, 38, '耶稣说：“你愿意为我舍命吗？我实实在在告诉你，鸡叫之前，你必定三次不认我。”'),
('CNV', '约翰福音', 43, 14, 1, '“你们心里不要难过，你们应当信神，也应当信我。'),
('CNV', '约翰福音', 43, 14, 2, '在我父的家里，有许多住的地方；如果没有，我怎么会告诉你们我去是要为你们预备地方呢？（下半节或译：“如果没有，我早就对你们说了，因为我去是为你们预备地方。”）'),
('CNV', '约翰福音', 43, 14, 3, '我若去为你们预备地方，就必再来接你们到我那里去，好使我在哪里，你们也在哪里。'),
('CNV', '约翰福音', 43, 14, 4, '我去的地方，你们知道那条路。”'),
('CNV', '约翰福音', 43, 14, 5, '多马说：“主啊，我们不知道你去的地方，怎能知道那条路呢？”'),
('CNV', '约翰福音', 43, 14, 6, '耶稣对他说：“我就是道路、真理、生命，如果不是藉着我，没有人能到父那里去。'),
('CNV', '约翰福音', 43, 14, 7, '如果你们认识我，就必认识我的父；从今以后，你们认识他，并且看见了他。”'),
('CNV', '约翰福音', 43, 14, 8, '腓力说：“主啊，请把父显示给我们，我们就满足了。”'),
('CNV', '约翰福音', 43, 14, 9, '耶稣说：“腓力，我跟你们在一起这么久了，你还不认识我吗？那看见了我的就是看见了父，你怎么还说‘把父显示给我们’呢？'),
('CNV', '约翰福音', 43, 14, 10, '你不信我是在父里面，父是在我里面吗？我对你们说的话，不是凭着自己说的，而是住在我里面的父作他自己的事。'),
('CNV', '约翰福音', 43, 14, 11, '你们应当信我是在父里面，父是在我里面；不然，也要因我所作的而相信。'),
('CNV', '约翰福音', 43, 14, 12, '我实实在在告诉你们，我所作的事，信我的人也要作，并且要作比这些更大的，因为我往父那里去。'),
('CNV', '约翰福音', 43, 14, 13, '你们奉我的名无论求什么，我必定成全，使父在子的身上得着荣耀。'),
('CNV', '约翰福音', 43, 14, 14, '你们若奉我的名向我求什么，我必定成全。'),
('CNV', '约翰福音', 43, 14, 15, '“如果你们爱我，就要遵守我的命令。'),
('CNV', '约翰福音', 43, 14, 16, '我要请求父，他就会赐给你们另一位保惠师，使他跟你们永远在一起。'),
('CNV', '约翰福音', 43, 14, 17, '这保惠师就是真理的灵，世人不能接受他，因为看不见他，也不认识他。你们却认识他，因为他跟你们住在一起，也要在你们里面。'),
('CNV', '约翰福音', 43, 14, 18, '我不会撇下你们为孤儿，我要回到你们这里来。'),
('CNV', '约翰福音', 43, 14, 19, '不久以后，世人不再看见我，你们却要看见我，因为我活着，你们也要活着。'),
('CNV', '约翰福音', 43, 14, 20, '到那日，你们就知道我是在我父里面，你们是在我里面，我也在你们里面。'),
('CNV', '约翰福音', 43, 14, 21, '那领受我的命令，并且遵守的，就是爱我的；爱我的，我父必定爱他，我也要爱他，并且要亲自向他显现。”'),
('CNV', '约翰福音', 43, 14, 22, '犹大（不是加略人犹大）对耶稣说：“主啊，你为什么要亲自向我们显现，不向世人显现呢？”'),
('CNV', '约翰福音', 43, 14, 23, '耶稣回答：“人若爱我，就要遵守我的话，我父必定爱他，并且我们要到他那里去，跟他住在一起。'),
('CNV', '约翰福音', 43, 14, 24, '不爱我的，就不会遵守我的话。你们所听见的道，不是我的，而是那差我来的父的道。'),
('CNV', '约翰福音', 43, 14, 25, '“我还跟你们在一起的时候，就对你们讲了这些事。'),
('CNV', '约翰福音', 43, 14, 26, '但保惠师，就是父因我的名要差来的圣灵，他要把一切事教导你们，也要使你们想起我对你们所说过的一切话。'),
('CNV', '约翰福音', 43, 14, 27, '我留下平安给你们，我把自己的平安赐给你们；我给你们的，不像世界所给的。你们心里不要难过，也不要恐惧。'),
('CNV', '约翰福音', 43, 14, 28, '你们听见我对你们说过：‘我去，但还要回到你们这里来。’你们若爱我，就要喜乐，因为我到父那里去，又因为父是比我大的。'),
('CNV', '约翰福音', 43, 14, 29, '现在事情还没有发生，我就已经告诉你们，使你们在事情发生的时候可以相信。'),
('CNV', '约翰福音', 43, 14, 30, '我不会再跟你们讲很多的事，因为这世界的统治者将到；他在我身上毫无作用，'),
('CNV', '约翰福音', 43, 14, 31, '但这些事是要使世人知道我爱父，并且知道父怎样吩咐了我，我就怎样作。起来，我们走吧！”'),
('CNV', '约翰福音', 43, 15, 1, '“我是真葡萄树，我父是培植的人。'),
('CNV', '约翰福音', 43, 15, 2, '所有属我而不结果子的枝子，他就剪去；所有结果子的，他就修剪干净，让它结更多的果子。'),
('CNV', '约翰福音', 43, 15, 3, '现在你们因着我对你们所讲的道，已经干净了。'),
('CNV', '约翰福音', 43, 15, 4, '你们要住在我里面，我也就住在你们里面。枝子若不连在葡萄树上，自己就不能结果子；你们若不住在我里面，也是这样。'),
('CNV', '约翰福音', 43, 15, 5, '我是葡萄树，你们是枝子。住在我里面的，我也住在他里面，他就结出很多果子；因为离开了我，你们就不能作什么。'),
('CNV', '约翰福音', 43, 15, 6, '人若不住在我里面，就像枝子丢在外面枯干了，人把它们拾起来，丢在火里烧掉了。'),
('CNV', '约翰福音', 43, 15, 7, '你们若住在我里面，我的话也留在你们里面；无论你们想要什么，祈求，就给你们成就。'),
('CNV', '约翰福音', 43, 15, 8, '这样，你们结出很多果子，我父就因此得荣耀，你们也就是我的门徒了。'),
('CNV', '约翰福音', 43, 15, 9, '父怎样爱我，我也怎样爱你们；你们要住在我的爱里。'),
('CNV', '约翰福音', 43, 15, 10, '如果你们遵守我的命令，就必定住在我的爱里，正像我遵守了我父的命令，住在他的爱里一样。'),
('CNV', '约翰福音', 43, 15, 11, '“我把这些事告诉了你们，好让我的喜乐存在你们心里，并且使你们的喜乐满溢。'),
('CNV', '约翰福音', 43, 15, 12, '你们要彼此相爱，像我爱你们一样，这就是我的命令。'),
('CNV', '约翰福音', 43, 15, 13, '人为朋友舍命，人间的爱没有比这个更大的了。'),
('CNV', '约翰福音', 43, 15, 14, '你们若行我所吩咐你们的，就是我的朋友了。'),
('CNV', '约翰福音', 43, 15, 15, '我不再称你们为仆人，因为仆人不知道主人所作的事；我已经称你们为朋友了，因为我从我父那里听见的一切，都已经告诉你们了。'),
('CNV', '约翰福音', 43, 15, 16, '不是你们拣选了我，而是我拣选了你们，并且分派你们去结果子，就是结常存的果子，使你们奉我的名，无论向父求什么，他必定赐给你们。'),
('CNV', '约翰福音', 43, 15, 17, '我把这些事吩咐你们，是要你们彼此相爱。'),
('CNV', '约翰福音', 43, 15, 18, '“如果世人恨你们，你们要知道他们在恨你们以先，已经恨我了。'),
('CNV', '约翰福音', 43, 15, 19, '你们若属于这世界，世人必定爱属自己的；但因为你们不属于世界，而是我从世界中拣选了你们，所以世人就恨你们。'),
('CNV', '约翰福音', 43, 15, 20, '你们要记住我对你们说过的话：‘仆人不能大过主人。’他们若迫害我，也必定迫害你们；他们若遵守我的话，也必定遵守你们的话。'),
('CNV', '约翰福音', 43, 15, 21, '但他们因着我的名，要向你们行这一切，因为他们不认识那差我来的。'),
('CNV', '约翰福音', 43, 15, 22, '如果我没有来，也没有对他们讲过什么，他们就没有罪；但现在他们的罪是无可推诿的了。'),
('CNV', '约翰福音', 43, 15, 23, '恨我的，也恨我的父。'),
('CNV', '约翰福音', 43, 15, 24, '如果我没有在他们中间作过别人没有作过的事，他们就没有罪；但现在我和我的父，他们都看见了，也都恨恶。'),
('CNV', '约翰福音', 43, 15, 25, '这就应验了他们律法上所写的话：‘他们无故地恨我。’'),
('CNV', '约翰福音', 43, 15, 26, '“我从父那里要差来给你们的保惠师，就是从父那里出来的真理的灵，他来到的时候，要为我作见证。'),
('CNV', '约翰福音', 43, 15, 27, '你们也要作见证，因为从开始你们就是跟我在一起的。”'),
('CNV', '约翰福音', 43, 16, 1, '“我把这些事告诉了你们，使你们不致后退。'),
('CNV', '约翰福音', 43, 16, 2, '人要把你们赶出会堂；并且时候要到，所有要杀害你们的人，以为这样就是事奉神。'),
('CNV', '约翰福音', 43, 16, 3, '他们要作这些事，因为他们不认识父，也不认识我。'),
('CNV', '约翰福音', 43, 16, 4, '我把这些事告诉了你们，让你们到了那个时候，可以想起我告诉过你们了。“我起初没有把这些事告诉你们，因为我跟你们在一起。'),
('CNV', '约翰福音', 43, 16, 5, '现在我要到那差我来的那里去，你们中间并没有人问：‘你到哪里去？’'),
('CNV', '约翰福音', 43, 16, 6, '然而因为我把这些事告诉了你们，你们心里就充满忧愁。'),
('CNV', '约翰福音', 43, 16, 7, '但我要把实情告诉你们，我去是对你们有益的。如果我不去，保惠师就不会到你们这里来；我若去了，就会差他到你们这里来。'),
('CNV', '约翰福音', 43, 16, 8, '他来了，就要在罪、在义、在审判各方面指证世人的罪。'),
('CNV', '约翰福音', 43, 16, 9, '在罪方面，是因为他们不信我；'),
('CNV', '约翰福音', 43, 16, 10, '在义方面，是因为我到父那里去，你们就再看不见我；'),
('CNV', '约翰福音', 43, 16, 11, '在审判方面，是因为这世界的统治者已经受了审判。'),
('CNV', '约翰福音', 43, 16, 12, '“我还有许多事要告诉你们，可是你们现在担当不了；'),
('CNV', '约翰福音', 43, 16, 13, '只等真理的灵来了，他要引导你们进入一切真理。他不是凭着自己说话，而是把他听见的都说出来，并且要把将来的事告诉你们。'),
('CNV', '约翰福音', 43, 16, 14, '他要荣耀我，因为他要把从我那里所领受的告诉你们。'),
('CNV', '约翰福音', 43, 16, 15, '父所有的一切，都是我的；所以我说，他要把从我那里所领受的告诉你们。'),
('CNV', '约翰福音', 43, 16, 16, '“不久，你们不会再看见我；再过不久，你们还要看见我。”'),
('CNV', '约翰福音', 43, 16, 17, '于是他的门徒中有几个彼此说：“他对我们说：‘不久，你们不会看见我；再过不久，你们还要看见我。’又说：‘因为我到父那里去。’这是什么意思呢？”'),
('CNV', '约翰福音', 43, 16, 18, '他们又说：“他所说的‘不久’，是什么意思呢？我们不晓得他在讲什么。”'),
('CNV', '约翰福音', 43, 16, 19, '耶稣知道他们想问他，就说：“我所说的‘不久，你们不会看见我；再过不久，你们还要看见我’，你们为了这话彼此议论吗？'),
('CNV', '约翰福音', 43, 16, 20, '我实实在在告诉你们，你们要痛哭哀号，世人却要欢喜；你们要忧愁，但你们的忧愁要变为喜乐。'),
('CNV', '约翰福音', 43, 16, 21, '妇人生产的时候会有忧愁，因为她的时候到了；但生了孩子以后，就不再记住那痛苦了，因为欢喜有一个人生到世上来。'),
('CNV', '约翰福音', 43, 16, 22, '现在你们也有忧愁；但我要再见你们，你们的心就会喜乐，你们的喜乐是没有人能够夺去的。'),
('CNV', '约翰福音', 43, 16, 23, '到了那天，你们什么也不会问我了。我实实在在告诉你们，你们奉我的名无论向父求什么，他必定赐给你们。'),
('CNV', '约翰福音', 43, 16, 24, '你们向来没有奉我的名求什么；现在你们祈求，就必定得着，让你们的喜乐满溢。'),
('CNV', '约翰福音', 43, 16, 25, '“我用譬喻对你们说了这些事，时候要到，我不再用譬喻对你们说了，而是把关于父的事明明白白告诉你们。'),
('CNV', '约翰福音', 43, 16, 26, '到了那天，你们要奉我的名祈求，我不是说我要为你们请求父；'),
('CNV', '约翰福音', 43, 16, 27, '父自己爱你们，因为你们已经爱我，并且信我是从神那里来的。'),
('CNV', '约翰福音', 43, 16, 28, '我从父那里来，到了这世界；我又离开这世界，到父那里去。”'),
('CNV', '约翰福音', 43, 16, 29, '门徒说：“你看，现在你是明说，不是用譬喻说了。'),
('CNV', '约翰福音', 43, 16, 30, '现在我们知道你是无所不知的，不需要人向你发问。因此，我们信你是从神那里来的。”'),
('CNV', '约翰福音', 43, 16, 31, '耶稣对他们说：“现在你们信吗？'),
('CNV', '约翰福音', 43, 16, 32, '看哪，时候要到，而且已经到了，你们要分散，各人到自己的地方去，只留下我独自一个人。其实我不是独自一个人，因为有父与我同在。'),
('CNV', '约翰福音', 43, 16, 33, '我把这些事告诉你们，是要使你们在我里面有平安。在世上你们有患难，但你们放心，我已经胜了这世界。”'),
('CNV', '约翰福音', 43, 17, 1, '耶稣讲完了这些话，就举目望天，说：“父啊，时候到了，求你荣耀你的儿子，让儿子也荣耀你，'),
('CNV', '约翰福音', 43, 17, 2, '正如你把管理全人类的权柄给了他，使他赐永生给你所赐给他的人。'),
('CNV', '约翰福音', 43, 17, 3, '认识你是独一的真神，并且认识你所差来的耶稣基督，这就是永生。'),
('CNV', '约翰福音', 43, 17, 4, '我在地上已经荣耀了你，你交给我要作的工，我已经完成了。'),
('CNV', '约翰福音', 43, 17, 5, '父啊，现在让我在你自己面前得着荣耀，就是在创世以前我与你同享的荣耀。'),
('CNV', '约翰福音', 43, 17, 6, '“你从世上分别出来赐给我的人，我已经把你的名显明给他们了。他们是你的，你把他们赐给了我，他们也遵守了你的道。'),
('CNV', '约翰福音', 43, 17, 7, '现在他们知道，你所给我的，无论是什么，都是从你那里来的；'),
('CNV', '约翰福音', 43, 17, 8, '因为你赐给我的话，我已经给了他们，他们也领受了，又确实知道我是从你那里来的，并且信你差了我来。'),
('CNV', '约翰福音', 43, 17, 9, '我为他们求；我不为世人求，而是为你赐给我的人求，因为他们是你的。'),
('CNV', '约翰福音', 43, 17, 10, '我的一切都是你的，你的一切也是我的，并且我因着他们得了荣耀。'),
('CNV', '约翰福音', 43, 17, 11, '我不再在这世上，他们却在这世上，我要到你那里去。圣父啊，求你因你赐给我的名，保守他们，使他们合而为一，好像我们一样。'),
('CNV', '约翰福音', 43, 17, 12, '我跟他们在一起的时候，因你赐给我的名，我保守了他们，也护卫了他们；他们中间除了那灭亡的人以外，没有一个是灭亡的，这就应验了经上的话。'),
('CNV', '约翰福音', 43, 17, 13, '现在我到你那里去，我在世上说这些话，是要他们心里充满我的喜乐。'),
('CNV', '约翰福音', 43, 17, 14, '我把你的道赐给了他们；世人恨他们，因为他们不属于这世界，像我不属于这世界一样。'),
('CNV', '约翰福音', 43, 17, 15, '我不求你使他们离开世界，只求你保守他们脱离那恶者。'),
('CNV', '约翰福音', 43, 17, 16, '他们不属于这世界，像我不属于这世界一样。'),
('CNV', '约翰福音', 43, 17, 17, '求你用真理使他们成圣；你的道就是真理。'),
('CNV', '约翰福音', 43, 17, 18, '你怎样差我到世上来，我也怎样差他们到世上去。'),
('CNV', '约翰福音', 43, 17, 19, '我为了他们的缘故，自己分别为圣，使他们也因着真理成圣。'),
('CNV', '约翰福音', 43, 17, 20, '“我不但为他们求，也为那些因他们的话而信我的人求，'),
('CNV', '约翰福音', 43, 17, 21, '使他们都合而为一，像父你在我里面，我在你里面一样；使他们也在我们里面，让世人相信你差了我来。'),
('CNV', '约翰福音', 43, 17, 22, '你赐给我的荣耀，我已经赐给了他们，使他们合而为一，像我们合而为一。'),
('CNV', '约翰福音', 43, 17, 23, '我在他们里面，你在我里面，使他们完完全全合而为一，让世人知道你差了我来，并且知道你爱他们，好像爱我一样。'),
('CNV', '约翰福音', 43, 17, 24, '父啊，我在哪里，愿你赐给我的人也和我同在哪里，让他们看见你赐给我的荣耀，因为在创立世界以前，你已经爱我了。'),
('CNV', '约翰福音', 43, 17, 25, '公义的父啊，世人虽然不认识你，我却认识你，这些人也知道你差了我来。'),
('CNV', '约翰福音', 43, 17, 26, '我已经把你的名指示他们，还要再指示，使你爱我的爱在他们里面，我也在他们里面。”'),
('CNV', '约翰福音', 43, 18, 1, '耶稣说完了这些话，就和门徒出去，过了汲沦溪。在那里有一个园子，耶稣和门徒进去了。'),
('CNV', '约翰福音', 43, 18, 2, '出卖耶稣的犹大也知道那地方，因为耶稣和门徒常常在那里聚集。'),
('CNV', '约翰福音', 43, 18, 3, '那时，犹大带着一队兵，还有祭司长和法利赛人的差役，拿着灯笼、火把、武器，来到园子里。'),
('CNV', '约翰福音', 43, 18, 4, '耶稣知道快要临到他身上的一切事，就出来对他们说：“你们找谁？”'),
('CNV', '约翰福音', 43, 18, 5, '他们回答：“拿撒勒人耶稣！”耶稣说：“我就是。”出卖耶稣的犹大和他们站在那里。'),
('CNV', '约翰福音', 43, 18, 6, '耶稣一说“我就是”，他们就往后退，倒在地上。'),
('CNV', '约翰福音', 43, 18, 7, '他再问他们：“你们找谁？”他们说：“拿撒勒人耶稣！”'),
('CNV', '约翰福音', 43, 18, 8, '耶稣回答：“我已经告诉你们，我就是了。如果你们来找我，就让这些人走吧。”'),
('CNV', '约翰福音', 43, 18, 9, '这应验了耶稣说过的话：“你赐给我的人，我一个也没有失落。”'),
('CNV', '约翰福音', 43, 18, 10, '西门．彼得带着一把刀，就拔出来，向大祭司的仆人马勒古砍去，削掉他的右耳。'),
('CNV', '约翰福音', 43, 18, 11, '耶稣对彼得说：“把刀收入鞘里去！父给我的杯，我怎能不喝呢？”'),
('CNV', '约翰福音', 43, 18, 12, '于是那一队兵和千夫长，以及犹太人的差役拿住耶稣，把他绑起来，'),
('CNV', '约翰福音', 43, 18, 13, '先带到亚那面前。亚那是当年的大祭司该亚法的岳父。'),
('CNV', '约翰福音', 43, 18, 14, '该亚法就是从前向犹太人提议说“一个人代替人民死，这是有益的”那个人。'),
('CNV', '约翰福音', 43, 18, 15, '西门．彼得和另一个门徒跟着耶稣；那门徒是大祭司认识的。他跟耶稣一起进了大祭司的院子，'),
('CNV', '约翰福音', 43, 18, 16, '彼得却站在门外。大祭司所认识的那门徒出来，对看门的婢女说了一声，就带了彼得进去。'),
('CNV', '约翰福音', 43, 18, 17, '那看门的婢女对彼得说：“你不也是这个人的门徒吗？”他说：“我不是。”'),
('CNV', '约翰福音', 43, 18, 18, '因为天气寒冷，仆人和差役就生了炭火，站着取暖；彼得也和他们站在一起取暖。'),
('CNV', '约翰福音', 43, 18, 19, '那时，大祭司查问耶稣有关他的门徒和他的教训的事。'),
('CNV', '约翰福音', 43, 18, 20, '耶稣对大祭司说：“我向来对世人讲话都是公开的，我常常在会堂和圣殿里，就是在所有犹太人聚集的地方教导人，暗地里我并没有讲什么。'),
('CNV', '约翰福音', 43, 18, 21, '你为什么查问我呢？问问那些听过我讲话的人吧，他们知道我讲过什么。”'),
('CNV', '约翰福音', 43, 18, 22, '耶稣说了这些话，站在旁边的一个差役，就打他一巴掌，说：“你竟敢这样回答大祭司吗？”'),
('CNV', '约翰福音', 43, 18, 23, '耶稣对他说：“如果我讲错了，你可以指证错在哪里；如果我讲对了，你为什么打我呢？”'),
('CNV', '约翰福音', 43, 18, 24, '亚那仍然绑着耶稣，把他押到大祭司该亚法那里去。'),
('CNV', '约翰福音', 43, 18, 25, '西门．彼得仍然站在火旁取暖。有人对他说：“你不也是他的门徒吗？”彼得否认说：“我不是。”'),
('CNV', '约翰福音', 43, 18, 26, '有一个大祭司的仆人，就是彼得削掉耳朵的那个人的亲戚，说：“我不是看见你跟他在园子里吗？”'),
('CNV', '约翰福音', 43, 18, 27, '彼得又否认，立刻鸡就叫了。'),
('CNV', '约翰福音', 43, 18, 28, '清早的时候，犹太人把耶稣从该亚法那里押往总督的官邸。他们自己没有进到官邸里去，恐怕沾染了污秽，不能吃逾越节的晚餐。'),
('CNV', '约翰福音', 43, 18, 29, '于是彼拉多走到外面见他们，说：“你们控告这个人什么呢？”'),
('CNV', '约翰福音', 43, 18, 30, '他们回答：“如果这个人没有作恶，我们就不会把他交给你。”'),
('CNV', '约翰福音', 43, 18, 31, '彼拉多对他们说：“你们自己把他带去，按着你们的律法审问他吧。”犹太人说：“我们没有权去判人死罪。”'),
('CNV', '约翰福音', 43, 18, 32, '这就应验了耶稣预先说到自己将要怎样死的那句话。'),
('CNV', '约翰福音', 43, 18, 33, '彼拉多又进了官邸，把耶稣叫来，问他说：“你是犹太人的王吗？”')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '约翰福音', 43, 18, 34, '耶稣回答：“这话是你自己说的，还是别人对你说到我的呢？”'),
('CNV', '约翰福音', 43, 18, 35, '彼拉多说：“难道我是犹太人吗？你本国的人和祭司长把你交给我，你究竟作了什么事？”'),
('CNV', '约翰福音', 43, 18, 36, '耶稣回答：“我的国不属于这世界；如果我的国属于这世界，我的臣仆就要作战，使我不至被交给犹太人。不过，我的国不是这世上的。”'),
('CNV', '约翰福音', 43, 18, 37, '于是彼拉多问他：“那么，你是王吗？”耶稣说：“我是王，你已经说了（“你已经说了”或译：“这是你说的”）。我要为真理作见证，我为此而生，也为此来到世上。凡是属于真理的人，都听我的声音。”'),
('CNV', '约翰福音', 43, 18, 38, '彼拉多问他：“真理是什么？”彼拉多说了这话，又出来见犹太人，对他们说：“我查不出他有什么罪。'),
('CNV', '约翰福音', 43, 18, 39, '你们有个惯例，每逢逾越节，要我给你们释放一个囚犯。你们愿意我给你们释放这个犹太人的王吗？”'),
('CNV', '约翰福音', 43, 18, 40, '他们又喊叫说：“不要他！要巴拉巴！”这巴拉巴是个强盗。'),
('CNV', '约翰福音', 43, 19, 1, '那时，彼拉多吩咐人把耶稣拉去鞭打。'),
('CNV', '约翰福音', 43, 19, 2, '士兵用荆棘编成冠冕，戴在他的头上，又给他披上紫色的外袍，'),
('CNV', '约翰福音', 43, 19, 3, '然后来到他面前，说：“犹太人的王万岁！”并且用手掌打他。'),
('CNV', '约翰福音', 43, 19, 4, '彼拉多再次出到外面，对犹太人说：“看！我把他带出来给你们，让你们知道我查不出他有什么罪。”'),
('CNV', '约翰福音', 43, 19, 5, '于是耶稣出来，戴着荆棘的冠冕，披着紫色的外袍。彼拉多对他们说：“看，这个人！”'),
('CNV', '约翰福音', 43, 19, 6, '祭司长和差役看见耶稣，就喊叫说：“把他钉十字架！把他钉十字架！”彼拉多对他们说：“你们自己把他带去钉十字架吧！我查不出他有什么罪。”'),
('CNV', '约翰福音', 43, 19, 7, '犹太人回答：“我们有律法，根据那律法，他是该死的，因为他自命为神的儿子。”'),
('CNV', '约翰福音', 43, 19, 8, '彼拉多听见这话，就更加害怕，'),
('CNV', '约翰福音', 43, 19, 9, '又进了官邸，问耶稣：“你究竟是从哪里来的？”耶稣却不回答他。'),
('CNV', '约翰福音', 43, 19, 10, '彼拉多对他说：“你不对我说话吗？你不知道我有权释放你，也有权把你钉十字架吗？”'),
('CNV', '约翰福音', 43, 19, 11, '耶稣说：“如果不是从天上给你权柄，你就无权办我；因此，把我交给你的那人，罪更重了。”'),
('CNV', '约翰福音', 43, 19, 12, '从那时起，彼拉多想释放耶稣；可是犹太人却喊叫说：“如果你释放这个人，就不是凯撒的忠臣了。凡是自命为王的，就是与凯撒为敌。”'),
('CNV', '约翰福音', 43, 19, 13, '彼拉多听了这些话，就把耶稣带到外面，到了一个名叫“铺石地”（希伯来话叫加巴大）的地方，就在那里开庭审问。'),
('CNV', '约翰福音', 43, 19, 14, '那天是逾越节的预备日，约在正午的时候。彼拉多对犹太人说：“看，你们的王！”'),
('CNV', '约翰福音', 43, 19, 15, '他们就喊叫起来：“除掉他！除掉他！把他钉十字架！”彼拉多问他们：“我可以把你们的王钉十字架吗？”祭司长回答：“除了凯撒，我们没有王！”'),
('CNV', '约翰福音', 43, 19, 16, '于是彼拉多把耶稣交给他们去钉十字架。'),
('CNV', '约翰福音', 43, 19, 17, '他们把耶稣带去了。耶稣自己背着十字架出来，到了一个名叫“髑髅”的地方，希伯来话叫各各他。'),
('CNV', '约翰福音', 43, 19, 18, '他们就在那里把耶稣钉在十字架上；和他一同钉十字架的，还有两个人，一边一个，耶稣在中间。'),
('CNV', '约翰福音', 43, 19, 19, '彼拉多写了一个牌子，放在十字架上头，写的是：“犹太人的王拿撒勒人耶稣。”'),
('CNV', '约翰福音', 43, 19, 20, '有许多犹太人念了这牌子上所写的，因为耶稣钉十字架的地方离城不远，而且那牌子是用希伯来文、拉丁文和希腊文写的。'),
('CNV', '约翰福音', 43, 19, 21, '犹太人的祭司长对彼拉多说：“不要写‘犹太人的王’，要写‘这个人自称：我是犹太人的王’。”'),
('CNV', '约翰福音', 43, 19, 22, '彼拉多说：“我所写的，我已经写了！”'),
('CNV', '约翰福音', 43, 19, 23, '士兵把耶稣钉了十字架之后，就把他的衣服拿来，分成四份，每个兵一份。他们又拿他的内衣；这内衣是没有缝的，是从上到下整件织成的。'),
('CNV', '约翰福音', 43, 19, 24, '因此，他们彼此说：“我们不要把它撕开，我们来抽签吧，看看是谁的。”这就应验了经上所说的：“他们分了我的外衣，又为我的内衣抽签。”士兵果然这样作了。'),
('CNV', '约翰福音', 43, 19, 25, '站在耶稣十字架旁边的，有他母亲和他母亲的姊妹，还有高罗巴的妻子马利亚，和抹大拉的马利亚。'),
('CNV', '约翰福音', 43, 19, 26, '耶稣看见母亲，又看见他所爱的那门徒站在旁边，就对母亲说：“母亲（“母亲”原文作“妇人”），看！你的儿子。”'),
('CNV', '约翰福音', 43, 19, 27, '然后他对那门徒说：“看！你的母亲。”从那时起，那门徒就把她接到自己的家里去了。'),
('CNV', '约翰福音', 43, 19, 28, '这事以后，耶稣知道一切都已经成就了，为了要使经上的话应验，就说：“我渴了。”'),
('CNV', '约翰福音', 43, 19, 29, '在那里有一个坛子，盛满了酸酒，他们就拿海绵浸了酸酒，绑在牛膝草上，送到他的口里。'),
('CNV', '约翰福音', 43, 19, 30, '耶稣尝了那酸酒，说：“成了！”就低下头，断了气。'),
('CNV', '约翰福音', 43, 19, 31, '因为那天是预备日，为了要避免尸体在安息日留在十字架上（因为那安息日是个重要的日子），犹太人就请求彼拉多打断那些被钉十字架的人的腿，把他们拿下来。'),
('CNV', '约翰福音', 43, 19, 32, '于是士兵来了，把和耶稣一同钉十字架的那两个人的腿都先后打断了。'),
('CNV', '约翰福音', 43, 19, 33, '他们来到耶稣那里，看见他已经死了，就没有打断他的腿。'),
('CNV', '约翰福音', 43, 19, 34, '但是有一个士兵用枪刺他的肋旁，立刻有血和水流出来。'),
('CNV', '约翰福音', 43, 19, 35, '那看见这事的人已经作证了，他的见证是真实的，他也知道自己所说的是实在的，使你们也相信。'),
('CNV', '约翰福音', 43, 19, 36, '这些事的发生，是要应验经上所说的：“他的骨头，一根也不可折断。”'),
('CNV', '约翰福音', 43, 19, 37, '另有一处经文说：“他们要仰望自己所刺的人。”'),
('CNV', '约翰福音', 43, 19, 38, '这些事以后，有一个亚利马太人约瑟来求彼拉多，要领耶稣的身体；他因为怕犹太人，就暗暗地作耶稣的门徒。彼拉多批准了，他便把耶稣的身体领去。'),
('CNV', '约翰福音', 43, 19, 39, '从前夜间来见耶稣的尼哥德慕也来了，带着没药和沉香混合的香料，约有三十二公斤。'),
('CNV', '约翰福音', 43, 19, 40, '他们领取了耶稣的身体，照着犹太人的葬礼的规例，用细麻布和香料把他裹好。'),
('CNV', '约翰福音', 43, 19, 41, '在耶稣钉十字架的地方，有一个园子，园里有一个新的墓穴，是从来没有葬过人的。'),
('CNV', '约翰福音', 43, 19, 42, '因为那天是犹太人的预备日，又因为那墓穴就在附近，他们就把耶稣葬在那里。'),
('CNV', '约翰福音', 43, 20, 1, '礼拜日清早，天还没有亮的时候，抹大拉的马利亚来到墓旁，看见石头已经从坟墓移开了。'),
('CNV', '约翰福音', 43, 20, 2, '她就跑去见西门．彼得，和耶稣所爱的那个门徒，对他们说：“有人把主从坟墓里搬走了，我们不知道他们把他放在哪里。”'),
('CNV', '约翰福音', 43, 20, 3, '彼得和那门徒就动身，到坟墓那里去。'),
('CNV', '约翰福音', 43, 20, 4, '两个人一齐跑，那门徒比彼得跑得快，先到了坟墓，'),
('CNV', '约翰福音', 43, 20, 5, '屈身向里面观看，看见细麻布还在那里，但他却没有进去。'),
('CNV', '约翰福音', 43, 20, 6, '西门．彼得随后也到了；他进入坟墓，看见细麻布还放在那里，'),
('CNV', '约翰福音', 43, 20, 7, '也看见耶稣的裹头巾，没有和细麻布放在一起，而是卷着放在一边。'),
('CNV', '约翰福音', 43, 20, 8, '那时，先到坟墓的那门徒也进去，他看见，就信了。'),
('CNV', '约翰福音', 43, 20, 9, '他们还不明白经上所说“他必须从死人中复活”这句话的意思。'),
('CNV', '约翰福音', 43, 20, 10, '于是两个门徒就回家去了。'),
('CNV', '约翰福音', 43, 20, 11, '马利亚站在坟墓外面哭泣。她哭的时候，屈身往里面观看，'),
('CNV', '约翰福音', 43, 20, 12, '看见两个身穿白衣的天使，坐在安放耶稣身体的地方，一个在头那边，一个在脚那边。'),
('CNV', '约翰福音', 43, 20, 13, '天使问她：“妇人，你为什么哭？”她说：“有人把我的主搬走了，我不知道他们把他放在哪里。”'),
('CNV', '约翰福音', 43, 20, 14, '马利亚说了这话，就转过身来，看见耶稣站在那里，却不知道他就是耶稣。'),
('CNV', '约翰福音', 43, 20, 15, '耶稣对她说：“妇人，你为什么哭？你找谁呢？”马利亚以为耶稣是园丁，就对他说：“先生，如果是你把他挪去了，请告诉我你把他放在什么地方，我好去搬回来。”'),
('CNV', '约翰福音', 43, 20, 16, '耶稣对她说：“马利亚！”她转过身来，用希伯来话对他说：“拉波尼！”（就是“老师”的意思。）'),
('CNV', '约翰福音', 43, 20, 17, '耶稣说：“你不要拉住我，因为我还没有上去见父。你要到我的弟兄们那里去，告诉他们我要上去见我的父，也是你们的父；见我的神，也是你们的神。”'),
('CNV', '约翰福音', 43, 20, 18, '抹大拉的马利亚就去，向门徒报信说：“我已经看见主了！”她又把主对她所说的话告诉他们。'),
('CNV', '约翰福音', 43, 20, 19, '礼拜日黄昏的时候，门徒聚在一起，因为怕犹太人，就把门户都关上。耶稣来了，站在他们中间，说：“愿你们平安。”'),
('CNV', '约翰福音', 43, 20, 20, '说了这话，就把手和肋旁给他们看。门徒看见主，就欢喜了。'),
('CNV', '约翰福音', 43, 20, 21, '耶稣又对他们说：“愿你们平安。父怎样差遣了我，我也怎样差遣你们。”'),
('CNV', '约翰福音', 43, 20, 22, '说了这话，就向他们吹一口气，说：“你们领受圣灵吧！'),
('CNV', '约翰福音', 43, 20, 23, '你们赦免谁的罪，谁的罪就得赦免；你们不赦免谁的罪，谁的罪就不得赦免。”'),
('CNV', '约翰福音', 43, 20, 24, '十二个门徒中，有一个称为“双生子”（“双生子”原文作“低土马”）的多马。耶稣来的时候，他没有和门徒在一起。'),
('CNV', '约翰福音', 43, 20, 25, '其他的门徒对他说：“我们已经见过主了。”多马对他们说：“除非我亲眼看见他手上的钉痕，用我的指头探入那钉痕，又用我的手探入他的肋旁，我决不相信。”'),
('CNV', '约翰福音', 43, 20, 26, '过了八天，门徒又在屋子里，多马也和他们在一起。门户都关上了。耶稣来了，站在他们中间，说：“愿你们平安。”'),
('CNV', '约翰福音', 43, 20, 27, '然后对多马说：“把你的指头放在这里，看看我的手吧！伸出你的手来，探探我的肋旁！不要疑惑，只要信！”'),
('CNV', '约翰福音', 43, 20, 28, '多马对他说：“我的主！我的神！”'),
('CNV', '约翰福音', 43, 20, 29, '耶稣说：“你因为看见我才信吗？那些没有看见就信的人，是有福的。”'),
('CNV', '约翰福音', 43, 20, 30, '耶稣在门徒面前还行了许多别的神迹，没有记在这书上。'),
('CNV', '约翰福音', 43, 20, 31, '但把这些事记下来，是要你们信耶稣是基督，是神的儿子，并且使你们信了，可以因他的名得生命。'),
('CNV', '约翰福音', 43, 21, 1, '这些事以后，耶稣在提比里亚海边再次向门徒显现。他显现的经过是这样的：'),
('CNV', '约翰福音', 43, 21, 2, '当时西门．彼得、称为“双生子”的多马、加利利的迦拿人拿但业、西庇太的两个儿子，和另外两个门徒都聚在一起。'),
('CNV', '约翰福音', 43, 21, 3, '西门．彼得对他们说：“我要打鱼去。”他们说：“我们也跟你一起去。”于是他们出去，上了船，可是那一夜他们并没有打到什么。'),
('CNV', '约翰福音', 43, 21, 4, '清早的时候，耶稣站在岸边；门徒却不知道他就是耶稣。'),
('CNV', '约翰福音', 43, 21, 5, '耶稣对他们说：“孩子们，打到鱼没有？”他们回答：“没有。”'),
('CNV', '约翰福音', 43, 21, 6, '耶稣说：“把网撒在船的右边，就可以得着。”他们就把网撒下去，可是拉不上来，因为鱼太多。'),
('CNV', '约翰福音', 43, 21, 7, '耶稣所爱的那门徒对彼得说：“是主！”西门．彼得一听见是主，就立刻束上外衣（因为他当时赤着身子），纵身跳进海里。'),
('CNV', '约翰福音', 43, 21, 8, '其他的门徒，因为离岸不远（约有一百公尺），就坐在小船上，把那网鱼拖过来。'),
('CNV', '约翰福音', 43, 21, 9, '他们上了岸，就看见那里有一堆炭火，上面有鱼有饼。'),
('CNV', '约翰福音', 43, 21, 10, '耶稣对他们说：“把你们刚才打的鱼拿几条来。”'),
('CNV', '约翰福音', 43, 21, 11, '西门．彼得就上船，把网拉到岸上；那网满了大鱼，共有一百五十三条。鱼虽然这么多，网却没有破。'),
('CNV', '约翰福音', 43, 21, 12, '耶稣对他们说：“你们来，吃早饭吧。”门徒中没有一个人敢问他：“你是谁？”因为知道他是主。'),
('CNV', '约翰福音', 43, 21, 13, '耶稣走过来，拿饼递给他们，又照样拿鱼递给他们。'),
('CNV', '约翰福音', 43, 21, 14, '这是耶稣从死人中复活之后，第三次向门徒显现。'),
('CNV', '约翰福音', 43, 21, 15, '他们吃了早饭，耶稣问西门．彼得：“约翰的儿子西门，你爱我比这些更深吗？”他回答：“主啊，是的，你知道我爱你。”耶稣说：“你喂养我的小羊。”'),
('CNV', '约翰福音', 43, 21, 16, '耶稣第二次又问他：“约翰的儿子西门，你爱我吗？”他回答：“主啊，是的，你知道我爱你。”耶稣说：“你牧养我的羊。”'),
('CNV', '约翰福音', 43, 21, 17, '耶稣第三次问他：“约翰的儿子西门，你爱我吗？”彼得因为耶稣第三次问他：“你爱我吗？”就忧愁起来，对耶稣说：“主啊，你是无所不知的，你知道我爱你。”耶稣说：“你喂养我的羊。'),
('CNV', '约翰福音', 43, 21, 18, '我实实在在告诉你，你年轻的时候，自己束上腰带，随意往来；但到了年老的时候，你要伸出手来，别人要把你绑着，带你到你不愿意去的地方。”'),
('CNV', '约翰福音', 43, 21, 19, '耶稣说这话，是指明彼得将怎样死，来荣耀神。说了这话，就对彼得说：“你跟从我吧！”'),
('CNV', '约翰福音', 43, 21, 20, '彼得转过身来，看见耶稣所爱的那门徒跟着，就是在晚饭的时候，靠着耶稣的胸膛，问“主啊，出卖你的是谁？”的那个人。'),
('CNV', '约翰福音', 43, 21, 21, '彼得看见他，就问耶稣：“主啊，这个人将来怎么样？”'),
('CNV', '约翰福音', 43, 21, 22, '耶稣回答他：“如果我要他活到我来的时候，跟你有什么关系呢？你只管跟从我吧！”'),
('CNV', '约翰福音', 43, 21, 23, '于是这话流传在弟兄中间，说那门徒不会死。其实耶稣并没有对他说他不会死，只是说：“如果我要他活到我来的时候，跟你有什么关系呢？”'),
('CNV', '约翰福音', 43, 21, 24, '为这些事作证，并且记述这些事的，就是这门徒；我们知道他的见证是真实的。'),
('CNV', '约翰福音', 43, 21, 25, '耶稣所行的，还有许多其他的事；如果都一一写下来，所要写成的书，我想就是这个世界也容不下了。'),
('CNV', '使徒行传', 44, 1, 1, '提阿非罗先生：我已经写了前书，叙述耶稣开始所行所教的一切，'),
('CNV', '使徒行传', 44, 1, 2, '一直到他藉着圣灵吩咐所拣选的使徒之后，被接上升的日子为止。'),
('CNV', '使徒行传', 44, 1, 3, '他受难以后，用许多凭据向使徒显示自己是活着的。他向使徒显现，并且讲论神的国的事，有四十天之久。'),
('CNV', '使徒行传', 44, 1, 4, '耶稣和他们一同吃饭的时候，吩咐他们不要离开耶路撒冷，说：“你们要等候父的应许，就是你们听我讲过的，'),
('CNV', '使徒行传', 44, 1, 5, '约翰是用水施洗，但再过几天，你们要受圣灵的洗。”'),
('CNV', '使徒行传', 44, 1, 6, '他们聚集的时候，问耶稣说：“主啊，你要在这时候使以色列复国吗？”'),
('CNV', '使徒行传', 44, 1, 7, '耶稣说：“父凭着自己的权柄所定的时间或日期，你们不必知道。'),
('CNV', '使徒行传', 44, 1, 8, '可是圣灵降临在你们身上，你们就必领受能力，并且要在耶路撒冷、犹太全地、撒玛利亚，直到地极，作我的见证人。”'),
('CNV', '使徒行传', 44, 1, 9, '说完了这话，他们还在看的时候，他被接上升，有一朵云把他接去，就看不见他了。'),
('CNV', '使徒行传', 44, 1, 10, '当他往上升，他们定睛望天的时候，忽然有两个人，身穿白衣，站在他们旁边，'),
('CNV', '使徒行传', 44, 1, 11, '说：“加利利人哪，为什么站着望天呢？这位被接升天离开你们的耶稣，你们看见他怎样往天上去，他也要怎样回来。”'),
('CNV', '使徒行传', 44, 1, 12, '后来，他们从橄榄山回到耶路撒冷。那山靠近耶路撒冷，有一安息日可走的路程。'),
('CNV', '使徒行传', 44, 1, 13, '他们进了城，上了一间楼房，就是彼得、约翰、雅各、安得烈、腓力、多马、巴多罗迈、马太、亚勒腓的儿子雅各、激进派的西门、雅各的儿子犹大等人所住的。'),
('CNV', '使徒行传', 44, 1, 14, '这些人和几个妇女，耶稣的母亲马利亚，还有他的兄弟们，都在一起，同心地恒切祷告。'),
('CNV', '使徒行传', 44, 1, 15, '那时，约有一百二十人聚会，彼得在众弟兄中间站起来说：'),
('CNV', '使徒行传', 44, 1, 16, '“弟兄们，经上的话，就是圣灵藉着大卫的口，预言那领人捉拿耶稣的犹大的事，是一定会应验的。'),
('CNV', '使徒行传', 44, 1, 17, '他本是我们中间的一个，一同领受了这职分。'),
('CNV', '使徒行传', 44, 1, 18, '他用不义的酬劳买了一块田，结果倒头栽了下去，腹破肠流。'),
('CNV', '使徒行传', 44, 1, 19, '这事住在耶路撒冷的人全都知道，所以按当地的话，那块地称为亚革大马，意思就是‘血田’。'),
('CNV', '使徒行传', 44, 1, 20, '因为诗篇上写着：‘愿他的住处变为荒场，无人居在其中。’又说：‘愿别人取代他的职分。’'),
('CNV', '使徒行传', 44, 1, 21, '所以，从约翰施洗起，直到主离开我们被接上升的那天为止，当他在我们中间来往的时候，那些跟我们常在一起的人中，应该有一个人出来与我们一同作耶稣复活的见证人。”'),
('CNV', '使徒行传', 44, 1, 23, '于是他们提出两个人：约瑟（号称巴撒巴，又名犹士都）和马提亚，'),
('CNV', '使徒行传', 44, 1, 24, '就祷告说：“主啊！你知道万人的心，求你从这两个人中，指明你要拣选谁，'),
('CNV', '使徒行传', 44, 1, 25, '来承担这使徒的职位和工作。这职位犹大已经放弃，往他自己的地方去了。”'),
('CNV', '使徒行传', 44, 1, 26, '大家就为他们抽签，结果抽中了马提亚，他就与十一使徒同列。'),
('CNV', '使徒行传', 44, 2, 1, '五旬节到了，他们都聚集在一起。'),
('CNV', '使徒行传', 44, 2, 2, '忽然有一阵好像强风吹过的响声，从天而来，充满了他们坐在里面的整间屋子。'),
('CNV', '使徒行传', 44, 2, 3, '又有火焰般的舌头显现出来，分别落在他们各人身上。'),
('CNV', '使徒行传', 44, 2, 4, '他们都被圣灵充满，就照着圣灵所赐给他们的口才，用别种语言说出话来。'),
('CNV', '使徒行传', 44, 2, 5, '那时住在耶路撒冷的，有从天下各国来的虔诚的犹太人。'),
('CNV', '使徒行传', 44, 2, 6, '这声音一响，许多人都聚了来，人人都听见门徒讲出听众各人本乡的话，就莫名其妙。'),
('CNV', '使徒行传', 44, 2, 7, '他们又惊讶、又惊奇，说：“你看，这些说话的，不都是加利利人吗？'),
('CNV', '使徒行传', 44, 2, 8, '我们各人怎么听见他们讲我们从小所用的本乡话呢？'),
('CNV', '使徒行传', 44, 2, 9, '我们帕提亚人、玛代人、以拦人和住在美索不达米亚、犹太、加帕多家、本都、亚西亚、'),
('CNV', '使徒行传', 44, 2, 10, '弗吕家、旁非利亚、埃及，并靠近古利奈的利比亚一带地方的人，客居罗马的犹太人和归信犹太教的人，'),
('CNV', '使徒行传', 44, 2, 11, '克里特人以及阿拉伯人，都听见他们用我们的语言，讲说神的大作为。”'),
('CNV', '使徒行传', 44, 2, 12, '众人还在惊讶迷惘的时候，彼此说：“这是什么意思？”'),
('CNV', '使徒行传', 44, 2, 13, '另有些人讥笑说：“他们是给新酒灌醉了。”'),
('CNV', '使徒行传', 44, 2, 14, '彼得和十一使徒站起来，他高声对众人说：“犹太人和所有住在耶路撒冷的人哪，你们应当明白这件事，也应该留心听我的话。'),
('CNV', '使徒行传', 44, 2, 15, '这些人并不是照你们所想的喝醉了，现在不过是上午九点钟罢了。'),
('CNV', '使徒行传', 44, 2, 16, '这正是约珥先知所说的：'),
('CNV', '使徒行传', 44, 2, 17, '‘神说：在末后的日子，我要把我的灵浇灌所有的人，你们的儿女要说预言，你们的青年人要见异象，你们的老年人要作异梦。'),
('CNV', '使徒行传', 44, 2, 18, '在那些日子，我也要把我的灵浇灌我的仆人和使女，他们就要说预言。'),
('CNV', '使徒行传', 44, 2, 19, '我要在天上显出奇事，在地上显出神迹，有血、有火、有烟雾；'),
('CNV', '使徒行传', 44, 2, 20, '太阳将变为黑暗，月亮将变为血红，在主伟大显赫的日子临到以前，这一切都要发生。'),
('CNV', '使徒行传', 44, 2, 21, '那时，凡求告主名的，都必得救。’'),
('CNV', '使徒行传', 44, 2, 22, '“以色列人哪，请听听这几句话：正如你们所知道的，神已经藉着拿撒勒人耶稣在你们中间施行了大能、奇事、神迹，向你们证明他是神所立的。'),
('CNV', '使徒行传', 44, 2, 23, '他照着神的定旨和预知被交了出去，你们就藉不法之徒的手，把他钉死了。'),
('CNV', '使徒行传', 44, 2, 24, '神却把死的痛苦解除，使他复活了，因为他不能被死亡拘禁。'),
('CNV', '使徒行传', 44, 2, 25, '大卫指着他说：‘我时常看见主在我面前，因他在我右边，我必不会动摇。'),
('CNV', '使徒行传', 44, 2, 26, '为此我的心快乐，我的口舌欢呼，我的肉身也要安居在盼望中。'),
('CNV', '使徒行传', 44, 2, 27, '因你必不把我的灵魂撇在阴间，也必不容你的圣者见朽坏。'),
('CNV', '使徒行传', 44, 2, 28, '你已经把生命之路指示了我，必使我在你面前有满足的喜乐。’'),
('CNV', '使徒行传', 44, 2, 29, '“弟兄们，关于祖先大卫的事，我不妨坦白告诉你们，他死了，葬了，直到今日他的坟墓还在我们这里。'),
('CNV', '使徒行传', 44, 2, 30, '他是先知，既然知道神向他起过誓，要从他的后裔中立一位，坐在他的宝座上，'),
('CNV', '使徒行传', 44, 2, 31, '又预先看见了这事，就讲论基督的复活说：‘他不会被撇在阴间，他的肉身也不见朽坏。’'),
('CNV', '使徒行传', 44, 2, 32, '这位耶稣，神已经使他复活了，我们都是这事的见证人。'),
('CNV', '使徒行传', 44, 2, 33, '他既然被高举到神的右边，从父领受了所应许的圣灵，就把他浇灌下来，这就是你们所看见所听见的。'),
('CNV', '使徒行传', 44, 2, 34, '大卫并没有升到天上，他却说：‘主对我主说：你坐在我的右边，'),
('CNV', '使徒行传', 44, 2, 35, '等我使你的仇敌作你的脚凳。’'),
('CNV', '使徒行传', 44, 2, 36, '因此，以色列全家应当确实知道，你们钉在十字架上的这位耶稣，神已经立他为主为基督了。”'),
('CNV', '使徒行传', 44, 2, 37, '他们听了以后，觉得扎心，就对彼得和其余的使徒说：“弟兄们，我们应当作什么呢？”'),
('CNV', '使徒行传', 44, 2, 38, '彼得说：“你们应当悔改，并且每一个人都要奉耶稣基督的名受洗，使你们的罪得赦，就必领受圣灵，那白白的恩典。'),
('CNV', '使徒行传', 44, 2, 39, '这应许原是给你们和你们的儿女，以及所有在远方的人，就是给凡是我们主神召来归他的人。”'),
('CNV', '使徒行传', 44, 2, 40, '彼得还用许多别的话，郑重作证，并且劝勉他们，说：“你们应当救自己脱离这弯曲的世代！”'),
('CNV', '使徒行传', 44, 2, 41, '于是接受他话的人都受了洗，那一天门徒增加了约三千人。'),
('CNV', '使徒行传', 44, 2, 42, '他们恒心遵守使徒的教训，彼此相通、擘饼和祈祷。'),
('CNV', '使徒行传', 44, 2, 43, '使徒行了许多奇事神迹，众人就都惧怕。'),
('CNV', '使徒行传', 44, 2, 44, '所有信的人都在一起，凡物公用，'),
('CNV', '使徒行传', 44, 2, 45, '并且变卖产业和财物，按照各人的需要分给他们。'),
('CNV', '使徒行传', 44, 2, 46, '他们天天同心在殿里恒切地聚集，一家一家地擘饼，存着欢乐和诚恳的心用饭，'),
('CNV', '使徒行传', 44, 2, 47, '又赞美神，并且得到全民的喜爱。主将得救的人，天天加给教会。'),
('CNV', '使徒行传', 44, 3, 1, '在下午三点祷告的时辰，彼得和约翰上圣殿去。'),
('CNV', '使徒行传', 44, 3, 2, '有一个生来瘸腿的人被人抬来。他们天天把他放在那名叫美门的殿门口，让他好向进殿的人讨饭。'),
('CNV', '使徒行传', 44, 3, 3, '他看见彼得和约翰将要进殿，就向他们讨饭。'),
('CNV', '使徒行传', 44, 3, 4, '彼得和约翰定睛看着他，彼得说：“你看我们！”'),
('CNV', '使徒行传', 44, 3, 5, '那人就留意看着他们，希望从他们得些什么。'),
('CNV', '使徒行传', 44, 3, 6, '彼得却说：“金银我都没有，只把我有的给你：我奉拿撒勒人耶稣基督的名，吩咐你行走！”'),
('CNV', '使徒行传', 44, 3, 7, '于是拉着他的右手，扶他起来；他的脚和踝骨立刻强壮有力，'),
('CNV', '使徒行传', 44, 3, 8, '他一跳就站了起来，并且行走。他连走带跳，赞美神，同他们进入殿中。'),
('CNV', '使徒行传', 44, 3, 9, '群众看见他一边走一边赞美神；'),
('CNV', '使徒行传', 44, 3, 10, '他们一认出他就是那平时坐在圣殿美门口讨饭的，就因他所经历的事，满心希奇，惊讶不已。'),
('CNV', '使徒行传', 44, 3, 11, '那人拉着彼得和约翰的时候，群众都很惊奇，跑到他们那里，就是所罗门廊的下面。'),
('CNV', '使徒行传', 44, 3, 12, '彼得看见了，就对群众说：“以色列人哪，为什么因这事希奇呢？为什么瞪着我们，好像我们是凭着自己的能力和虔诚，使这人行走呢？'),
('CNV', '使徒行传', 44, 3, 13, '亚伯拉罕、以撒、雅各的神，就是我们祖宗的神，荣耀了他的仆人耶稣。这位耶稣，你们把他送交官府。彼拉多本来定意要放他，你们却当着彼拉多的面拒绝他。'),
('CNV', '使徒行传', 44, 3, 14, '你们把那圣者义者拒绝了，反而要求给你们释放一个杀人犯。'),
('CNV', '使徒行传', 44, 3, 15, '你们杀了那‘生命的创始者’，神却使他从死人中复活。我们就是这件事的见证人。'),
('CNV', '使徒行传', 44, 3, 16, '是他的名—因信他的名—使你们所看见所认识的这个人强壮了。这从耶稣而来的信心，当着你们众人面前，把他完全医好了。'),
('CNV', '使徒行传', 44, 3, 17, '弟兄们，我知道你们所作的，是出于无知，你们的官长也是这样。'),
('CNV', '使徒行传', 44, 3, 18, '但神曾经藉着众先知的口，预先宣告他所立的基督将要受害的事，就这样应验了。'),
('CNV', '使徒行传', 44, 3, 19, '所以你们应当悔改归正，使你们的罪得着涂抹。'),
('CNV', '使徒行传', 44, 3, 20, '这样，那安乐的日子，必从主面前来到，并且他必把为你们预先选定的基督（耶稣）差来。'),
('CNV', '使徒行传', 44, 3, 21, '他必留在天上，直到万物复兴的时候，就是神自古藉着圣先知的口所说的。'),
('CNV', '使徒行传', 44, 3, 22, '摩西曾说：‘你们的主神要从你们弟兄中间，给你们兴起一位先知像我；无论他对你们说什么，你们都应当听从。'),
('CNV', '使徒行传', 44, 3, 23, '无论谁不听从那位先知，必定从民中灭绝。’'),
('CNV', '使徒行传', 44, 3, 24, '所有从撒母耳起，以及相继兴起来讲话的先知，都曾经宣告这些日子。'),
('CNV', '使徒行传', 44, 3, 25, '你们是先知的子孙，也是承受神向你们祖先所立之约的人。神曾经对亚伯拉罕说：‘地上万族，都要因你的后裔得福。’'),
('CNV', '使徒行传', 44, 3, 26, '神先给你们兴起他的仆人，差他来祝福你们，使你们各人回转，离开邪恶。”'),
('CNV', '使徒行传', 44, 4, 1, '使徒们正对群众讲话的时候，祭司、圣殿的守卫长，和撒都该人来到他们那里。'),
('CNV', '使徒行传', 44, 4, 2, '因为使徒教训群众，并且传扬耶稣从死人中复活，他们就非常恼怒，'),
('CNV', '使徒行传', 44, 4, 3, '于是下手拿住使徒。那时天已经晚了，就把他们拘留到第二天。'),
('CNV', '使徒行传', 44, 4, 4, '然而有许多听道的人信了，男人的数目，约有五千。'),
('CNV', '使徒行传', 44, 4, 5, '第二天，犹太人的官长、长老、经学家，都聚集在耶路撒冷，'),
('CNV', '使徒行传', 44, 4, 6, '还有大祭司亚那和该亚法、约翰、亚历山大，以及大祭司的家人，所有的人都在那里。'),
('CNV', '使徒行传', 44, 4, 7, '他们叫使徒都站在当中，查问说：“你们凭什么能力，奉谁的名作这事？”'),
('CNV', '使徒行传', 44, 4, 8, '当时彼得被圣灵充满，对他们说：“民众的领袖和长老啊！'),
('CNV', '使徒行传', 44, 4, 9, '我们今天受审，如果是为了在那残疾人身上所行的善事，就是这个人怎么会好的，'),
('CNV', '使徒行传', 44, 4, 10, '那么，你们各位和以色列全民都应当知道，站在你们面前这人好了，是因拿撒勒人耶稣基督的名。这位耶稣基督，你们把他钉死在十字架上，神却使他从死人中复活。'),
('CNV', '使徒行传', 44, 4, 11, '这耶稣是你们‘建筑工人所弃的石头，成了房角的主要石头。’'),
('CNV', '使徒行传', 44, 4, 12, '除了他以外，别无拯救，因为在天下人间，没有赐下别的名，我们可以靠着得救。”'),
('CNV', '使徒行传', 44, 4, 13, '他们看见彼得和约翰的胆量，也知道这两个人是没有学问的平民，就很惊奇；同时认出他们是跟耶稣一伙的，'),
('CNV', '使徒行传', 44, 4, 14, '又看见那医好了的人，和他们一同站着，就没有话可辩驳。'),
('CNV', '使徒行传', 44, 4, 15, '于是吩咐他们到公议会外面去，彼此商议，'),
('CNV', '使徒行传', 44, 4, 16, '说：“对这些人我们应该怎么办呢？因为有一件人所共知的神迹，藉着他们行了出来，所有住在耶路撒冷的人都知道，我们也无法否认。'),
('CNV', '使徒行传', 44, 4, 17, '为了避免这件事在民间越传越广，我们应该警告他们，不许再奉这名向任何人谈道。”'),
('CNV', '使徒行传', 44, 4, 18, '于是叫了他们来，严禁他们再奉耶稣的名讲论教导。'),
('CNV', '使徒行传', 44, 4, 19, '彼得和约翰回答：“听从你们过于听从神，在神面前对不对，你们自己说吧！'),
('CNV', '使徒行传', 44, 4, 20, '我们看见的听见的，不能不说！”'),
('CNV', '使徒行传', 44, 4, 21, '众人因着所发生的事，都颂赞神，于是公议会为了群众的缘故，也因为找不到借口惩罚他们，就恐吓一番，把他们放了。'),
('CNV', '使徒行传', 44, 4, 22, '原来藉着神迹医好的那人，有四十多岁了。'),
('CNV', '使徒行传', 44, 4, 23, '彼得和约翰被释放了之后，回到自己的人那里去，把祭司长和长老说的一切，都告诉他们。'),
('CNV', '使徒行传', 44, 4, 24, '他们听了，就同心向神高声说：“主啊，你是那创造天地、海洋和其中万物的主宰。'),
('CNV', '使徒行传', 44, 4, 25, '你曾以圣灵藉着你仆人我们祖先大卫的口说：‘列国为什么骚动？万民为什么空谋妄想？'),
('CNV', '使徒行传', 44, 4, 26, '地上的君王都起来，首领聚在一起，敌对主和他的受膏者。’'),
('CNV', '使徒行传', 44, 4, 27, '希律和本丢．彼拉多，外族人和以色列民，真的在这城里聚集，反对你所膏立的圣仆耶稣，'),
('CNV', '使徒行传', 44, 4, 28, '行了你手和你旨意所预定要成就的一切。'),
('CNV', '使徒行传', 44, 4, 29, '主啊，他们恐吓我们，现在求你鉴察，也赐你仆人们大有胆量，传讲你的道。'),
('CNV', '使徒行传', 44, 4, 30, '求你伸手医治，藉着你圣仆耶稣的名，大行神迹奇事。”'),
('CNV', '使徒行传', 44, 4, 31, '他们祷告完了，聚会的地方震动起来，他们都被圣灵充满，放胆传讲神的道。'),
('CNV', '使徒行传', 44, 4, 32, '全体信徒一心一意，没有一个人说自己的财物是自己的，他们凡物公用。'),
('CNV', '使徒行传', 44, 4, 33, '使徒大有能力，为主耶稣的复活作见证，众人都蒙了大恩。'),
('CNV', '使徒行传', 44, 4, 34, '他们中间没有一个有缺乏的，因为凡有田产房屋的都卖了，把得到的钱拿来，'),
('CNV', '使徒行传', 44, 4, 35, '放在使徒脚前，照着各人的需要来分配。'),
('CNV', '使徒行传', 44, 4, 36, '有一个人名叫约瑟，使徒称他为巴拿巴，就是“安慰者”的意思，他是个利未人，生在塞浦路斯。'),
('CNV', '使徒行传', 44, 4, 37, '他卖掉了自己的田地，把钱拿来，放在使徒的脚前。'),
('CNV', '使徒行传', 44, 5, 1, '有一个人名叫亚拿尼亚，同他妻子撒非拉，把田产卖了。'),
('CNV', '使徒行传', 44, 5, 2, '他私底下把钱留了一部分，妻子也知道这件事。他把其余的一部分带来，放在使徒的脚前。'),
('CNV', '使徒行传', 44, 5, 3, '彼得说：“亚拿尼亚，为什么撒但充满了你的心，使你欺骗圣灵，私底下把卖地的钱留了一部分呢？'),
('CNV', '使徒行传', 44, 5, 4, '田地还没有卖，不是你自己的吗？既然卖了，所得的钱不是由你作主吗？你为什么存心这样作呢？你这不是欺骗人，而是欺骗神。”'),
('CNV', '使徒行传', 44, 5, 5, '亚拿尼亚一听见这话，就仆倒断了气。所有听见的人都十分害怕。'),
('CNV', '使徒行传', 44, 5, 6, '有几个青年人来把他包好，抬出去埋了。'),
('CNV', '使徒行传', 44, 5, 7, '大约三小时之后，亚拿尼亚的妻子进来，还不知道发生了什么事。'),
('CNV', '使徒行传', 44, 5, 8, '彼得问她：“你告诉我，你们卖田地的钱，就是这么多吗？”她说：“是的，就是这么多。”'),
('CNV', '使徒行传', 44, 5, 9, '彼得说：“你们为什么串同试探主的灵呢？你看，埋你丈夫的人的脚，已经到了门口，他们也要把你抬出去。”'),
('CNV', '使徒行传', 44, 5, 10, '她立刻就仆倒在彼得脚前，断了气。那些青年人进来，发现她死了，把她也抬出去，埋在她丈夫旁边。'),
('CNV', '使徒行传', 44, 5, 11, '全体会众和所有听见这事的人，都很害怕。'),
('CNV', '使徒行传', 44, 5, 12, '主藉着使徒的手，在民间行了许多神迹奇事。他们都同心聚集在所罗门廊下，'),
('CNV', '使徒行传', 44, 5, 13, '其余的人，没有一个敢接近他们，可是民众都很敬重他们。'),
('CNV', '使徒行传', 44, 5, 14, '信主的男男女女越来越多，'),
('CNV', '使徒行传', 44, 5, 15, '甚至有人把病人抬到街上，放在小床和褥子上，好让彼得经过时，至少他的身影可以落在一些人身上。'),
('CNV', '使徒行传', 44, 5, 16, '耶路撒冷周围城市的人，也带着病人和受污灵缠扰的，蜂拥而来，结果病人全都医好了。'),
('CNV', '使徒行传', 44, 5, 17, '大祭司和他的同党撒都该人都起来，满心忌恨，'),
('CNV', '使徒行传', 44, 5, 18, '于是下手拿住使徒，把他们押在公共拘留所里。'),
('CNV', '使徒行传', 44, 5, 19, '夜间有一位天使，打开监门，把他们领出来，说：'),
('CNV', '使徒行传', 44, 5, 20, '“你们去，站在殿里，把一切有关这生命的话，都讲给众民听。”'),
('CNV', '使徒行传', 44, 5, 21, '使徒听完了，就在黎明的时候，进到殿里去教导。大祭司和他的同党来到了，就召集了公议会和以色列人的众长老，派人到监牢去带使徒出来。'),
('CNV', '使徒行传', 44, 5, 22, '差役到了监里，找不到他们，回来报告说：'),
('CNV', '使徒行传', 44, 5, 23, '“我们发现监门紧闭，狱卒也守在门外；等到开了门，里面连一个人也找不到。”'),
('CNV', '使徒行传', 44, 5, 24, '圣殿的守卫长和祭司长听了这些话，觉得很困惑，不知道这件事将来会怎样。'),
('CNV', '使徒行传', 44, 5, 25, '忽然有人来报告说：“你们押在监里的那些人，正站在殿里教导众民呢！”'),
('CNV', '使徒行传', 44, 5, 26, '于是守卫长和差役去带使徒来，不过没有用暴力，因为怕众民用石头打他们。'),
('CNV', '使徒行传', 44, 5, 27, '既然带来了，就叫他们站在公议会前。大祭司问他们：'),
('CNV', '使徒行传', 44, 5, 28, '“我们严厉地吩咐过你们，不准再奉这名教导。看，你们却把你们的道理传遍了耶路撒冷，想要把流这人的血的责任推到我们身上。”'),
('CNV', '使徒行传', 44, 5, 29, '彼得和众使徒回答：“服从神过于服从人，是应当的。'),
('CNV', '使徒行传', 44, 5, 30, '你们挂在木头上亲手杀害的耶稣，我们祖先的神已经使他复活了。'),
('CNV', '使徒行传', 44, 5, 31, '神把他高举在自己的右边，作元首作救主，把悔改的心赐给了以色列人，使他们罪得赦免。'),
('CNV', '使徒行传', 44, 5, 32, '我们为这些事作证，神赐给顺从的人的圣灵也为这些事作证。”'),
('CNV', '使徒行传', 44, 5, 33, '公议会的人听了，非常恼怒，就想要杀他们。'),
('CNV', '使徒行传', 44, 5, 34, '但有一个法利赛人，名叫迦玛列，是民众所尊敬的律法教师。他在公议会中站起来，吩咐人把使徒暂时带出去，'),
('CNV', '使徒行传', 44, 5, 35, '然后对大家说：“以色列人哪，你们应当小心处理这些人！'),
('CNV', '使徒行传', 44, 5, 36, '从前有个丢大，自命不凡，附从他的人约有四百。他一被杀，跟从他的人尽都星散，一败涂地。'),
('CNV', '使徒行传', 44, 5, 37, '这人之后，在户口登记的时候，又有一个加利利人犹大，拉拢人们来跟从他。后来他也丧命，跟从他的人也就烟消云散了。'),
('CNV', '使徒行传', 44, 5, 38, '至于目前的事，我劝你们不要管这些人，由他们吧！因为这计划或这行动，如果是出于人意，终必失败；'),
('CNV', '使徒行传', 44, 5, 39, '如果是出于神，你们就不能破坏他们，恐怕你们是与神作对了。”他们接受了他的劝告，'),
('CNV', '使徒行传', 44, 5, 40, '就传使徒进来，鞭打一顿，禁止他们奉耶稣的名传讲，就把他们释放了。'),
('CNV', '使徒行传', 44, 5, 41, '使徒欢欢喜喜从公议会里出来，因为他们算是配得为主的名受辱。'),
('CNV', '使徒行传', 44, 5, 42, '他们天天在殿里并在各人的家中，不断地教导，传讲耶稣是基督。'),
('CNV', '使徒行传', 44, 6, 1, '门徒不断增加的时候，讲希腊话的犹太人，埋怨本地的希伯来人，因为在日常的供给上，忽略了他们的寡妇。'),
('CNV', '使徒行传', 44, 6, 2, '于是十二使徒召集了众门徒，说：“要我们放下神的道，去管理伙食，是不合适的。'),
('CNV', '使徒行传', 44, 6, 3, '所以弟兄们，应当从你们中间选出七个有好见证、满有圣灵和智慧的人，我们就派他们负责这事。'),
('CNV', '使徒行传', 44, 6, 4, '至于我们，我们要专心祈祷、传道。”'),
('CNV', '使徒行传', 44, 6, 5, '这个意见全会众都很满意，于是选出司提反，他是一位满有信心和圣灵的人，还有腓利、伯罗哥罗、尼加挪、提门、巴米拿，以及归信犹太教的安提阿人尼哥拉，'),
('CNV', '使徒行传', 44, 6, 6, '叫他们站在使徒面前。使徒祷告后，就为他们按手。'),
('CNV', '使徒行传', 44, 6, 7, '神的道传开了；在耶路撒冷，门徒人数大大增加，有很多祭司也信从了真道。'),
('CNV', '使徒行传', 44, 6, 8, '司提反满有恩惠能力，在民间施行大奇事和神迹。'),
('CNV', '使徒行传', 44, 6, 9, '当时有几个称为“自由人”会堂的人，就是从古利奈和亚历山太来的人，另外还有基利家人和亚西亚人，他们出面与司提反辩论，'),
('CNV', '使徒行传', 44, 6, 10, '但司提反靠着圣灵和智慧说话，他们就抵挡不住。'),
('CNV', '使徒行传', 44, 6, 11, '于是他们唆使众人，说：“我们听过他说谤渎摩西和神的话。”'),
('CNV', '使徒行传', 44, 6, 12, '又煽动民众、长老、经学家，这些人就来捉拿他，把他带到公议会，'),
('CNV', '使徒行传', 44, 6, 13, '并且造了假的证供说：“这人不断抨击圣地和律法。'),
('CNV', '使徒行传', 44, 6, 14, '我们听他说过：‘这拿撒勒人耶稣要毁坏这地方，改变摩西传给我们的规例。’”'),
('CNV', '使徒行传', 44, 6, 15, '当时，坐在公议会里的人，都注视他，见他的面貌像天使一样。'),
('CNV', '使徒行传', 44, 7, 1, '大祭司说：“真有这些事吗？”'),
('CNV', '使徒行传', 44, 7, 2, '司提反说：“各位父老兄弟请听！我们的祖宗亚伯拉罕，在美索不达米亚，还没有住在哈兰的时候，荣耀的神向他显现，'),
('CNV', '使徒行传', 44, 7, 3, '对他说：‘你要离开本地本族，到我指示你的地方去。’'),
('CNV', '使徒行传', 44, 7, 4, '他就离开迦勒底人的地方，住在哈兰。他父亲死后，神又叫他从那里迁到你们现在所住的地方。'),
('CNV', '使徒行传', 44, 7, 5, '在这里神并没有赐他产业，连立足之地也没有。但神应许把这地赐给他和他的后裔为业，虽然那时他还没有儿子。'),
('CNV', '使徒行传', 44, 7, 6, '神就这样说：‘你的后裔必在外地寄居，人要奴役、虐待他们四百年。’'),
('CNV', '使徒行传', 44, 7, 7, '神又说：‘奴役他们的那个国家，我要亲自惩罚。以后，他们要出来，在这地方事奉我。’'),
('CNV', '使徒行传', 44, 7, 8, '神也赐他割礼为约。这样，亚伯拉罕生了以撒，第八天就给他行了割礼。后来，以撒生雅各，雅各生了十二位祖先。'),
('CNV', '使徒行传', 44, 7, 9, '“祖先妒忌约瑟，把他卖到埃及去，然而神与他同在，'),
('CNV', '使徒行传', 44, 7, 10, '救他脱离一切苦难，使他在埃及王法老面前，有智慧、得恩宠。法老立他为首相，管理埃及和法老的全家。'),
('CNV', '使徒行传', 44, 7, 11, '后来埃及和迦南全地遭遇饥荒、大灾难，我们的祖先找不到粮食。'),
('CNV', '使徒行传', 44, 7, 12, '雅各听见埃及有谷粮，就派我们的祖先去，这是第一次。'),
('CNV', '使徒行传', 44, 7, 13, '第二次的时候，约瑟就向哥哥们表露自己的身世，法老才知道约瑟的家世。'),
('CNV', '使徒行传', 44, 7, 14, '约瑟就派人去把他父亲雅各和全家七十五人都接来。'),
('CNV', '使徒行传', 44, 7, 15, '于是雅各下了埃及。后来他和我们祖先都死了，'),
('CNV', '使徒行传', 44, 7, 16, '运到示剑，埋葬在亚伯拉罕用银子向哈抹子孙买来的坟地里。'),
('CNV', '使徒行传', 44, 7, 17, '“神给亚伯拉罕的应许快要实现的时候，以色列人在埃及人口繁盛增多；'),
('CNV', '使徒行传', 44, 7, 18, '但是，到了另一位不认识约瑟的君王兴起统治埃及的时候，'),
('CNV', '使徒行传', 44, 7, 19, '他就谋害我们的同胞，虐待我们的祖先，逼他们抛弃自己的婴孩，不容婴孩存活。'),
('CNV', '使徒行传', 44, 7, 20, '就在那时候，摩西出生了，他非常俊美，在父亲的家中抚养了三个月。'),
('CNV', '使徒行传', 44, 7, 21, '他被抛弃的时候，法老的女儿把他拾起来，当作儿子抚养。'),
('CNV', '使徒行传', 44, 7, 22, '摩西学尽了埃及人的一切学问，说话行事都有能力。'),
('CNV', '使徒行传', 44, 7, 23, '“到了四十岁，他心中起了一个念头，要去看望自己的同胞以色列人。'),
('CNV', '使徒行传', 44, 7, 24, '当他看见有一个人受欺负，就去护卫，为那受屈的抱不平，打死了那个埃及人。'),
('CNV', '使徒行传', 44, 7, 25, '他以为同胞们都必知道神要藉着他的手拯救他们，事实上他们却不知道。'),
('CNV', '使徒行传', 44, 7, 26, '第二天，有人在打架，摩西就出面调解，说：‘你们是弟兄，为什么彼此欺负呢？’'),
('CNV', '使徒行传', 44, 7, 27, '那欺负邻舍的把他推开，说：‘谁立了你作我们的领袖和审判官呢？'),
('CNV', '使徒行传', 44, 7, 28, '难道你想杀我，像昨天杀那个埃及人一样吗？’'),
('CNV', '使徒行传', 44, 7, 29, '摩西因为这句话，就逃到米甸地寄居，在那里生了两个儿子。'),
('CNV', '使徒行传', 44, 7, 30, '“过了四十年，在西奈山的旷野，有一位使者，在荆棘中的火焰里，向摩西显现。'),
('CNV', '使徒行传', 44, 7, 31, '他见了这个异象，十分惊奇；他正上前察看的时候，就有主的声音说：'),
('CNV', '使徒行传', 44, 7, 32, '‘我是你祖宗的神，就是亚伯拉罕、以撒、雅各的神。’摩西战战兢兢，不敢观看。'),
('CNV', '使徒行传', 44, 7, 33, '主对他说：‘把你脚上的鞋脱掉，因为你所站的地方是圣地。'),
('CNV', '使徒行传', 44, 7, 34, '我的子民在埃及所受的痛苦，我实在看见了；他们的叹息我也听见了，我下来是要救他们。你来，我要派你到埃及去。’'),
('CNV', '使徒行传', 44, 7, 35, '他们拒绝了这位摩西，说：‘谁立了你作领袖和审判官呢？’但神藉着在荆棘中向他显现的使者的手，派他作领袖和救赎者。'),
('CNV', '使徒行传', 44, 7, 36, '这人领他们出来，并且在埃及地、红海和旷野，行奇事神迹四十年。'),
('CNV', '使徒行传', 44, 7, 37, '以前那位对以色列人说‘神要从你们弟兄中间，给你们兴起一位先知像我’的，就是这摩西。'),
('CNV', '使徒行传', 44, 7, 38, '那曾经在旷野的大会中，和那在西奈山上对他说话的使者同在，也与我们的祖先同在的，就是他。他领受了活的圣言，传给我们。'),
('CNV', '使徒行传', 44, 7, 39, '我们的祖先不肯听从他，反而把他推开，他们的心已经转向了埃及，'),
('CNV', '使徒行传', 44, 7, 40, '就对亚伦说：‘给我们做一些神像，可以走在我们前头。因为把我们从埃及地领出来的那个摩西，我们不知道他遭遇了什么事。’'),
('CNV', '使徒行传', 44, 7, 41, '在那些日子里，他们做了一个牛犊，把祭物献给那偶像，并且因自己手所做的而欢乐。'),
('CNV', '使徒行传', 44, 7, 42, '于是神转身离开，任凭他们事奉天象，正如先知书所说：‘以色列家啊，你们在旷野四十年，岂是将祭牲和祭物献给我呢？'),
('CNV', '使徒行传', 44, 7, 43, '你们抬着摩洛的帐幕，和理番神的星，就是你们做来敬拜的像。所以我要把你们放逐到巴比伦那一边去。’'),
('CNV', '使徒行传', 44, 7, 44, '“我们的祖先在旷野有作证的帐幕，就是跟摩西谈话的那位指示他，依照他看见的样式做的。'),
('CNV', '使徒行传', 44, 7, 45, '我们的祖先相继承受了这帐幕，神把外族人从他们面前赶走以后，他们就同约书亚把帐幕带进所得为业的地方，直到大卫的日子。'),
('CNV', '使徒行传', 44, 7, 46, '大卫在神面前蒙了恩，就求为雅各的神找个居所，'),
('CNV', '使徒行传', 44, 7, 47, '而由所罗门为他建造殿宇。'),
('CNV', '使徒行传', 44, 7, 48, '其实至高者并不住人手所造的，正如先知说：'),
('CNV', '使徒行传', 44, 7, 49, '‘主说：天是我的宝座，地是我的脚凳，你们要为我建造怎样的殿呢？哪里是我安息的地方呢？'),
('CNV', '使徒行传', 44, 7, 50, '这一切不都是我手所造的吗？’'),
('CNV', '使徒行传', 44, 7, 51, '“你们颈项刚硬、心和耳都未受割礼的人哪！你们时常抗拒圣灵，你们的祖先怎样，你们也怎样。'),
('CNV', '使徒行传', 44, 7, 52, '有哪一个先知，你们的祖先不迫害呢？你们杀了那些预先宣告那义者要来的人，现在又把那义者出卖了，杀害了。'),
('CNV', '使徒行传', 44, 7, 53, '你们领受了由天使传达的律法，却不遵守。”'),
('CNV', '使徒行传', 44, 7, 54, '众人听了这些话，心中非常恼怒，就向着司提反咬牙切齿。'),
('CNV', '使徒行传', 44, 7, 55, '但司提反被圣灵充满，定睛望着天，看见神的荣耀，并且看见耶稣站在神的右边，'),
('CNV', '使徒行传', 44, 7, 56, '就说：“看哪！我看见天开了，人子站在神的右边。”'),
('CNV', '使徒行传', 44, 7, 57, '众人大声喊叫，掩着耳朵，一齐向他冲过去，'),
('CNV', '使徒行传', 44, 7, 58, '把他推出城外，用石头打他。那些证人把自己的衣服，放在一个名叫扫罗的青年人脚前。'),
('CNV', '使徒行传', 44, 7, 59, '他们用石头打司提反的时候，他呼求说：“主耶稣啊，求你接收我的灵魂！”'),
('CNV', '使徒行传', 44, 7, 60, '然后跪下来大声喊着说：“主啊，不要把这罪归给他们！”说了这话，就睡了。'),
('CNV', '使徒行传', 44, 8, 1, '司提反被害，扫罗也欣然同意。从那天起，耶路撒冷的教会大受迫害；除了使徒以外，所有的人都分散到犹太和撒玛利亚各地。'),
('CNV', '使徒行传', 44, 8, 2, '有些虔诚的人安葬了司提反，为他大大悲痛一番。'),
('CNV', '使徒行传', 44, 8, 3, '扫罗却残害教会，逐家进去，连男带女拉去坐监。'),
('CNV', '使徒行传', 44, 8, 4, '那些分散的人，经过各地，传扬福音真道。'),
('CNV', '使徒行传', 44, 8, 5, '腓利下到撒玛利亚城，宣讲基督。'),
('CNV', '使徒行传', 44, 8, 6, '群众听了腓利所讲的，看见他所行的神迹，就同心听从了他的话。'),
('CNV', '使徒行传', 44, 8, 7, '许多人有污灵附在他们身上，污灵大声喊叫了之后，就出来了；还有许多瘫子瘸子都医好了。'),
('CNV', '使徒行传', 44, 8, 8, '在那城里，就大有欢乐。'),
('CNV', '使徒行传', 44, 8, 9, '有一个人名叫西门，从前在城里行过邪术，使撒玛利亚的居民惊奇，他又自命不凡，'),
('CNV', '使徒行传', 44, 8, 10, '城里大大小小都听从他，说：“这就是那称为‘神的大能’的人。”'),
('CNV', '使徒行传', 44, 8, 11, '他们听从他，因为他长久用邪术，使他们惊奇。'),
('CNV', '使徒行传', 44, 8, 12, '等到腓利向他们传了神的国的福音，和耶稣基督的名，他们就信了腓利，连男带女都受了洗。'),
('CNV', '使徒行传', 44, 8, 13, '连西门自己也信了，他受洗之后，常和腓利在一起，看见所发生的神迹和大能的事，就觉得很惊奇。'),
('CNV', '使徒行传', 44, 8, 14, '在耶路撒冷的使徒，听见撒玛利亚居民领受了神的道，就差派彼得和约翰到他们那里去。'),
('CNV', '使徒行传', 44, 8, 15, '二人到了，就为大家祷告，要让他们接受圣灵。'),
('CNV', '使徒行传', 44, 8, 16, '因为圣灵还没有降在他们任何一个身上，他们只是受了洗归入主耶稣的名下。'),
('CNV', '使徒行传', 44, 8, 17, '于是使徒为他们按手，他们就受了圣灵。'),
('CNV', '使徒行传', 44, 8, 18, '西门看见使徒一按手，就有圣灵赐下来，就拿钱给他们，'),
('CNV', '使徒行传', 44, 8, 19, '说：“请把这权柄也给我，叫我为谁按手，谁就可以受圣灵。”'),
('CNV', '使徒行传', 44, 8, 20, '彼得对他说：“你的银子跟你一同灭亡吧！因为你以为神的恩赐，是可以用钱买的。'),
('CNV', '使徒行传', 44, 8, 21, '你和这件事是毫无关系的，因为你在神面前存心不正。'),
('CNV', '使徒行传', 44, 8, 22, '所以，你要悔改离弃这罪恶，要祈求主，也许你心中的意念可以得到赦免。'),
('CNV', '使徒行传', 44, 8, 23, '我看出你正在苦胆之中，邪恶捆绑着你。”'),
('CNV', '使徒行传', 44, 8, 24, '西门回答：“请你们为我求主，好让你们所说的，没有一样临到我身上。”'),
('CNV', '使徒行传', 44, 8, 25, '使徒作了见证，讲了主的道，就回耶路撒冷去，一路上在撒玛利亚人的许多村庄里传扬福音。'),
('CNV', '使徒行传', 44, 8, 26, '有主的一位使者对腓利说：“起来，向南走，往那从耶路撒冷下迦萨的路上去。”那条路在旷野里。'),
('CNV', '使徒行传', 44, 8, 27, '他就动身去了。有一个衣索匹亚人，是衣索匹亚女王干大基有权力的太监，掌管女王全部国库。他上耶路撒冷去礼拜。'),
('CNV', '使徒行传', 44, 8, 28, '他回去的时候，坐在车上读以赛亚先知的书。'),
('CNV', '使徒行传', 44, 8, 29, '圣灵对腓利说：“你往前去，靠近那车子！”'),
('CNV', '使徒行传', 44, 8, 30, '腓利就跑过去，听见他读以赛亚先知的书，就问他：“你所读的，你明白吗？”'),
('CNV', '使徒行传', 44, 8, 31, '他说：“没有人指导我，怎能明白呢？”于是请腓利上车，同他坐在一起。'),
('CNV', '使徒行传', 44, 8, 32, '他所读的那段经文，就是：“他像羊被牵去宰杀，又像羊羔在剪毛的人面前无声，他总是这样不开口。'),
('CNV', '使徒行传', 44, 8, 33, '他受屈辱的时候，得不到公平的审判，谁能说出他的身世呢？因为他的生命从地上被夺去。”'),
('CNV', '使徒行传', 44, 8, 34, '太监对腓利说：“请问先知这话是指谁说的？指他自己呢？还是指别人？”'),
('CNV', '使徒行传', 44, 8, 35, '腓利就开口，从这段经文开始，向他传讲耶稣。'),
('CNV', '使徒行传', 44, 8, 36, '他们一路走，到了有水的地方，太监说：“你看，这里有水，有什么可以阻止我受洗呢？”（有些抄本在此有第'),
('CNV', '使徒行传', 44, 8, 37, '节：“腓利说：‘你若全心相信，就可以受洗。’他回答说：‘我信耶稣基督是神的儿子。’”）'),
('CNV', '使徒行传', 44, 8, 38, '于是太监吩咐停车，腓利和他两人下到水中，腓利就给他施洗。'),
('CNV', '使徒行传', 44, 8, 39, '他们从水里上来的时候，主的灵就把腓利提去了，太监再也看不见他，就欢欢喜喜地上路。'),
('CNV', '使徒行传', 44, 8, 40, '后来有人在亚锁都遇见腓利。他走遍各城，传讲福音，直到该撒利亚。'),
('CNV', '使徒行传', 44, 9, 1, '扫罗仍向主的门徒发恐吓凶杀的话。他到大祭司那里，'),
('CNV', '使徒行传', 44, 9, 2, '要求他发公函给大马士革各会堂，如果发现奉行这道的人，准他连男带女缉拿到耶路撒冷。'),
('CNV', '使徒行传', 44, 9, 3, '他快到大马士革的时候，忽然有光从天上向他四面照射。'),
('CNV', '使徒行传', 44, 9, 4, '他仆倒在地，听见有声音对他说：“扫罗，扫罗！你为什么迫害我？”'),
('CNV', '使徒行传', 44, 9, 5, '他说：“主啊，你是谁？”主说：“我就是你所迫害的耶稣。'),
('CNV', '使徒行传', 44, 9, 6, '起来，进城去！你应当作的事，一定有人告诉你。”'),
('CNV', '使徒行传', 44, 9, 7, '同行的人，听见声音，却看不见人，只是目瞪口呆地站在那里。'),
('CNV', '使徒行传', 44, 9, 8, '扫罗从地上爬起来，睁开眼睛，却什么也看不见。他们牵着他的手，领他进大马士革。'),
('CNV', '使徒行传', 44, 9, 9, '他三天都不能看见什么，不吃也不喝。'),
('CNV', '使徒行传', 44, 9, 10, '在大马士革，有一个门徒名叫亚拿尼亚，主在异象中对他说：“亚拿尼亚！”他说：“主啊，我在这里。”'),
('CNV', '使徒行传', 44, 9, 11, '主说：“起来，到那叫直街的路上去，要在犹大家里找一个大数人，名叫扫罗。你看，他正在祷告，'),
('CNV', '使徒行传', 44, 9, 12, '在异象中他看见一个人，名叫亚拿尼亚，进来为他按手，使他可以再看得见。”'),
('CNV', '使徒行传', 44, 9, 13, '但亚拿尼亚回答：“主啊，我听见许多人说起这个人，他在耶路撒冷作了许多苦害你圣徒的事；'),
('CNV', '使徒行传', 44, 9, 14, '并且他在这里得到祭司长的授权，要捆绑所有求告你名的人。”'),
('CNV', '使徒行传', 44, 9, 15, '主对他说：“你去吧！这人是我拣选的器皿，为要把我的名传给外族人、君王和以色列人。'),
('CNV', '使徒行传', 44, 9, 16, '我要指示他，为了我的名他必须受许多的苦。”'),
('CNV', '使徒行传', 44, 9, 17, '亚拿尼亚就去了，进了那家，为扫罗按手，说：“扫罗弟兄，在你来的路上向你显现的耶稣，就是主，差我来使你可以看见，又被圣灵充满。”'),
('CNV', '使徒行传', 44, 9, 18, '立刻有鳞状的东西，从扫罗的眼里掉下来，他就能看见了。于是起来，受了洗，'),
('CNV', '使徒行传', 44, 9, 19, '吃过了饭，就有气力了。他和大马士革的门徒一同住了几天，'),
('CNV', '使徒行传', 44, 9, 20, '随即在各会堂传讲耶稣，说他是神的儿子。'),
('CNV', '使徒行传', 44, 9, 21, '听见的人都很惊奇，说：“在耶路撒冷残害求告这名的，不是这个人吗？他来这里不是要缉拿他们交给祭司长吗？”'),
('CNV', '使徒行传', 44, 9, 22, '然而扫罗更加有能力，驳倒住在大马士革的犹太人，证明耶稣是基督。'),
('CNV', '使徒行传', 44, 9, 23, '过了许多日子，犹太人商议要杀掉扫罗；'),
('CNV', '使徒行传', 44, 9, 24, '但他们的计谋给扫罗知道了。他们就在各城门日夜把守，要杀掉他。'),
('CNV', '使徒行传', 44, 9, 25, '于是他的门徒就趁夜用大篮子把他从城墙上缒下去。'),
('CNV', '使徒行传', 44, 9, 26, '扫罗到了耶路撒冷，想要接近门徒，但大家都怕他，不信他是个门徒。'),
('CNV', '使徒行传', 44, 9, 27, '只有巴拿巴接待他，带他去见使徒，把他怎样在路上看见主，主向他说话，和他怎样在大马士革奉耶稣的名放胆讲道，都讲了出来。'),
('CNV', '使徒行传', 44, 9, 28, '于是扫罗在耶路撒冷和门徒一同出入，奉主的名放胆讲道，'),
('CNV', '使徒行传', 44, 9, 29, '并且与讲希腊话的犹太人谈论辩驳，那些人却想下手杀他。'),
('CNV', '使徒行传', 44, 9, 30, '弟兄们知道了，就送他到该撒利亚，差他往大数去。'),
('CNV', '使徒行传', 44, 9, 31, '那时犹太、加利利、撒玛利亚各处的教会，都得到平安，被建立起来，存着敬畏主的心过生活，并且因着圣灵的激励，人数增多起来。'),
('CNV', '使徒行传', 44, 9, 32, '彼得周游各地的时候，也到了住在吕大的圣徒那里。'),
('CNV', '使徒行传', 44, 9, 33, '他遇见一个人，名叫以尼雅，害了瘫痪病，在床上躺卧了八年。'),
('CNV', '使徒行传', 44, 9, 34, '彼得对他说：“以尼雅，耶稣基督医好你了！起来，收好你的褥子！”他就立刻起来。'),
('CNV', '使徒行传', 44, 9, 35, '所有住在吕大和沙仑的人，看见了他就归向主。'),
('CNV', '使徒行传', 44, 9, 36, '在约帕有一个女门徒，名叫戴比莎，希腊话叫多加；她为人乐善好施。'),
('CNV', '使徒行传', 44, 9, 37, '那时，她因病死了；有人把她洗净了，停放在楼上。'),
('CNV', '使徒行传', 44, 9, 38, '吕大靠近约帕，门徒听说彼得在那边，就派两个人去求他，说：“请到我们那边去，不要耽延！”'),
('CNV', '使徒行传', 44, 9, 39, '彼得就动身，跟他们一同去。到了之后，他们领他上楼。所有寡妇站在彼得旁边哭，把多加和她们在一起的时候所做的内衣外衣拿给他看。'),
('CNV', '使徒行传', 44, 9, 40, '彼得叫大家出去之后，就跪下来祷告，然后转过身来对着尸体说：“戴比莎，起来！”她就睁开眼睛，一看见彼得，就坐了起来。'),
('CNV', '使徒行传', 44, 9, 41, '彼得伸手扶她起来，叫圣徒们和寡妇都进来，把多加活活地交给他们。'),
('CNV', '使徒行传', 44, 9, 42, '这事传遍了约帕，就有很多人信了主。'),
('CNV', '使徒行传', 44, 9, 43, '此后，彼得在约帕一个制皮工人西门的家里住了许多日子。'),
('CNV', '使徒行传', 44, 10, 1, '在该撒利亚有一个人，名叫哥尼流，是意大利营的百夫长。'),
('CNV', '使徒行传', 44, 10, 2, '他是一个虔诚的人，他和全家都敬畏神，对人民行过许多善事，常常向神祷告。'),
('CNV', '使徒行传', 44, 10, 3, '有一天，大约下午三点钟，他在异象中，清清楚楚看见神的一位天使来到他那里，对他说：“哥尼流！”'),
('CNV', '使徒行传', 44, 10, 4, '他定睛一看，害怕起来，说：“主啊，什么事？”天使说：“你的祷告和善行，已经达到神面前，蒙他记念了。'),
('CNV', '使徒行传', 44, 10, 5, '现在你要派人到约帕去，请那个名叫彼得的西门来。'),
('CNV', '使徒行传', 44, 10, 6, '他在一个制皮工人西门的家里作客，房子就在海边。”'),
('CNV', '使徒行传', 44, 10, 7, '和他说话的天使走了之后，他就叫了两个家仆和侍候他的一个虔诚的士兵来，'),
('CNV', '使徒行传', 44, 10, 8, '把一切事向他们讲明，然后派他们到约帕去。'),
('CNV', '使徒行传', 44, 10, 9, '第二天，大约正午，他们走近那座城的时候，彼得上了房顶去祷告。'),
('CNV', '使徒行传', 44, 10, 10, '那家人正在预备饭的时候，彼得觉得饿了，很想吃饭。这时候他魂游象外，'),
('CNV', '使徒行传', 44, 10, 11, '看见天开了，有一件东西，好像一块大布，绑着四角，降在地上。'),
('CNV', '使徒行传', 44, 10, 12, '里面有地上的各样四足牲畜，还有昆虫和天空的飞鸟。'),
('CNV', '使徒行传', 44, 10, 13, '有声音对他说：“彼得，起来，宰了吃！”'),
('CNV', '使徒行传', 44, 10, 14, '彼得说：“主啊，千万不可！我从来不吃俗物和不洁的东西。”'),
('CNV', '使徒行传', 44, 10, 15, '第二次又有声音对他说：“神所洁净的，你不可当作俗物。”'),
('CNV', '使徒行传', 44, 10, 16, '这样一连三次，那件东西就立刻收回天上去了。'),
('CNV', '使徒行传', 44, 10, 17, '彼得犹豫不定，不明白所看见的异象是什么意思，恰好哥尼流派来的人，找到西门的家，站在门口，'),
('CNV', '使徒行传', 44, 10, 18, '大声问：“有没有一个名叫彼得的西门在这里作客？”'),
('CNV', '使徒行传', 44, 10, 19, '彼得还在思量那异象，圣灵对他说：“你看，有三个人来找你！'),
('CNV', '使徒行传', 44, 10, 20, '起来，下去吧，跟他们一起去，不要疑惑，因为是我差他们来的。”'),
('CNV', '使徒行传', 44, 10, 21, '于是彼得下楼到他们那里，说：“看，我就是你们所要找的人。你们是为什么来的？”'),
('CNV', '使徒行传', 44, 10, 22, '他们说：“百夫长哥尼流是个义人，敬畏神，全犹太族都称赞他。他得到一位圣天使的指示，请你到他家里，要听你的话。”'),
('CNV', '使徒行传', 44, 10, 23, '彼得就请他们进去，留他们住下。第二天，彼得动身跟他们一同去，另有约帕的几位弟兄同行。'),
('CNV', '使徒行传', 44, 10, 24, '第三天，他们到了该撒利亚。哥尼流已经招聚了自己的亲戚好友在恭候他们。'),
('CNV', '使徒行传', 44, 10, 25, '彼得一进去，哥尼流就迎接他，俯伏在他脚前叩拜。'),
('CNV', '使徒行传', 44, 10, 26, '彼得扶起他，说：“起来，我也是人。”'),
('CNV', '使徒行传', 44, 10, 27, '彼得和他说了话，就进去，看见许多人聚集在那里，'),
('CNV', '使徒行传', 44, 10, 28, '就对他们说：“你们知道，犹太人本来是不准和外国人接近来往的，但神已经指示了我，不可把任何人当作凡俗或不洁的。'),
('CNV', '使徒行传', 44, 10, 29, '所以我一被邀请，就毫不推辞地来了。现在请问：你们请我来是为什么事？”'),
('CNV', '使徒行传', 44, 10, 30, '哥尼流说：“四天以前下午三点钟，我在家里祷告的时候，忽然有一位身穿光明衣服的人，站在我面前，'),
('CNV', '使徒行传', 44, 10, 31, '说：‘哥尼流，你的祷告已蒙垂听，你的善行在神面前已蒙记念。'),
('CNV', '使徒行传', 44, 10, 32, '你要派人到约帕去，请那个名叫彼得的西门来。他在海边一个制皮工人西门的家作客。’'),
('CNV', '使徒行传', 44, 10, 33, '所以我立刻派人去请你，现在你来了，好极了！我们都在神面前，要听主吩咐你的一切话。”'),
('CNV', '使徒行传', 44, 10, 34, '彼得就开口说：“我实在看出神是不偏待人的。'),
('CNV', '使徒行传', 44, 10, 35, '原来在各民族中，凡敬畏他而行义的，都蒙他悦纳。'),
('CNV', '使徒行传', 44, 10, 36, '神藉着耶稣基督（他是万有的主）传和平的福音，把这道传给以色列人。'),
('CNV', '使徒行传', 44, 10, 37, '你们知道：在约翰传讲洗礼之后，这道从加利利传遍了犹太，'),
('CNV', '使徒行传', 44, 10, 38, '并且知道神怎样用圣灵和能力膏立拿撒勒人耶稣。他到各处行善事，医好所有被魔鬼压制的人，因为神与他同在。'),
('CNV', '使徒行传', 44, 10, 39, '我们就是他在犹太人之地和耶路撒冷所行一切事的见证人；他们竟然把他挂在木头上，杀了他。'),
('CNV', '使徒行传', 44, 10, 40, '神叫他第三天复活，并且使他显现，'),
('CNV', '使徒行传', 44, 10, 41, '不是显现给所有的人看，而是给神预先拣选的见证人看，就是我们这些在他从死人中复活之后，与他一同吃喝的人。'),
('CNV', '使徒行传', 44, 10, 42, '他吩咐我们向人民传讲，郑重证明他是神所立，审判活人死人的主。'),
('CNV', '使徒行传', 44, 10, 43, '所有先知都为他作见证：所有信他的，都必藉着他的名，罪得赦免。”'),
('CNV', '使徒行传', 44, 10, 44, '彼得还在说话的时候，圣灵降在所有听道的人身上，'),
('CNV', '使徒行传', 44, 10, 45, '那些受了割礼、跟彼得一同来的信徒，因为圣灵的恩赐（“恩赐”或译：“恩赏”）也浇灌在外族人的身上，都很惊讶；'),
('CNV', '使徒行传', 44, 10, 46, '原来听见他们讲方言，尊神为大。于是彼得说：'),
('CNV', '使徒行传', 44, 10, 47, '“这些人既然领受了圣灵，跟我们一样，谁能禁止他们受水的洗礼呢？”'),
('CNV', '使徒行传', 44, 10, 48, '就吩咐他们奉耶稣基督的名受洗。后来，他们请彼得住了几天。'),
('CNV', '使徒行传', 44, 11, 1, '使徒和在犹太的弟兄们，听说外族人也接受了神的道。'),
('CNV', '使徒行传', 44, 11, 2, '彼得上到耶路撒冷的时候，那些守割礼的人与他争论，'),
('CNV', '使徒行传', 44, 11, 3, '说：“你竟然到未受割礼的人那里，跟他们一起吃饭！”'),
('CNV', '使徒行传', 44, 11, 4, '彼得就按着次序向他们讲解，说：'),
('CNV', '使徒行传', 44, 11, 5, '“我在约帕城祷告的时候，魂游象外，见到异象：有一件东西，好像一块大布，绑着四角，从天上降下来，一直来到我面前。'),
('CNV', '使徒行传', 44, 11, 6, '我定睛观察，看见里面有地上的四足牲畜、走兽，还有昆虫和天空的飞鸟。'),
('CNV', '使徒行传', 44, 11, 7, '我也听见有声音对我说：‘彼得，起来，宰了吃！’'),
('CNV', '使徒行传', 44, 11, 8, '我说：‘主啊，千万不可，因为俗物或不洁的东西，从来没有进过我的口。’'),
('CNV', '使徒行传', 44, 11, 9, '第二次又有声音从天上回答：‘神所洁净的，你不可当作俗物。’'),
('CNV', '使徒行传', 44, 11, 10, '这样一连三次之后，所有的东西都拉回天上去了。'),
('CNV', '使徒行传', 44, 11, 11, '就在那个时候，有三个从该撒利亚派到我这里来的人，站在我住的房子门前。'),
('CNV', '使徒行传', 44, 11, 12, '圣灵吩咐我跟他们一起去，一点也不要疑惑。这六位弟兄也跟我一起去，我们就进了那人的家。'),
('CNV', '使徒行传', 44, 11, 13, '他告诉我们，他怎样看见天使站在他家里说：‘派人到约帕去，请那个名叫彼得的西门来，'),
('CNV', '使徒行传', 44, 11, 14, '他有话要告诉你，使你和你全家都可以得救。’'),
('CNV', '使徒行传', 44, 11, 15, '我一开始讲话，圣灵就降在他们身上，正像当初降在我们身上一样。'),
('CNV', '使徒行传', 44, 11, 16, '我就想起主所说的话：‘约翰用水施洗，但你们要受圣灵的洗。’'),
('CNV', '使徒行传', 44, 11, 17, '神既然把同样的恩赐（“恩赐”或译：“恩赏”）给他们，像给我们这些信了主耶稣基督的人一样，我是谁，我能够阻止神吗？”'),
('CNV', '使徒行传', 44, 11, 18, '众人听见这些话，就默然无声，把荣耀归给神，说：“这样看来，神也把悔改的心赐给外族人，使他们得生命。”'),
('CNV', '使徒行传', 44, 11, 19, '那些因司提反事件遭受苦难而四散的门徒，一直走到腓尼基、塞浦路斯、安提阿；他们不对别人传讲，只对犹太人传讲。'),
('CNV', '使徒行传', 44, 11, 20, '但其中有些塞浦路斯人和古利奈人，来到安提阿，也对希腊人传讲主耶稣。'),
('CNV', '使徒行传', 44, 11, 21, '主的手与他们同在，信而归主的人就多起来。'),
('CNV', '使徒行传', 44, 11, 22, '这事传到耶路撒冷教会的耳中，他们就派巴拿巴到安提阿去。'),
('CNV', '使徒行传', 44, 11, 23, '他到了那里，看见神所施的恩，就很欢喜，劝勉众人坚心靠主。'),
('CNV', '使徒行传', 44, 11, 24, '巴拿巴是个好人，满有圣灵和信心，于是许多人归了主。'),
('CNV', '使徒行传', 44, 11, 25, '后来他到大数去找扫罗，'),
('CNV', '使徒行传', 44, 11, 26, '找到了，就带他来安提阿。足足有一年，他们一同在教会聚集，教导了许多人。门徒称为基督徒，是从安提阿开始的。'),
('CNV', '使徒行传', 44, 11, 27, '那时，有几位先知从耶路撒冷下到安提阿。'),
('CNV', '使徒行传', 44, 11, 28, '其中有一个名叫亚迦布的站起来，藉着圣灵指出天下将要有大饥荒；这事在革老丢时期果然发生了。'),
('CNV', '使徒行传', 44, 11, 29, '于是门徒决定按着各人的力量捐款，好送给住在犹太的弟兄。'),
('CNV', '使徒行传', 44, 11, 30, '他们就这样行了，由巴拿巴和扫罗经手送到长老们那里。'),
('CNV', '使徒行传', 44, 12, 1, '那时，希律王下手苦害教会中的几个人，'),
('CNV', '使徒行传', 44, 12, 2, '用刀杀了约翰的哥哥雅各。'),
('CNV', '使徒行传', 44, 12, 3, '他见这事博得了犹太人的欢心，就在除酵节期间，再次捉拿彼得。'),
('CNV', '使徒行传', 44, 12, 4, '捉到了，就把他关在监里，交给四班士兵看守，每班四个人，打算过了逾越节，把他提出来交给民众。'),
('CNV', '使徒行传', 44, 12, 5, '彼得就这样被拘留在监里；但教会却为他迫切地祈求神。'),
('CNV', '使徒行传', 44, 12, 6, '希律要提他出来的前一夜，彼得被两条锁链锁住，睡在两个士兵中间，还有卫兵守在门前。'),
('CNV', '使徒行传', 44, 12, 7, '忽然，有主的一位使者出现，牢房里就光芒四射。天使拍拍彼得的肋旁，唤醒他，说：“快起来！”他手上的锁链就脱落了。'),
('CNV', '使徒行传', 44, 12, 8, '天使对他说：“束上带子，穿上鞋！”他就这样作了。天使又说：“披上外衣，跟我走！”'),
('CNV', '使徒行传', 44, 12, 9, '他就出来跟着天使走，但他不知道天使所作的事是真的，还以为是见了异象。'),
('CNV', '使徒行传', 44, 12, 10, '他们经过第一、第二两个岗位，来到通往城内的铁门，那门自动给他们开了。他们出来，往前走了一条街，天使立刻离开了他。'),
('CNV', '使徒行传', 44, 12, 11, '彼得清醒过来，说：“现在我确实知道，主差他的天使来，救我脱离希律的手和犹太人所期望的一切。”'),
('CNV', '使徒行传', 44, 12, 12, '他明白了之后，就到约翰（别名马可）的母亲马利亚家里去；有许多人聚集在那里祷告。'),
('CNV', '使徒行传', 44, 12, 13, '彼得敲了大门，有一个名叫罗大的使女，出来应门。'),
('CNV', '使徒行传', 44, 12, 14, '她认出是彼得的声音，欢喜到顾不得开门，就跑进去报告，说彼得站在门外。'),
('CNV', '使徒行传', 44, 12, 15, '大家说：“你疯了！”她却坚持地说这是真的。他们说：“一定是他的天使。”'),
('CNV', '使徒行传', 44, 12, 16, '彼得继续敲门；他们打开了，一见是他，就非常惊讶。'),
('CNV', '使徒行传', 44, 12, 17, '彼得作了一个手势，要他们安静，然后对他们述说主怎样领他出监，又说：“你们把这些事告诉雅各和众弟兄。”就离开那里，到别的地方去了。'),
('CNV', '使徒行传', 44, 12, 18, '天亮的时候，士兵们非常慌乱，不知彼得出了什么事。'),
('CNV', '使徒行传', 44, 12, 19, '希律搜索他，却找不到，就审问卫兵，下令把他们带出去处死。后来希律离开犹太，到该撒利亚去，住在那里。'),
('CNV', '使徒行传', 44, 12, 20, '当时希律对推罗和西顿人怀怒在心。这两地的人因为他们的地区都需要从王的领土得到粮食，就先拉拢了王的内侍臣伯拉斯都，然后同心地去见希律，要向他求和。'),
('CNV', '使徒行传', 44, 12, 21, '到了定好的日期，希律穿上王服，坐在高台上，向他们演讲。'),
('CNV', '使徒行传', 44, 12, 22, '群众大声说：“这是神的声音，不是人的声音！”'),
('CNV', '使徒行传', 44, 12, 23, '他不归荣耀给神，所以主的使者立刻击打他，他被虫咬，就断了气。'),
('CNV', '使徒行传', 44, 12, 24, '神的道日渐兴旺，越发广传。'),
('CNV', '使徒行传', 44, 12, 25, '巴拿巴和扫罗完成了送交捐项的任务，就带著名叫马可的约翰，从耶路撒冷回来。'),
('CNV', '使徒行传', 44, 13, 1, '安提阿教会中，有几位先知和教师，就是巴拿巴、名叫尼结的西面、古利奈人路求、与分封王希律一同长大的马念，和扫罗。'),
('CNV', '使徒行传', 44, 13, 2, '他们事奉主，并且禁食的时候，圣灵说：“要为我把巴拿巴和扫罗分别出来，去作我呼召他们作的工。”'),
('CNV', '使徒行传', 44, 13, 3, '于是他们禁食祷告，为两人按手，就派他们去了。'),
('CNV', '使徒行传', 44, 13, 4, '他们既然奉圣灵差遣，就下到西流基，从那里坐船往塞浦路斯。'),
('CNV', '使徒行传', 44, 13, 5, '他们到了撒拉米，就在犹太人的各会堂里宣讲神的道，还有约翰作他们的助手。'),
('CNV', '使徒行传', 44, 13, 6, '他们走遍全岛，到了帕弗，遇见一个犹太人，名叫巴．耶稣，是个术士，又是个假先知。'),
('CNV', '使徒行传', 44, 13, 7, '他常常和省长士求．保罗在一起；省长是个聪明人，他请了巴拿巴和扫罗来，要听听神的道。'),
('CNV', '使徒行传', 44, 13, 8, '但术士以吕马（以吕马就是“术士”的意思）与使徒作对，要使省长转离真道。'),
('CNV', '使徒行传', 44, 13, 9, '扫罗，也就是保罗，却被圣灵充满，定睛看着他，'),
('CNV', '使徒行传', 44, 13, 10, '说：“你这充满各样诡诈和各样奸恶的人，魔鬼的儿子，公义的仇敌！你歪曲了主的正路，还不停止吗？'),
('CNV', '使徒行传', 44, 13, 11, '你看，现在主的手临到你，你要瞎了眼睛，暂时看不见阳光。”他就立刻被雾和黑暗笼罩着，周围找人牵他的手，给他领路。'),
('CNV', '使徒行传', 44, 13, 12, '那时，省长看见了所发生的事，就信了，因为他惊奇主的教训。'),
('CNV', '使徒行传', 44, 13, 13, '保罗和同伴从帕弗开船，来到旁非利亚的别加，约翰却离开他们，回耶路撒冷去了。'),
('CNV', '使徒行传', 44, 13, 14, '他们从别加往前走，到了彼西底的安提阿，在安息日进了会堂，就坐下来。'),
('CNV', '使徒行传', 44, 13, 15, '宣读了律法和先知书以后，会堂的理事们派人到他们那里来，说：“弟兄们，如果有什么劝勉众人的话，请说吧！”'),
('CNV', '使徒行传', 44, 13, 16, '保罗就站起来，作了一个手势，说：“以色列人和敬畏神的人，请听！'),
('CNV', '使徒行传', 44, 13, 17, '以色列民的神，拣选了我们的祖先；当他们在埃及地寄居的时候，神抬举这民，用大能（“大能”原文作“高”）的膀臂，把他们从那地领出来；'),
('CNV', '使徒行传', 44, 13, 18, '又在旷野容忍（“容忍”有些抄本作“养育”）他们，约有四十年之久；'),
('CNV', '使徒行传', 44, 13, 19, '灭了迦南地的七族之后，就把那地分给他们为业；'),
('CNV', '使徒行传', 44, 13, 20, '这一切历时约四百五十年。后来神赐给他们士师，直到撒母耳先知为止。'),
('CNV', '使徒行传', 44, 13, 21, '那时，他们要求立一个王，神就把便雅悯支派中一个人，基士的儿子扫罗，赐给他们作王，共四十年之久。'),
('CNV', '使徒行传', 44, 13, 22, '废去扫罗之后，又为他们兴起大卫作王，并且为他作证说：‘我找到耶西的儿子大卫，他是合我心意的人，必遵行我的一切旨意。’'),
('CNV', '使徒行传', 44, 13, 23, '神照着应许，已经从这人的后裔中，给以色列带来了一位救主，就是耶稣。'),
('CNV', '使徒行传', 44, 13, 24, '在他来临之前，约翰早已向以色列全民宣讲悔改的洗礼。'),
('CNV', '使徒行传', 44, 13, 25, '约翰快要跑完他的路程的时候，说：‘你们以为我是谁？我不是基督。他是在我以后来的，我就是给他解脚上的鞋带也不配。’'),
('CNV', '使徒行传', 44, 13, 26, '“弟兄们，亚伯拉罕的子孙，和你们中间敬畏神的人哪，这救恩之道是传给我们的。'),
('CNV', '使徒行传', 44, 13, 27, '住在耶路撒冷的人和他们的官长，因为不认识基督，也不明白每逢安息日所读的先知的话，就把他定了罪，正好应验了先知的话。'),
('CNV', '使徒行传', 44, 13, 28, '他们虽然找不出该死的罪状，还是要求彼拉多杀害他。'),
('CNV', '使徒行传', 44, 13, 29, '他们把所记载一切关于他的事作成了，就把他从木头上取下来，放在坟墓里。'),
('CNV', '使徒行传', 44, 13, 30, '但神却使他从死人中复活了。'),
('CNV', '使徒行传', 44, 13, 31, '有许多日子，他向那些跟他一同从加利利上耶路撒冷的人显现，现在这些人在民众面前作了他的见证人，'),
('CNV', '使徒行传', 44, 13, 32, '我们报好信息给你们：神给列祖的应许，'),
('CNV', '使徒行传', 44, 13, 33, '藉着耶稣的复活，向我们这些作子孙的应验了。就如诗篇第二篇所记的：‘你是我的儿子，我今日生了你。’'),
('CNV', '使徒行传', 44, 13, 34, '至于神使他从死人中复活，不再归于朽坏，他曾这样说：‘我必把应许大卫的、神圣可靠的恩福赐给你们。’'),
('CNV', '使徒行传', 44, 13, 35, '所以他在另一篇说：‘你必不容你的圣者见朽坏。’'),
('CNV', '使徒行传', 44, 13, 36, '“大卫在他自己的世代里，遵行了神的计划，就睡了，归回他列祖那里，见了朽坏。'),
('CNV', '使徒行传', 44, 13, 37, '唯独神所复活的那一位，没有见过朽坏。'),
('CNV', '使徒行传', 44, 13, 38, '所以弟兄们，你们当知道，赦罪之道是由这位耶稣传给你们的。在你们靠摩西律法不能称义的一切事上，'),
('CNV', '使徒行传', 44, 13, 39, '信靠他的人就得称义了。'),
('CNV', '使徒行传', 44, 13, 40, '你们要小心，免得先知书上所说的临到你们：'),
('CNV', '使徒行传', 44, 13, 41, '‘傲慢的人哪！你们要看、要惊奇、要灭亡，因为在你们的日子，我要作一件事，就算有人告诉你们，你们总是不信。’”'),
('CNV', '使徒行传', 44, 13, 42, '保罗和巴拿巴出来的时候，众人请求他们下一个安息日再对他们讲这些话。'),
('CNV', '使徒行传', 44, 13, 43, '散会以后，许多犹太人和归信犹太教的虔诚人，跟从了保罗和巴拿巴。两人对他们谈话，勉励他们要恒久住在神的恩典中。'),
('CNV', '使徒行传', 44, 13, 44, '下一个安息日，几乎全城的人都聚了来，要听主的道。'),
('CNV', '使徒行传', 44, 13, 45, '犹太人看见这么多人，就满心嫉妒，反驳保罗所讲的，并且毁谤他们。'),
('CNV', '使徒行传', 44, 13, 46, '保罗和巴拿巴却放胆说：“神的道，先讲给你们听，是应该的。但因为你们弃绝这道，断定自己不配得永生，所以我们现在就转向外族人去了。'),
('CNV', '使徒行传', 44, 13, 47, '因为主曾这样吩咐我们说：‘我已立你作外族人的光，使你把救恩带到地极去。’”'),
('CNV', '使徒行传', 44, 13, 48, '外族人听见了就欢喜，赞美主的道，凡指定得永生的都信了。'),
('CNV', '使徒行传', 44, 13, 49, '于是主的道传遍那地。'),
('CNV', '使徒行传', 44, 13, 50, '但犹太人唆使虔诚尊贵的妇女和城内的显要，煽动大家迫害保罗和巴拿巴，把他们驱逐出境。'),
('CNV', '使徒行传', 44, 13, 51, '两人当众跺掉脚上的尘土，往以哥念去了。'),
('CNV', '使徒行传', 44, 13, 52, '门徒满有喜乐，又被圣灵充满。'),
('CNV', '使徒行传', 44, 14, 1, '保罗和巴拿巴在以哥念照样进犹太的会堂讲道，结果一大群犹太人和希腊人都信了。'),
('CNV', '使徒行传', 44, 14, 2, '但不顺从的犹太人，煽动外族人，激起他们仇恨的心，来反对弟兄们。'),
('CNV', '使徒行传', 44, 14, 3, '两人却仍住了很久，靠着主放胆讲论，主也藉着他们的手行神迹奇事，证实他恩惠的道。'),
('CNV', '使徒行传', 44, 14, 4, '城里众人就分裂了，有的附从犹太人，也有的附从使徒。'),
('CNV', '使徒行传', 44, 14, 5, '当时，外族人、犹太人，和他们的首领，蠢蠢欲动，想要侮辱使徒，用石头打他们。'),
('CNV', '使徒行传', 44, 14, 6, '两人知道了，就逃往吕高尼的路司得和特庇两城，以及周围的地方，'),
('CNV', '使徒行传', 44, 14, 7, '在那里传福音。'),
('CNV', '使徒行传', 44, 14, 8, '路司得城有一个双脚无力的人，坐在那里。他生来就是瘸腿的，从来没有走过路。'),
('CNV', '使徒行传', 44, 14, 9, '他听保罗讲道；保罗注视他，见他有信心，可以治好，'),
('CNV', '使徒行传', 44, 14, 10, '就大声说：“你起来，两脚站直！”他就跳起来，并且走起路来。'),
('CNV', '使徒行传', 44, 14, 11, '众人看见保罗所作的事，就用吕高尼话大声说：“有神明成了人形，降到我们这里来了！”'),
('CNV', '使徒行传', 44, 14, 12, '于是他们称巴拿巴为宙斯，称保罗为汉密士，因为保罗带头讲话。'),
('CNV', '使徒行传', 44, 14, 13, '城门前宙斯庙的祭司，牵着几头公牛，拿着一些花环来到门口，要同群众一起献祭。'),
('CNV', '使徒行传', 44, 14, 14, '巴拿巴和保罗两个使徒听见了，就撕裂衣服，跳进群众中间，喊着说：'),
('CNV', '使徒行传', 44, 14, 15, '“各位，为什么这样作呢？我们也是人，性情和你们一样，我们传福音给你们，正是要你们远离这些虚妄的事，归向永活的神，就是那创造天、地、海和其中万物的神。'),
('CNV', '使徒行传', 44, 14, 16, '在从前的世代里，他容忍万国各行其道，'),
('CNV', '使徒行传', 44, 14, 17, '然而却未尝不为自己留下明证，就如常常行善事，从天上降下雨来，常常赏赐丰年，使你们吃喝充足，满心欢乐。”'),
('CNV', '使徒行传', 44, 14, 18, '两人说完了这些话，这才阻止群众，不向他们献祭。'),
('CNV', '使徒行传', 44, 14, 19, '但有些犹太人，从安提阿、以哥念来，挑唆群众，用石头打保罗，以为他死了，就拖到城外去。'),
('CNV', '使徒行传', 44, 14, 20, '门徒正围着他的时候，他竟然站起来，走进城里去了。第二天，他跟巴拿巴一同到特庇去。'),
('CNV', '使徒行传', 44, 14, 21, '他们在那城里传福音，使许多人作了门徒，然后回到路司得、以哥念、安提阿，'),
('CNV', '使徒行传', 44, 14, 22, '坚固门徒的心，劝他们恒守所信的道，又说：“我们进入神的国，必须经历许多苦难。”'),
('CNV', '使徒行传', 44, 14, 23, '两人在各教会为他们指派了长老；禁食祈祷之后，就把他们交托给所信的主。'),
('CNV', '使徒行传', 44, 14, 24, '两人经过彼西底，来到旁非利亚，'),
('CNV', '使徒行传', 44, 14, 25, '在别加讲道以后，就下到亚大利。'),
('CNV', '使徒行传', 44, 14, 26, '从那里坐船往安提阿。从前众人就是在这地方，把他们交托在神的恩典中，派他们去工作，现在他们已经完成了。'),
('CNV', '使徒行传', 44, 14, 27, '他们到了那里，就召集了会众，报告神跟他们一起所行的一切，并且他为外族人开了信道的门。'),
('CNV', '使徒行传', 44, 14, 28, '两人同门徒住了不少日子。'),
('CNV', '使徒行传', 44, 15, 1, '有几个人从犹太下来，教导弟兄们说：“你们若不照摩西的规例受割礼，就不能得救。”'),
('CNV', '使徒行传', 44, 15, 2, '保罗和巴拿巴，与他们大大地争执辩论起来。大家就派保罗、巴拿巴和他们中间的几个人，为这个问题上耶路撒冷去见使徒和长老。'),
('CNV', '使徒行传', 44, 15, 3, '于是教会给他们送行，他们就经过腓尼基、撒玛利亚，述说外族人怎样归主的事，使弟兄们大大喜乐。'),
('CNV', '使徒行传', 44, 15, 4, '到了耶路撒冷，他们受到教会、使徒和长老的接待，就报告神同他们一起所行的一切。'),
('CNV', '使徒行传', 44, 15, 5, '然而有几个法利赛派的信徒站起来，说：“我们必须给外族人行割礼，吩咐他们遵守摩西的律法。”'),
('CNV', '使徒行传', 44, 15, 6, '使徒和长老聚集在一起，商议这件事。'),
('CNV', '使徒行传', 44, 15, 7, '经过了很多的辩论，彼得站起来对他们说：“弟兄们，你们知道，前些时候神在你们中间拣选了我，使外族人从我的口中听见福音的道，而且信了。'),
('CNV', '使徒行传', 44, 15, 8, '知道人心的神也为他们作证─赐圣灵给他们，像给我们一样；'),
('CNV', '使徒行传', 44, 15, 9, '而且他待他们和我们没有分别，因为藉着信，他洁净了他们的心。'),
('CNV', '使徒行传', 44, 15, 10, '现在你们为什么试探神，把我们祖先和我们所不能负的轭，放在门徒的颈上呢？'),
('CNV', '使徒行传', 44, 15, 11, '我们相信，我们得救是藉着主耶稣的恩，和他们也是一样。”'),
('CNV', '使徒行传', 44, 15, 12, '大家都静默无声，听巴拿巴和保罗述说神藉着他们在外族人中所行的神迹奇事。'),
('CNV', '使徒行传', 44, 15, 13, '他们讲完了，雅各说：“弟兄们，请听我说！'),
('CNV', '使徒行传', 44, 15, 14, '刚才西门述说神当初怎样关怀外族人，从他们中间拣选了众人，归在自己的名下。'),
('CNV', '使徒行传', 44, 15, 15, '众先知的话，也符合这个意思，正如经上所记：'),
('CNV', '使徒行传', 44, 15, 16, '‘此后我要回来，重建大卫倒塌了的帐幕，重建它损坏之处，把它重新竖立起来，'),
('CNV', '使徒行传', 44, 15, 17, '使余下的人，就是所有称为我名下的外族人，都寻求主，'),
('CNV', '使徒行传', 44, 15, 18, '这是自古以来就显明了这些事的主所说的。’'),
('CNV', '使徒行传', 44, 15, 19, '“所以我认为不可难为这些归服神的外族人，'),
('CNV', '使徒行传', 44, 15, 20, '只要写信叫他们禁戒偶像的污秽、淫乱，勒死的牲畜和血。'),
('CNV', '使徒行传', 44, 15, 21, '因为自古以来，在各城里都有人宣讲摩西的书，每逢安息日，在各会堂里都有人诵读。”'),
('CNV', '使徒行传', 44, 15, 22, '当时，使徒、长老和全教会都认为好，就从他们中间选出人来，差他们和保罗、巴拿巴一同到安提阿去，所选的就是别号巴撒巴的犹大和西拉，他们是弟兄中的领袖。'),
('CNV', '使徒行传', 44, 15, 23, '于是写信给他们带去，信上说：“使徒和作长老的弟兄们，向安提阿、叙利亚、基利家的外族众弟兄问安。'),
('CNV', '使徒行传', 44, 15, 24, '我们听说有人从我们这里出去，说了一些话搅扰你们，使你们心里不安，其实我们并没有吩咐他们。'),
('CNV', '使徒行传', 44, 15, 25, '因此，我们一致同意，选派一些人跟我们亲爱的巴拿巴和保罗去见你们，'),
('CNV', '使徒行传', 44, 15, 26, '这两个人为了我们主耶稣基督的名，曾经把性命置之度外。'),
('CNV', '使徒行传', 44, 15, 27, '我们派了犹大和西拉一同去，他们也会亲口述说这些事。'),
('CNV', '使徒行传', 44, 15, 28, '圣灵和我们都同意，不把别的重担加在你们身上，然而有几件事是重要的，'),
('CNV', '使徒行传', 44, 15, 29, '就是禁戒祭过偶像的食物、血、勒死的牲畜和淫乱。这些事你们若能保守自己不作，那就好了。祝你们平安！”'),
('CNV', '使徒行传', 44, 15, 30, '他们受了差派，下安提阿去，集合了众人，就把书信交上。'),
('CNV', '使徒行传', 44, 15, 31, '众人读了，因信上的劝勉，就感到欣慰。'),
('CNV', '使徒行传', 44, 15, 32, '犹大和西拉也是先知，说了许多话劝勉弟兄，坚固他们。'),
('CNV', '使徒行传', 44, 15, 33, '住了一段时间，弟兄们就给他们送行，祝一路平安；他们就回到差派他们的人那里去。（有些抄本在此有第'),
('CNV', '使徒行传', 44, 15, 34, '节：“但西拉认为自己应当在那里住下来，只有犹大回到耶路撒冷。”）'),
('CNV', '使徒行传', 44, 15, 35, '保罗和巴拿巴却住在安提阿，跟许多别的人一同教导，传讲主的道。'),
('CNV', '使徒行传', 44, 15, 36, '过了一些时候，保罗对巴拿巴说：“我们要回到我们传过主道的各城，探望弟兄们，好知道他们的情形怎么样。”'),
('CNV', '使徒行传', 44, 15, 37, '巴拿巴有意要带别号马可的约翰一同去，'),
('CNV', '使徒行传', 44, 15, 38, '但保罗认为不应带他去，因为他从前在旁非利亚离开过他们，不跟他们一起去作工。'),
('CNV', '使徒行传', 44, 15, 39, '他们各持己见，以致彼此分手。巴拿巴带着马可，坐船到塞浦路斯去；'),
('CNV', '使徒行传', 44, 15, 40, '保罗却选了西拉，众弟兄把他交托在主的恩典中之后，他就出发了。'),
('CNV', '使徒行传', 44, 15, 41, '他走遍了叙利亚、基利家，坚固众教会。'),
('CNV', '使徒行传', 44, 16, 1, '保罗来到了特庇，又到了路司得。在那里有一个门徒，名叫提摩太，是一个信主的犹太妇人的儿子，父亲却是希腊人。'),
('CNV', '使徒行传', 44, 16, 2, '路司得和以哥念的弟兄们都称赞他。'),
('CNV', '使徒行传', 44, 16, 3, '保罗有意要他一同出去，但为了那些地方的犹太人，就给他行了割礼，因为他们都知道他父亲是希腊人。'),
('CNV', '使徒行传', 44, 16, 4, '他们经过各城，把耶路撒冷的使徒和长老所定的规条，交给门徒遵守。'),
('CNV', '使徒行传', 44, 16, 5, '于是众教会信心越发坚固，人数天天增加。'),
('CNV', '使徒行传', 44, 16, 6, '圣灵既然禁止他们在亚西亚传道，他们就走遍弗吕家、加拉太地区。'),
('CNV', '使徒行传', 44, 16, 7, '他们来到每西亚边境，想要去庇推尼，耶稣的灵也不许。'),
('CNV', '使徒行传', 44, 16, 8, '他们经过每西亚，下到特罗亚。'),
('CNV', '使徒行传', 44, 16, 9, '夜间有一个异象向保罗显现：有一个马其顿人站着求他说：“请你到马其顿来，帮助我们！”'),
('CNV', '使徒行传', 44, 16, 10, '保罗见了这异象，我们就认定是神呼召我们去传福音给他们，于是立刻设法前往马其顿。'),
('CNV', '使徒行传', 44, 16, 11, '我们从特罗亚开船，直航撒摩特拉，第二天到达尼亚波利，'),
('CNV', '使徒行传', 44, 16, 12, '从那里来到腓立比，就是马其顿地区的首要城市，是罗马的殖民地。我们在这城里住了几天。'),
('CNV', '使徒行传', 44, 16, 13, '安息日我们出了城门，来到河边，以为那里是个祈祷的地方。我们坐下，对聚集的妇女讲论。'),
('CNV', '使徒行传', 44, 16, 14, '有一位敬畏神的妇女，名叫吕底亚，是推雅推拉城卖紫色布的商人，她一直在听，主开启她的心，使她留心听保罗所讲的。'),
('CNV', '使徒行传', 44, 16, 15, '她和她一家受了洗以后，就请求说：“你们若认为我是对主忠实的，就请到我家来住。”于是她强留我们。'),
('CNV', '使徒行传', 44, 16, 16, '有一次，我们到祈祷的地方去的时候，一个被巫鬼附着的婢女迎面而来；她行占卜使主人们发了大财。'),
('CNV', '使徒行传', 44, 16, 17, '她跟着保罗和我们，喊叫说：“这些人是至高神的仆人，向你们传讲得救的道路。”'),
('CNV', '使徒行传', 44, 16, 18, '她一连多日这样喊叫，保罗觉得厌烦，就转身对那鬼说：“我奉耶稣基督的名，命令你从她身上出来！”那鬼就立刻出来了。'),
('CNV', '使徒行传', 44, 16, 19, '她的主人们看见发财的希望完了，就揪住保罗和西拉，拉到市中心去见官长，'),
('CNV', '使徒行传', 44, 16, 20, '又带到裁判官面前，说：“这些人是犹太人，扰乱我们的城市，'),
('CNV', '使徒行传', 44, 16, 21, '传我们罗马人不准接受、不准实行的规例。”'),
('CNV', '使徒行传', 44, 16, 22, '群众一齐起来攻击他们，裁判官就剥去他们的衣服，下令用棍子打他们。'),
('CNV', '使徒行传', 44, 16, 23, '打了很多棍，就把他们放在监牢里，吩咐狱吏严密看守。'),
('CNV', '使徒行传', 44, 16, 24, '狱吏领了命令，就把他们押入内监，两脚拴了木狗。'),
('CNV', '使徒行传', 44, 16, 25, '约在半夜，保罗和西拉祈祷歌颂神，囚犯们都侧耳听着。'),
('CNV', '使徒行传', 44, 16, 26, '忽然发生了大地震，以致监牢的地基都摇动起来，所有的监门立刻开了，囚犯的锁链都松了。'),
('CNV', '使徒行传', 44, 16, 27, '狱吏醒过来，看见监门全开，以为囚犯都已经逃脱了，就拔出刀来想要自刎。'),
('CNV', '使徒行传', 44, 16, 28, '保罗大声呼叫说：“不要伤害自己，我们都在这里！”'),
('CNV', '使徒行传', 44, 16, 29, '狱吏叫人拿了灯来，就冲进去，战战兢兢地俯伏在保罗和西拉面前，'),
('CNV', '使徒行传', 44, 16, 30, '随后领他们出来，说：“先生，我应该作什么才可以得救？”'),
('CNV', '使徒行传', 44, 16, 31, '他们说：“当信主耶稣，你和你一家人都必定得救。”'),
('CNV', '使徒行传', 44, 16, 32, '他们就把主的道，讲给他和所有在他家里的人听。'),
('CNV', '使徒行传', 44, 16, 33, '就在当夜的那个时候，狱吏领他们去洗伤，狱吏和他家人都受了洗，'),
('CNV', '使徒行传', 44, 16, 34, '就带他们到家里，摆上饭食，他和全家因信了神就大大喜乐。'),
('CNV', '使徒行传', 44, 16, 35, '到了天亮，裁判官派法警来，说：“放了这些人！”'),
('CNV', '使徒行传', 44, 16, 36, '狱吏就把这话告诉保罗，说：“裁判官派人来释放你们，现在可以出来，平平安安地去吧！”'),
('CNV', '使徒行传', 44, 16, 37, '保罗对他们说：“我们是罗马人，还没有定罪，他们就公开打我们，又放在监里；现在要私下赶我们出去吗？不行！他们应当亲自来，领我们出去！”'),
('CNV', '使徒行传', 44, 16, 38, '法警把这番话回报裁判官，裁判官听说他们是罗马人，就害怕起来，'),
('CNV', '使徒行传', 44, 16, 39, '于是来请求他们，领他们出监之后，就请他们离开那城。'),
('CNV', '使徒行传', 44, 16, 40, '两人出了监，就到吕底亚的家里去，见了弟兄们，劝勉他们一番，就离开了。'),
('CNV', '使徒行传', 44, 17, 1, '保罗和西拉经过暗非波里、亚波罗尼亚，来到帖撒罗尼迦，在那里有犹太人的会堂。'),
('CNV', '使徒行传', 44, 17, 2, '保罗照他的习惯进去，一连三个安息日，根据圣经与他们辩论，'),
('CNV', '使徒行传', 44, 17, 3, '讲解证明基督必须受害，从死人中复活，说：“我所传给你们的这位耶稣，就是基督。”'),
('CNV', '使徒行传', 44, 17, 4, '他们中间有人给说服了，就附从了保罗和西拉；还有一大群虔诚的希腊人，和不少显要的妇女。'),
('CNV', '使徒行传', 44, 17, 5, '但犹太人嫉妒起来，招聚了一些市井流氓，纠合成群，骚动全城，冲进了耶孙的家，搜索保罗和西拉，要把他们交给民众。'),
('CNV', '使徒行传', 44, 17, 6, '搜索不到他们，就把耶孙和几个弟兄，拉到地方长官那里，喊叫着说：“这些扰乱天下的人，也到这里来了，'),
('CNV', '使徒行传', 44, 17, 7, '耶孙却收留他们。这些人都违背凯撒的法令，说另外还有一个王耶稣。”'),
('CNV', '使徒行传', 44, 17, 8, '群众和地方长官听见这话，就惊慌起来，'),
('CNV', '使徒行传', 44, 17, 9, '取得耶孙和其余的人签保后，才放了他们。'),
('CNV', '使徒行传', 44, 17, 10, '弟兄们当夜立刻送保罗和西拉往比里亚去。二人到了，就进入犹太人的会堂。'),
('CNV', '使徒行传', 44, 17, 11, '这里的人，比帖撒罗尼迦人开明，热切接受主的道，天天考查圣经，要知道所听的是否与圣经相符。'),
('CNV', '使徒行传', 44, 17, 12, '结果他们中间有很多人信了，也有高贵的希腊妇女，男的也不少。'),
('CNV', '使徒行传', 44, 17, 13, '但帖撒罗尼迦的犹太人，知道保罗又在比里亚宣讲神的道，就到那里去，煽动挑拨群众。'),
('CNV', '使徒行传', 44, 17, 14, '弟兄们立刻把保罗送到海边去；西拉和提摩太仍然留在比里亚。'),
('CNV', '使徒行传', 44, 17, 15, '护送保罗的人带他到了雅典；保罗吩咐他们叫西拉和提摩太赶快去见他，于是他们就回去了。'),
('CNV', '使徒行传', 44, 17, 16, '保罗在雅典等候他们的时候，看见满城都是偶像，心灵十分忿激。'),
('CNV', '使徒行传', 44, 17, 17, '于是在会堂里，同犹太人和虔诚的人辩论；并且天天在市中心和所遇见的人辩论。'),
('CNV', '使徒行传', 44, 17, 18, '还有一些伊壁鸠鲁派和斯多亚派的哲学家也同他争论，有的说：“这个拾人牙慧的人要说什么呢？”有的说：“他似乎是一个宣传外地鬼神的人。”这是因为保罗传扬耶稣和复活的道理。'),
('CNV', '使徒行传', 44, 17, 19, '他们拉着保罗，把他带到亚略．巴古那里，说：“你所讲的这个新道理，我们可以知道吗？'),
('CNV', '使徒行传', 44, 17, 20, '因为你把一切新奇的事，传到我们耳中，我们愿意知道这些事是什么意思。”'),
('CNV', '使徒行传', 44, 17, 21, '原来所有雅典人和外侨，专好谈论和打听新奇的事，来打发时间。'),
('CNV', '使徒行传', 44, 17, 22, '保罗站在亚略．巴古当中，说：“各位雅典人，我看你们在各方面都非常敬畏鬼神。'),
('CNV', '使徒行传', 44, 17, 23, '我走路的时候，仔细看你们所敬拜的，发现有一座坛，上面写着‘献给不认识的神’。我现在把你们不认识而敬拜的这位神，传给你们。'),
('CNV', '使徒行传', 44, 17, 24, '创造宇宙和其中万有的神，既然是天地的主，就不住在人手所造的殿宇，'),
('CNV', '使徒行传', 44, 17, 25, '也不受人手的服事，好像他缺少什么；他自己反而把生命、气息和一切，赐给万人。'),
('CNV', '使徒行传', 44, 17, 26, '他从一个本源造出了万族来，使他们住在整个大地上，并且定了他们的期限和居住的疆界，'),
('CNV', '使徒行传', 44, 17, 27, '要他们寻求神，或者可以摸索而找到他。其实他离我们各人不远，'),
('CNV', '使徒行传', 44, 17, 28, '因着他我们可以生存、活动、存在，就如你们有些诗人说：‘原来我们也是他的子孙。’'),
('CNV', '使徒行传', 44, 17, 29, '我们既然是神的子孙，就不应该以为他的神性是好像人用手艺、心思所雕刻的金银石头一样。'),
('CNV', '使徒行传', 44, 17, 30, '过去那无知的时代，神不加以追究；现在，他却吩咐各处的人都要悔改，'),
('CNV', '使徒行传', 44, 17, 31, '因为他已经定好了日子，要藉着他所立的人，按公义审判天下，并且使他从死人中复活，给万人作一个可信的凭据。”'),
('CNV', '使徒行传', 44, 17, 32, '众人一听到死人复活的事，就讥笑他，但有的说：“我们要再听听你讲这件事！”'),
('CNV', '使徒行传', 44, 17, 33, '这样，保罗就离开他们。'),
('CNV', '使徒行传', 44, 17, 34, '但有几个人接近他，并且信了主，其中有亚略．巴古的议员丢尼修，一个名叫戴马里的女子，还有其他在一起的人。'),
('CNV', '使徒行传', 44, 18, 1, '此后，保罗离开雅典，来到哥林多，'),
('CNV', '使徒行传', 44, 18, 2, '遇见一个生在本都的犹太人，名叫亚居拉。因为革老丢下令所有的犹太人都要离开罗马，所以亚居拉最近同他的妻子百基拉从意大利来了，保罗就去找他们。'),
('CNV', '使徒行传', 44, 18, 3, '他们是以做帐棚为业的，因为是同业，保罗就与他们同住，一同工作。'),
('CNV', '使徒行传', 44, 18, 4, '每逢安息日，保罗在会堂辩论，劝导犹太人和希腊人归主。'),
('CNV', '使徒行传', 44, 18, 5, '西拉和提摩太从马其顿下来的时候，保罗就专心传扬主的道，向犹太人极力证明耶稣是基督。'),
('CNV', '使徒行传', 44, 18, 6, '但是他们抗拒、亵渎，保罗就抖着衣服，对他们说：“你们的罪你们自己承担，这与我无关。从今以后，我要到外族人那里去了。”'),
('CNV', '使徒行传', 44, 18, 7, '他离开那里，到了提多．犹士都的家去。这人是敬拜神的，他的家靠近会堂。'),
('CNV', '使徒行传', 44, 18, 8, '会堂主管基利司布和他全家都信了主，许多哥林多人也听了道，信了主，而且受了洗。'),
('CNV', '使徒行传', 44, 18, 9, '夜里，主藉着异象对保罗说：“不要怕，只管讲，不要闭口！'),
('CNV', '使徒行传', 44, 18, 10, '有我与你同在，必定没有人会攻击和伤害你，因为在这城里有许多属我的人。”'),
('CNV', '使徒行传', 44, 18, 11, '保罗在那里住了一年零六个月，把神的道教导他们。'),
('CNV', '使徒行传', 44, 18, 12, '当迦流作亚该亚省长的时候，犹太人一致起来攻击保罗，拉他到审判台前，'),
('CNV', '使徒行传', 44, 18, 13, '说：“这个人劝人不照着律法去敬拜神。”'),
('CNV', '使徒行传', 44, 18, 14, '保罗刚要开口，迦流就对犹太人说：“犹太人啊，如果有犯法或邪恶的罪行，我当然要耐心听你们；'),
('CNV', '使徒行传', 44, 18, 15, '但所争论的若是关于字句、名称和你们的律法，你们就应当自己处理。我不愿意审判这件事！”'),
('CNV', '使徒行传', 44, 18, 16, '于是就把他们从审判台前赶出去。'),
('CNV', '使徒行传', 44, 18, 17, '众人揪住会堂主管苏提尼，在审判台前打他。这些事迦流一概不理。'),
('CNV', '使徒行传', 44, 18, 18, '保罗住了许多日子，然后辞别弟兄们，坐船去叙利亚，同行的有百基拉和亚居拉。他因为许过愿，现在期满了，就在坚革里剃了头发。'),
('CNV', '使徒行传', 44, 18, 19, '到了以弗所，保罗留他们在那里，自己却到会堂去，跟犹太人辩论。'),
('CNV', '使徒行传', 44, 18, 20, '众人请他多住些时候，他没有答应，'),
('CNV', '使徒行传', 44, 18, 21, '却辞别他们说：“神若许可，我还要回到你们这里来。”于是从以弗所开船去了。'),
('CNV', '使徒行传', 44, 18, 22, '保罗在该撒利亚登岸，上耶路撒冷问候教会，然后下安提阿去。'),
('CNV', '使徒行传', 44, 18, 23, '住了一些时候，他又动身，先后经过加拉太地区和弗吕家，坚固众门徒。'),
('CNV', '使徒行传', 44, 18, 24, '有一个生在亚历山太的犹太人，名叫亚波罗，来到了以弗所。他很有口才，擅长讲解圣经。'),
('CNV', '使徒行传', 44, 18, 25, '这人在主的道上受过训练，心灵火热，很准确地讲论，并且教导人关于耶稣的事，但他只晓得约翰的洗礼。'),
('CNV', '使徒行传', 44, 18, 26, '这人在会堂里放胆讲论起来；百基拉和亚居拉听了，就把他接来，把神的道更准确地向他讲解。'),
('CNV', '使徒行传', 44, 18, 27, '亚波罗有意要到亚该亚去，弟兄们就鼓励他，又写信请门徒接待他。他到了那里，对那些蒙恩信主的人帮助很多，'),
('CNV', '使徒行传', 44, 18, 28, '因为他当众有力地驳倒犹太人，引用圣经证明耶稣是基督。'),
('CNV', '使徒行传', 44, 19, 1, '亚波罗在哥林多的时候，保罗经过内地一带，来到以弗所。他遇见几个门徒，'),
('CNV', '使徒行传', 44, 19, 2, '问他们说：“你们信的时候，受了圣灵没有？”他们说：“没有，连圣灵赐下来这件事，我们也没有听过。”'),
('CNV', '使徒行传', 44, 19, 3, '保罗问：“那么你们受的是什么洗呢？”他们说：“是约翰的洗礼。”'),
('CNV', '使徒行传', 44, 19, 4, '保罗说：“约翰施的是悔改的洗礼，他告诉人民当信在他以后要来的那一位，就是耶稣。”'),
('CNV', '使徒行传', 44, 19, 5, '他们听见了，就受洗归入主耶稣的名下。'),
('CNV', '使徒行传', 44, 19, 6, '保罗为他们按手，圣灵就降在他们身上，他们就用各种的语言讲话，并且说预言。'),
('CNV', '使徒行传', 44, 19, 7, '他们一共约有十二人。'),
('CNV', '使徒行传', 44, 19, 8, '一连三个月，保罗都到会堂里去，放胆宣讲，辩论神的国的事，劝导人。'),
('CNV', '使徒行传', 44, 19, 9, '可是有些人心里刚硬，不受劝化，在群众面前毁谤这道，保罗就离开他们，也叫门徒与他们分开。他每天在推喇奴学院跟人辩论。'),
('CNV', '使徒行传', 44, 19, 10, '这样过了两年，全亚西亚的居民，无论犹太人或希腊人，都听见了主的道。'),
('CNV', '使徒行传', 44, 19, 11, '神藉着保罗的手，行了一些不平凡的神迹。'),
('CNV', '使徒行传', 44, 19, 12, '甚至有人把保罗贴身的手巾围巾拿去，放在病人身上，病就好了，邪灵也出来了。'),
('CNV', '使徒行传', 44, 19, 13, '那时，有几个赶鬼的犹太人，周游各处，擅自用主耶稣的名，向身上有邪灵的人说：“我奉保罗所传的耶稣的名，命令你们出来。”'),
('CNV', '使徒行传', 44, 19, 14, '有一个犹太人士基瓦，是祭司长，他的七个儿子都作这事。'),
('CNV', '使徒行传', 44, 19, 15, '邪灵回答他们：“耶稣我认识，保罗我也知道；你们是谁？”'),
('CNV', '使徒行传', 44, 19, 16, '邪灵所附的那人就扑到他们身上，制伏了两人，胜过了他们，使他们赤着身带着伤，从那房子逃了出来。'),
('CNV', '使徒行传', 44, 19, 17, '所有住在以弗所的犹太人和希腊人，都知道这件事；大家都惧怕，尊主耶稣的名为大。'),
('CNV', '使徒行传', 44, 19, 18, '也有许多信了的人，来承认和述说自己行过的事。'),
('CNV', '使徒行传', 44, 19, 19, '又有许多行巫术的人，把他们的书堆在一起当众烧掉。他们估计书价，才知道共值五万块银子。'),
('CNV', '使徒行传', 44, 19, 20, '这样，主的道大有能力地兴旺起来，而且得胜。'),
('CNV', '使徒行传', 44, 19, 21, '这些事以后，保罗心里定意要经过马其顿、亚该亚，往耶路撒冷去。他说：“我到了那边以后，也该去罗马看看。”'),
('CNV', '使徒行传', 44, 19, 22, '于是从服事他的人中，派了提摩太和以拉都两人去马其顿，自己暂时留在亚西亚。'),
('CNV', '使徒行传', 44, 19, 23, '那时，因这道起了大扰乱，'),
('CNV', '使徒行传', 44, 19, 24, '有一个银匠，名叫低米丢，是制造亚底米女神银龛的。他让技工们作了不少的生意。'),
('CNV', '使徒行传', 44, 19, 25, '他把这些人和同业的工人聚集起来，说：“各位，你们知道，我们是靠这生意赚钱的。'),
('CNV', '使徒行传', 44, 19, 26, '现在你们看见了，也听见了，这个保罗不单在以弗所，而且几乎在整个亚西亚，说服了，也带坏了许多人，说：‘人手所做的，都不是神。’'),
('CNV', '使徒行传', 44, 19, 27, '这样，不只我们这一行要给人鄙视，就是大女神亚底米的庙也会给人撇弃，连全亚西亚和普天下所敬拜的女神也要垮台，威荣尽都失掉了。”'),
('CNV', '使徒行传', 44, 19, 28, '他们听了，怒气冲冲喊着说：“以弗所人的女神，伟大的亚底米啊！”'),
('CNV', '使徒行传', 44, 19, 29, '全城骚动起来，他们捉住了保罗的旅伴马其顿人该犹和亚里达古，齐心冲进了剧场。'),
('CNV', '使徒行传', 44, 19, 30, '保罗想要到人群当中去，门徒却不许。'),
('CNV', '使徒行传', 44, 19, 31, '还有几位亚西亚的首长，是保罗的朋友，派人来劝他，不要冒险到剧场里去。'),
('CNV', '使徒行传', 44, 19, 32, '那时大家叫这个喊那个，乱成一团，大多数的人都不知道聚集的原因。'),
('CNV', '使徒行传', 44, 19, 33, '犹太人把亚历山大推到前面，群众中有人把这事的因由告诉他。亚历山大作了一个手势，要向民众申辩。'),
('CNV', '使徒行传', 44, 19, 34, '大家一认出他是犹太人，就异口同声高呼：“以弗所人的女神，伟大的亚底米啊！”喊了约有两个钟头。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '使徒行传', 44, 19, 35, '后来，书记官安抚群众说：“以弗所人哪！谁不知道你们的城，是看守大亚底米的庙，又是看守宙斯那里降下的神像的呢？'),
('CNV', '使徒行传', 44, 19, 36, '这些事既然是驳不倒的，你们就应当平心静气，不可轻举妄动。'),
('CNV', '使徒行传', 44, 19, 37, '你们带来的这些人，既没有行劫庙宇，也没有亵渎我们的女神。'),
('CNV', '使徒行传', 44, 19, 38, '如果低米丢和同他一起的技工要控告谁，大可以告上法庭，或呈交总督；让他们彼此控告好了。'),
('CNV', '使徒行传', 44, 19, 39, '如果还有其他的事件，可以在合法的集会里，谋求解决。'),
('CNV', '使徒行传', 44, 19, 40, '今天的动乱，本来是无缘无故的，我们可能有被控告的危险；关于这次的骚动，我们实在无法解释。”'),
('CNV', '使徒行传', 44, 19, 41, '说了这些话，就把群众解散了。'),
('CNV', '使徒行传', 44, 20, 1, '骚乱平息以后，保罗派人把门徒请了来，劝勉一番，就辞别起行，往马其顿去。'),
('CNV', '使徒行传', 44, 20, 2, '他走遍那一带地方，用许多话劝勉众人，然后来到希腊。'),
('CNV', '使徒行传', 44, 20, 3, '他在那里住了三个月，正要坐船往叙利亚去的时候，有些犹太人设计要害他，他就决意路经马其顿回去。'),
('CNV', '使徒行传', 44, 20, 4, '与他同行的有比里亚人毕罗斯的儿子所巴特，帖撒罗尼迦人亚里达古和西公都，特庇人该犹和提摩太，亚西亚人推基古和特罗非摩。'),
('CNV', '使徒行传', 44, 20, 5, '这些人先走，在特罗亚等候我们。'),
('CNV', '使徒行传', 44, 20, 6, '至于我们，过了除酵节才从腓立比开船，五天后到特罗亚他们那里，逗留了七天。'),
('CNV', '使徒行传', 44, 20, 7, '礼拜日，我们聚会擘饼的时候，保罗对大家讲道，他因第二天就要起行，就一直讲到半夜。'),
('CNV', '使徒行传', 44, 20, 8, '我们聚会的那座楼上，有许多灯火。'),
('CNV', '使徒行传', 44, 20, 9, '有一个少年人，名叫犹推古，坐在窗台上，因为保罗讲得很长，他很困倦，沉沉地睡着了，就从三楼跌下来；把他扶起来的时候，已经死了。'),
('CNV', '使徒行传', 44, 20, 10, '保罗走下去，伏在他身上；把他抱住，说：“你们不要惊慌，他还活着。”'),
('CNV', '使徒行传', 44, 20, 11, '随即回到楼上，擘饼吃了，又讲了很久，直到天亮才走。'),
('CNV', '使徒行传', 44, 20, 12, '他们把活着的孩子带走，得到很大的安慰。'),
('CNV', '使徒行传', 44, 20, 13, '我们先上船，开往亚朔，照着保罗的安排，要在那边接他，因为他自己要走陆路去。'),
('CNV', '使徒行传', 44, 20, 14, '他在亚朔与我们会合，我们接他上船，去到米推利尼。'),
('CNV', '使徒行传', 44, 20, 15, '从那里开船，第二天到了基阿对面，过了一天就在撒摩靠岸，再过一天到了米利都。'),
('CNV', '使徒行传', 44, 20, 16, '原来保罗决定越过以弗所，免得在亚西亚耽搁时间，因为他希望能在五旬节赶到耶路撒冷。'),
('CNV', '使徒行传', 44, 20, 17, '他从米利都派人去以弗所，请教会的长老来。'),
('CNV', '使徒行传', 44, 20, 18, '他们到了，保罗说：“你们知道，自从我到了亚西亚的第一天，我一直怎样跟你们相处，'),
('CNV', '使徒行传', 44, 20, 19, '怎样服事主，凡事谦卑，常常流泪，忍受犹太人谋害的试炼。'),
('CNV', '使徒行传', 44, 20, 20, '你们也知道，我从来没有留下一件有益的事，不在众人面前或在各人家里告诉你们，教导你们。'),
('CNV', '使徒行传', 44, 20, 21, '我对犹太人和希腊人都作过见证，要他们悔改归向神，信靠我们的主耶稣。'),
('CNV', '使徒行传', 44, 20, 22, '现在，我的心灵受到催逼，要去耶路撒冷，我不知道在那里会遭遇什么事，'),
('CNV', '使徒行传', 44, 20, 23, '只知道在各城里圣灵都向我指明，说有捆锁和患难在等着我。'),
('CNV', '使徒行传', 44, 20, 24, '但我并不珍惜自己的性命，只求跑完我的路程，完成我从主耶稣所领受的职分，为神恩惠的福音作见证。'),
('CNV', '使徒行传', 44, 20, 25, '“我曾在你们那里走遍各地，宣扬神的国。现在，我知道你们众人不会再见我的面了。'),
('CNV', '使徒行传', 44, 20, 26, '所以我今天向你们作证，我是清白的，与众人的罪（“罪”原文作“血”）无关。'),
('CNV', '使徒行传', 44, 20, 27, '因为神的全部计划，我已经毫无保留地传给你们了。'),
('CNV', '使徒行传', 44, 20, 28, '圣灵既然立你们为全群的监督，牧养神用自己的血所赎来的教会，你们就应当为自己谨慎，也为全群谨慎。'),
('CNV', '使徒行传', 44, 20, 29, '我知道在我离开之后，必有凶暴的豺狼进入你们中间，不顾惜羊群。'),
('CNV', '使徒行传', 44, 20, 30, '你们自己中间也必有人起来，讲些歪曲悖谬的话，引诱门徒跟从他们。'),
('CNV', '使徒行传', 44, 20, 31, '所以你们应当警醒，记念我三年之久，昼夜不停地带着眼泪劝戒你们各人。'),
('CNV', '使徒行传', 44, 20, 32, '现在我把你们交托给神和他恩惠的道；这道能建立你们，也能在所有成圣的人中赐基业给你们。'),
('CNV', '使徒行传', 44, 20, 33, '我从来没有贪图任何人的金银或衣服。'),
('CNV', '使徒行传', 44, 20, 34, '我这两只手，供应了我和同伴的需要，这是你们自己知道的。'),
('CNV', '使徒行传', 44, 20, 35, '我凡事以身作则，你们必须照样辛劳，扶助软弱的人，并且记念主耶稣的话：‘施比受更为有福。’”'),
('CNV', '使徒行传', 44, 20, 36, '他说了这些话，就跪下来同大家一起祷告。'),
('CNV', '使徒行传', 44, 20, 37, '众人都痛哭，抱着保罗，与他亲吻。'),
('CNV', '使徒行传', 44, 20, 38, '他们最伤心的，是保罗说他们不会再见他的面那句话。最后他们送他上了船。'),
('CNV', '使徒行传', 44, 21, 1, '我们离别了他们以后，船就直航到了哥士，第二天到罗底，从那里开往帕大拉；'),
('CNV', '使徒行传', 44, 21, 2, '遇见了一艘开往腓尼基的船，就上船起行。'),
('CNV', '使徒行传', 44, 21, 3, '我们远远看见塞浦路斯，就从南边驶过，直航叙利亚，在推罗靠了岸，因为船要在那里卸货。'),
('CNV', '使徒行传', 44, 21, 4, '我们找到了一些门徒，就在那里住了七天。他们凭着圣灵的指示告诉保罗不要上耶路撒冷去。'),
('CNV', '使徒行传', 44, 21, 5, '过了这几天，我们就启程前行，他们众人带着妻子儿女送我们到城外。我们跪在海滩上祷告，'),
('CNV', '使徒行传', 44, 21, 6, '互相道别。我们上了船，他们就回家去了。'),
('CNV', '使徒行传', 44, 21, 7, '我们从推罗继续航行，到了多利买，问候那里的弟兄，与他们同住了一天。'),
('CNV', '使徒行传', 44, 21, 8, '第二天我们离开那里，来到该撒利亚，到了传福音的腓利家里，与他住在一起。他是那七位执事中的一位。'),
('CNV', '使徒行传', 44, 21, 9, '他有四个女儿，都是童女，是会说预言的。'),
('CNV', '使徒行传', 44, 21, 10, '我们住了几天之后，有一位先知，名叫亚迦布，从犹太下来。'),
('CNV', '使徒行传', 44, 21, 11, '他来见我们，把保罗的腰带拿过来，绑住自己的手脚，说：“圣灵说，犹太人在耶路撒冷要这样捆绑这腰带的主人，把他交在外族人的手里。”'),
('CNV', '使徒行传', 44, 21, 12, '我们听了这些话，就和当地的人劝保罗不要去耶路撒冷。'),
('CNV', '使徒行传', 44, 21, 13, '保罗却回答：“你们为什么哭，使我心碎呢？我为主耶稣的名，不但被捆绑，就算死在耶路撒冷我也都准备好了。”'),
('CNV', '使徒行传', 44, 21, 14, '他既然不听劝，我们只说了“愿主的旨意成就”，就不出声了。'),
('CNV', '使徒行传', 44, 21, 15, '过了几天，我们收拾行装，上耶路撒冷去。'),
('CNV', '使徒行传', 44, 21, 16, '有该撒利亚的几个门徒同我们在一起，领我们到一个塞浦路斯人拿孙家里住宿；他作了门徒已经很久了。'),
('CNV', '使徒行传', 44, 21, 17, '我们到了耶路撒冷，弟兄们欢欢喜喜接待我们。'),
('CNV', '使徒行传', 44, 21, 18, '第二天，保罗和我们一同去见雅各，长老们也都在座。'),
('CNV', '使徒行传', 44, 21, 19, '保罗问候了他们，就把神藉着他的工作在外族人中所行的事，一一述说出来。'),
('CNV', '使徒行传', 44, 21, 20, '他们听了，就赞美神，对保罗说：“弟兄，你看，犹太人中信主的有好几万，都是对律法很热心的人。'),
('CNV', '使徒行传', 44, 21, 21, '他们听说，你教导所有在外族人中的犹太人背弃摩西，叫他们不要给孩子行割礼，也不要遵守规例。'),
('CNV', '使徒行传', 44, 21, 22, '他们总会听见你来了，那怎么办呢？'),
('CNV', '使徒行传', 44, 21, 23, '你就照我们的话作吧，我们这里有四个人，都有愿在身。'),
('CNV', '使徒行传', 44, 21, 24, '你把他们带去，和他们一同行洁净礼，并且替他们付钱，让他们剃去头发，这样大家就知道以前所听见关于你的事，都不是真实的，也知道你是遵守律法循规蹈矩而行的人。'),
('CNV', '使徒行传', 44, 21, 25, '至于信主的外族人，我们已经写了信，吩咐他们要禁戒祭偶像的食物、血、勒死的牲畜和淫乱。”'),
('CNV', '使徒行传', 44, 21, 26, '保罗就把那几个人带走了，第二天和他们一同行了洁净礼。他们进了殿，报明了他们洁净期满的日子，以及各人献祭的时间。'),
('CNV', '使徒行传', 44, 21, 27, '七日将完的时候，从亚西亚来的犹太人看见保罗在殿里，就煽动群众，并且捉住他，'),
('CNV', '使徒行传', 44, 21, 28, '喊叫着说：“以色列人哪，快来帮忙！这个人到处教导众人反对人民，反对律法和这个地方，他甚至把希腊人也带进殿里，污秽了这圣地。”'),
('CNV', '使徒行传', 44, 21, 29, '原来他们看见过以弗所人特罗非摩同保罗在城里，就以为保罗带他进了殿。'),
('CNV', '使徒行传', 44, 21, 30, '于是全城震动，民众一齐跑来，捉住保罗，拉出殿外，殿门就立刻关起来了。'),
('CNV', '使徒行传', 44, 21, 31, '他们正想杀他的时候，有人报告营部的千夫长，说：“整个耶路撒冷都乱了！”'),
('CNV', '使徒行传', 44, 21, 32, '千夫长立刻带着一些百夫长和士兵跑到他们那里。众人一看见千夫长和士兵，就停止殴打保罗。'),
('CNV', '使徒行传', 44, 21, 33, '于是千夫长上前捉住保罗，吩咐人用两条铁链捆住他，问他是什么人，作过什么事。'),
('CNV', '使徒行传', 44, 21, 34, '那时众人叫这个喊那个，吵吵闹闹，以致千夫长没有办法知道真相，只好下令把保罗带到营楼去。'),
('CNV', '使徒行传', 44, 21, 35, '保罗到了台阶下面的时候，士兵把他抬起来，因为群众猛挤，'),
('CNV', '使徒行传', 44, 21, 36, '而且有一群人跟在后面叫喊：“干掉他！”'),
('CNV', '使徒行传', 44, 21, 37, '他们带着保罗快到营楼的时候，保罗对千夫长说：“我可以跟你讲一句话吗？”千夫长说：“你懂希腊话吗？'),
('CNV', '使徒行传', 44, 21, 38, '难道你不就是不久以前作乱的、带领四千个杀手到旷野去的那个埃及人吗？”'),
('CNV', '使徒行传', 44, 21, 39, '保罗说：“我是犹太人，是基利家的大数人，并不是无名小城的公民，求你准我向民众讲几句话。”'),
('CNV', '使徒行传', 44, 21, 40, '千夫长准许了他，保罗就站在台阶上，向民众作了一个手势。大家安静下来了，保罗就用希伯来语讲话，说：'),
('CNV', '使徒行传', 44, 22, 1, '“各位父老弟兄，请听听我现在对你们的申辩。”'),
('CNV', '使徒行传', 44, 22, 2, '他们听见保罗用希伯来语说话，就更加安静了。保罗说：'),
('CNV', '使徒行传', 44, 22, 3, '“我是犹太人，生在基利家的大数，在城里长大，按照我们祖宗律法的严格要求，在迦玛列门下受教，我为神热心，好像你们大家今天一样。'),
('CNV', '使徒行传', 44, 22, 4, '我曾经迫害信奉这道的人直至死地，把男男女女都捆绑起来，送进监狱，'),
('CNV', '使徒行传', 44, 22, 5, '这是大祭司和全公议会都可以给我作证的。我也从他们那里得到了写给众弟兄的信，就去大马士革，要把那里的人捆绑起来，带到耶路撒冷接受惩罚。'),
('CNV', '使徒行传', 44, 22, 6, '“约在正午，当我走近大马士革的时候，忽然有大光从天上向我四面照射，'),
('CNV', '使徒行传', 44, 22, 7, '我仆倒在地上，听见有声音对我说：‘扫罗，扫罗，你为什么迫害我？’'),
('CNV', '使徒行传', 44, 22, 8, '我回答：‘主啊，你是谁？’他说：‘我就是你所迫害的拿撒勒人耶稣。’'),
('CNV', '使徒行传', 44, 22, 9, '跟我在一起的人，只看见那光，却听不清楚那位对我说话的声音。'),
('CNV', '使徒行传', 44, 22, 10, '我说：‘主啊，我应当作什么呢？’主说：‘起来，进大马士革去，在那里有人会把指定给你作的一切事告诉你。’'),
('CNV', '使徒行传', 44, 22, 11, '因为那光太强烈，我的眼睛就瞎了，跟我在一起的人就牵着我的手，进了大马士革。'),
('CNV', '使徒行传', 44, 22, 12, '“有一个人名叫亚拿尼亚的，他是一个虔诚而遵守律法的人，当地所有的犹太人都称赞他。'),
('CNV', '使徒行传', 44, 22, 13, '他来见我，站在我旁边，对我说：‘扫罗弟兄，你现在可以看见了。’我立刻往上一看，看见了他。'),
('CNV', '使徒行传', 44, 22, 14, '他又说：‘我们祖先的神选派了你，让你明白他的旨意，看见那义者，听见他口中的声音。'),
('CNV', '使徒行传', 44, 22, 15, '因为你要把所看见所听见的，向万人为他作见证。'),
('CNV', '使徒行传', 44, 22, 16, '现在你为什么还耽搁呢？起来受洗，求告他的名，洗净你的罪吧。’'),
('CNV', '使徒行传', 44, 22, 17, '“后来，我回到耶路撒冷，在殿里祷告的时候，魂游象外，'),
('CNV', '使徒行传', 44, 22, 18, '看见主对我说：‘你要快快离开耶路撒冷，因为你为我作的见证，他们是不会接受的。’'),
('CNV', '使徒行传', 44, 22, 19, '我说：‘主啊，他们知道我曾把信你的人监禁起来，又在各会堂拷打他们，'),
('CNV', '使徒行传', 44, 22, 20, '并且你的见证人司提反受害流血的时候，我也亲自在场，表示同意，并且为杀他的人看守衣服。’'),
('CNV', '使徒行传', 44, 22, 21, '他对我说：‘你走吧，我要派你到远方的外族人那里去。’”'),
('CNV', '使徒行传', 44, 22, 22, '众人听见他说到这句话，就高声说：“这样的人应该从地上除掉，不应该活着！”'),
('CNV', '使徒行传', 44, 22, 23, '大家正在喊叫着，抛掷衣服，向空中扬灰撒土的时候，'),
('CNV', '使徒行传', 44, 22, 24, '千夫长下令把保罗带到营楼去，吩咐人用鞭子拷问他，要知道群众为什么这样向他喊叫。'),
('CNV', '使徒行传', 44, 22, 25, '士兵正用皮带绑他的时候，保罗对站在旁边的百夫长说：“你们鞭打一个还没有定罪的罗马公民，是合法的吗？”'),
('CNV', '使徒行传', 44, 22, 26, '百夫长听了，就去报告千夫长，说：“这个人是罗马公民，你要怎么办呢？”'),
('CNV', '使徒行传', 44, 22, 27, '千夫长就来问保罗：“告诉我，你是罗马公民吗？”他说：“是的。”'),
('CNV', '使徒行传', 44, 22, 28, '千夫长说：“我花了一大笔钱，才取得罗马籍。”保罗说：“我生下来就是罗马公民。”'),
('CNV', '使徒行传', 44, 22, 29, '于是那些要拷问他的人，立刻离开他走了。千夫长既知道他是罗马公民，又因捆绑过他，就害怕起来。'),
('CNV', '使徒行传', 44, 22, 30, '第二天，千夫长为要知道犹太人控告保罗的真相，就解开他，召集了祭司长和公议会全体在一起，把保罗带下来，叫他站在他们面前。'),
('CNV', '使徒行传', 44, 23, 1, '保罗定睛看着公议会的各人，说：“各位弟兄，我在神面前，行事为人一向都是凭着良心的。”'),
('CNV', '使徒行传', 44, 23, 2, '大祭司亚拿尼亚就吩咐站在他旁边的人打保罗的嘴巴。'),
('CNV', '使徒行传', 44, 23, 3, '保罗对他说：“你这粉饰的墙啊，神要击打你！你坐堂要按着律法审问我，现在你竟然违背律法吩咐人打我吗？”'),
('CNV', '使徒行传', 44, 23, 4, '站在旁边的人民说：“你敢辱骂神的大祭司吗？”'),
('CNV', '使徒行传', 44, 23, 5, '保罗说：“弟兄们，我不知道他是大祭司。经上说：‘不可咒诅你人民的领袖。’”'),
('CNV', '使徒行传', 44, 23, 6, '保罗看出其中一部分是撒都该人，另一部分是法利赛人，就在公议会中大声说：“我是法利赛人，也是法利赛人的子孙，我现在受审，是为了盼望死人复活！”'),
('CNV', '使徒行传', 44, 23, 7, '他说了这话，法利赛人和撒都该人就起了争论，会众也分裂了，成为两派。'),
('CNV', '使徒行传', 44, 23, 8, '原来撒都该人说没有复活，没有天使，也没有鬼灵，法利赛人却认定这些都有。'),
('CNV', '使徒行传', 44, 23, 9, '于是众人大嚷大闹，有几个法利赛派的经学家站起来辩论说：“我们看不出这个人作过什么坏事；说不定有灵或天使对他说过话。”'),
('CNV', '使徒行传', 44, 23, 10, '争论越来越大，千夫长怕保罗被他们撕碎了，就吩咐士兵下去，把他从人群中抢救出来，带到营楼去。'),
('CNV', '使徒行传', 44, 23, 11, '当天晚上，主站在保罗身边，说：“你要壮起胆来，你怎样在耶路撒冷作见证，也必照样在罗马为我作见证。”'),
('CNV', '使徒行传', 44, 23, 12, '到了天亮，犹太人在一起秘密计谋，并且发誓说，不杀保罗，就不吃不喝。'),
('CNV', '使徒行传', 44, 23, 13, '一同策划这项阴谋的有四十多人。'),
('CNV', '使徒行传', 44, 23, 14, '他们来见众祭司长和长老，说：“我们已经发了誓，不杀保罗，就不吃东西。'),
('CNV', '使徒行传', 44, 23, 15, '现在你们和公议会要通知千夫长，带保罗到你们这里来，装作要详细审查他。我们已经预备好了，不等他走近，就把他杀了。”'),
('CNV', '使徒行传', 44, 23, 16, '但保罗的外甥听见这项埋伏的诡计，就到营楼去，告诉保罗。'),
('CNV', '使徒行传', 44, 23, 17, '保罗请了一个百夫长来，说：“请你带这个青年人去见千夫长，他有事要报告。”'),
('CNV', '使徒行传', 44, 23, 18, '百夫长就带保罗的外甥去见千夫长，说：“囚犯保罗请了我去，求我带这个青年人来见你，他有事要向你报告。”'),
('CNV', '使徒行传', 44, 23, 19, '千夫长拉着他的手，走到一边，私下问他：“你有什么事要向我报告？”'),
('CNV', '使徒行传', 44, 23, 20, '他说：“犹太人已经约好了，要求你明天把保罗带到公议会里去，装作要详细审查他。'),
('CNV', '使徒行传', 44, 23, 21, '你不要听他们，因为他们有四十多人正在埋伏起来等着保罗；他们发了誓，不杀保罗，就不吃不喝。现在他们已经准备好了，只等你答应。”'),
('CNV', '使徒行传', 44, 23, 22, '千夫长嘱咐那青年人：“不要告诉人你把这事告诉了我。”然后就打发他走了。'),
('CNV', '使徒行传', 44, 23, 23, '千夫长叫了两个百夫长来，说：“预备两百个步兵，七十个骑兵、两百个长枪手，晚上九点钟往该撒利亚去。'),
('CNV', '使徒行传', 44, 23, 24, '也要预备好牲口，好让保罗骑上，护送他安全到达腓力斯总督那里。”'),
('CNV', '使徒行传', 44, 23, 25, '千夫长写了一封信，大意如下：'),
('CNV', '使徒行传', 44, 23, 26, '“革老丢．吕西亚问候总督腓力斯大人。'),
('CNV', '使徒行传', 44, 23, 27, '这个人被犹太人捉住，快要遭害的时候，我听说他是罗马公民，就带兵去把他救出来。'),
('CNV', '使徒行传', 44, 23, 28, '为要知道犹太人控告他的原因，我就带他到他们的公议会那里去。'),
('CNV', '使徒行传', 44, 23, 29, '我发现他被控告，是为了他们律法上的问题，并没有什么该死该绑的罪名。'),
('CNV', '使徒行传', 44, 23, 30, '后来我接到密报，得知害他的阴谋，就立刻把他送到你那里去，并且吩咐原告到你面前来控告他。”'),
('CNV', '使徒行传', 44, 23, 31, '于是士兵照着吩咐，把保罗提出来，连夜带到安提帕底。'),
('CNV', '使徒行传', 44, 23, 32, '第二天，他们把保罗交给骑兵队护送，就回营楼去了。'),
('CNV', '使徒行传', 44, 23, 33, '骑兵到了该撒利亚，把信呈上总督，同时把保罗也交给他。'),
('CNV', '使徒行传', 44, 23, 34, '总督读了信，就问保罗是哪一省的人；知道了他是基利家人，'),
('CNV', '使徒行传', 44, 23, 35, '就说：“等到原告也来了，我才审问你。”于是吩咐人把他拘留在希律的王府里。'),
('CNV', '使徒行传', 44, 24, 1, '过了五天，大祭司亚拿尼亚同几个长老，和一个律师帖土罗来了，他们向总督控告保罗。'),
('CNV', '使徒行传', 44, 24, 2, '保罗传来了之后，帖土罗就控诉他说：“腓力斯大人，因着你的缘故，我们大大地享受着太平；因着你的远见，本国大事改革；'),
('CNV', '使徒行传', 44, 24, 3, '我们随时随地感激不尽。'),
('CNV', '使徒行传', 44, 24, 4, '现在我不想多烦扰你，只求你宽容一下，听我们讲几句话。'),
('CNV', '使徒行传', 44, 24, 5, '我们看这个人就像瘟疫一样，是煽动普天下犹太人生乱的人，又是拿撒勒派的首领。'),
('CNV', '使徒行传', 44, 24, 6, '他还意图污秽圣殿，我们就把他捉住。（有些抄本在此有以下一段：“我们想按照我们的律法审问他。7可是千夫长吕西亚来了，用武力把他从我们手中抢走，8还吩咐原告到你这里来。”）'),
('CNV', '使徒行传', 44, 24, 8, '你亲自审问之后，就必清楚知道我们告他的一切事了。”'),
('CNV', '使徒行传', 44, 24, 9, '犹太人也都跟他一同控告保罗，证实事情确是这样。'),
('CNV', '使徒行传', 44, 24, 10, '总督向保罗示意，叫他说话，他就说：“我知道你在本国审案多年，所以乐意为自己申辩。'),
('CNV', '使徒行传', 44, 24, 11, '你清楚知道，自从我上耶路撒冷去礼拜，到现在还没有十二天；'),
('CNV', '使徒行传', 44, 24, 12, '无论在殿里、会堂中或城里，他们都没有看见我跟人辩论，或煽动群众作乱，'),
('CNV', '使徒行传', 44, 24, 13, '也不能向你证明他们现在控告我的事。'),
('CNV', '使徒行传', 44, 24, 14, '但有一件事我要向你承认，他们所称为异端的这道，我正是根据这道来敬拜我祖先的神的。一切律法和先知所记的，我都相信。'),
('CNV', '使徒行传', 44, 24, 15, '我靠着神所存的盼望，也是他们自己所期待的，就是义人和不义的人都要复活；'),
('CNV', '使徒行传', 44, 24, 16, '因此，我常常勉励自己，对神对人要常存无亏的良心。'),
('CNV', '使徒行传', 44, 24, 17, '过了几年我带着捐款回来周济本国，同时也带了祭物，'),
('CNV', '使徒行传', 44, 24, 18, '他们看见我在殿里的时候，我已经行完了洁净礼，并没有和一大群人在一起，也没有生乱，'),
('CNV', '使徒行传', 44, 24, 19, '只有几个从亚西亚来的犹太人而已。他们若有事要控告我，就应该到你面前来控告。'),
('CNV', '使徒行传', 44, 24, 20, '要不然，当我站在公议会中受审的时候，这些人若发现我有什么罪行，早就亲自说出来了。'),
('CNV', '使徒行传', 44, 24, 21, '如果有的话，就是我站在他们中间所喊的：‘我今天在你们面前受审，是为了死人复活的事’那一句话。”'),
('CNV', '使徒行传', 44, 24, 22, '腓力斯本来就详细晓得这道，却故意拖延他们，说：“等千夫长吕西亚来了，再断定你们的事。”'),
('CNV', '使徒行传', 44, 24, 23, '于是吩咐百夫长看守保罗，但要宽待他，不可阻止亲友来照料他。'),
('CNV', '使徒行传', 44, 24, 24, '过了几天，腓力斯和他的犹太妻子土西拉一同来到，他又传见保罗，听他谈论在耶稣基督里的信仰。'),
('CNV', '使徒行传', 44, 24, 25, '保罗讲到公义、自制和将来的审判的时候，腓力斯就害怕起来，说：“你先走吧，等我有空的时候再叫你来。”'),
('CNV', '使徒行传', 44, 24, 26, '同时他也希望保罗送钱给他，所以又多次传见他，和他谈话。'),
('CNV', '使徒行传', 44, 24, 27, '过了两年，波求．非斯都接了腓力斯的任；腓力斯为要讨好犹太人，就把保罗留在监里。'),
('CNV', '使徒行传', 44, 25, 1, '非斯都到任三天之后，就从该撒利亚去耶路撒冷。'),
('CNV', '使徒行传', 44, 25, 2, '祭司长和犹太人的首领，到他面前控告保罗。他们又要求非斯都，'),
('CNV', '使徒行传', 44, 25, 3, '求他恩准对付保罗，把保罗解来耶路撒冷，他们好埋伏在路上杀死他。'),
('CNV', '使徒行传', 44, 25, 4, '非斯都回答：“保罗现今押在该撒利亚，我就要回到那里去。”'),
('CNV', '使徒行传', 44, 25, 5, '又说：“你们中间有权势的，和我一同去吧！那人若有什么不是，他们就可以告他。”'),
('CNV', '使徒行传', 44, 25, 6, '非斯都在他们那里大约逗留了不过十天八天，就回到该撒利亚去。第二天就开庭，吩咐把保罗带来。'),
('CNV', '使徒行传', 44, 25, 7, '保罗一到，那些从耶路撒冷来的犹太人，就站在他周围，提出许多严重的控告，可是所控告的他们都不能证实。'),
('CNV', '使徒行传', 44, 25, 8, '保罗申辩说：“无论对犹太人的律法、圣殿或凯撒，我都没有罪。”'),
('CNV', '使徒行传', 44, 25, 9, '但非斯都为要讨好犹太人，就问保罗：“你愿意去耶路撒冷，让我在那里审问这事吗？”'),
('CNV', '使徒行传', 44, 25, 10, '保罗说：“我现在站在凯撒的审判台前，这里是我应当受审的地方。我对犹太人并没有作过什么不对的事，这是你清楚知道的。'),
('CNV', '使徒行传', 44, 25, 11, '我若作过不对的事，犯过什么该死的罪，就是死我也不推辞。不过，如果这些人告我的事不是真的，谁也不可以把我送给他们。我要向凯撒上诉。”'),
('CNV', '使徒行传', 44, 25, 12, '非斯都同议会商量后，答覆说：“你既然要向凯撒上诉，可以到凯撒那里去。”'),
('CNV', '使徒行传', 44, 25, 13, '过了一些日子，亚基帕王和百尼基到该撒利亚来，问候非斯都。'),
('CNV', '使徒行传', 44, 25, 14, '他们在那里逗留了许多天，非斯都把保罗的案情向王陈明，说：“这里有一个囚犯，是腓力斯留下来的。'),
('CNV', '使徒行传', 44, 25, 15, '我在耶路撒冷的时候，祭司长和犹太人的长老控告他，要求把他定罪。'),
('CNV', '使徒行传', 44, 25, 16, '我答覆他们说，被告还没有和原告当面对证，又没有机会为所控的罪申辩，就被送给对方，罗马人没有这个规例。'),
('CNV', '使徒行传', 44, 25, 17, '后来他们都到了这里，我没有耽延时间，第二天就开庭，吩咐把那人提出来。'),
('CNV', '使徒行传', 44, 25, 18, '原告都站在那里，他们所控诉他的，并不是我所意料的恶事。'),
('CNV', '使徒行传', 44, 25, 19, '他们与他争辩的，只是他们的宗教问题；还论到一位已经死了的耶稣，保罗却说他是活着的。'),
('CNV', '使徒行传', 44, 25, 20, '关于这些争论，我不知道怎样处理，就问他愿不愿意上耶路撒冷去为这些事在那里受审。'),
('CNV', '使徒行传', 44, 25, 21, '但保罗要求把他留下，等待皇上裁判，我就下令把他押起来，等候解往凯撒那里。”'),
('CNV', '使徒行传', 44, 25, 22, '亚基帕对非斯都说：“我也想听听这人说些什么。”非斯都说：“明天就请你来听。”'),
('CNV', '使徒行传', 44, 25, 23, '第二天，亚基帕和百尼基威风凛凛地来了，同千夫长和城中的显要进了厅堂。非斯都吩咐一声，就有人把保罗提出来。'),
('CNV', '使徒行传', 44, 25, 24, '非斯都说：“亚基帕王和在座的各位，请看这个人。耶路撒冷和本地的犹太人都向我请求，嚷着说这个人不该活着。'),
('CNV', '使徒行传', 44, 25, 25, '我查明他没有犯什么该死的罪，但是他自己既然要向皇上上诉，我就决定把他解去。'),
('CNV', '使徒行传', 44, 25, 26, '关于这个人，我没有什么确实的事可以呈奏主上的。所以把他带到你们面前，特别是你亚基帕王面前，为要在审查之后，有所陈奏。'),
('CNV', '使徒行传', 44, 25, 27, '因为我认为解送囚犯，不指明他的罪状，是不合理的。”'),
('CNV', '使徒行传', 44, 26, 1, '亚基帕对保罗说：“准你为自己申辩。”于是保罗伸手辩护说：'),
('CNV', '使徒行传', 44, 26, 2, '“亚基帕王啊，犹太人控告我的事，今天我可以在你面前辩护，实在是万幸；'),
('CNV', '使徒行传', 44, 26, 3, '特别是你熟悉犹太人的一切规例和争论，所以求你耐心听我申诉：'),
('CNV', '使徒行传', 44, 26, 4, '我从幼年到现在，在本国、在耶路撒冷为人怎样，犹太人都知道。'),
('CNV', '使徒行传', 44, 26, 5, '如果他们肯作证的话，他们是早就知道，我是按着我们祖宗最严格的教派，过着法利赛人的生活。'),
('CNV', '使徒行传', 44, 26, 6, '现在我站着受审，是为了对神向我们祖先的应许存着盼望。'),
('CNV', '使徒行传', 44, 26, 7, '我们十二支派昼夜切切地事奉神，都是盼望这应许实现。王啊，我被犹太人控告，正是为了这个盼望。'),
('CNV', '使徒行传', 44, 26, 8, '神使死人复活，你们为什么认为是不可信的呢？'),
('CNV', '使徒行传', 44, 26, 9, '从前，我也认为应该多方敌对拿撒勒人耶稣的名。'),
('CNV', '使徒行传', 44, 26, 10, '后来就在耶路撒冷这样作了。我得到了众祭司长授权，把许多圣徒关在监里，并且他们被杀的时候，我也表示同意。'),
('CNV', '使徒行传', 44, 26, 11, '我在各会堂里多次用刑强迫他们说亵渎的话；我非常愤恨他们，甚至追到国外的城巿去迫害他们。'),
('CNV', '使徒行传', 44, 26, 12, '“那时候，我得到祭司长的授权和准许，去大马士革。'),
('CNV', '使徒行传', 44, 26, 13, '王啊，就在中午的时候，我在路上看见一道光，比太阳更明亮，从天上四面照着我和同行的人。'),
('CNV', '使徒行传', 44, 26, 14, '我们都仆倒在地上，我听见有声音用希伯来话对我说：‘扫罗！扫罗！你为什么迫害我？你要踢刺棒是难的。’'),
('CNV', '使徒行传', 44, 26, 15, '我说：‘主啊，你是谁？’主说：‘我就是你所迫害的耶稣。'),
('CNV', '使徒行传', 44, 26, 16, '你起来，站着，我向你显现，是要指派你为我工作。你要为你所见过的事，和我将要向你显明的事作见证。'),
('CNV', '使徒行传', 44, 26, 17, '我要救你脱离这人民和外族人，差遣你到他们那里去，'),
('CNV', '使徒行传', 44, 26, 18, '开他们的眼睛，使他们从黑暗中归向光明，从撒但的权下归向神，使他们的罪恶得到赦免，并且在那些因信我而成圣的人中同得基业。’'),
('CNV', '使徒行传', 44, 26, 19, '“亚基帕王啊，因此，我没有违背这从天上来的异象，'),
('CNV', '使徒行传', 44, 26, 20, '先向大马士革、耶路撒冷、犹太全地的人宣讲，后向外族人宣讲，叫他们悔改，归向神，行事与悔改的心相称。'),
('CNV', '使徒行传', 44, 26, 21, '犹太人就是为了这缘故在殿里捉住我，想要杀我。'),
('CNV', '使徒行传', 44, 26, 22, '然而，我得到神的帮助，直到今日还是站得稳，向尊卑老幼作见证，我所讲的都是众先知和摩西所论的将来必成的事，'),
('CNV', '使徒行传', 44, 26, 23, '就是基督必须受难，并且从死人中首先复活，把光明的信息传报给这人民和外族人。”'),
('CNV', '使徒行传', 44, 26, 24, '保罗申诉到这里，非斯都大声说：“保罗！你疯了；你的学问太大，使你疯了！”'),
('CNV', '使徒行传', 44, 26, 25, '保罗说：“非斯都大人，我没有疯，我说的都是真实的话，清醒的话。'),
('CNV', '使徒行传', 44, 26, 26, '因为王知道这些事，所以我对王坦白直说。我确信这些事没有一件能瞒得过他，因为这不是在背地里作的。'),
('CNV', '使徒行传', 44, 26, 27, '亚基帕王啊，你信先知吗？我知道你是信的。”'),
('CNV', '使徒行传', 44, 26, 28, '亚基帕对保罗说：“你想用这样短短的时间就可以说服我作基督徒吗！”'),
('CNV', '使徒行传', 44, 26, 29, '保罗说：“无论时间短也好，时间长也好，我向神所求的，不单是你，而且是今天所有的听众，都能像我一样作基督徒，只是不要有这些锁链。”'),
('CNV', '使徒行传', 44, 26, 30, '亚基帕王、总督和百尼基，还有在座的人都站起来，'),
('CNV', '使徒行传', 44, 26, 31, '退到一边，彼此谈论，说：“这个人并没有犯过什么该死该绑的罪。”'),
('CNV', '使徒行传', 44, 26, 32, '亚基帕对非斯都说：“这个人若没有向凯撒上诉，早就可以释放了。”'),
('CNV', '使徒行传', 44, 27, 1, '他们决定要我们坐船往意大利去，就把保罗和别的囚犯，交给皇家军营里的一个百夫长，名叫犹流。'),
('CNV', '使徒行传', 44, 27, 2, '有一艘亚大米田来的船，要开往亚西亚沿岸一带的地方，我们上去，船就开了。跟我们在一起的，还有马其顿的帖撒罗尼迦人亚里达古。'),
('CNV', '使徒行传', 44, 27, 3, '第二天到了西顿，犹流宽待保罗，准他去看看朋友，接受他们的招待。'),
('CNV', '使徒行传', 44, 27, 4, '我们又从那里开船，因为逆风，就沿着塞浦路斯背风而行。'),
('CNV', '使徒行传', 44, 27, 5, '渡过基利家和旁非利亚一带的海面，就到了吕家的每拉。'),
('CNV', '使徒行传', 44, 27, 6, '百夫长在那里找到一艘亚历山太来的船，要开往意大利去，就叫我们上了那船。'),
('CNV', '使徒行传', 44, 27, 7, '一连几天，船都走得很慢，好不容易才到了革尼土的对面。因为有风阻挡着我们，就沿着克里特背风而行，从撒摩尼对面经过，'),
('CNV', '使徒行传', 44, 27, 8, '沿着海岸行驶，航程很艰难，后来才到了靠近拉西亚城一个名叫美港的地方。'),
('CNV', '使徒行传', 44, 27, 9, '过了相当的时候，连禁食节也过去了，所以航行很危险，保罗就劝告他们，'),
('CNV', '使徒行传', 44, 27, 10, '说：“各位，我看这次航行，不单货物和船只要遭到损失，大受破坏，连我们的性命也难保。”'),
('CNV', '使徒行传', 44, 27, 11, '但百夫长宁愿相信船长和船主的话，却不相信保罗所说的。'),
('CNV', '使徒行传', 44, 27, 12, '而且这港口不适宜过冬，所以大多数人主张离开那里，也许可以到非尼基去过冬。非尼基是克里特的一个港口，一面向西南，一面向西北。'),
('CNV', '使徒行传', 44, 27, 13, '这时南风徐徐地吹来，他们以为风势有利，就起锚沿着克里特航行。'),
('CNV', '使徒行传', 44, 27, 14, '可是过了不久，有一股名叫“友拉革罗”（“友拉革罗”意即“东北风”）的飓风，向岛上吹袭。'),
('CNV', '使徒行传', 44, 27, 15, '船给风困住了，不能迎风前行，只好随着风向飘流。'),
('CNV', '使徒行传', 44, 27, 16, '有一个小岛名叫高达，我们就在这岛的背风岸急航，好不容易才把救生艇拉住。'),
('CNV', '使徒行传', 44, 27, 17, '水手把艇拉上来，用缆索绕过船身捆好。他们怕船在赛耳底搁浅，就收下船帆，任船飘流。'),
('CNV', '使徒行传', 44, 27, 18, '风浪把我们颠簸得很厉害，第二天他们就把货物抛在海里，'),
('CNV', '使徒行传', 44, 27, 19, '第三天又亲手把船上的用具扔掉。'),
('CNV', '使徒行传', 44, 27, 20, '好几天，都看不见星星和太阳，狂风大浪催逼着我们，这样看来，我们连生还的希望都没有了。'),
('CNV', '使徒行传', 44, 27, 21, '大家很久没有吃饭了，保罗就站在他们中间，说：“各位，你们本来应该听我的话不离开克里特，就不会遭受这场损失和破坏了。'),
('CNV', '使徒行传', 44, 27, 22, '现在我劝你们放心。除了这艘船以外，你们没有一个人会丧命的。'),
('CNV', '使徒行传', 44, 27, 23, '因为我所归属所事奉的神，他的使者昨天夜里站在我的旁边，说：'),
('CNV', '使徒行传', 44, 27, 24, '‘保罗，不要怕。你必定可以站在凯撒面前；神已经把那些和你同船的人赐给你了。’'),
('CNV', '使徒行传', 44, 27, 25, '所以，各位请放心。我相信神对我怎样说，也必怎样成就。'),
('CNV', '使徒行传', 44, 27, 26, '不过我们必会搁浅在一个海岛上。”'),
('CNV', '使徒行传', 44, 27, 27, '到了第十四天的晚上，我们在亚得里亚海飘来飘去。约在半夜的时候，水手以为接近了陆地，'),
('CNV', '使徒行传', 44, 27, 28, '就探测一下，深三十六公尺；稍往前行，再探测一下，深二十七公尺。'),
('CNV', '使徒行传', 44, 27, 29, '他们怕我们会在乱石上搁浅，就从船尾抛下四个锚，期待着天亮。'),
('CNV', '使徒行传', 44, 27, 30, '水手们想要离船逃走，就把救生艇放在海上，假装要从船头抛锚的样子。'),
('CNV', '使徒行传', 44, 27, 31, '保罗对百夫长和士兵说：“这些人若不留在船上，你们就性命难保！”'),
('CNV', '使徒行传', 44, 27, 32, '于是士兵砍断救生艇的绳子，任它掉下去。'),
('CNV', '使徒行传', 44, 27, 33, '天快亮的时候，保罗劝大家吃饭，说：“你们一直不吃东西，挨饿苦候，到今天已经十四天了！'),
('CNV', '使徒行传', 44, 27, 34, '所以，我劝你们吃点饭，这可以维持你们的性命！因为你们没有人会失掉一根头发。”'),
('CNV', '使徒行传', 44, 27, 35, '保罗说了这话，就拿起饼来，在众人面前感谢神，然后擘开来吃。'),
('CNV', '使徒行传', 44, 27, 36, '于是大家都安心吃饭了。'),
('CNV', '使徒行传', 44, 27, 37, '我们在船上的共有二百七十六人，'),
('CNV', '使徒行传', 44, 27, 38, '大家吃饱了，把麦子抛在海里，好减轻船的负荷。'),
('CNV', '使徒行传', 44, 27, 39, '天亮的时候，他们不认得那个地方，只看见一个可以登岸的海湾，就有意尽可能把船拢岸。'),
('CNV', '使徒行传', 44, 27, 40, '于是把锚砍掉，丢在海里，同时又松开舵绳，拉起前帆，顺风向岸驶去。'),
('CNV', '使徒行传', 44, 27, 41, '但在海水夹流的地方，船就搁了浅，船头胶着不动，船尾被海浪冲击，就损坏了。'),
('CNV', '使徒行传', 44, 27, 42, '士兵想把囚犯都杀掉，免得有人游泳逃脱。'),
('CNV', '使徒行传', 44, 27, 43, '但百夫长想要救保罗，就阻止他们这样行。他吩咐会游泳的跳下水去，先到岸上，'),
('CNV', '使徒行传', 44, 27, 44, '其余的人可以用木板，或船上的器具上岸。这样，大家都安全地上岸了。'),
('CNV', '使徒行传', 44, 28, 1, '我们脱险之后，才知道那岛名叫马尔他。'),
('CNV', '使徒行传', 44, 28, 2, '当地的人对我们非常友善；因为下过一场雨，天气又冷，他们就生了火来招待我们。'),
('CNV', '使徒行传', 44, 28, 3, '保罗拾了一捆干柴，放在火上的时候，有一条毒蛇，受不住热，爬了出来，缠住他的手。'),
('CNV', '使徒行传', 44, 28, 4, '当地的人看见那条蛇悬在他手上，就彼此说：“这个人一定是凶手，虽然从海里脱险，天理也不容他活着！”'),
('CNV', '使徒行传', 44, 28, 5, '但是保罗却把那条蛇抖在火里，自己一点也没有受伤。'),
('CNV', '使徒行传', 44, 28, 6, '他们等着看他发肿，或者忽然暴毙。但等了很久，见他平安无事，就转念说，他是个神明。'),
('CNV', '使徒行传', 44, 28, 7, '那地附近有些田产，是岛上的首领部百流所拥有的。他欢迎我们，善意招待我们三天。'),
('CNV', '使徒行传', 44, 28, 8, '那时，部百流的父亲患了痢疾，发热卧病在床，保罗到他那里，为他祈祷按手，医好了他。'),
('CNV', '使徒行传', 44, 28, 9, '这么一来，岛上其他有病的都来了，也都治好了。'),
('CNV', '使徒行传', 44, 28, 10, '他们多方面尊敬我们；到开船的时候，又把我们所需要的东西送来。'),
('CNV', '使徒行传', 44, 28, 11, '过了三个月，我们上了一艘亚历山太来的船。这船在岛上过冬，船的名字是“宙斯双子”。'),
('CNV', '使徒行传', 44, 28, 12, '到了叙拉古，我们停留了三天。'),
('CNV', '使徒行传', 44, 28, 13, '从那里绕道航行，来到利基翁。过了一天，起了南风，第二天到达部丢利。'),
('CNV', '使徒行传', 44, 28, 14, '我们在那里遇见一些弟兄，他们邀请我们一同住了七天。这样，我们就来到了罗马。'),
('CNV', '使徒行传', 44, 28, 15, '弟兄们听到了我们的消息，就从罗马出来，在亚比乌和三馆迎接我们。保罗见了他们，就感谢神，胆子也壮了起来。'),
('CNV', '使徒行传', 44, 28, 16, '我们到了罗马，保罗获准独自与看守他的士兵居住。'),
('CNV', '使徒行传', 44, 28, 17, '过了三天，保罗请犹太人的首领来。他们都到了，保罗说：“各位弟兄，我虽然没有作过什么事反对人民或者反对祖先的规例，却像囚犯被逮捕，从耶路撒冷交到罗马人的手里。'),
('CNV', '使徒行传', 44, 28, 18, '他们审讯之后，因为在我身上没有什么该死的罪，就想要释放我。'),
('CNV', '使徒行传', 44, 28, 19, '可是犹太人反对，我迫不得已才上诉凯撒，并不是有什么事要控告我的国民。'),
('CNV', '使徒行传', 44, 28, 20, '因此，我请你们来见面谈谈。我原是为了以色列的盼望，才带上这条锁链的。”'),
('CNV', '使徒行传', 44, 28, 21, '他们说：“我们没有收到犹太来的信，是提到你的，弟兄中也没有人来报告，或说你什么坏话。'),
('CNV', '使徒行传', 44, 28, 22, '但我们觉得应该听听你本人的意见，因为关于这教派，我们知道是到处遭人反对的。”'),
('CNV', '使徒行传', 44, 28, 23, '他们和保罗约好了一个日子，到那日有很多人到他的住所来见他。他从早到晚向他们讲解，为神的国竭力作见证，引用摩西的律法和先知的话劝他们信耶稣。'),
('CNV', '使徒行传', 44, 28, 24, '他所说的话，有人信服，也有人不信。'),
('CNV', '使徒行传', 44, 28, 25, '他们彼此不合，就分散了。未散以前，保罗说了几句话：“圣灵藉以赛亚先知对你们祖先所说的，一点不错。'),
('CNV', '使徒行传', 44, 28, 26, '他说：‘你去告诉这人民：你们听是听见了，总是不明白；看是看见了，总是不领悟。'),
('CNV', '使徒行传', 44, 28, 27, '因为这人民的心思迟钝，用不灵的耳朵去听，又闭上了眼睛；免得自己眼睛看见，耳朵听见，心里明白，回转过来，我就医好他们。’'),
('CNV', '使徒行传', 44, 28, 28, '所以你们应当知道，神这救恩，已经传给外族人，他们也必听从。”（有些抄本在此有第29节：“他说了这话，犹太人中间大起争论，就走了。”）'),
('CNV', '使徒行传', 44, 28, 30, '保罗在自己所租的房子里，住了整整两年。凡来见他的人，他都接待，'),
('CNV', '使徒行传', 44, 28, 31, '并且放胆地传讲神的国，教导有关主耶稣基督的事，没有受到什么禁止。'),
('CNV', '罗马书', 45, 1, 1, '基督耶稣的仆人保罗，蒙召作使徒，奉派传神的福音。'),
('CNV', '罗马书', 45, 1, 2, '这福音是神藉着众先知在圣经上预先所应许的，'),
('CNV', '罗马书', 45, 1, 3, '就是论到他的儿子我们的主耶稣基督：按肉身说，他是从大卫的后裔生的；'),
('CNV', '罗马书', 45, 1, 4, '按圣洁的灵说，因为从死人中复活，显明他是大有能力的、神的儿子（“显明他是大有能力的、神的儿子”或译：“以大能显明他是神的儿子）。'),
('CNV', '罗马书', 45, 1, 5, '我们从他领受了恩典和使徒的职分，在万族中使人因他的名相信而顺服，'),
('CNV', '罗马书', 45, 1, 6, '其中也有你们这蒙耶稣基督所召的人。'),
('CNV', '罗马书', 45, 1, 7, '我写信给各位住在罗马，为神所爱，蒙召为圣徒的人。愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '罗马书', 45, 1, 8, '首先，我靠着耶稣基督，为你们大家感谢我的神，因为你们的信心传遍天下。'),
('CNV', '罗马书', 45, 1, 9, '我在传扬他儿子福音的事上，用心灵事奉的神，可以作证我是怎样不断地记念你们，'),
('CNV', '罗马书', 45, 1, 10, '常常在祷告中恳切祈求，也许我可以照着他的旨意，终于能够顺利地到你们那里去。'),
('CNV', '罗马书', 45, 1, 11, '因为我很想见你们，好把一些属灵的恩赐分给你们，使你们可以坚定；'),
('CNV', '罗马书', 45, 1, 12, '也使我在你们中间，藉着你我彼此的信心，大家一同得到安慰。'),
('CNV', '罗马书', 45, 1, 13, '弟兄们，我不愿意你们不知道，我好几次预先定好了要到你们那里去，为了要在你们中间也得一些果子，像在其他的民族中间一样，可是直到现在还有阻碍。'),
('CNV', '罗马书', 45, 1, 14, '无论是希腊人或是未开化的人，聪明的人或是愚笨的人，我都欠他们的债。'),
('CNV', '罗马书', 45, 1, 15, '所以，对我来说，我随时都愿意把福音也传给你们在罗马的人。'),
('CNV', '罗马书', 45, 1, 16, '我不以福音为耻；这福音是神的大能，要救所有相信的，先是犹太人，后是希腊人。'),
('CNV', '罗马书', 45, 1, 17, '神的义就是藉着这福音显明出来，本于信而归于信，正如经上所记：“义人必因信得生。”'),
('CNV', '罗马书', 45, 1, 18, '神的震怒，从天上向所有不虔不义的人显露出来，就是向那些以不义压制真理的人显露出来。'),
('CNV', '罗马书', 45, 1, 19, '神的事情，人所能知道的，在他们里面原是明显的，因为神已经向他们显明了。'),
('CNV', '罗马书', 45, 1, 20, '其实自从创世以来，神那看不见的事，就如他永恒的大能和神性，都是看得见的，就是从他所造的万物中可以领悟，叫人没有办法推诿。'),
('CNV', '罗马书', 45, 1, 21, '因为他们虽然知道神，却不尊他为神，也不感谢他，反而心思变为虚妄，愚顽的心就迷糊了。'),
('CNV', '罗马书', 45, 1, 22, '他们自以为是聪明的，却成了愚蠢的。'),
('CNV', '罗马书', 45, 1, 23, '他们用必朽坏的人、飞禽、走兽和昆虫的形象，取代了永不朽坏的神的荣耀。'),
('CNV', '罗马书', 45, 1, 24, '因此，神就任凭他们顺着心中的私欲去作污秽的事，以致羞辱自己的身体。'),
('CNV', '罗马书', 45, 1, 25, '他们用虚谎取代了神的真理，敬拜事奉受造之物，却不敬拜事奉造物的主。他是永远可称颂的，阿们。'),
('CNV', '罗马书', 45, 1, 26, '因此，神就任凭他们放纵可耻的情欲：他们的女人把原来的性的功能，变成违反自然的功能；'),
('CNV', '罗马书', 45, 1, 27, '同样地，男人也舍弃了女人原来的性功能，彼此欲火攻心，男人与男人作出可耻的事。他们这样妄为，就在自己身上受到应该受的报应。'),
('CNV', '罗马书', 45, 1, 28, '他们既然故意不认识神，神就任凭他们存着败坏的心，去作那些不正当的事。'),
('CNV', '罗马书', 45, 1, 29, '这些人充满了各样的不义、邪恶、贪心、阴险；满怀嫉妒、凶杀、好斗、欺诈、幸灾乐祸；又是好说谗言的、'),
('CNV', '罗马书', 45, 1, 30, '毁谤人的、憎恨神的、凌辱人的、傲慢的、自夸的、制造恶事的、忤逆父母的、'),
('CNV', '罗马书', 45, 1, 31, '冥顽不灵的、不守信用的、冷酷无情的、没有恻隐之心的。'),
('CNV', '罗马书', 45, 1, 32, '他们虽然明明知道行这些事的人，神判定他们是该死的，然而他们不单自己去行，也喜欢别人去行。'),
('CNV', '罗马书', 45, 2, 1, '你这判断人的啊！无论你是谁，都没有办法推诿。你在什么事上判断人，就在什么事上定自己的罪；因为你所作的，正是你所判断的事。'),
('CNV', '罗马书', 45, 2, 2, '我们知道，神必照着真理审判行这些事的人。'),
('CNV', '罗马书', 45, 2, 3, '你这个人，你判断行这些事的人，自己所行的却是一样，你以为能逃脱神的审判吗？'),
('CNV', '罗马书', 45, 2, 4, '还是你藐视神丰富的恩慈、宽容和忍耐，不晓得他的恩慈是要领你悔改的吗？'),
('CNV', '罗马书', 45, 2, 5, '可是你一直硬着心肠，不肯悔改，为自己积蓄神的忿怒，就是他彰显公义审判的那天所要发的忿怒。'),
('CNV', '罗马书', 45, 2, 6, '神必照各人所作的报应各人：'),
('CNV', '罗马书', 45, 2, 7, '以永生报答那些耐心行善、寻求荣耀尊贵和不朽的人，'),
('CNV', '罗马书', 45, 2, 8, '却以震怒和愤恨报应那些自私自利、不顺从真理而顺从不义的人；'),
('CNV', '罗马书', 45, 2, 9, '把患难和愁苦加给所有作恶的人，先是犹太人，后是希腊人，'),
('CNV', '罗马书', 45, 2, 10, '却把荣耀、尊贵与平安赐给所有行善的人，先是犹太人，后是希腊人。'),
('CNV', '罗马书', 45, 2, 11, '因为神并不偏待人。'),
('CNV', '罗马书', 45, 2, 12, '凡不在律法之下犯了罪的，将不按律法而灭亡；凡在律法之下犯了罪的，将按律法受审判。'),
('CNV', '罗马书', 45, 2, 13, '因为在神面前，不是听律法的为义，而是行律法的得称为义。'),
('CNV', '罗马书', 45, 2, 14, '没有律法的外族人，如果按本性行律法上的事，他们虽然没有律法，自己就是自己的律法；'),
('CNV', '罗马书', 45, 2, 15, '这就表明律法的作用是刻在他们的心里，有他们的良心一同作证，他们的思想互相较量，或作控告、或作辩护。'),
('CNV', '罗马书', 45, 2, 16, '这也要照着我所传的福音，在神藉着耶稣基督审判各人隐情的那一天，彰显出来。'),
('CNV', '罗马书', 45, 2, 17, '你身为犹太人，倚靠律法，仗着神夸口，'),
('CNV', '罗马书', 45, 2, 18, '而且明白他的旨意，又从律法得了教导，能够辨别什么是好的，'),
('CNV', '罗马书', 45, 2, 19, '自信是瞎子的向导，在黑暗中的人的光，'),
('CNV', '罗马书', 45, 2, 20, '愚昧人的导师，小孩子的教师，在律法上得了整套的知识和真理；'),
('CNV', '罗马书', 45, 2, 21, '你既然教导别人，难道不教导自己吗？你传讲不可偷窃，自己却偷窃吗？'),
('CNV', '罗马书', 45, 2, 22, '你说不可奸淫，自己却奸淫吗？你憎恶偶像，自己却劫掠庙宇吗？'),
('CNV', '罗马书', 45, 2, 23, '你既然以律法夸口，自己却因犯律法而羞辱神吗？'),
('CNV', '罗马书', 45, 2, 24, '正如经上所说的：“神的名，因你们的缘故在列邦中被亵渎。”'),
('CNV', '罗马书', 45, 2, 25, '你若遵行律法，割礼固然有益处；但你若是犯律法的，你的割礼就不是割礼了。'),
('CNV', '罗马书', 45, 2, 26, '这样，没有受割礼的人，如果遵守律法所规定的，他虽然没有受过割礼，不也算是受过割礼的吗？'),
('CNV', '罗马书', 45, 2, 27, '那本来没有受割礼却遵守律法的人，就要审判你这有仪文和割礼而犯律法的人。'),
('CNV', '罗马书', 45, 2, 28, '因为表面上作犹太人的并不是犹太人，在肉身上表面的割礼也不是割礼。'),
('CNV', '罗马书', 45, 2, 29, '唯有在内心作犹太人的才是犹太人；割礼也是心里的，是靠着圣灵而不是靠着仪文。这样的人所受的称赞，不是从人来的，而是从神来的。'),
('CNV', '罗马书', 45, 3, 1, '这样说来，犹太人独特的地方在哪里呢？割礼又有什么益处呢？'),
('CNV', '罗马书', 45, 3, 2, '从各方面来说，的确很多。最重要的，是神的圣言已经托付了他们。'),
('CNV', '罗马书', 45, 3, 3, '即使有人不信，又有什么关系呢？难道他们的不信会使神的信实无效吗？'),
('CNV', '罗马书', 45, 3, 4, '绝不可能！神总是诚实的，人却是虚谎的，正如经上所记：“你在话语上，显为公义；你被论断时，必然得胜。”'),
('CNV', '罗马书', 45, 3, 5, '我且照着人的见解来说，我们的不义若彰显神的义，我们可以说什么呢？难道降怒的神是不义的吗？'),
('CNV', '罗马书', 45, 3, 6, '绝对不是！如果是这样，神怎能审判世界呢？'),
('CNV', '罗马书', 45, 3, 7, '但是神的诚实，如果因我的虚谎而更加显出他的荣耀来，为什么我还要像罪人一样受审判呢？'),
('CNV', '罗马书', 45, 3, 8, '为什么不说：“我们去作恶以成善吧！”（有人毁谤我们，说我们讲过这话。）这种人被定罪是理所当然的。'),
('CNV', '罗马书', 45, 3, 9, '那又怎么样呢？我们比他们强吗？绝不是的。因为我们已经控诉过，无论是犹太人或是希腊人，都在罪恶之下，'),
('CNV', '罗马书', 45, 3, 10, '正如经上所说：“没有义人，连一个也没有，'),
('CNV', '罗马书', 45, 3, 11, '没有明白的，没有寻求神的；'),
('CNV', '罗马书', 45, 3, 12, '人人都偏离了正道，一同变成污秽；没有行善的，连一个也没有。'),
('CNV', '罗马书', 45, 3, 13, '他们的喉咙是敞开的坟墓，他们用舌头弄诡诈，他们嘴里有虺蛇的毒，'),
('CNV', '罗马书', 45, 3, 14, '满口是咒骂和恶毒；'),
('CNV', '罗马书', 45, 3, 15, '为了杀人流血，他们的脚步飞快，'),
('CNV', '罗马书', 45, 3, 16, '在经过的路上留下毁灭和悲惨。'),
('CNV', '罗马书', 45, 3, 17, '和睦之道，他们不晓得，'),
('CNV', '罗马书', 45, 3, 18, '他们的眼中也不怕神。”'),
('CNV', '罗马书', 45, 3, 19, '然而我们晓得，凡律法所说的，都是对在律法之下的人说的，好让每一个人都没有话可讲，使全世界的人都伏在神的审判之下。'),
('CNV', '罗马书', 45, 3, 20, '没有一个人可以靠行律法，在神面前得称为义，因为藉着律法，人对于罪才有充分的认识。'),
('CNV', '罗马书', 45, 3, 21, '现在，有律法和先知的话可以证明：神的义在律法之外已经显明出来，'),
('CNV', '罗马书', 45, 3, 22, '就是神的义，因着信耶稣基督，毫无区别地临到所有信的人。'),
('CNV', '罗马书', 45, 3, 23, '因为人人都犯了罪，亏缺了神的荣耀，'),
('CNV', '罗马书', 45, 3, 24, '但他们却因着神的恩典，藉着在基督耶稣里的救赎，就白白地称义。'),
('CNV', '罗马书', 45, 3, 25, '神设立了耶稣为赎罪祭（“赎罪祭”直译作“赎罪或使神息怒之法”），是凭着他的血，藉着人的信，为的是要显明神的义；因为神用忍耐的心宽容了人从前所犯的罪，'),
('CNV', '罗马书', 45, 3, 26, '好在现今显明他的义，使人知道他自己为义，又称信耶稣的人为义。'),
('CNV', '罗马书', 45, 3, 27, '这样，有什么可夸的呢？没有可夸的了。凭什么准则说没有的呢？凭行为吗？不是的，而是以信心为准则说的。'),
('CNV', '罗马书', 45, 3, 28, '因为我们认定，人称义是由于信，并不是靠行律法。'),
('CNV', '罗马书', 45, 3, 29, '难道神只是犹太人的神吗？不也是外族人的神吗？是的，他也是外族人的神。'),
('CNV', '罗马书', 45, 3, 30, '神既然只有一位，他就以信为准则称受割礼的为义，也要以信为准则称没有受割礼的为义。'),
('CNV', '罗马书', 45, 3, 31, '这样说来，我们以信废掉了律法吗？绝对不是，倒是巩固了律法。'),
('CNV', '罗马书', 45, 4, 1, '那么，论到在血统（“血统”原文作“肉身”）上作我们祖先的亚伯拉罕所经验的，我们可以说什么呢？'),
('CNV', '罗马书', 45, 4, 2, '亚伯拉罕若是因行为称义，就有可夸的，只是不能在神面前夸口。'),
('CNV', '罗马书', 45, 4, 3, '经上怎么样说呢？“亚伯拉罕信神，这就算为他的义。”'),
('CNV', '罗马书', 45, 4, 4, '作工的得工资，不算是恩典，是他应得的。'),
('CNV', '罗马书', 45, 4, 5, '可是，那不作工而只信那称不敬虔的人为义的神的，他的信就算为义了。'),
('CNV', '罗马书', 45, 4, 6, '大卫也是这样说，那不靠行为而蒙神算为义的人是有福的！'),
('CNV', '罗马书', 45, 4, 7, '“过犯得蒙赦免，罪恶得到遮盖的人，是有福的；'),
('CNV', '罗马书', 45, 4, 8, '主不算为有罪的，这人是有福的。”'),
('CNV', '罗马书', 45, 4, 9, '这样看来，那有福的人，是指受割礼的呢，还是也指没有受割礼的呢？因为我们说：“亚伯拉罕的信算为他的义。”'),
('CNV', '罗马书', 45, 4, 10, '那么，是怎样算的呢？是在他受割礼以后呢，还是在他受割礼之前呢？不是在他受割礼以后，而是在他受了割礼以前。'),
('CNV', '罗马书', 45, 4, 11, '他领受了割礼为记号，作他受割礼之前因信称义的印证，使他作所有没有受割礼而信之人的父，使他们也被算为义；'),
('CNV', '罗马书', 45, 4, 12, '又作受割礼之人的父，就是作那些不仅受割礼，并且照着我们祖宗亚伯拉罕未受割礼时就信的那脚踪而行之人的父。'),
('CNV', '罗马书', 45, 4, 13, '原来神给亚伯拉罕和他后裔承受世界的应许，并不是因着律法，而是藉着因信而来的义。'),
('CNV', '罗马书', 45, 4, 14, '如果属于律法的人才能成为后嗣，信就没有作用，应许也就落空了。'),
('CNV', '罗马书', 45, 4, 15, '因为律法带来刑罚，没有律法，就没有违背律法的事。'),
('CNV', '罗马书', 45, 4, 16, '所以，成为后嗣是因着信，为的是要按着神的恩典，使给所有后裔的应许坚定不移，不但临到那属于律法的人，也临到那效法亚伯拉罕而信的人。亚伯拉罕在神面前作我们众人的父，'),
('CNV', '罗马书', 45, 4, 17, '如经上所记：“我已经立了你作万国的父。”他所信的，是叫死人得生命、使无变为有的神。'),
('CNV', '罗马书', 45, 4, 18, '在他没有盼望的时候，仍然怀着盼望去信，因此就成了万国的父，正如神所说：“你的后裔将要这样众多。”'),
('CNV', '罗马书', 45, 4, 19, '他快到一百岁的时候，想到自己的身体好像已经死了，撒拉也不能生育，他的信心还是不软弱，'),
('CNV', '罗马书', 45, 4, 20, '也没有因着不信而疑惑神的应许，反倒坚信不移，把荣耀归给神，'),
('CNV', '罗马书', 45, 4, 21, '满心相信神所应许的，神必能成就。'),
('CNV', '罗马书', 45, 4, 22, '因此，这就算为他的义。'),
('CNV', '罗马书', 45, 4, 23, '“算为他的义”这一句话，不是单为他写的，'),
('CNV', '罗马书', 45, 4, 24, '也是为我们这将来得算为义的人写的，就是为我们这信神使我们的主耶稣从死人中复活的人写的。'),
('CNV', '罗马书', 45, 4, 25, '耶稣为我们的过犯被交去处死，为我们的称义而复活。'),
('CNV', '罗马书', 45, 5, 1, '所以，我们既然因信称义，就藉着我们的主耶稣基督与神和好；'),
('CNV', '罗马书', 45, 5, 2, '我们也凭着信，藉着他可以进入现在所站的这恩典中，并且以盼望得享神的荣耀为荣。'),
('CNV', '罗马书', 45, 5, 3, '不但这样，我们更以患难为荣；知道患难产生忍耐，'),
('CNV', '罗马书', 45, 5, 4, '忍耐产生毅力，毅力产生盼望；'),
('CNV', '罗马书', 45, 5, 5, '盼望是不会令人蒙羞的，因为神藉着所赐给我们的圣灵，把他的爱浇灌在我们的心里。'),
('CNV', '罗马书', 45, 5, 6, '当我们还软弱的时候，基督就照所定的日期，为不敬虔的人死了。'),
('CNV', '罗马书', 45, 5, 7, '为义人死，是少有的；为好人死，或有敢作的；'),
('CNV', '罗马书', 45, 5, 8, '唯有基督在我们还作罪人的时候为我们死，神对我们的爱就在此显明了。'),
('CNV', '罗马书', 45, 5, 9, '所以，我们现在既然因他的血称义，就更要藉着他免受神的忿怒。'),
('CNV', '罗马书', 45, 5, 10, '我们作仇敌的时候，尚且藉着神儿子的死与他复和，既然复和了，就更要因他的生得救了！'),
('CNV', '罗马书', 45, 5, 11, '不但这样，我们现在已经藉着我们的主耶稣基督与神复和，也藉着他以神为荣。'),
('CNV', '罗马书', 45, 5, 12, '正好像罪藉着一个人入了世界，死又是从罪来的，所以死就临到所有人，因为所有人都犯了罪。'),
('CNV', '罗马书', 45, 5, 13, '没有律法以前，罪已经在世界上了；不过，没有律法的时候，罪也不算罪。'),
('CNV', '罗马书', 45, 5, 14, '可是，从亚当到摩西，死就掌权了，甚至那些不像亚当那样犯罪的人，也在死的权下；亚当正是要来的那一位的预表。'),
('CNV', '罗马书', 45, 5, 15, '但恩赏和过犯是截然不同的；如果因着那一人的过犯，众人都死了，神的恩典和这一人耶稣基督在恩典里的赏赐，对众人就更加丰盛了。'),
('CNV', '罗马书', 45, 5, 16, '这赏赐和那一人犯罪的后果也是不同的；因为审判是由一人而来，以致定罪，恩赏却由许多过犯而来，以致称义。'),
('CNV', '罗马书', 45, 5, 17, '如果因着那一人的过犯，死就因那一人而掌权，那些蒙丰富的恩典并且得公义为赏赐的，就更要因这一位耶稣基督在生命中掌权了。'),
('CNV', '罗马书', 45, 5, 18, '这样看来，因一次的过犯，所有人都被定罪；照样，因一次的义行，所有人都被称义得生命了。'),
('CNV', '罗马书', 45, 5, 19, '因着那一人的悖逆，众人就被列为罪人；照样，因着这一人的顺服，众人也被列为义人了。'),
('CNV', '罗马书', 45, 5, 20, '律法的出现，是要叫过犯增多；然而罪在哪里增多，恩典就更加增多了。'),
('CNV', '罗马书', 45, 5, 21, '罪藉着死掌权；照样，恩典也藉着义掌权，使人藉着我们的主耶稣基督进入永生。'),
('CNV', '罗马书', 45, 6, 1, '这样，我们可以说什么呢？我们可以常在罪中，叫恩典增多吗？'),
('CNV', '罗马书', 45, 6, 2, '绝对不可！我们向罪死了的人，怎么可以仍然活在罪中呢？'),
('CNV', '罗马书', 45, 6, 3, '难道你们不晓得我们这受洗归入基督耶稣的人，是受洗归入他的死吗？'),
('CNV', '罗马书', 45, 6, 4, '所以我们藉着洗礼归入死，与他同葬，为的是要我们过新生命的生活，像基督藉着父的荣耀从死人中复活一样。'),
('CNV', '罗马书', 45, 6, 5, '我们若在他死的样式上与他联合，也要在他复活的样式上与他联合。'),
('CNV', '罗马书', 45, 6, 6, '我们知道，我们的旧人已经与基督同钉十字架，使罪身丧失机能，使我们不再作罪的奴仆，'),
('CNV', '罗马书', 45, 6, 7, '因为死了的人已经脱离罪了。'),
('CNV', '罗马书', 45, 6, 8, '我们既然与基督同死，就信也必与他同活。'),
('CNV', '罗马书', 45, 6, 9, '我们知道，基督既然从死人中复活，就不再死，死也不再辖制他了。'),
('CNV', '罗马书', 45, 6, 10, '他死，是向罪死了，只有这一次；他活，是向神活着。'),
('CNV', '罗马书', 45, 6, 11, '你们也应当这样，向罪算自己是死的，在基督耶稣里，向神却是活的。'),
('CNV', '罗马书', 45, 6, 12, '所以，不要容罪在你们必死的肉身上掌权，使你们顺从肉身的私欲，'),
('CNV', '罗马书', 45, 6, 13, '也不要把你们的肢体献给罪，作不义的用具；倒要像出死得生的人，把自己献给神，并且把你们的肢体献给神作义的用具。'),
('CNV', '罗马书', 45, 6, 14, '罪必不能辖制你们，因为你们不是在律法之下，而是在恩典之下。'),
('CNV', '罗马书', 45, 6, 15, '那却怎么样呢？我们不在律法之下，而在恩典之下，就可以犯罪吗？绝对不可！'),
('CNV', '罗马书', 45, 6, 16, '难道你们不知道你们自愿作奴仆去顺从人，顺从谁就作谁的奴仆，或作罪的奴仆以致于死，或作顺从的奴仆以致于义吗？'),
('CNV', '罗马书', 45, 6, 17, '感谢神，你们虽然作过罪的奴仆，现在却从心里顺从了传授给你们的教义的规范。'),
('CNV', '罗马书', 45, 6, 18, '你们既然从罪里得了释放，就作了义的奴仆。'),
('CNV', '罗马书', 45, 6, 19, '因为你们肉体的弱点，我就按一般人的话来说，你们从前怎样把你们的肢体献给不洁和不法作奴仆，以致于不法，现在也要照样把你们的肢体献给义作奴仆，以致于成圣。'),
('CNV', '罗马书', 45, 6, 20, '你们作罪的奴仆的时候，就不受义的约束。'),
('CNV', '罗马书', 45, 6, 21, '那么，你们在现今以为羞耻的事上，当时得了什么呢？那些事的结局就是死。'),
('CNV', '罗马书', 45, 6, 22, '现在你们既然从罪里得了释放，作了神的奴仆，就有成圣的果子，那结局就是永生。'),
('CNV', '罗马书', 45, 6, 23, '因为罪的工价就是死，但神的恩赏，在我们的主基督耶稣里，却是永生。'),
('CNV', '罗马书', 45, 7, 1, '弟兄们，我对懂得律法的人说，你们不晓得律法管辖人，是在他活着的期间吗？'),
('CNV', '罗马书', 45, 7, 2, '一个已婚的妇人，在丈夫活着的时候，她是受律法约束归属丈夫；丈夫若死了，她就脱离丈夫在律法上的约束。'),
('CNV', '罗马书', 45, 7, 3, '所以，当丈夫还活着的时候，如果她归属别的男人，就称为淫妇；丈夫若死了，她就脱离了律法的约束，如果她归属别的男人，也不是淫妇。'),
('CNV', '罗马书', 45, 7, 4, '这样，我的弟兄们，你们藉着基督的身体，对律法来说也已经死了，使你们归属另一位，就是那从死人中复活的，为的是要我们结果子给神。'),
('CNV', '罗马书', 45, 7, 5, '我们从前属肉体的时候，罪恶的情欲藉着律法在我们的肢体里发动，就结出死亡的果子。'),
('CNV', '罗马书', 45, 7, 6, '但现在，我们既然向那捆绑我们的律法死了，就脱离了律法的约束，好让我们用心灵的新样子，而不用仪文的旧方式来服事主。'),
('CNV', '罗马书', 45, 7, 7, '这样，我们可以说什么呢？难道律法是罪吗？绝对不是。不过，如果不是藉着律法，我就不知道什么是罪；如果不是律法说“不可贪心”，我就不知道什么是贪心。'),
('CNV', '罗马书', 45, 7, 8, '但罪趁着机会，藉着诫命在我里面发动各样的贪心，因为没有律法，罪是死的。'),
('CNV', '罗马书', 45, 7, 9, '在没有律法的时候，我是活的；但诫命一来，罪就活了，我就死了。'),
('CNV', '罗马书', 45, 7, 10, '那本来使人活的诫命，反而使我死了；'),
('CNV', '罗马书', 45, 7, 11, '因为罪藉着诫命把握着机会来欺骗我，并且杀了我。'),
('CNV', '罗马书', 45, 7, 12, '这样，律法是圣洁的，诫命也是圣洁、公义和良善的。'),
('CNV', '罗马书', 45, 7, 13, '既是这样，那良善的反而使我死吗？绝对不是！但罪藉着那良善的使我死，就显出真是罪，为了要使罪藉着诫命变成更加邪恶。'),
('CNV', '罗马书', 45, 7, 14, '我们知道律法是属灵的，我却是属肉体的，已经卖给罪了。'),
('CNV', '罗马书', 45, 7, 15, '因为我所作的，我不明白；我所愿意的，我没有去作，我所恨恶的，我倒去作。'),
('CNV', '罗马书', 45, 7, 16, '如果我所不愿意的，我倒去作，我就不得不承认律法是好的。'),
('CNV', '罗马书', 45, 7, 17, '既是这样，那就不是我作的，而是住在我里面的罪作的。'),
('CNV', '罗马书', 45, 7, 18, '我知道在我里面，就是在我肉体之中，没有良善，因为立志行善由得我，行出来却由不得我。'),
('CNV', '罗马书', 45, 7, 19, '所以我愿意行的善，我没有去行；我不愿意作的恶，我倒去作了。'),
('CNV', '罗马书', 45, 7, 20, '我若作自己不愿意作的事，那就不是我作的，而是住在我里面的罪作的。'),
('CNV', '罗马书', 45, 7, 21, '因此，我发现了一个律，就是我想向善的时候，恶就在我里面出现。'),
('CNV', '罗马书', 45, 7, 22, '按着我里面的人来说，我是喜欢神的律，'),
('CNV', '罗马书', 45, 7, 23, '但我发觉肢体中另有一个律，和我心中的律争战，把我掳去附从肢体中的罪律。'),
('CNV', '罗马书', 45, 7, 24, '我这个人真是苦啊！谁能救我脱离这使我死亡的身体呢？'),
('CNV', '罗马书', 45, 7, 25, '感谢神，藉着我们的主耶稣基督就能脱离了。可见，一方面我自己心里服事神的律，另一方面我的肉体却服事罪的律。'),
('CNV', '罗马书', 45, 8, 1, '所以现在，那些在耶稣基督里的人就不被定罪了；'),
('CNV', '罗马书', 45, 8, 2, '因为生命之灵的律在基督耶稣里使我自由，脱离了罪和死的律。'),
('CNV', '罗马书', 45, 8, 3, '律法是因肉体而软弱无力，所作不到的，神作到了：他差遣自己的儿子成为罪身的样式，为了除掉罪，就在肉体中把罪判决了，'),
('CNV', '罗马书', 45, 8, 4, '使律法所要求的义，可以在我们这些不随从肉体而随从圣灵去行的人身上实现出来。'),
('CNV', '罗马书', 45, 8, 5, '随从肉体的人，以肉体的事为念；随从圣灵的人，以圣灵的事为念。'),
('CNV', '罗马书', 45, 8, 6, '以肉体为念就是死，以圣灵为念就是生命、平安；'),
('CNV', '罗马书', 45, 8, 7, '因为以肉体为念就是与神为仇，既不服从神的律法，也的确不能够服从；'),
('CNV', '罗马书', 45, 8, 8, '属肉体的人不能得神的喜悦。'),
('CNV', '罗马书', 45, 8, 9, '神的灵既然住在你们里面，你们就不是属于肉体，而是属于圣灵的了。如果人没有基督的灵，就不是属于基督的。'),
('CNV', '罗马书', 45, 8, 10, '基督若在你们里面，你们的身体因着罪的缘故是死的，而圣灵却因着义的缘故赐给你们生命。'),
('CNV', '罗马书', 45, 8, 11, '如果那使耶稣从死人中复活者的灵住在你们里面，那使基督从死人中复活的，也必藉着住在你们里面的圣灵，使你们必死的身体活过来。'),
('CNV', '罗马书', 45, 8, 12, '弟兄们，可见我们并不是欠肉体的债，随着肉体而活。'),
('CNV', '罗马书', 45, 8, 13, '如果随着肉体而活，你们必定死；如果靠着圣灵治死身体的恶行，你们就必活着。'),
('CNV', '罗马书', 45, 8, 14, '因为蒙神的灵引导的，都是神的儿子。'),
('CNV', '罗马书', 45, 8, 15, '你们接受的，不是奴仆的灵，使你们仍旧惧怕；你们接受的，是使人成为嗣子的灵，使我们呼叫“阿爸、父”。'),
('CNV', '罗马书', 45, 8, 16, '圣灵亲自和我们的灵一同证明我们是神的儿女。'),
('CNV', '罗马书', 45, 8, 17, '既然是儿女，就是后嗣；是神的后嗣，也和基督一同作后嗣。我们既然和他一同受苦，就必和他一同得荣耀。'),
('CNV', '罗马书', 45, 8, 18, '我看现在的苦难，与将要向我们显出的荣耀，是无法相比的。'),
('CNV', '罗马书', 45, 8, 19, '被造的万物都热切渴望神的众子显现出来。'),
('CNV', '罗马书', 45, 8, 20, '因为被造的万物服在虚空之下，不是自己愿意这样，而是由于使它屈服的那一位；'),
('CNV', '罗马书', 45, 8, 21, '被造的万物盼望自己得着释放，脱离败坏的奴役，得着神儿女荣耀的自由。'),
('CNV', '罗马书', 45, 8, 22, '我们知道被造的万物直到现在都一同在痛苦呻吟。'),
('CNV', '罗马书', 45, 8, 23, '不但这样，连我们这些有圣灵作为初熟果子的人，自己也在内心叹息，热切期待成为嗣子，就是我们的身体得赎。'),
('CNV', '罗马书', 45, 8, 24, '我们得救时就存着这盼望；但是看得见的盼望不是盼望，因为谁会盼望自己看见了的呢？'),
('CNV', '罗马书', 45, 8, 25, '但如果我们盼望没有看见的，就会耐心地热切期待。'),
('CNV', '罗马书', 45, 8, 26, '照样，圣灵也在我们的软弱上帮助我们。原来我们不晓得应当怎样祷告，但圣灵亲自用不可言喻的叹息，替我们祈求。'),
('CNV', '罗马书', 45, 8, 27, '那鉴察人心的，晓得圣灵的心意，因为圣灵照着神的旨意替圣徒祈求。'),
('CNV', '罗马书', 45, 8, 28, '我们知道，为了爱神的人，就是按他旨意蒙召的人的益处，万事都一同效力。'),
('CNV', '罗马书', 45, 8, 29, '因为神预先知道的人，他就预先命定他们和他儿子的形象一模一样，使他的儿子在许多弟兄中作长子，'),
('CNV', '罗马书', 45, 8, 30, '他预先命定的人，又呼召他们；所召来的人，又称他们为义；所称为义的人，又使他们得荣耀。'),
('CNV', '罗马书', 45, 8, 31, '既是这样，我们对这一切还有什么话说呢？神若这样为我们，谁能敌对我们呢？'),
('CNV', '罗马书', 45, 8, 32, '他连自己的儿子都舍得，为我们众人把他交出来，难道不也把万有和他一同白白地赐给我们吗？'),
('CNV', '罗马书', 45, 8, 33, '谁能控告神拣选的人呢？有神称我们为义了。'),
('CNV', '罗马书', 45, 8, 34, '谁能定我们的罪呢？有基督耶稣死了，而且复活了，现今在神的右边，也替我们祈求。'),
('CNV', '罗马书', 45, 8, 35, '谁能使我们与基督的爱隔绝呢？是患难吗？是困苦吗？是迫害吗？是饥饿吗？是赤身露体吗？是危险吗？是刀剑吗？'),
('CNV', '罗马书', 45, 8, 36, '正如经上所记：“为你的缘故，我们终日面对死亡，人看我们像待宰的羊。”'),
('CNV', '罗马书', 45, 8, 37, '但靠着爱我们的那一位，我们在这一切事上就得胜有余了。'),
('CNV', '罗马书', 45, 8, 38, '因为我深信：无论是死、是生，是天使、是掌权的，是现在的事，是将来的事，是有能力的，'),
('CNV', '罗马书', 45, 8, 39, '是高天的、是深渊的，或是任何别的被造之物，都不能叫我们与神的爱隔绝，这爱是在我们的主耶稣基督里的。'),
('CNV', '罗马书', 45, 9, 1, '我在基督里说的是实话，并没有撒谎，因为我的良心在圣灵里一同为我作证；'),
('CNV', '罗马书', 45, 9, 2, '我大大忧愁，心里常常伤痛。'),
('CNV', '罗马书', 45, 9, 3, '为我的同胞，就是我骨肉之亲，就算自己受咒诅，与基督隔绝，我也甘心。'),
('CNV', '罗马书', 45, 9, 4, '他们是以色列人：嗣子的名分、荣耀、众约、律法、敬拜的礼仪和各样的应许，都是他们的。'),
('CNV', '罗马书', 45, 9, 5, '蒙拣选的列祖也是他们的祖宗；按肉身来说，基督也是出自他们这一族。其实，他是在万有之上，永远受称颂的神。阿们。'),
('CNV', '罗马书', 45, 9, 6, '当然，这不是说神的话落了空，因为出自以色列的，不都是以色列人；'),
('CNV', '罗马书', 45, 9, 7, '也不因为他们是亚伯拉罕的后裔，就都成为他的儿女，只有“以撒生的，才可以称为你的后裔”，'),
('CNV', '罗马书', 45, 9, 8, '这就是说，肉身生的儿女并不是神的儿女，只有凭着应许生的儿女才算是后裔。'),
('CNV', '罗马书', 45, 9, 9, '因为所应许的话是这样：“明年这个时候我要来，撒拉必定生一个儿子。”'),
('CNV', '罗马书', 45, 9, 10, '不但如此，利百加也是这样：既然从一个人，就是从我们的祖宗以撒怀了孕，'),
('CNV', '罗马书', 45, 9, 11, '双生子还没有生下来，善恶也没有行出来（为要坚定神拣选人的旨意，不是由于行为，而是由于那呼召者），'),
('CNV', '罗马书', 45, 9, 12, '神就对她说：“将来大的要服事小的。”'),
('CNV', '罗马书', 45, 9, 13, '正如经上所记的：“我爱雅各，却恶以扫。”'),
('CNV', '罗马书', 45, 9, 14, '既是这样，我们可以说什么呢？神不公平吗？绝对不会！'),
('CNV', '罗马书', 45, 9, 15, '因为他对摩西说：“我要怜悯谁，就怜悯谁；我要恩待谁，就恩待谁。”'),
('CNV', '罗马书', 45, 9, 16, '这样看来，既不是出于人意，也不是由于人为（“人为”原文作“奔走”或“奔跑”），只在于那怜悯人的神。'),
('CNV', '罗马书', 45, 9, 17, '经上有话对法老说：“我把你兴起来，是要藉着你显出我的大能，并且使我的名传遍全地。”'),
('CNV', '罗马书', 45, 9, 18, '这样看来，他愿意怜悯谁就怜悯谁，愿意谁刚硬就使谁刚硬。'),
('CNV', '罗马书', 45, 9, 19, '这样，你会对我说：“那么他为什么责怪人呢？有谁抗拒他的旨意呢？”'),
('CNV', '罗马书', 45, 9, 20, '你这个人哪，你是谁，竟敢跟神顶嘴呢？被造的怎么可以对造他的说：“你为什么把我做成这个样子呢？”'),
('CNV', '罗马书', 45, 9, 21, '陶匠难道没有权用同一团的泥，又做贵重的、又做卑贱的器皿吗？'),
('CNV', '罗马书', 45, 9, 22, '如果神有意要显明他的忿怒，彰显他的大能，而多多容忍那可怒、预备遭毁灭的器皿，'),
('CNV', '罗马书', 45, 9, 23, '为了要使他丰盛的荣耀，彰显在那蒙恩、早已预备要得荣耀的器皿上，这又有什么不可呢？'),
('CNV', '罗马书', 45, 9, 24, '这器皿就是我们这些不但从犹太人中，也从外族人中蒙召的人。'),
('CNV', '罗马书', 45, 9, 25, '就如神在何西阿书上说的：“我要称那不是我子民的为我的子民，那不蒙爱的为蒙爱的；'),
('CNV', '罗马书', 45, 9, 26, '从前在什么地方对他们说：你们不是我的子民，将来就在那里称他们为永活神的儿子。”'),
('CNV', '罗马书', 45, 9, 27, '以赛亚指着以色列人大声说：“以色列子孙的数目虽然多如海沙，得救的不过是剩下的余数；'),
('CNV', '罗马书', 45, 9, 28, '因为主必在地上迅速而彻底地成就他的话。”'),
('CNV', '罗马书', 45, 9, 29, '又如以赛亚早已说过的：“如果不是万军之主给我们存留后裔，我们早就像所多玛和蛾摩拉一样了。”'),
('CNV', '罗马书', 45, 9, 30, '既是这样，我们还有什么可说的呢？那不追求义的外族人却得了义，就是因信而得的义。'),
('CNV', '罗马书', 45, 9, 31, '但以色列人追求律法的义（“律法的义”原文作“义的律法”），却达不到律法的要求。'),
('CNV', '罗马书', 45, 9, 32, '这是什么缘故呢？因为他们不凭信心，只靠行为。他们绊倒在那绊脚石上，'),
('CNV', '罗马书', 45, 9, 33, '正如经上所记：“看哪，我在锡安放了一块绊脚石，是绊倒人的磐石；信靠他的人，必不致失望。”'),
('CNV', '罗马书', 45, 10, 1, '弟兄们，我心里切切盼望的，并且为以色列人向神祈求的，是要他们得救。'),
('CNV', '罗马书', 45, 10, 2, '我可以为他们作证，他们对神有热心，但不是按着真见识；'),
('CNV', '罗马书', 45, 10, 3, '他们既然不明白神的义，而又企图建立自己的义，就不服神的义了。'),
('CNV', '罗马书', 45, 10, 4, '因为律法的终极就是基督，使所有信的人都得着义。'),
('CNV', '罗马书', 45, 10, 5, '论到出于律法的义，摩西写着说：“遵行这些事的人就必因这些事而活。”'),
('CNV', '罗马书', 45, 10, 6, '但那出于信心的义却这样说：“你心里不要说：‘谁要升到天上去呢？’（就是要把基督领下来，）'),
('CNV', '罗马书', 45, 10, 7, '或是说：‘谁要下到深渊去呢？’（就是要把基督从死人中领上来。）”'),
('CNV', '罗马书', 45, 10, 8, '然而那出于信心的义还说什么呢？“这话与你相近，在你口里，也在你心里。”这话就是我们所传信心的信息。'),
('CNV', '罗马书', 45, 10, 9, '你若口里认耶稣为主，心里信神使他从死人中复活，就必得救；'),
('CNV', '罗马书', 45, 10, 10, '因为心里相信就必称义，用口承认就必得救。'),
('CNV', '罗马书', 45, 10, 11, '经上说：“所有信靠他的人，必不致失望。”'),
('CNV', '罗马书', 45, 10, 12, '其实并不分犹太人和希腊人，因为大家同有一位主；他厚待所有求告他的人，'),
('CNV', '罗马书', 45, 10, 13, '因为“凡求告主名的，都必得救。”'),
('CNV', '罗马书', 45, 10, 14, '然而，人还没有信他，怎能求告他呢？没有听见他，怎能信他呢？没有人传扬，怎能听见呢？'),
('CNV', '罗马书', 45, 10, 15, '如果没有蒙差遣，怎能传扬呢？如经上所记：“那些传美事报喜讯的人，他们的脚踪多么美！”'),
('CNV', '罗马书', 45, 10, 16, '但并不是所有的人都顺从福音，因为以赛亚说：“主啊，我们所传的，有谁信呢？”'),
('CNV', '罗马书', 45, 10, 17, '可见信心是从所听的道来的，所听的道是藉着基督的话来的。'),
('CNV', '罗马书', 45, 10, 18, '但是我要说，他们没有听见吗？他们的确听见了，如经上所记：“他们的声音传遍全地，他们的言语传到地极。”'),
('CNV', '罗马书', 45, 10, 19, '我再说：以色列人真的不明白吗？首先，摩西说：“我要使你们对那不是子民的生嫉妒，对那无知的民族起忿怒。”'),
('CNV', '罗马书', 45, 10, 20, '后来，以赛亚也放胆地说：“没有寻找我的，我让他们找到；没有求问我的，我向他们显现。”'),
('CNV', '罗马书', 45, 10, 21, '论到以色列人，他却说：“我整天向那悖逆顶嘴的子民伸开双手。”'),
('CNV', '罗马书', 45, 11, 1, '那么我要说，难道神丢弃了他的子民吗？绝对没有！因为我自己也是以色列人，是亚伯拉罕的后裔，属于便雅悯支派的。'),
('CNV', '罗马书', 45, 11, 2, '神并没有丢弃他预先知道的子民。难道你们不知道在经上以利亚的话是怎样说的吗？他向神控诉以色列人：'),
('CNV', '罗马书', 45, 11, 3, '“主啊，他们杀了你的众先知，拆毁了你的祭坛，只剩下我一个人，他们还在寻索我的性命。”'),
('CNV', '罗马书', 45, 11, 4, '但神怎样回答他呢？“我为自己留下了七千人，是没有向巴力屈膝的。”'),
('CNV', '罗马书', 45, 11, 5, '因此，现在也是这样，按着恩典的拣选，还有剩下的余数。'),
('CNV', '罗马书', 45, 11, 6, '既然是靠着恩典，就不再是由于行为了；不然的话，恩典就不再是恩典了。'),
('CNV', '罗马书', 45, 11, 7, '那又怎么样呢？以色列人恳切寻找的，他们没有得到，蒙拣选的人倒得着了。其余的人都成了顽固的，'),
('CNV', '罗马书', 45, 11, 8, '正如经上所记：“神给了他们麻木的灵，有眼睛却看不见，有耳朵却听不到，直到今日。”'),
('CNV', '罗马书', 45, 11, 9, '大卫也说：“愿他们的筵席成为他们的网罗、陷阱、绊脚石和报应；'),
('CNV', '罗马书', 45, 11, 10, '愿他们的眼睛昏暗，不能看见；愿他们的背脊常常弯曲。”'),
('CNV', '罗马书', 45, 11, 11, '那么我要说，他们失足是要倒下去吗？绝对不是！反而因为他们的过犯，救恩就临到外族人，为了要激起他们奋发。'),
('CNV', '罗马书', 45, 11, 12, '既然他们的过犯可以使世人富足，他们的失败可以使外族人富足，何况他们的丰盛呢？'),
('CNV', '罗马书', 45, 11, 13, '我现在对你们外族人说话，因为我是外族人的使徒，所以尊重我的职分，'),
('CNV', '罗马书', 45, 11, 14, '这样也许可以激起我骨肉之亲奋发，使他们中间有一些人得救。'),
('CNV', '罗马书', 45, 11, 15, '如果他们被舍弃，世人就可以与神复和；他们蒙接纳，不就等于从死人中复活吗？'),
('CNV', '罗马书', 45, 11, 16, '如果首先献上的生面是圣的，整团面也是圣的；如果树根是圣的，树枝也是圣的。'),
('CNV', '罗马书', 45, 11, 17, '如果把几根树枝折下来，让你这野橄榄可以接上去，一同分享那橄榄树根的汁浆，'),
('CNV', '罗马书', 45, 11, 18, '你就不可向那些树枝夸口。你若要夸口，就应当想想：不是你支持着树根，而是树根支持着你。'),
('CNV', '罗马书', 45, 11, 19, '那么你会说，那些树枝被折下来，就是要把我接上去。'),
('CNV', '罗马书', 45, 11, 20, '不错，他们因为不信而被折下来，你因着信才站立得住。只是不可心高气傲，倒要存畏惧的心。'),
('CNV', '罗马书', 45, 11, 21, '神既然不顾惜那本来的树枝，也不会顾惜你。'),
('CNV', '罗马书', 45, 11, 22, '所以要留意神的恩慈和严厉：对跌倒的人，他是严厉的；对你，只要你继续在他的恩慈里，他是恩慈的；不然的话，你也会被砍下来。'),
('CNV', '罗马书', 45, 11, 23, '至于他们，如果不是继续不信，他们仍然会被接上去，因为神能够把他们再接上去。'),
('CNV', '罗马书', 45, 11, 24, '你这从野生的橄榄树上砍下来的，尚且可以不自然地接在栽种的橄榄树上，那些本来就有的树枝，不是更能够接在原来的橄榄树上吗？'),
('CNV', '罗马书', 45, 11, 25, '弟兄们，我不愿意你们对这奥秘一无所知，免得你们自以为聪明。这奥秘就是以色列人当中有一部分是硬心的，直到外族人的全数满了；'),
('CNV', '罗马书', 45, 11, 26, '这样，全以色列都要得救，如经上所记：“拯救者必从锡安出来，除掉雅各家的不敬虔的心；'),
('CNV', '罗马书', 45, 11, 27, '我除去他们罪恶的时候，就与他们立这样的约。”'),
('CNV', '罗马书', 45, 11, 28, '就福音来说，因你们的缘故，他们是仇敌；就拣选来说，因祖宗的缘故，他们是蒙爱的。'),
('CNV', '罗马书', 45, 11, 29, '因为神的恩赏和呼召是决不会反悔的。'),
('CNV', '罗马书', 45, 11, 30, '正如你们从前不顺服神，现在却因着他们的不顺服，你们倒蒙了怜悯；'),
('CNV', '罗马书', 45, 11, 31, '照样，他们因着你们所蒙的怜悯，现在也不顺服，使他们现在也可以蒙怜悯。'),
('CNV', '罗马书', 45, 11, 32, '因为神把所有的人都圈在不顺服之中，为了要怜悯所有的人。'),
('CNV', '罗马书', 45, 11, 33, '神的丰富、智慧和知识，是多么高深啊！他的判断是多么难测，他的道路是多么难寻！'),
('CNV', '罗马书', 45, 11, 34, '“谁知道主的心意，谁作过他的参谋？”'),
('CNV', '罗马书', 45, 11, 35, '“谁先给了他，以致他要偿还呢？”'),
('CNV', '罗马书', 45, 11, 36, '因为万有都是本于他，倚靠他，归于他。愿荣耀归给他，直到永远。阿们。'),
('CNV', '罗马书', 45, 12, 1, '所以弟兄们，我凭着神的仁慈劝你们，要把身体献上，作圣洁而蒙神悦纳的活祭；这是你们理所当然的事奉（“理所当然的事奉”或译：“属灵的敬拜”）。'),
('CNV', '罗马书', 45, 12, 2, '不要模仿这个世代，倒要藉着心意的更新而改变过来，使你们可以察验出什么是神的旨意，就是察验出什么是美好的、蒙他悦纳的和完全的事。'),
('CNV', '罗马书', 45, 12, 3, '我凭着所赐给我的恩典，对你们各人说，不可自视太高，高于所当看的，反而应该照着神分给各人信心的大小，看得适中。'),
('CNV', '罗马书', 45, 12, 4, '就像一个身体有许多肢体，各肢体都有不同的功用；'),
('CNV', '罗马书', 45, 12, 5, '照样，我们大家在基督里成为一个身体，也是互相作肢体。'),
('CNV', '罗马书', 45, 12, 6, '照着所赐给我们的恩典，我们各有不同的恩赐：说预言的，就应当照着信心的程度去说；'),
('CNV', '罗马书', 45, 12, 7, '服事人的，就应当照着恩赐去服事；教导的，就应当照着恩赐教导；'),
('CNV', '罗马书', 45, 12, 8, '劝慰的，就应当照着恩赐劝慰；把财物分给人的要真诚；领导的要殷勤；行善的要乐意。'),
('CNV', '罗马书', 45, 12, 9, '爱，不可虚伪；恶，要厌恶；善，要持守。'),
('CNV', '罗马书', 45, 12, 10, '要以手足之爱彼此相亲，用恭敬的心互相礼让。'),
('CNV', '罗马书', 45, 12, 11, '殷勤不可懒惰，心灵要火热，常常服事主；'),
('CNV', '罗马书', 45, 12, 12, '在盼望中要喜乐，在患难中要坚忍，祷告要恒切。'),
('CNV', '罗马书', 45, 12, 13, '圣徒有缺乏的，就要接济；客旅要热诚地款待。'),
('CNV', '罗马书', 45, 12, 14, '迫害你们的，要为他们祝福；只可祝福，不可咒诅。'),
('CNV', '罗马书', 45, 12, 15, '要与喜乐的人一同喜乐，与哀哭的人一同哀哭。'),
('CNV', '罗马书', 45, 12, 16, '要彼此同心，不可心高气傲，倒要俯就卑微的。不可自以为聪明。'),
('CNV', '罗马书', 45, 12, 17, '不可以恶报恶。大家以为美的事，要努力去作。'),
('CNV', '罗马书', 45, 12, 18, '可能的话，总要尽你们的所能与人和睦。'),
('CNV', '罗马书', 45, 12, 19, '亲爱的啊，不要为自己伸冤，宁可等候主的忿怒，因为经上记着，主说：“伸冤在我，我必报应。”'),
('CNV', '罗马书', 45, 12, 20, '相反地，“如果你的仇敌饿了，就给他吃；如果渴了，就给他喝。因为你这样作，就是把炭火堆在他的头上。”'),
('CNV', '罗马书', 45, 12, 21, '不可被恶所胜，反要以善胜恶。'),
('CNV', '罗马书', 45, 13, 1, '政府的权柄，人人都应当服从。因为没有一样权柄不是从神来的；掌权的都是神设立的。'),
('CNV', '罗马书', 45, 13, 2, '所以抗拒掌权的，就是反对神所设立的；反对的人必自招刑罚。'),
('CNV', '罗马书', 45, 13, 3, '执政的不是要使行善的惧怕，而是要使作恶的惧怕。你想不怕掌权的吗？只要行善，就会得到称赞；'),
('CNV', '罗马书', 45, 13, 4, '因为他是神的仆役，是对你有益的。但如果你作恶，就应当惧怕；因为他佩剑，不是没有作用的。他是神的仆役，是向作恶的人施行刑罚的。'),
('CNV', '罗马书', 45, 13, 5, '所以你们必须服从，不但是因为刑罚，也是因为良心的缘故。'),
('CNV', '罗马书', 45, 13, 6, '因此，你们也当纳税，因为他们是神的差役，专责处理这事的。'),
('CNV', '罗马书', 45, 13, 7, '你们要向各人清还所欠的；应当纳税的，就要给他纳税；应当进贡的，就给他进贡；应当敬畏的，就敬畏他；应当尊敬的，就尊敬他。'),
('CNV', '罗马书', 45, 13, 8, '不要欠人的债；但在彼此相爱的事上，要觉得是欠了人的债。爱别人的，就成全了律法。'),
('CNV', '罗马书', 45, 13, 9, '那“不可奸淫，不可杀人，不可偷盗，不可贪心”等等的诫命，都包括在“爱人如己”这一句话里面了。'),
('CNV', '罗马书', 45, 13, 10, '爱是不加害于人的，所以爱是成全律法的。'),
('CNV', '罗马书', 45, 13, 11, '还有，你们知道这是什么时期了，现在正是你们应该睡醒的时候，因为我们得救，现在比初信的时候更加接近了。'),
('CNV', '罗马书', 45, 13, 12, '黑夜已深，白昼近了，所以我们要除掉暗昧的行为，带上光明的武器。'),
('CNV', '罗马书', 45, 13, 13, '行事为人要光明磊落，好像行在白昼。不可荒宴醉酒，不可放荡纵欲，不可纷争嫉妒。'),
('CNV', '罗马书', 45, 13, 14, '总要披戴主耶稣基督，不要为肉体安排，去放纵私欲。'),
('CNV', '罗马书', 45, 14, 1, '你们要接纳信心软弱的人，不要论断引起争论的事。'),
('CNV', '罗马书', 45, 14, 2, '有人相信所有的食物都可以吃，信心软弱的人却只吃蔬菜。'),
('CNV', '罗马书', 45, 14, 3, '吃的人不要轻看不吃的人，不吃的人也不要批评吃的人，因为神已经接纳他了。'),
('CNV', '罗马书', 45, 14, 4, '你是谁，竟然批评别人的家仆呢？他或站稳或跌倒，只和自己的主人有关；但他必定站稳，因为主能够使他站稳。'),
('CNV', '罗马书', 45, 14, 5, '有人认为这日比那日好，也有人认为日日都是一样；只要各人自己心意坚定就可以了。'),
('CNV', '罗马书', 45, 14, 6, '守日的人是为主守的，吃的人是为主吃的，因为他感谢神；不吃的人是为主不吃，他也感谢神。'),
('CNV', '罗马书', 45, 14, 7, '我们没有一个人为自己活，也没有一个人为自己死。我们若活着，是为主而活；'),
('CNV', '罗马书', 45, 14, 8, '我们若死了，是为主而死。所以，我们无论活着或是死了，总是属于主的人。'),
('CNV', '罗马书', 45, 14, 9, '为了这缘故，基督死了，又活过来，就是要作死人和活人的主。'),
('CNV', '罗马书', 45, 14, 10, '这样，你为什么批评你的弟兄呢？为什么又轻看你的弟兄呢？我们都要站在神的审判台前；'),
('CNV', '罗马书', 45, 14, 11, '因为经上记着：“主说，我指着我的永生起誓：万膝必向我跪拜，万口必称颂神。”'),
('CNV', '罗马书', 45, 14, 12, '这样看来，我们各人都要把自己的事向神交代。'),
('CNV', '罗马书', 45, 14, 13, '所以，我们不要再彼此批评了；倒要立定主意，决不作绊倒弟兄或使他跌倒的事。'),
('CNV', '罗马书', 45, 14, 14, '我知道，并且在主耶稣里深信，没有一样东西的本身是不洁的，但如果有人认为是不洁的，对他来说那东西就成为不洁了。'),
('CNV', '罗马书', 45, 14, 15, '如果你为了食物使你的弟兄忧愁，你就不再是凭着爱心行事了。你不可因着你的食物，使基督已经替他死了的人灭亡。'),
('CNV', '罗马书', 45, 14, 16, '所以，不可使你们看为好的被人毁谤；'),
('CNV', '罗马书', 45, 14, 17, '因为神的国不在于吃喝，而在于公义、和睦，以及圣灵里的喜乐。'),
('CNV', '罗马书', 45, 14, 18, '这样服事基督的人，必蒙神喜悦，又得众人嘉许。'),
('CNV', '罗马书', 45, 14, 19, '所以，我们总要追求和睦的事，与彼此造就的事。'),
('CNV', '罗马书', 45, 14, 20, '不可因食物的缘故拆毁神的工作。一切都是洁净的，但人若因食物绊倒弟兄，对他来说，这就是恶事了。'),
('CNV', '罗马书', 45, 14, 21, '无论是吃肉，是喝酒，或是什么使你的弟兄跌倒的事，一律不要作才好。'),
('CNV', '罗马书', 45, 14, 22, '你所信的，你自己要在神面前持守。人在经自己考验后认可的事上能够不自责，他就有福了。'),
('CNV', '罗马书', 45, 14, 23, '但如果有人存着疑惑的心去吃，他就被定罪了，因为他不是出于信心。凡不是出于信心的，都是罪。'),
('CNV', '罗马书', 45, 15, 1, '我们坚强的人，应该担当不坚强的人的软弱，不应该求自己的喜悦。'),
('CNV', '罗马书', 45, 15, 2, '我们各人务要叫邻舍喜悦，好让他得到益处、得到造就。'),
('CNV', '罗马书', 45, 15, 3, '因为连基督也不求自己的喜悦；反而像经上所记的：“辱骂你的人的辱骂，都落在我的身上。”'),
('CNV', '罗马书', 45, 15, 4, '从前经上所写的，都是为教训我们而写的，好使我们藉着忍耐和圣经中的安慰得着盼望。'),
('CNV', '罗马书', 45, 15, 5, '愿赐忍耐和安慰的神，使你们彼此同心，效法基督耶稣，'),
('CNV', '罗马书', 45, 15, 6, '同心一致地荣耀我们主耶稣基督的父神。'),
('CNV', '罗马书', 45, 15, 7, '因此，你们应当彼此接纳，就像基督接纳了你们一样，使荣耀归于神。'),
('CNV', '罗马书', 45, 15, 8, '我说，基督为了神的真理，成了受割礼的人的仆人，为的是要证实对祖先的应许，'),
('CNV', '罗马书', 45, 15, 9, '使外族人因着所蒙的怜悯荣耀神；如经上所记：“因此我要在列邦中称赞你，歌颂你的名。”'),
('CNV', '罗马书', 45, 15, 10, '又说：“列邦啊，当与他的子民一同快乐。”'),
('CNV', '罗马书', 45, 15, 11, '又说：“万国啊，你们当赞美主；愿万民都颂赞他。”'),
('CNV', '罗马书', 45, 15, 12, '以赛亚也说：“将来必有耶西的根，就是那兴起来治理列邦的；列邦都寄望于他。”'),
('CNV', '罗马书', 45, 15, 13, '愿那赐盼望的神，因着你们的信，把一切喜乐平安充满你们，使你们靠着圣灵的大能满有盼望。'),
('CNV', '罗马书', 45, 15, 14, '我的弟兄们，我个人深信你们自己也满有良善，充满丰富的知识，也能够彼此劝导。'),
('CNV', '罗马书', 45, 15, 15, '但有些地方，我写得稍为大胆一点，是要提醒你们；我因着神赐给我的恩典，'),
('CNV', '罗马书', 45, 15, 16, '为外族人作了基督耶稣的仆役，作了神福音的祭司，使所献上的外族人得蒙悦纳，靠着圣灵成为圣洁。'),
('CNV', '罗马书', 45, 15, 17, '所以，在神的事上，我在基督耶稣里倒有可以引以为荣的。'),
('CNV', '罗马书', 45, 15, 18, '别的我不敢说，我只说基督藉着我所作的事，就是用言语行为，藉着神迹和奇事的大能，以及圣灵的大能，使外族人顺服；这样，我从耶路撒冷直到以利里古，把基督的福音都传开了。'),
('CNV', '罗马书', 45, 15, 20, '我立定主意，不在宣扬过基督的地方传福音，免得建立在别人的根基上，'),
('CNV', '罗马书', 45, 15, 21, '反而照经上所记：“那对他一无所闻的，将要看见；那没有听过的，将要明白。”'),
('CNV', '罗马书', 45, 15, 22, '因此，我多次受到拦阻，不能到你们那里去。'),
('CNV', '罗马书', 45, 15, 23, '但现在这一带再没有可传的地方，而我多年来又很想去见你们，'),
('CNV', '罗马书', 45, 15, 24, '所以，无论我什么时候到西班牙去，都希望趁我路过时和你们见面，先稍微满足我的心愿，然后由你们给我送行到那里去。'),
('CNV', '罗马书', 45, 15, 25, '不过，我现在为了供应圣徒的事要往耶路撒冷去；'),
('CNV', '罗马书', 45, 15, 26, '因为马其顿和亚该亚人乐意捐了一些钱，给耶路撒冷圣徒中的穷人。'),
('CNV', '罗马书', 45, 15, 27, '他们是乐意的，而且那也是他们的本分（“本分”原文作“债”），因为外族人既然分享了犹太人属灵的好处，就应该供应他们肉身的需要。'),
('CNV', '罗马书', 45, 15, 28, '等我办好这件事，把这笔款项安全地交了给他们，我就要路过你们那里到西班牙去。'),
('CNV', '罗马书', 45, 15, 29, '我知道我到你们那里去的时候，一定会带着基督丰盛的福分。'),
('CNV', '罗马书', 45, 15, 30, '弟兄们，我靠着我们的主耶稣基督，凭着圣灵的慈爱，劝你们和我一同竭力为我向神祈祷，'),
('CNV', '罗马书', 45, 15, 31, '求神救我脱离犹太地不信从的人，使我带到耶路撒冷的捐款，可以得到圣徒的悦纳；'),
('CNV', '罗马书', 45, 15, 32, '也使我照着神的旨意，高高兴兴地到你们那里去，好和你们一同得到安息。'),
('CNV', '罗马书', 45, 15, 33, '愿赐平安的神与你们众人同在。阿们。'),
('CNV', '罗马书', 45, 16, 1, '我向你们推荐我们的姊妹非比；她是坚革里教会的执事。'),
('CNV', '罗马书', 45, 16, 2, '请你们在主里用合乎圣徒身分的态度去接待她。无论她在什么事上有需要，请你们都帮助她；因为她曾经帮助许多人，也帮助了我。'),
('CNV', '罗马书', 45, 16, 3, '问候在基督耶稣里与我同工的百基拉和亚居拉；'),
('CNV', '罗马书', 45, 16, 4, '他们为了我的性命，置生死于度外，不但我感激他们，连外族的众教会也感激他们。'),
('CNV', '罗马书', 45, 16, 5, '也问候他们家里的教会。问候我亲爱的以拜尼妥，他是亚西亚省初结的果子。'),
('CNV', '罗马书', 45, 16, 6, '问候马利亚，她为你们多多劳苦。'),
('CNV', '罗马书', 45, 16, 7, '问候曾经与我一同被囚的亲族安多尼古和犹尼亚；他们在使徒中是有名望的，也比我先在基督里。'),
('CNV', '罗马书', 45, 16, 8, '问候在主里我亲爱的暗伯利。'),
('CNV', '罗马书', 45, 16, 9, '问候在基督里与我们同工的珥巴努和我亲爱的士达古。'),
('CNV', '罗马书', 45, 16, 10, '问候在基督里蒙称许的亚比利。问候亚里斯多博家里的人。'),
('CNV', '罗马书', 45, 16, 11, '问候我的亲族希罗天。问候拿其舒家中在主里的人。'),
('CNV', '罗马书', 45, 16, 12, '问候在主里劳苦的土非拿和土富撒。问候亲爱的彼息；她在主里多多劳苦。'),
('CNV', '罗马书', 45, 16, 13, '问候在主里蒙拣选的鲁孚和他的母亲；她也是我在主里的母亲。'),
('CNV', '罗马书', 45, 16, 14, '问候亚逊其都、弗勒干、赫米、百罗巴、赫马，以及和他们在一起的弟兄们。'),
('CNV', '罗马书', 45, 16, 15, '问候非罗罗哥和犹利亚，尼利亚与他的姊妹和阿林巴，以及同他们在一起的众圣徒。'),
('CNV', '罗马书', 45, 16, 16, '你们要用圣洁的亲吻彼此问安。基督的众教会都问候你们。'),
('CNV', '罗马书', 45, 16, 17, '弟兄们，我劝你们要提防那些离间你们、绊倒你们、使你们违反你们所学的教义的人。你们也要避开他们，'),
('CNV', '罗马书', 45, 16, 18, '因为这样的人不服事我们的主基督，只服事自己的肚腹，用花言巧语欺骗老实人的心。'),
('CNV', '罗马书', 45, 16, 19, '你们的顺服已经名闻各处，所以我为你们高兴。我愿你们在善事上有智慧，在恶事上毫不沾染。'),
('CNV', '罗马书', 45, 16, 20, '赐平安的神快要把撒但践踏在你们脚下。愿我们主耶稣的恩惠与你们同在。'),
('CNV', '罗马书', 45, 16, 21, '我的同工提摩太和我的亲族路求、耶逊和所西巴德都问候你们。'),
('CNV', '罗马书', 45, 16, 22, '（我─代笔写这封信的德图─也在主里问候你们。）'),
('CNV', '罗马书', 45, 16, 23, '那接待我也接待全教会的该犹，问候你们。本城的司库以拉都和夸图弟兄问候你们。（有些抄本有第24节：“愿我们主耶稣基督的恩惠，与你们众人同在。阿们。”）'),
('CNV', '罗马书', 45, 16, 25, '神能依照我所传的福音和耶稣基督所传的信息，照着他奥秘的启示，坚定你们。这奥秘自古以来秘而不宣，'),
('CNV', '罗马书', 45, 16, 26, '但现在藉着众先知所写的，照着永恒的神的谕旨，已经向万国显明出来，使他们相信而顺服。'),
('CNV', '罗马书', 45, 16, 27, '愿荣耀藉着耶稣基督，归给独一全智的神，直到永远。阿们。'),
('CNV', '哥林多前书', 46, 1, 1, '奉神旨意蒙召作基督耶稣使徒的保罗，和苏提尼弟兄，'),
('CNV', '哥林多前书', 46, 1, 2, '写信给在哥林多神的教会，就是在基督耶稣里已经被分别为圣，蒙召为圣徒的人，和所有在各地呼求我们主耶稣基督的名的人。基督是他们的主，也是我们的主。'),
('CNV', '哥林多前书', 46, 1, 3, '愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '哥林多前书', 46, 1, 4, '我因着神在基督耶稣里赐给你们的恩典，常常为你们感谢我的神，'),
('CNV', '哥林多前书', 46, 1, 5, '因为你们在他里面凡事都富足，很有口才，知识丰富，'),
('CNV', '哥林多前书', 46, 1, 6, '就如我们为基督所作的见证在你们中间得到坚立一样，'),
('CNV', '哥林多前书', 46, 1, 7, '以致你们在恩赐上一无所缺，殷切盼望着我们主耶稣基督的显现；'),
('CNV', '哥林多前书', 46, 1, 8, '他也必坚定你们到底，使你们在我们主耶稣基督的日子无可指摘。'),
('CNV', '哥林多前书', 46, 1, 9, '神是信实的，他呼召了你们，是要你们与他的儿子我们主耶稣基督连合在一起。'),
('CNV', '哥林多前书', 46, 1, 10, '弟兄们，我凭着我们主耶稣基督的名，劝你们大家要同心，在你们中间不要分党，只要在同一的心思、同一的意念上团结起来。'),
('CNV', '哥林多前书', 46, 1, 11, '我的弟兄们，革来氏家里的人向我提到你们，说你们中间有纷争。'),
('CNV', '哥林多前书', 46, 1, 12, '我的意思就是，你们各人说，我是保罗派的，我是亚波罗派的，我是矶法派的，我是基督派的。'),
('CNV', '哥林多前书', 46, 1, 13, '基督是分开的吗？保罗为你们钉了十字架吗？你们受洗是归入保罗的名下吗？'),
('CNV', '哥林多前书', 46, 1, 14, '我感谢神，除了基利司布和该犹以外，我没有给你们任何人施过洗，'),
('CNV', '哥林多前书', 46, 1, 15, '所以你们没有人可以说是受洗归入我名下的。'),
('CNV', '哥林多前书', 46, 1, 16, '我也给司提反一家的人施过洗；此外，有没有给别人施过洗，我就不记得了。'),
('CNV', '哥林多前书', 46, 1, 17, '基督差遣我，不是要我去施洗，而是去传福音；不是靠着智慧的言论去传，免得基督的十字架失去了效力。'),
('CNV', '哥林多前书', 46, 1, 18, '因为十字架的道理，对走向灭亡的人来说是愚笨的，但对我们这些得救的人，却是神的大能。'),
('CNV', '哥林多前书', 46, 1, 19, '因为经上记着说：“我要灭绝智慧人的智慧，废弃聪明人的聪明。”'),
('CNV', '哥林多前书', 46, 1, 20, '智慧人在哪里？经学家在哪里？今世的辩士在哪里？神不是使属世的智慧变成了愚笨吗？'),
('CNV', '哥林多前书', 46, 1, 21, '因为在神的智慧里，世人凭自己的智慧，既然不能认识神，神就乐意藉着所传的愚笨的道理，去拯救那些信的人。'),
('CNV', '哥林多前书', 46, 1, 22, '犹太人要求神迹，希腊人寻找智慧，'),
('CNV', '哥林多前书', 46, 1, 23, '我们却传扬钉十字架的基督；在犹太人看来是绊脚石，在外族人看来是愚笨的，'),
('CNV', '哥林多前书', 46, 1, 24, '但对那些蒙召的人，不论是犹太人或希腊人，基督是神的能力，神的智慧。'),
('CNV', '哥林多前书', 46, 1, 25, '因为神的愚笨总比人智慧，神的软弱总比人刚强。'),
('CNV', '哥林多前书', 46, 1, 26, '弟兄们，你们想想，你们这些蒙召的，按人（“人”或译：“世上的标准”、“世界的标准”）来看有智慧的不多，有权势的不多，出身尊贵的也不多。'),
('CNV', '哥林多前书', 46, 1, 27, '但是神却拣选了世上愚笨的，使那些有智慧的羞愧。他也拣选了世上软弱的，使那些刚强的羞愧。'),
('CNV', '哥林多前书', 46, 1, 28, '他也拣选了世上卑贱的和被人轻视的，以及算不得什么的，为了要废弃那些自以为是的，'),
('CNV', '哥林多前书', 46, 1, 29, '使所有的人在神面前都不能自夸。'),
('CNV', '哥林多前书', 46, 1, 30, '你们因着神得以在基督耶稣里，他使基督成了我们的智慧；就是公义、圣洁和救赎，'),
('CNV', '哥林多前书', 46, 1, 31, '正如经上所说的：“夸口的应当靠着主夸口。”'),
('CNV', '哥林多前书', 46, 2, 1, '弟兄们，我从前到你们那里去，并没有用高言大智向你们传讲神的奥秘。'),
('CNV', '哥林多前书', 46, 2, 2, '因为我曾立定主意，在你们中间什么都不想知道，只知道耶稣基督和他钉十字架的事。'),
('CNV', '哥林多前书', 46, 2, 3, '我在你们那里的时候，又软弱又惧怕，而且战战兢兢；'),
('CNV', '哥林多前书', 46, 2, 4, '我说的话、讲的道，都不是用智慧的话去说服人，而是用圣灵和能力来证明，'),
('CNV', '哥林多前书', 46, 2, 5, '使你们的信不是凭着人的智慧，而是凭着神的能力。'),
('CNV', '哥林多前书', 46, 2, 6, '然而在信心成熟的人中间，我们也讲智慧，但不是这世代的智慧，也不是这世代将要灭亡的执政者的智慧。'),
('CNV', '哥林多前书', 46, 2, 7, '我们所讲的，是从前隐藏的、神奥秘的智慧，就是神在万世以前，为我们的荣耀所预定的；'),
('CNV', '哥林多前书', 46, 2, 8, '这智慧，这世代执政的人没有一个知道，如果他们知道，就不会把荣耀的主钉在十字架上了。'),
('CNV', '哥林多前书', 46, 2, 9, '正如经上所记：“神为爱他的人所预备的，是眼睛未曾见过，耳朵未曾听过，人心也未曾想到的。”'),
('CNV', '哥林多前书', 46, 2, 10, '但神却藉着圣灵把这些向我们显明了，因为圣灵测透万事，连神深奥的事也测透了。'),
('CNV', '哥林多前书', 46, 2, 11, '除了在人里面的灵，谁能知道人的事呢？同样，除了神的灵，也没有人知道神的事。'),
('CNV', '哥林多前书', 46, 2, 12, '我们所领受的，不是这世界的灵，而是从神来的灵，使我们能知道神开恩赐给我们的事。'),
('CNV', '哥林多前书', 46, 2, 13, '我们也讲这些事，不是用人的智慧所教的言语，而是用圣灵所教的言语，向属灵的人解释属灵的事（“向属灵的人解释属灵的事”或译：“用属灵的话解释属灵的事”）。'),
('CNV', '哥林多前书', 46, 2, 14, '然而属血气的人不接受神的灵的事，因为他以为是愚笨的；而且他也不能够明白，因为这些事，要有属灵的眼光才能领悟。'),
('CNV', '哥林多前书', 46, 2, 15, '属灵的人能看透万事，却没有人能看透他，'),
('CNV', '哥林多前书', 46, 2, 16, '如经上所记：“谁曾知道主的心意，能够指教他呢？”但我们已经得着基督的心意了。'),
('CNV', '哥林多前书', 46, 3, 1, '弟兄们，我从前对你们说话，还不能把你们看作属灵的人，只能看作属肉体的人，看作在基督里的婴孩。'),
('CNV', '哥林多前书', 46, 3, 2, '我喂给你们吃的是奶，不是饭，因为那时你们不能吃，就是现在还是不能，'),
('CNV', '哥林多前书', 46, 3, 3, '因为你们仍然是属肉体的。在你们当中既然有嫉妒纷争，你们不还是属肉体，照着世人的方式而行吗？'),
('CNV', '哥林多前书', 46, 3, 4, '有人说“我是保罗派的”，又有人说“我是亚波罗派的”，你们不是和世人一样吗？'),
('CNV', '哥林多前书', 46, 3, 5, '亚波罗算什么？保罗算什么？我们不过是神的仆人，你们藉着我们信了主；按着主所赐给各人的，'),
('CNV', '哥林多前书', 46, 3, 6, '我栽种了，亚波罗浇灌了，唯有神使它生长。'),
('CNV', '哥林多前书', 46, 3, 7, '所以，栽种的算不得什么，浇灌的也算不得什么，只在乎那使它生长的神。'),
('CNV', '哥林多前书', 46, 3, 8, '栽种的和浇灌的都是一样，只是各人要照着自己的劳苦得着自己的报酬。'),
('CNV', '哥林多前书', 46, 3, 9, '我们是神的同工，你们是神的田地，神的房屋。'),
('CNV', '哥林多前书', 46, 3, 10, '我照着神赐给我的恩典，就像一个聪明的工程师，立好了根基，别人在上面建造。各人要注意怎样在上面建造，'),
('CNV', '哥林多前书', 46, 3, 11, '因为除了那已经立好的根基以外，没有人能立别的根基。那根基就是耶稣基督。'),
('CNV', '哥林多前书', 46, 3, 12, '如果有人用金、银、宝石、草、木、禾秸，在这根基上建造，'),
('CNV', '哥林多前书', 46, 3, 13, '各人的工程将来必要显露，因为那日子必把它显明出来。有火要把它显露出来，那火要考验各人的工程是怎样的。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '哥林多前书', 46, 3, 14, '如果有人在这根基上建造的工程存得住，他就要得到赏赐；'),
('CNV', '哥林多前书', 46, 3, 15, '如果有人的工程被烧毁，他就要受亏损；自己却要得救，只是要像从火里经过一样。'),
('CNV', '哥林多前书', 46, 3, 16, '难道不知道你们是神的殿，神的灵住在你们里面吗？'),
('CNV', '哥林多前书', 46, 3, 17, '如果有人毁坏神的殿，神必要毁坏这人，因为神的殿是圣洁的，这殿就是你们。'),
('CNV', '哥林多前书', 46, 3, 18, '谁也不要自欺。如果你们当中有人以为自己在这世代里是有智慧的，他就应该变为愚笨，好让他有智慧。'),
('CNV', '哥林多前书', 46, 3, 19, '因为这世界的智慧，在神看来是愚笨的，如经上所记：“他使有智慧的人中了自己的诡计。”'),
('CNV', '哥林多前书', 46, 3, 20, '又说：“主知道智慧人的意念是虚妄的。”'),
('CNV', '哥林多前书', 46, 3, 21, '所以，谁都不可拿人来夸耀，因为一切都是你们的。'),
('CNV', '哥林多前书', 46, 3, 22, '无论是保罗，是亚波罗，是矶法，是世界，是生，是死，是现在的事，是将来的事，都是你们的。'),
('CNV', '哥林多前书', 46, 3, 23, '你们是属基督的，基督是属神的。'),
('CNV', '哥林多前书', 46, 4, 1, '这样，人应该把我们看作基督的仆人，神奥秘的事的管家。'),
('CNV', '哥林多前书', 46, 4, 2, '对于管家的要求，就是要他忠心。'),
('CNV', '哥林多前书', 46, 4, 3, '我被你们论断，或被人间法庭审判，我都认为是极小的事，连我自己也不论断自己。'),
('CNV', '哥林多前书', 46, 4, 4, '我虽然问心无愧，却不能因此自以为义，因为判断我的是主。'),
('CNV', '哥林多前书', 46, 4, 5, '所以时候还没有到，你们不要批评，直等到主来；他要照出黑暗中的隐情，显明人心里的动机。那时，各人要从神那里得著称赞。'),
('CNV', '哥林多前书', 46, 4, 6, '弟兄们，我为你们的缘故，拿了这些事来比拟自己和亚波罗，让你们在我们身上学到的，不会超过圣经所记的，免得你们中间有人自高自大，看重这个轻视那个。'),
('CNV', '哥林多前书', 46, 4, 7, '使你与人不同的是谁呢？你有什么不是领受的呢？既然是领受的，为什么要自夸，好像不是领受的呢？'),
('CNV', '哥林多前书', 46, 4, 8, '你们已经满足了，已经丰富了，不需要我们，自己作王了。我恨不得你们真的作了王，让我们也可以跟你们一同作王！'),
('CNV', '哥林多前书', 46, 4, 9, '我想神是把我们作使徒的列在最后，好像定了死刑的人，因为我们成了一台戏给宇宙观看，就是给天使和世人观看！'),
('CNV', '哥林多前书', 46, 4, 10, '我们为基督的缘故，成了愚笨的；你们在基督里，倒成了聪明的。我们软弱，你们倒强壮；你们受人尊敬，我们倒被轻视。'),
('CNV', '哥林多前书', 46, 4, 11, '直到现在，我们还是又饥又渴，衣不蔽体，又挨打，又没有栖身的地方，'),
('CNV', '哥林多前书', 46, 4, 12, '并且劳苦，亲手作工。被人咒骂，我们就祝福；遭受迫害，我们就忍受；'),
('CNV', '哥林多前书', 46, 4, 13, '被人毁谤，我们却好好地劝导；直到现在，人还是把我们当作世上的垃圾，万物的渣滓。'),
('CNV', '哥林多前书', 46, 4, 14, '我写这些话，不是要叫你们羞愧，而是把你们当作我亲爱的儿女一样劝戒你们。'),
('CNV', '哥林多前书', 46, 4, 15, '纵然你们在基督里有上万的启蒙教师，可是父亲却不多，因为是我在基督耶稣里藉着福音生了你们。'),
('CNV', '哥林多前书', 46, 4, 16, '所以我劝你们要效法我。'),
('CNV', '哥林多前书', 46, 4, 17, '因此，我打发提摩太到你们那里去。他是我在主里亲爱又忠心的儿子，他要提醒你们我在基督里是怎样行事为人，正如我在各处教会中所教导的一样。'),
('CNV', '哥林多前书', 46, 4, 18, '有人以为我不会到你们那里去，就自高自大。'),
('CNV', '哥林多前书', 46, 4, 19, '然而主若愿意，我很快就要到你们那里去；到时我要知道的，不是那些自高自大的人所讲的，而是他们的能力。'),
('CNV', '哥林多前书', 46, 4, 20, '因为神的国不在乎言语，而在乎权能。'),
('CNV', '哥林多前书', 46, 4, 21, '你们愿意怎么样呢？要我带着刑杖到你们那里去，还是以温柔的灵，带着爱心去呢？'),
('CNV', '哥林多前书', 46, 5, 1, '听说你们中间竟然有淫乱的事，这样的淫乱在教外人中间都没有，就是有人和他的继母同居。'),
('CNV', '哥林多前书', 46, 5, 2, '你们还是自高自大！难道你们不该觉得痛心，把作这件事的人从你们中间赶出去吗？'),
('CNV', '哥林多前书', 46, 5, 3, '我身体虽然不在你们那里，心灵却与你们在一起，好像我亲身在那里审判了作这件事的人，'),
('CNV', '哥林多前书', 46, 5, 4, '就是当你们奉我们主耶稣的名聚集在一起，我的灵在那里，我们主耶稣的权能也同在的时候，'),
('CNV', '哥林多前书', 46, 5, 5, '要把这样的人交给撒但，败坏他的身体，使他的灵魂在主的日子可以得救。'),
('CNV', '哥林多前书', 46, 5, 6, '你们这样自夸是不好的。你们不知道一点面酵能使全团面发起来吗？'),
('CNV', '哥林多前书', 46, 5, 7, '你们既是无酵的面，就应当把旧酵除净，好让你们成为新的面团；因为我们逾越节的羊羔基督已经被杀献祭了。'),
('CNV', '哥林多前书', 46, 5, 8, '所以我们守这节，不可用旧酵，也不可用又邪又恶的酵，而是要用纯洁真实的无酵饼。'),
('CNV', '哥林多前书', 46, 5, 9, '我以前写信告诉你们，不可与淫乱的人来往。'),
('CNV', '哥林多前书', 46, 5, 10, '这话当然不是指这世上行淫乱的、贪心的、勒索的，或拜偶像的人；如果是这样，你们就非脱离这世界不可。'),
('CNV', '哥林多前书', 46, 5, 11, '但现在我写信告诉你们，如果有称为弟兄，却是行淫乱、贪心、拜偶像、辱骂人、醉酒或勒索的，这样的人，不可和他来往，连和他吃饭都不可。'),
('CNV', '哥林多前书', 46, 5, 12, '审判教外的人，跟我有什么关系？教内的人不是你们审判的吗？'),
('CNV', '哥林多前书', 46, 5, 13, '至于教外的人，神会审判他们。你们要把那恶人从你们中间赶出去。'),
('CNV', '哥林多前书', 46, 6, 1, '你们中间有人和弟兄起了争执，怎敢告到不义的人面前，却不告在圣徒面前呢？'),
('CNV', '哥林多前书', 46, 6, 2, '你们不知道圣徒要审判世界吗？既然世界要由你们来审判，难道你们不配审判这些最小的事吗？'),
('CNV', '哥林多前书', 46, 6, 3, '你们不知道我们要审判天使吗？何况今生的事呢？'),
('CNV', '哥林多前书', 46, 6, 4, '你们既然要审判今生的事，为什么让教会不重视的人来审判呢？'),
('CNV', '哥林多前书', 46, 6, 5, '我说这话，是要使你们羞愧。难道你们中间没有一个有智慧的人，能够审判弟兄之间的事吗？'),
('CNV', '哥林多前书', 46, 6, 6, '你们竟然是弟兄告弟兄，而且告到不信的人面前去吗？'),
('CNV', '哥林多前书', 46, 6, 7, '你们彼此告状，已经是你们的失败了。为什么不宁愿受委屈呢？为什么不甘心吃亏呢？'),
('CNV', '哥林多前书', 46, 6, 8, '但你们反倒使人受委屈，叫人吃亏，而且他们就是你们的弟兄。'),
('CNV', '哥林多前书', 46, 6, 9, '你们不知道不义的人不能承受神的国吗？不要自欺，无论是行淫乱的、拜偶像的、奸淫的、作娈童的、亲男色的、'),
('CNV', '哥林多前书', 46, 6, 10, '偷窃的、贪心的、醉酒的、辱骂人的或勒索的，都不能承受神的国。'),
('CNV', '哥林多前书', 46, 6, 11, '你们有些人从前也是这样的，但现在藉着我们主耶稣基督的名，靠着我们神的灵，都已经洗净了，圣洁了，称义了。'),
('CNV', '哥林多前书', 46, 6, 12, '什么事我都可以作，但不是都有益处。什么事我都可以作，但我不要受任何事的辖制。'),
('CNV', '哥林多前书', 46, 6, 13, '食物是为了肚腹，肚腹是为了食物；但神却要把这两样都废掉。身体不是为了淫乱，而是为了主，主也是为了身体。'),
('CNV', '哥林多前书', 46, 6, 14, '神不但使主复活了，也要用他的能力使我们复活。'),
('CNV', '哥林多前书', 46, 6, 15, '你们不知道你们的身体就是基督的肢体吗？这样，我们可以把基督的肢体当作娼妓的肢体吗？当然不可以！'),
('CNV', '哥林多前书', 46, 6, 16, '你们不知道那跟娼妓苟合的，就是与她成为一体了吗？因为经上说：“二人要成为一体。”'),
('CNV', '哥林多前书', 46, 6, 17, '但那与主联合的，就是与他成为一灵了。'),
('CNV', '哥林多前书', 46, 6, 18, '你们要逃避淫乱的事。人所犯的，无论是什么罪，都是在身体以外，唯有行淫乱的，是触犯自己的身体。'),
('CNV', '哥林多前书', 46, 6, 19, '你们不知道你们的身体就是那位住在你们里面的圣灵的殿吗？这圣灵是你们从神那里领受的。你们不是属于自己的，'),
('CNV', '哥林多前书', 46, 6, 20, '因为你们是用重价买来的。所以你们务要用自己的身体荣耀神。'),
('CNV', '哥林多前书', 46, 7, 1, '关于你们信上所提的事:“男人不亲近女人倒好”。'),
('CNV', '哥林多前书', 46, 7, 2, '但为了避免淫乱的事，男人应当各有自己的妻子，女人也应当各有自己的丈夫。'),
('CNV', '哥林多前书', 46, 7, 3, '丈夫对妻子应该尽他的本分，妻子对丈夫也应当这样。'),
('CNV', '哥林多前书', 46, 7, 4, '妻子对自己的身体没有主权，权在丈夫；照样，丈夫对自己的身体也没有主权，权在妻子。'),
('CNV', '哥林多前书', 46, 7, 5, '夫妻不可彼此亏负，除非为了要专心祷告，双方才可以同意暂时分房。以后仍要同房，免得撒但趁着你们情不自禁的时候诱惑你们。'),
('CNV', '哥林多前书', 46, 7, 6, '我说这话是容许你们，并不是命令。'),
('CNV', '哥林多前书', 46, 7, 7, '我愿人人都像我一样；只是各人有各人从神得来的恩赐，有人是这样，有人是那样。'),
('CNV', '哥林多前书', 46, 7, 8, '我现在要对未婚的人和寡妇说，他们若保持像我这样就好了；'),
('CNV', '哥林多前书', 46, 7, 9, '但如果不能自制，就应当结婚，因为结婚总比欲火焚身好。'),
('CNV', '哥林多前书', 46, 7, 10, '我要吩咐已婚的人（其实不是我，而是主吩咐的），妻子不可离开丈夫。'),
('CNV', '哥林多前书', 46, 7, 11, '如果离开了，就不可再嫁，不然，就要跟丈夫复合。丈夫也不可离弃妻子。'),
('CNV', '哥林多前书', 46, 7, 12, '我要对其余的人说（是我说的，不是主说的），倘若某弟兄有不信的妻子，而她也情愿和他住在一起，他就不要离弃她。'),
('CNV', '哥林多前书', 46, 7, 13, '如果妻子有不信的丈夫，而他也情愿和她住在一起，她也不要离弃丈夫。'),
('CNV', '哥林多前书', 46, 7, 14, '因为不信的丈夫因着妻子成为圣洁，不信的妻子也因着那个弟兄成为圣洁了。不然，你们的儿女就是不洁净的，但现在他们都是圣洁的了。'),
('CNV', '哥林多前书', 46, 7, 15, '如果那不信的要离去，就由他离去吧；在这种情形之下，信主的弟兄或姊妹都不必勉强。神呼召你们，是要你们和睦。'),
('CNV', '哥林多前书', 46, 7, 16, '你这作妻子的，你怎么知道能否救你的丈夫呢？你这作丈夫的，你怎么知道能否救你的妻子呢？'),
('CNV', '哥林多前书', 46, 7, 17, '不过，主怎样分给各人，神怎样呼召各人，各人就要照着去行事为人。我也这样吩咐各教会。'),
('CNV', '哥林多前书', 46, 7, 18, '有人受了割礼而蒙召的吗？他就不要遮掩割礼的记号。有人未受割礼而蒙召的吗？他就不要受割礼。'),
('CNV', '哥林多前书', 46, 7, 19, '割礼算不得什么，没有割礼也算不得什么，要紧的是遵守神的命令。'),
('CNV', '哥林多前书', 46, 7, 20, '各人蒙召的时候怎样，他就应当保持原来的情况。'),
('CNV', '哥林多前书', 46, 7, 21, '你蒙召的时候是作奴仆的吗？不要为此烦恼。但如果你能够得到自由，就要把握这机会。'),
('CNV', '哥林多前书', 46, 7, 22, '因为作奴仆的蒙了主的呼召，就是属于主的自由人了；照样，自由的人蒙了呼召，他就是基督的奴仆了。'),
('CNV', '哥林多前书', 46, 7, 23, '你们是用重价买来的，不要作人的奴仆。'),
('CNV', '哥林多前书', 46, 7, 24, '弟兄们，你们各人蒙召的时候怎样，就应当在神面前保持这原来的情况。'),
('CNV', '哥林多前书', 46, 7, 25, '关于未婚的，我没有主的命令，但我既然蒙了主的怜悯，成为可信靠的人，就把我的意见提出来。'),
('CNV', '哥林多前书', 46, 7, 26, '为了目前的困难，我认为人最好能保持现状。'),
('CNV', '哥林多前书', 46, 7, 27, '你已经有了妻子吗？就不要想摆脱。你还没有妻子吗？就不要去找妻子。'),
('CNV', '哥林多前书', 46, 7, 28, '如果你娶妻子，这不是犯罪；如果处女出嫁，也不是犯罪。不过，这样的人要受肉体上的苦难，我却不愿你们受这苦难。'),
('CNV', '哥林多前书', 46, 7, 29, '弟兄们，我是说时候不多了。从今以后，有妻子的要像没有妻子的，'),
('CNV', '哥林多前书', 46, 7, 30, '哀哭的要像不哀哭的，快乐的要像不快乐的，买了东西的要像一无所得的，'),
('CNV', '哥林多前书', 46, 7, 31, '享用世上百物的要像没有享用的一样，因为这世上的情况都要过去。'),
('CNV', '哥林多前书', 46, 7, 32, '我愿你们无所挂虑。没有娶妻子的人，挂念的是主的事，想怎样去得主喜悦；'),
('CNV', '哥林多前书', 46, 7, 33, '但娶了妻子的人是为世上的事挂虑，想怎样去讨妻子的欢心，'),
('CNV', '哥林多前书', 46, 7, 34, '这样他就分心了。没有结婚的妇女和守独身的女子，挂念的是主的事，好让身体和心灵都成为圣洁；但结了婚的妇女是为世上的事挂虑，想怎样去讨丈夫的欢心。'),
('CNV', '哥林多前书', 46, 7, 35, '我说这话，是为了你们自己的益处；我不是要限制你们，而是要你们作合宜的事，一心一意地对主忠诚。'),
('CNV', '哥林多前书', 46, 7, 36, '如果有人认为是亏待了自己的女朋友，她也过了结婚的年龄，而他觉得应当结婚，他就可以照着自己的意思去作，这不是犯罪；他们应该结婚。'),
('CNV', '哥林多前书', 46, 7, 37, '但如果他心里坚决，没有什么不得已的原因，又可以控制自己的意志，决心让女朋友持守独身；这样作也是好的。'),
('CNV', '哥林多前书', 46, 7, 38, '所以，那跟自己的女朋友结婚的，作得好，那不结婚的，作得更好。（或译：“36如果有人认为待自己的女儿不合适，她也过了结婚的年龄，而且应当这样行，他就可以照着自己的意思去作，让她们结婚，这不是犯罪。37但如果他心里坚定，没有什么不得已的原因，又有权作主，决心留下自己的女儿，这样作也是好的。38所以，那让自己女儿出嫁的，作得好，那不让女儿出嫁的，作得更好。”）'),
('CNV', '哥林多前书', 46, 7, 39, '丈夫活着的时候，妻子是受约束的；丈夫若死了，她就可以自由地嫁给她愿意嫁的人，只是要嫁给主里的人。'),
('CNV', '哥林多前书', 46, 7, 40, '然而照我的意见，倘若她能守节，就更有福了。我想我这话也是神的灵感动的。'),
('CNV', '哥林多前书', 46, 8, 1, '关于祭过偶像的食物，我们晓得我们都有知识。但知识会使人自高自大，唯有爱心能造就人。'),
('CNV', '哥林多前书', 46, 8, 2, '如果有人自以为知道些什么，那么，他应该知道的，他还是不知道。'),
('CNV', '哥林多前书', 46, 8, 3, '如果有人爱神，这人是神所知道的。'),
('CNV', '哥林多前书', 46, 8, 4, '关于吃祭过偶像的食物，我们知道世上的偶像算不得什么，也知道神只有一位，没有别的神。'),
('CNV', '哥林多前书', 46, 8, 5, '虽然有被称为神的，无论在天上或在地上（就如有许多的“神”许多的“主”），'),
('CNV', '哥林多前书', 46, 8, 6, '然而我们只有一位神，就是父；万物都是从他而来，我们也为了他而活。我们也只有一位主，就是耶稣基督；万物都是藉着他而有的，我们也是藉着他而有的。'),
('CNV', '哥林多前书', 46, 8, 7, '不过，这种知识不是人人都有的。有些人直到现在习惯了拜偶像的事，因此他们吃的时候，就把这些食物看作是真的献过给偶像的；他们的良心既然软弱，就被污秽了。'),
('CNV', '哥林多前书', 46, 8, 8, '其实食物不能使我们亲近神，我们不吃也无损，吃也无益。'),
('CNV', '哥林多前书', 46, 8, 9, '然而你们要谨慎，免得你们这自由成了软弱的人的绊脚石。'),
('CNV', '哥林多前书', 46, 8, 10, '因为如果有人看见你这有知识的人，在偶像的庙里吃喝，他的良心若是软弱，他不就放胆去吃那祭过偶像的食物吗？'),
('CNV', '哥林多前书', 46, 8, 11, '因此，基督已经为他死了的那软弱的弟兄，就因你的知识而灭亡了。'),
('CNV', '哥林多前书', 46, 8, 12, '你们这样得罪弟兄，伤了他们软弱的良心，就是得罪基督了。'),
('CNV', '哥林多前书', 46, 8, 13, '所以，如果食物使我的弟兄跌倒，我就永远不再吃肉，免得使我的弟兄跌倒了。'),
('CNV', '哥林多前书', 46, 9, 1, '我不是自由的吗？我不是使徒吗？我不是见过我们的主耶稣吗？你们不是我在主里面的工作吗？'),
('CNV', '哥林多前书', 46, 9, 2, '对别人来说，我或许不是使徒，但对你们来说，我总是使徒，因为你们就是我在主里作使徒的印记。'),
('CNV', '哥林多前书', 46, 9, 3, '对那些盘问我的人，这就是我的答辩。'),
('CNV', '哥林多前书', 46, 9, 4, '难道我们没有权利吃喝吗？'),
('CNV', '哥林多前书', 46, 9, 5, '难道我们没有权利，像其余的使徒、主的弟兄和矶法一样，带着信主的妻子往来吗？'),
('CNV', '哥林多前书', 46, 9, 6, '难道只有我和巴拿巴没有权利不作工吗？'),
('CNV', '哥林多前书', 46, 9, 7, '有谁当兵要自备粮饷呢？有谁栽种葡萄园，不吃园里的果子呢？有谁牧养羊群，不喝羊的奶呢？'),
('CNV', '哥林多前书', 46, 9, 8, '我说这话，不是照着人的意见，律法不也是这样说吗？'),
('CNV', '哥林多前书', 46, 9, 9, '就在摩西的律法上记着说：“牛踹谷的时候，不可笼住它的嘴。”难道神关心的只是牛吗？'),
('CNV', '哥林多前书', 46, 9, 10, '这不全是为我们说的吗？当然是为我们说的，因为耕种的应当存着希望去耕种，收割的也应当存着希望去分享收获。'),
('CNV', '哥林多前书', 46, 9, 11, '我们既然在你们中间撒了属灵的种子，如果要从你们那里收获一些物质的供应，这算是过分吗？'),
('CNV', '哥林多前书', 46, 9, 12, '如果别人在你们身上享有这种权利，我们不是更可以享有吗？然而我们没有用过这种权利，反而凡事容忍，免得我们拦阻了基督的福音。'),
('CNV', '哥林多前书', 46, 9, 13, '难道你们不知道，在圣殿供职的，就吃殿中的供物；侍候祭坛的，就分领坛上的祭物吗？'),
('CNV', '哥林多前书', 46, 9, 14, '主也曾这样吩咐，叫传福音的人靠福音为生。'),
('CNV', '哥林多前书', 46, 9, 15, '但这种权利，我一点也没有用过。我写这些话，并不是想叫人这样待我，因为我宁可死，也不让人使我所夸耀的落了空。'),
('CNV', '哥林多前书', 46, 9, 16, '我传福音原是没有可夸的，因我不能不传。如果不传福音，我就有祸了。'),
('CNV', '哥林多前书', 46, 9, 17, '如果我甘心作这事，就有赏赐；即使不甘心，这职责还是托付我了。'),
('CNV', '哥林多前书', 46, 9, 18, '那么，我的赏赐是什么呢？就是我传福音时，叫人免费得着福音。这样，我就没有用过传福音可以享有的权利了。'),
('CNV', '哥林多前书', 46, 9, 19, '我虽然自由，不受任何人管辖，但我自愿成为众人的奴仆，为的是要多得一些人。'),
('CNV', '哥林多前书', 46, 9, 20, '对犹太人，我就作犹太人，为了要得着犹太人；对律法以下的人，虽然我自己不在律法之下，还是作了律法以下的人，为了要得着律法以下的人。'),
('CNV', '哥林多前书', 46, 9, 21, '对没有律法的人，我就作了没有律法的人，其实我不是在神的律法以外，而是在基督的律法之下，为了要得着没有律法的人。'),
('CNV', '哥林多前书', 46, 9, 22, '对软弱的人，我就成了软弱的人，为了要得着软弱的人。对怎么样的人，我就作怎么样的人；无论如何，总要救一些人。'),
('CNV', '哥林多前书', 46, 9, 23, '我所作的一切，都是为了福音的缘故，好让我与别人同享福音的好处。'),
('CNV', '哥林多前书', 46, 9, 24, '难道你们不知道，在场上赛跑的人，虽然大家都跑，但得奖的只有一个人吗？你们都应当这样跑，好叫你们可以得奖。'),
('CNV', '哥林多前书', 46, 9, 25, '凡参加运动比赛的，在一切事上都有节制；他们这样作，不过要得到能坏的冠冕，我们却是要得不朽的冠冕。'),
('CNV', '哥林多前书', 46, 9, 26, '所以我奔跑，不是没有目标的；我斗拳，不是打空气的。'),
('CNV', '哥林多前书', 46, 9, 27, '我要克制自己的身体，叫身体服我，免得我传了给别人，自己反而落选了。'),
('CNV', '哥林多前书', 46, 10, 1, '弟兄们，我不愿意你们不知道，我们的祖宗都曾经在云下，都曾经从海中经过，'),
('CNV', '哥林多前书', 46, 10, 2, '都曾经在云里在海里受洗归于摩西。'),
('CNV', '哥林多前书', 46, 10, 3, '他们都吃了一样的灵粮，'),
('CNV', '哥林多前书', 46, 10, 4, '都喝了一样的灵水；他们所喝的，是从那随着他们的灵磐石那里来的，这磐石就是基督。'),
('CNV', '哥林多前书', 46, 10, 5, '但他们大多数的人，都得不到神的喜悦，因此他们都死在旷野。'),
('CNV', '哥林多前书', 46, 10, 6, '这些事都是我们的鉴戒，叫我们不要贪恋恶事，像他们那样。'),
('CNV', '哥林多前书', 46, 10, 7, '你们也不可拜偶像，像他们有些人那样；正如经上所记：“人民坐下吃喝，起来玩乐。”'),
('CNV', '哥林多前书', 46, 10, 8, '我们也不可淫乱，像他们有些人那样，一天就死了二万三千人。'),
('CNV', '哥林多前书', 46, 10, 9, '我们也不可试探主，像他们有些人那样，结果就被蛇咬死了。'),
('CNV', '哥林多前书', 46, 10, 10, '你们也不可发怨言，像他们有些人那样，就被那毁灭者所灭。'),
('CNV', '哥林多前书', 46, 10, 11, '这些事发生在他们身上，作为鉴戒，并且记下来，为了要警戒我们这些末世的人。'),
('CNV', '哥林多前书', 46, 10, 12, '所以，那自以为站得稳的，应当谨慎，免得跌倒。'),
('CNV', '哥林多前书', 46, 10, 13, '你们所受的试探，无非是人受得起的；神是信实的，他必不容许你们受试探过于你们承受得起的，而且在受试探的时候，必定给你们开一条出路，使你们能忍受得住。'),
('CNV', '哥林多前书', 46, 10, 14, '所以，我所亲爱的，你们要远避拜偶像的事。'),
('CNV', '哥林多前书', 46, 10, 15, '我是对明白事理的人说的，我所说的你们要自己判断。'),
('CNV', '哥林多前书', 46, 10, 16, '我们为福杯祝祷的时候，难道不是共享基督的血吗？我们擘饼的时候，难道不是共享基督的身体吗？'),
('CNV', '哥林多前书', 46, 10, 17, '因为事实上只有一个饼，我们人数虽多，还是一个身体，因为我们都是分享同一个饼。'),
('CNV', '哥林多前书', 46, 10, 18, '你们看看按肉身是以色列人，那些吃祭物的不就是与祭坛有分吗？'),
('CNV', '哥林多前书', 46, 10, 19, '我说的是什么意思呢？偶像算得什么，还是祭过偶像的食物算得什么？'),
('CNV', '哥林多前书', 46, 10, 20, '我是说，教外人所祭的是鬼，不是献给神；我却不愿意你们与鬼来往。'),
('CNV', '哥林多前书', 46, 10, 21, '你们不能喝主的杯又喝鬼的杯，你们不能参加主的筵席又参加鬼的筵席。'),
('CNV', '哥林多前书', 46, 10, 22, '难道我们要激起主的忿怒吗？我们比他更强吗？'),
('CNV', '哥林多前书', 46, 10, 23, '什么事情都可以作，但不是都有益处。什么事情都可以作，但不是都能造就人。'),
('CNV', '哥林多前书', 46, 10, 24, '人不要求自己的好处，却要求别人的好处。'),
('CNV', '哥林多前书', 46, 10, 25, '肉食市场所卖的一切，你们只管吃，不要为了良心的缘故问什么，'),
('CNV', '哥林多前书', 46, 10, 26, '因为地和地上所充满的都是属于主的。'),
('CNV', '哥林多前书', 46, 10, 27, '如果有不信的人邀请你们吃饭，你们也愿意去，凡摆在你们面前的，都可以吃，不要为了良心的缘故问什么。'),
('CNV', '哥林多前书', 46, 10, 28, '但是如果有人告诉你们：“这是献过祭的食物。”那么，为了那告诉你们的人，也为了良心的缘故，就不要吃。'),
('CNV', '哥林多前书', 46, 10, 29, '我说的良心，不是你的，而是他的。为什么我的自由要受别人的良心论断呢？'),
('CNV', '哥林多前书', 46, 10, 30, '我若存着感恩的心吃了，为什么我因着我所感恩的食物被人毁谤呢？'),
('CNV', '哥林多前书', 46, 10, 31, '所以，你们或吃喝，或作什么，一切都要为神的荣耀而行。'),
('CNV', '哥林多前书', 46, 10, 32, '无论是犹太人，是希腊人，是神的教会，你们总不可使他们跌倒；'),
('CNV', '哥林多前书', 46, 10, 33, '就好像我所作的一切，都是要使大家喜悦，不是要求自己的好处，而是要求别人的好处，为了要使他们得救。'),
('CNV', '哥林多前书', 46, 11, 1, '你们应该效法我，好像我效法基督一样。'),
('CNV', '哥林多前书', 46, 11, 2, '我称赞你们，因为你们在一切事上都记念我，又持守我传交给你们的教训。'),
('CNV', '哥林多前书', 46, 11, 3, '但是我愿意你们知道，基督是男人的头，男人是女人的头（“男人是女人的头”或译：“丈夫是妻子的头”），神是基督的头。'),
('CNV', '哥林多前书', 46, 11, 4, '男人祷告或讲道的时候，如果蒙着头，就是羞辱自己的头。'),
('CNV', '哥林多前书', 46, 11, 5, '女人祷告或讲道的时候，如果不蒙着头，就是羞辱自己的头，因为这就好像剃了头发一样。'),
('CNV', '哥林多前书', 46, 11, 6, '女人要不蒙着头，她就应当把头发剪了；如果女人以为剪发或剃头是羞耻的事，她就应当蒙着头。'),
('CNV', '哥林多前书', 46, 11, 7, '男人不应蒙着头，因为他是神的形象和荣耀，而女人是男人的荣耀。'),
('CNV', '哥林多前书', 46, 11, 8, '因为男人不是由女人而出，女人却是由男人而出，'),
('CNV', '哥林多前书', 46, 11, 9, '并且男人不是为了女人而造的，女人却是为了男人而造的。'),
('CNV', '哥林多前书', 46, 11, 10, '因此，为天使的缘故，女人应当在头上有服权柄的记号。'),
('CNV', '哥林多前书', 46, 11, 11, '然而在主里面，女人不可以没有男人，男人也不可以没有女人。'),
('CNV', '哥林多前书', 46, 11, 12, '因为正如女人是由男人而出，照样，男人是藉着女人而生；万有都是出于神。'),
('CNV', '哥林多前书', 46, 11, 13, '你们自己判断一下，女人向神祷告的时候不蒙头，是合适的吗？'),
('CNV', '哥林多前书', 46, 11, 14, '人的本性不是也教导你们，如果男人有长头发，就是他的羞耻吗？'),
('CNV', '哥林多前书', 46, 11, 15, '如果女人有长头发，不就是她的荣耀吗？因为头发是给她作盖头的。'),
('CNV', '哥林多前书', 46, 11, 16, '如果有人想要强辩，我们却没有这种习惯，神的众教会也没有。'),
('CNV', '哥林多前书', 46, 11, 17, '我现在要吩咐你们，不是要称赞你们，因为你们聚集在一起，并没有得到益处，反而有害处。'),
('CNV', '哥林多前书', 46, 11, 18, '首先，我听说你们在聚会的时候，你们中间起了分裂，这话我也稍微相信。'),
('CNV', '哥林多前书', 46, 11, 19, '你们中间会有分党结派的事，这是必然的，为的是要使那些经得起考验的人显明出来。'),
('CNV', '哥林多前书', 46, 11, 20, '你们聚集在一起，不是吃主的晚餐，'),
('CNV', '哥林多前书', 46, 11, 21, '因为吃的时候，各人都先吃自己的晚餐，结果有人饥饿，有人醉了。'),
('CNV', '哥林多前书', 46, 11, 22, '难道你们没有家可以吃喝吗？还是你们藐视神的教会，使那些没有的羞愧呢？我向你们可以说什么呢？称赞你们吗？在这事上我不能称赞。'),
('CNV', '哥林多前书', 46, 11, 23, '我当日传交给你们的，原是从主领受的，就是主耶稣被出卖的那一夜，他拿起饼来，'),
('CNV', '哥林多前书', 46, 11, 24, '祝谢了，就擘开，说：“这是我的身体，为你们擘开的；你们应当这样行，为的是记念我。”'),
('CNV', '哥林多前书', 46, 11, 25, '饭后，照样拿起杯来，说：“这杯是用我的血所立的新约，你们每逢喝的时候，应当这样行，为的是记念我。”'),
('CNV', '哥林多前书', 46, 11, 26, '你们每逢吃这饼，喝这杯，就是宣扬主的死，直等到他来。'),
('CNV', '哥林多前书', 46, 11, 27, '因此，无论什么人若用不合适的态度吃主的饼，喝主的杯，就是得罪主的身体、主的血了。'),
('CNV', '哥林多前书', 46, 11, 28, '所以人应当省察自己，然后才吃这饼，喝这杯。'),
('CNV', '哥林多前书', 46, 11, 29, '因为那吃喝的人，如果不辨明是主的身体，就是吃喝定在自己的身上的罪了。'),
('CNV', '哥林多前书', 46, 11, 30, '因此，你们中间有许多人是软弱的，患病的，而且死了（“死了”直译作“睡了”）的也不少。'),
('CNV', '哥林多前书', 46, 11, 31, '我们若仔细省察自己，就不会受审判了。'),
('CNV', '哥林多前书', 46, 11, 32, '然而我们被主审判的时候，是受他的管教，免得和世人一同被定罪。'),
('CNV', '哥林多前书', 46, 11, 33, '所以，我的弟兄们，你们聚集在一起吃的时候，要彼此等待。'),
('CNV', '哥林多前书', 46, 11, 34, '如果有人饿了，就应当在家里先吃，免得你们聚集在一起的时候受到审判。其余的事，我来的时候再作安排。'),
('CNV', '哥林多前书', 46, 12, 1, '弟兄们，关于属灵的恩赐，我不愿意你们不明白。'),
('CNV', '哥林多前书', 46, 12, 2, '你们知道，你们还是教外人的时候，总是受迷惑被引诱，去拜那不能说话的偶像。'),
('CNV', '哥林多前书', 46, 12, 3, '所以我要你们知道，被神的灵感动而说话的人，没有一个会说“耶稣是可咒诅的”；除非是被圣灵感动，也没有人能说“耶稣是主”。'),
('CNV', '哥林多前书', 46, 12, 4, '恩赐有许多种，却是同一位圣灵所赐的；'),
('CNV', '哥林多前书', 46, 12, 5, '服事的职分有许多种，但是同一位主；'),
('CNV', '哥林多前书', 46, 12, 6, '工作的方式也有许多种，但仍是一位神，是他在众人里面作成一切。'),
('CNV', '哥林多前书', 46, 12, 7, '圣灵显现在各人的身上，为的是要使人得着益处。'),
('CNV', '哥林多前书', 46, 12, 8, '有人藉着圣灵领受了智慧的言语，又有人靠着同一位圣灵领受了知识的言语，'),
('CNV', '哥林多前书', 46, 12, 9, '又有人因着同一位圣灵领受了信心，还有人因着这位圣灵领受了医病的恩赐，'),
('CNV', '哥林多前书', 46, 12, 10, '另有人可以行神迹，另有人可以讲道，另有人可以辨别诸灵，也有人能说各种的方言，也有人能翻译方言。'),
('CNV', '哥林多前书', 46, 12, 11, '这一切都是这同一位圣灵所作的，他按照自己的意思个别地分给各人。'),
('CNV', '哥林多前书', 46, 12, 12, '正如身体是一个，却有许多肢体，而且肢体虽然很多，身体仍是一个；基督也是这样。'),
('CNV', '哥林多前书', 46, 12, 13, '我们无论是犹太人，是希腊人，是作奴隶的，是自由的，都在那一位圣灵里受了洗，成为一个身体，都饮了那一位圣灵。'),
('CNV', '哥林多前书', 46, 12, 14, '原来身体有许多肢体，并不是只有一个肢体。'),
('CNV', '哥林多前书', 46, 12, 15, '假如脚说：“我不是手，所以我不属于身体。”它不能因此就不属于身体。'),
('CNV', '哥林多前书', 46, 12, 16, '假如耳朵说：“我不是眼睛，所以我不属于身体。”它也不能因此就不属于身体。'),
('CNV', '哥林多前书', 46, 12, 17, '假如整个身体只是眼睛，怎样听呢？假如整个身体只是耳朵，怎样闻味呢？'),
('CNV', '哥林多前书', 46, 12, 18, '但现在神按照自己的意思，把肢体一一放在身体上。'),
('CNV', '哥林多前书', 46, 12, 19, '假如所有的只是一个肢体，怎能算是身体呢？'),
('CNV', '哥林多前书', 46, 12, 20, '但现在肢体虽然很多，身体却只是一个。'),
('CNV', '哥林多前书', 46, 12, 21, '眼睛不能对手说：“我不需要你。”头也不能对脚说：“我不需要你们。”'),
('CNV', '哥林多前书', 46, 12, 22, '相反地，身体上那些似乎比较软弱的肢体，更是不可缺少的。'),
('CNV', '哥林多前书', 46, 12, 23, '我们认为身体上不大体面的部分，就更加要把它装饰得体面；不大美观的部分，就更加要使它美观。'),
('CNV', '哥林多前书', 46, 12, 24, '我们身体上美观的部分，就不需要这样了。但神却这样把身体组成了：格外地把体面加给比较有缺欠的肢体，'),
('CNV', '哥林多前书', 46, 12, 25, '好使肢体能够互相照顾，免得身体上有了分裂。'),
('CNV', '哥林多前书', 46, 12, 26, '如果一个肢体受苦，所有的肢体就一同受苦；如果一个肢体得荣耀，所有的肢体就一同快乐。'),
('CNV', '哥林多前书', 46, 12, 27, '你们就是基督的身体，并且每一个人都是作肢体的。'),
('CNV', '哥林多前书', 46, 12, 28, '神在教会里所设立的，第一是使徒，第二是先知，第三是教师，其次是行神迹的，再其次是有医病恩赐的，帮助人的，治理事的，说各种方言的。'),
('CNV', '哥林多前书', 46, 12, 29, '难道都是使徒吗？都是先知吗？都是教师吗？都是行神迹的吗？'),
('CNV', '哥林多前书', 46, 12, 30, '都是有医病恩赐的吗？都是说方言的吗？都是翻译方言的吗？'),
('CNV', '哥林多前书', 46, 12, 31, '你们却要热切地追求那些更大的恩赐。现在我要把更高的道路指示你们。'),
('CNV', '哥林多前书', 46, 13, 1, '我若能说世人和天使的方言，却没有爱，我就成了鸣的锣、响的钹一样。'),
('CNV', '哥林多前书', 46, 13, 2, '我若有先知讲道的恩赐，也明白各样的奥秘，各样的知识；并且有全备的信，叫我能够移山，却没有爱，我就算不得什么。'),
('CNV', '哥林多前书', 46, 13, 3, '我若把一切所有的分给人，又舍己身被人焚烧，却没有爱，对我仍然毫无益处。'),
('CNV', '哥林多前书', 46, 13, 4, '爱是恒久忍耐，又有恩慈。爱是不嫉妒，不自夸，不张狂；'),
('CNV', '哥林多前书', 46, 13, 5, '不作失礼的事，不求自己的益处，不轻易动怒，不计较人的过犯；'),
('CNV', '哥林多前书', 46, 13, 6, '不喜欢不义，只喜欢真理。'),
('CNV', '哥林多前书', 46, 13, 7, '爱是凡事包容，凡事相信，凡事盼望，凡事忍耐。'),
('CNV', '哥林多前书', 46, 13, 8, '爱是永存不息的。先知的讲道终必过去，方言终必停止，知识终必消失。'),
('CNV', '哥林多前书', 46, 13, 9, '因为我们现在所知道的，只是一部分；所讲的道也只是一部分；'),
('CNV', '哥林多前书', 46, 13, 10, '等那完全的来到，这部分的就要过去了。'),
('CNV', '哥林多前书', 46, 13, 11, '我作孩子的时候，说话像孩子，心思像孩子，想法像孩子，既然长大了，就把孩子的事都丢弃了。'),
('CNV', '哥林多前书', 46, 13, 12, '我们现在是对着镜子观看，模糊不清，到那时就要面对面了。我现在所知道的只是一部分，到那时就完全知道了，好像主完全知道我一样。'),
('CNV', '哥林多前书', 46, 13, 13, '现在常存的有信、望、爱这三样，其中最大的是爱。'),
('CNV', '哥林多前书', 46, 14, 1, '你们要追求爱，也要热切地渴慕属灵的恩赐，特别是先知讲道的恩赐。'),
('CNV', '哥林多前书', 46, 14, 2, '原来那说方言的不是对人说，而是对神说，因为没有人能听得懂；他是在灵里讲奥秘的事。'),
('CNV', '哥林多前书', 46, 14, 3, '但那讲道的是对人讲说，使他们得着造就、安慰和劝勉。'),
('CNV', '哥林多前书', 46, 14, 4, '那说方言的是造就自己，但那讲道的是造就教会。'),
('CNV', '哥林多前书', 46, 14, 5, '我愿意你们都说方言，但我更愿意你们都讲道；因为那说方言的，如果不翻译出来使教会得着造就，就远不如那讲道的了。'),
('CNV', '哥林多前书', 46, 14, 6, '弟兄们，你们想想，如果我到你们那里去，只说方言，不向你们讲有关启示、知识、预言，或教训的话，那我对你们有什么益处呢？'),
('CNV', '哥林多前书', 46, 14, 7, '甚至那些没有生命却能发声的东西，例如箫或琴，如果音调不分，怎能使人知道所弹所奏的是什么呢？'),
('CNV', '哥林多前书', 46, 14, 8, '又如果军号所发的声音不清楚，谁会准备作战呢？'),
('CNV', '哥林多前书', 46, 14, 9, '你们也是这样，如果用舌头发出人听不懂的话来，人怎会知道你所讲的是什么呢？这样，你们就是向空气说话了。'),
('CNV', '哥林多前书', 46, 14, 10, '世上有那么多种语言，但没有一种是没有意义的。'),
('CNV', '哥林多前书', 46, 14, 11, '我若不明白某一种语言的意思，在那讲的人来看，我就是个外国人；在我来说，那讲话的人也是个外国人。'),
('CNV', '哥林多前书', 46, 14, 12, '你们也是这样，你们既然热切地渴慕属灵的恩赐，就应当追求多多得着造就教会的恩赐。'),
('CNV', '哥林多前书', 46, 14, 13, '所以，说方言的应当祈求，使他能把方言翻译出来。'),
('CNV', '哥林多前书', 46, 14, 14, '我若用方言祷告，是我的灵在祷告，我的理智并没有作用。'),
('CNV', '哥林多前书', 46, 14, 15, '那么我应当怎样行呢？我要用灵祷告，也要用理智祷告；我要用灵歌唱，也要用理智歌唱。'),
('CNV', '哥林多前书', 46, 14, 16, '不然，如果你用灵赞美，在场那些不明白的人，因为不知道你在说什么，怎能在你感谢的时候说“阿们”呢？'),
('CNV', '哥林多前书', 46, 14, 17, '你感谢固然是好，但别人却得不着造就。'),
('CNV', '哥林多前书', 46, 14, 18, '我感谢神，我说方言比你们大家都多。'),
('CNV', '哥林多前书', 46, 14, 19, '但在教会中，我宁愿用理智说五句话去教导人，胜过用方言说万句话。'),
('CNV', '哥林多前书', 46, 14, 20, '弟兄们，你们在思想上不要作小孩子，却要在恶事上作婴孩，在思想上作成年人。'),
('CNV', '哥林多前书', 46, 14, 21, '律法上记着说：“主说：我要藉着说别种话的人，用外国人的嘴唇，对这人民说话；虽然这样，他们还是不听我。”'),
('CNV', '哥林多前书', 46, 14, 22, '可见说方言不是要给信主的人作记号，而是要给未信的人；讲道不是要给未信的人，而是要给信主的人作记号。'),
('CNV', '哥林多前书', 46, 14, 23, '所以，如果全教会聚在一起的时候，大家都说方言，有不明白的人或未信的人进来，不是要说你们疯了吗？'),
('CNV', '哥林多前书', 46, 14, 24, '如果大家都讲道，有未信的人或不明白的人进来，他就会被众人劝服而知罪，被众人审问了。'),
('CNV', '哥林多前书', 46, 14, 25, '他心里隐秘的事被显露出来，他就必俯伏敬拜神，宣告说：“神真的是在你们中间了。”'),
('CNV', '哥林多前书', 46, 14, 26, '弟兄们，那么应该怎么办呢？你们聚集在一起的时候，各人或有诗歌，或有教训，或有启示，或有方言，或有翻译出来的话，一切都应该能造就人。'),
('CNV', '哥林多前书', 46, 14, 27, '如果有人说方言，只可以有两个人，或最多三个人，并且要轮流说，同时要有一个人翻译。'),
('CNV', '哥林多前书', 46, 14, 28, '如果没有人翻译，他就应当在会中闭口，只对自己和对神说好了。'),
('CNV', '哥林多前书', 46, 14, 29, '讲道的，也只可以两三个人讲，其余的人要衡量他们所讲的。'),
('CNV', '哥林多前书', 46, 14, 30, '在座的有人得了启示，那先讲的人就应当住口。'),
('CNV', '哥林多前书', 46, 14, 31, '因为你们都可以轮流讲道，好让大家都可以学习，都可以得到勉励。'),
('CNV', '哥林多前书', 46, 14, 32, '先知的灵是受先知控制的，'),
('CNV', '哥林多前书', 46, 14, 33, '因为神不是混乱的，而是和平的。'),
('CNV', '哥林多前书', 46, 14, 34, '妇女在聚会中应当闭口，好像在圣徒的众教会中一样，因为她们是不准讲话的；就如律法所说的，她们应该顺服。'),
('CNV', '哥林多前书', 46, 14, 35, '如果她们想要学什么，可以在家里问自己的丈夫，因为妇女在聚会中讲话原是可耻的。'),
('CNV', '哥林多前书', 46, 14, 36, '难道神的道是从你们出来的吗？是单单临到你们的吗？'),
('CNV', '哥林多前书', 46, 14, 37, '如果有人自以为是先知或是属灵的，他就应该知道我写给你们的是主的命令；'),
('CNV', '哥林多前书', 46, 14, 38, '如果有人不理会，别人也不必理会他。'),
('CNV', '哥林多前书', 46, 14, 39, '所以我的弟兄们，你们要热切地追求讲道的恩赐，也不要禁止说方言。'),
('CNV', '哥林多前书', 46, 14, 40, '凡事都要规规矩矩地按着次序行。'),
('CNV', '哥林多前书', 46, 15, 1, '弟兄们，我要把我从前传给你们的福音向你们讲明。这福音你们已经领受了，并且靠着它站立得稳。'),
('CNV', '哥林多前书', 46, 15, 2, '你们若持守我所传给你们的道，就必靠这福音得救，不然就是徒然相信了。'),
('CNV', '哥林多前书', 46, 15, 3, '我从前领受了又传交给你们那最要紧的，就是基督照着圣经所记的，为我们的罪死了，'),
('CNV', '哥林多前书', 46, 15, 4, '又埋葬了，又照着圣经所记的，第三天复活了；'),
('CNV', '哥林多前书', 46, 15, 5, '并且曾经向矶法显现，然后向十二使徒显现。'),
('CNV', '哥林多前书', 46, 15, 6, '以后又有一次向五百多个弟兄显现。他们中间大多数到现今还在，也有些已经睡了。'),
('CNV', '哥林多前书', 46, 15, 7, '以后也向雅各显现，再后又向众使徒显现，'),
('CNV', '哥林多前书', 46, 15, 8, '最后也向我显现；我好像一个未到产期而生的人。'),
('CNV', '哥林多前书', 46, 15, 9, '我原是使徒中最小的，本来没有资格称为使徒，因为我曾经迫害神的教会。'),
('CNV', '哥林多前书', 46, 15, 10, '然而靠着神的恩典，我得以有了今天，而且他赐给我的恩典并没有落空；我比众使徒格外劳苦，其实不是我，而是神的恩典与我同在。'),
('CNV', '哥林多前书', 46, 15, 11, '因此，不论是我，或是众使徒，我们这样传，你们也这样信了。'),
('CNV', '哥林多前书', 46, 15, 12, '我们既然传基督从死人中复活了，你们中间怎么有人说没有死人复活呢？'),
('CNV', '哥林多前书', 46, 15, 13, '倘若没有死人复活的事，基督也就没有复活了。'),
('CNV', '哥林多前书', 46, 15, 14, '如果基督没有复活，我们所传的就是枉然，你们的信也是枉然，'),
('CNV', '哥林多前书', 46, 15, 15, '我们也会被人认为是替神作假见证的了，因为我们为神作过见证说，他使基督复活了。如果死人没有复活，神也就没有使基督复活了。'),
('CNV', '哥林多前书', 46, 15, 16, '因为如果死人没有复活，基督也就没有复活。'),
('CNV', '哥林多前书', 46, 15, 17, '基督若没有复活，你们的信就是徒然，你们仍在你们的罪里。'),
('CNV', '哥林多前书', 46, 15, 18, '那么，在基督里睡了的人也就灭亡了。'),
('CNV', '哥林多前书', 46, 15, 19, '如果我们在基督里只在今生有盼望，就比所有人更可怜了。'),
('CNV', '哥林多前书', 46, 15, 20, '现在基督已经从死人中复活，成为睡了的人初熟的果子。'),
('CNV', '哥林多前书', 46, 15, 21, '死既藉着一人而来，死人复活也藉着一人而来。'),
('CNV', '哥林多前书', 46, 15, 22, '在亚当里众人都死了，照样，在基督里众人也都要复活；'),
('CNV', '哥林多前书', 46, 15, 23, '只是各人要按着自己的次序：初熟的果子是基督，以后，在他来的时候，是那些属基督的人。'),
('CNV', '哥林多前书', 46, 15, 24, '再后，末期到了的时候，基督把所有的统治者、掌权者和有能者都毁灭了，就把国度交给父神。'),
('CNV', '哥林多前书', 46, 15, 25, '因为基督必要作王，直到神把所有的仇敌都放在他的脚下。'),
('CNV', '哥林多前书', 46, 15, 26, '最后要毁灭的仇敌就是死，'),
('CNV', '哥林多前书', 46, 15, 27, '因为经上记着说：“他使万物都服在他脚下。”既然说万物都服了他，显然那使万物服他的就不包括在内了。'),
('CNV', '哥林多前书', 46, 15, 28, '等到万物都服了他，那时子自己也要服那位叫万物服他的，好使神在万有之上。'),
('CNV', '哥林多前书', 46, 15, 29, '不然，那些为死人受洗的，是为了什么呢？如果死人根本不会复活，那么为什么要为他们受洗呢？'),
('CNV', '哥林多前书', 46, 15, 30, '我们又为什么时刻冒险呢？'),
('CNV', '哥林多前书', 46, 15, 31, '弟兄们，我是天天冒死的，这是我凭着我在我们的主耶稣基督里，因你们而夸口说的。'),
('CNV', '哥林多前书', 46, 15, 32, '我在以弗所和野兽搏斗，如果照着人的意思来看，那对我有什么益处呢？如果死人不会复活，“我们就吃吃喝喝吧，因为我们明天就要死了。”'),
('CNV', '哥林多前书', 46, 15, 33, '你们不要自欺，“滥交朋友是会败坏品德的。”'),
('CNV', '哥林多前书', 46, 15, 34, '你们理当醒悟过来，不要犯罪，因为你们中间有人不认识神；我说这话是要你们羞愧。'),
('CNV', '哥林多前书', 46, 15, 35, '但有人会说：“死人怎样复活呢？要带着怎么样的身体来呢？”'),
('CNV', '哥林多前书', 46, 15, 36, '无知的人哪，你所种的若不死去，就不能生。'),
('CNV', '哥林多前书', 46, 15, 37, '你们所种的，不是那将来要长成的形体，只不过是一粒种子，也许是麦子或别的种子。'),
('CNV', '哥林多前书', 46, 15, 38, '但神随着自己的意思给它一个形体，给每一样种子各有自己的形体。'),
('CNV', '哥林多前书', 46, 15, 39, '而且各种身体也都不一样，人有人的身体，兽有兽的身体，鸟有鸟的身体，鱼有鱼的身体。'),
('CNV', '哥林多前书', 46, 15, 40, '有天上的形体，也有地上的形体；天上形体的荣光是一样，地上形体的荣光又是一样。'),
('CNV', '哥林多前书', 46, 15, 41, '太阳有太阳的荣光，月亮有月亮的荣光，星星有星星的荣光，而且每一颗星的荣光也都不同。'),
('CNV', '哥林多前书', 46, 15, 42, '死人复活也是这样。所种的是必朽坏的，复活的是不朽坏的；'),
('CNV', '哥林多前书', 46, 15, 43, '所种的是卑贱的，复活的是荣耀的；所种的是软弱的，复活的是有能力的；'),
('CNV', '哥林多前书', 46, 15, 44, '所种的是属血气的身体，复活的是属灵的身体。既然有属血气的身体，也会有属灵的身体。'),
('CNV', '哥林多前书', 46, 15, 45, '经上也是这样记着说：“第一个人亚当成了有生命的活人，末后的亚当成了使人活的灵。”'),
('CNV', '哥林多前书', 46, 15, 46, '但那首先的不是属灵的，而是属血气的，然后才有属灵的。'),
('CNV', '哥林多前书', 46, 15, 47, '第一个人是出于地，是属土的；第二个人是出于天。'),
('CNV', '哥林多前书', 46, 15, 48, '那属土的怎样，所有属土的也都怎样；属天的怎样，所有属天的也都怎样。'),
('CNV', '哥林多前书', 46, 15, 49, '我们既然有了属土的形象，将来也必有属天的形象。'),
('CNV', '哥林多前书', 46, 15, 50, '弟兄们，我告诉你们，血肉之体不能承受神的国，必朽坏的也不能承受那不朽坏的。'),
('CNV', '哥林多前书', 46, 15, 51, '我现在把一个奥秘告诉你们：我们不是都要睡觉，而是在一剎那，眨眼之间，就是号角最后一次吹响的时候，我们都要改变；因为号角要吹响，死人要复活，成为不朽坏的，我们也要改变。'),
('CNV', '哥林多前书', 46, 15, 53, '这必朽坏的必须穿上不朽坏的，这必死的必须穿上不死的；'),
('CNV', '哥林多前书', 46, 15, 54, '这必朽坏的既穿上了不朽坏的，这必死的既穿上了不死的，那时，经上的话就应验了：“胜利了！死亡已经被吞灭。'),
('CNV', '哥林多前书', 46, 15, 55, '死亡啊！你的胜利在哪里？死亡啊！你的毒刺在哪里？”'),
('CNV', '哥林多前书', 46, 15, 56, '死的毒刺就是罪，罪的权势就是律法。'),
('CNV', '哥林多前书', 46, 15, 57, '感谢神，他藉着我们的主耶稣基督，把胜利赐给我们。'),
('CNV', '哥林多前书', 46, 15, 58, '所以，我亲爱的弟兄们，你们务要坚固，不可动摇，常常竭力多作主工，因为知道你们的劳苦，在主里面不是徒然的。'),
('CNV', '哥林多前书', 46, 16, 1, '关于捐献给圣徒的事，从前我怎样吩咐加拉太的众教会，你们也要照着去行。'),
('CNV', '哥林多前书', 46, 16, 2, '每逢七日的第一日，你们各人要按着自己的收入抽一些出来留着，免得我来的时候才现凑。'),
('CNV', '哥林多前书', 46, 16, 3, '我来到之后，你们选中了什么人，我就派他们带著书信，把你们的捐款送到耶路撒冷去。'),
('CNV', '哥林多前书', 46, 16, 4, '如果我也应该去，他们就可以和我一同去。'),
('CNV', '哥林多前书', 46, 16, 5, '我现在正要路过马其顿。过了马其顿，我就会到你们那里去。'),
('CNV', '哥林多前书', 46, 16, 6, '我也许会和你们同住一些时候，甚至和你们一同过冬；这样，我无论要到哪里去，你们都可以给我送行。'),
('CNV', '哥林多前书', 46, 16, 7, '我不愿意只是顺路见见你们，主若许可，我盼望和你们同住一个时期。'),
('CNV', '哥林多前书', 46, 16, 8, '不过我要在以弗所住到五旬节，'),
('CNV', '哥林多前书', 46, 16, 9, '因为这里有又宽大又有果效的门为我开了，同时反对的人也很多。'),
('CNV', '哥林多前书', 46, 16, 10, '如果提摩太来了，你们务要使他在你们那里不会惧怕，因为他像我一样是作主的工作的。'),
('CNV', '哥林多前书', 46, 16, 11, '所以，谁也不要小看他。你们要送他平平安安地前行，使他到我这里来，因为我正在等着他和弟兄们一同来。'),
('CNV', '哥林多前书', 46, 16, 12, '至于亚波罗弟兄，我曾再三劝他要和弟兄们一同到你们那里去；但他不愿意现在就去，机会到了，他是会去的。'),
('CNV', '哥林多前书', 46, 16, 13, '你们要警醒，要在信仰上站立得稳，要作大丈夫，要刚强。'),
('CNV', '哥林多前书', 46, 16, 14, '你们所作的一切，都要凭爱心去作。'),
('CNV', '哥林多前书', 46, 16, 15, '弟兄们，你们知道司提反一家人是亚该亚初结的果子，他们专心地服事圣徒。'),
('CNV', '哥林多前书', 46, 16, 16, '我劝你们要顺服这样的人，和所有与他们一同工作一同劳苦的人。'),
('CNV', '哥林多前书', 46, 16, 17, '司提反、福徒拿都和亚该古都来了，所以我很快乐，因为他们补上了你们的不足，'),
('CNV', '哥林多前书', 46, 16, 18, '使我和你们的心都得着畅快。这样的人你们要敬重他们。'),
('CNV', '哥林多前书', 46, 16, 19, '亚西亚的众教会都问候你们。亚居拉和百基拉，以及他们家里的教会在主里再三问候你们。'),
('CNV', '哥林多前书', 46, 16, 20, '所有的弟兄都问候你们。你们要用圣洁的亲吻彼此问安。'),
('CNV', '哥林多前书', 46, 16, 21, '我保罗亲笔问候你们。'),
('CNV', '哥林多前书', 46, 16, 22, '如果有人不爱主，他就该受咒诅。主啊，愿你来！'),
('CNV', '哥林多前书', 46, 16, 23, '愿主耶稣基督的恩惠与你们同在。'),
('CNV', '哥林多前书', 46, 16, 24, '我的爱在基督耶稣里也与你们同在。（有古卷加上“阿们”。）'),
('CNV', '哥林多后书', 47, 1, 1, '奉神旨意作基督耶稣使徒的保罗，和提摩太弟兄，写信给在哥林多神的教会，和全亚该亚所有的圣徒。'),
('CNV', '哥林多后书', 47, 1, 2, '愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '哥林多后书', 47, 1, 3, '我们主耶稣基督的父神是应当称颂的。他是满有怜悯的父，赐各样安慰的神。'),
('CNV', '哥林多后书', 47, 1, 4, '我们在一切患难中，神都安慰我们，使我们能用他所赐的安慰，去安慰那些在各样患难中的人。'),
('CNV', '哥林多后书', 47, 1, 5, '我们既然多受基督所受的痛苦，就靠着基督多得安慰。'),
('CNV', '哥林多后书', 47, 1, 6, '如果我们遭遇患难，那是要使你们得着安慰，得着拯救；如果我们得到安慰，也是要使你们得到安慰。这安慰使你们能够忍受我们所受那样的痛苦。'),
('CNV', '哥林多后书', 47, 1, 7, '我们对你们的盼望是坚定的，因为知道你们既然一同受痛苦，也必照样同得安慰。'),
('CNV', '哥林多后书', 47, 1, 8, '弟兄们，我们在亚西亚遭受的患难，我们很想让你们知道。那时我们受到了过于我们所能忍受的压力，甚至活下去的希望都没有了，'),
('CNV', '哥林多后书', 47, 1, 9, '而且断定自己是必死的了；然而，这正是要我们不倚靠自己，只倚靠那叫死人复活的神。'),
('CNV', '哥林多后书', 47, 1, 10, '他救我们脱离了那极大的死亡，而且他还要救我们，我们希望他将来仍要救我们。'),
('CNV', '哥林多后书', 47, 1, 11, '请你们一同用祷告支持我们，好使许多人为着我们所蒙的恩献上感谢。这恩是藉着许多人的代求而得到的。'),
('CNV', '哥林多后书', 47, 1, 12, '我们引以为荣的，就是我们处世为人，是本着神的圣洁和真诚，不是靠着人的聪明，而是靠着神的恩典，对你们更是这样，这是我们的良心可以作证的。'),
('CNV', '哥林多后书', 47, 1, 13, '我们现在写给你们的，不外是你们可以宣读、可以明白的。'),
('CNV', '哥林多后书', 47, 1, 14, '正如你们对我们已经有些认识，我盼望你们可以彻底明白：在我们的主耶稣的日子，我们是你们的光荣，你们也是我们的光荣。'),
('CNV', '哥林多后书', 47, 1, 15, '我既然有这样的信念，就打算先到你们那里，使你们再一次得到恩惠，'),
('CNV', '哥林多后书', 47, 1, 16, '然后经过你们那里，往马其顿去，再从马其顿回到你们中间，让你们给我送行往犹太去。'),
('CNV', '哥林多后书', 47, 1, 17, '我这样决定，难道是反覆不定吗？我所决定的，难道是体贴肉体而定，使我忽是忽非吗？'),
('CNV', '哥林多后书', 47, 1, 18, '神是信实的，我们向你们所传的道并不是“是”而又“非”的，'),
('CNV', '哥林多后书', 47, 1, 19, '因为我、西拉和提摩太，在你们中间所宣扬的耶稣基督，神的儿子，并不是“是”而又“非”的，在他总是“是”的。'),
('CNV', '哥林多后书', 47, 1, 20, '因为神的一切应许，在基督里都是“是”的，为此我们藉着他说“阿们”，使荣耀归于神。'),
('CNV', '哥林多后书', 47, 1, 21, '那在基督里坚定我们和你们，又膏抹我们的，就是神。'),
('CNV', '哥林多后书', 47, 1, 22, '他在我们身上盖了印，就是赐圣灵在我们心里作凭据。'),
('CNV', '哥林多后书', 47, 1, 23, '我呼求神给我作证，我没有再到哥林多来，是要宽容你们。'),
('CNV', '哥林多后书', 47, 1, 24, '我们并不是要辖制你们的信仰，而是要作你们的同工，使你们喜乐，因为你们在信仰上已经站稳了。'),
('CNV', '哥林多后书', 47, 2, 1, '我自己决定了，到你们那里去的时候，不再是忧愁的。'),
('CNV', '哥林多后书', 47, 2, 2, '如果我使你们忧愁，除了那因我而忧愁的人以外，谁能使我快乐呢？'),
('CNV', '哥林多后书', 47, 2, 3, '我写了这样的信，免得我来的时候，应该使我快乐的人反而使我忧愁；我深信你们众人都以我的喜乐为你们的喜乐。'),
('CNV', '哥林多后书', 47, 2, 4, '我从前心里痛苦难过，流着眼泪写信给你们，并不是要使你们忧愁，而是要你们知道我是多么爱你们。'),
('CNV', '哥林多后书', 47, 2, 5, '如果有人使人忧愁，他不是使我忧愁，而是使你们众人都有一点忧愁；我只说有一点，是避免说得过分。'),
('CNV', '哥林多后书', 47, 2, 6, '这样的人受了许多人的责备，也就够了，'),
('CNV', '哥林多后书', 47, 2, 7, '倒不如饶恕他，安慰他，免得他因忧愁过度而受不了。'),
('CNV', '哥林多后书', 47, 2, 8, '所以，我劝你们要向他确实显明你们的爱心。'),
('CNV', '哥林多后书', 47, 2, 9, '为这缘故，我写了那封信，要考验你们是不是凡事都顺从。'),
('CNV', '哥林多后书', 47, 2, 10, '你们饶恕谁，我也饶恕谁；我所饶恕了的（如果我饶恕过什么），是为了你们在基督面前饶恕的，'),
('CNV', '哥林多后书', 47, 2, 11, '免得撒但有机可乘，因为我们并不是不晓得他的诡计。'),
('CNV', '哥林多后书', 47, 2, 12, '从前我为基督的福音到了特罗亚，虽然主给我开了门，'),
('CNV', '哥林多后书', 47, 2, 13, '我心里仍然没有安宁，因为见不到提多弟兄。于是我辞别了那里的人，到马其顿去了。'),
('CNV', '哥林多后书', 47, 2, 14, '感谢神，他常常在基督里，使我们这些作俘虏的，列在凯旋的队伍当中，又藉着我们在各地散播香气，就是使人认识基督。'),
('CNV', '哥林多后书', 47, 2, 15, '因为无论在得救的人或灭亡的人中间，我们都是基督的馨香，是献给神的。'),
('CNV', '哥林多后书', 47, 2, 16, '对于灭亡的人，这是死亡的气味叫人死；对于得救的人，这却是生命的香气使人活。这些事谁够资格作呢？'),
('CNV', '哥林多后书', 47, 2, 17, '我们不像那许多的人，为了图利而谬讲神的道。相反地，我们讲话，是出于真诚，出于神，是在神面前、在基督里的。'),
('CNV', '哥林多后书', 47, 3, 1, '难道我们又在自我推荐吗？难道我们像有些人，要拿荐信给你们，或向你们拿荐信吗？'),
('CNV', '哥林多后书', 47, 3, 2, '你们就是我们的荐信，写在我们的心里，是众人所认识所诵读的，'),
('CNV', '哥林多后书', 47, 3, 3, '显明你们自己是基督的书信，是藉着我们写成的，不是用墨，而是用永活神的灵写的；不是写在石版上，而是写在心版上。'),
('CNV', '哥林多后书', 47, 3, 4, '我们在神面前，藉着基督才有这样的信心。'),
('CNV', '哥林多后书', 47, 3, 5, '我们不敢以为自己有资格作什么，我们所能够作的是出于神。'),
('CNV', '哥林多后书', 47, 3, 6, '他使我们有资格作新约的仆役，这新约不是从仪文来的，而是从圣灵来的；因为仪文会使人死，而圣灵却使人活。'),
('CNV', '哥林多后书', 47, 3, 7, '如果那以文字刻在石上使人死的律法的工作，尚且带有荣光，以致以色列人因着摩西脸上短暂的荣光，不能注视他的脸，'),
('CNV', '哥林多后书', 47, 3, 8, '那出于圣灵的工作不是更有荣光吗？'),
('CNV', '哥林多后书', 47, 3, 9, '如果那定人有罪的工作尚且有荣光，那使人称义的工作就更有荣光了！'),
('CNV', '哥林多后书', 47, 3, 10, '那从前有荣光的，现在因那超越的荣光，就算不得有荣光；'),
('CNV', '哥林多后书', 47, 3, 11, '如果那短暂的有荣光，那长存的就更有荣光了。'),
('CNV', '哥林多后书', 47, 3, 12, '所以，我们既然有这样的盼望，就大大地放胆行事，'),
('CNV', '哥林多后书', 47, 3, 13, '不像摩西那样，把帕子蒙在脸上，使以色列人看不见那短暂的荣光的结局。'),
('CNV', '哥林多后书', 47, 3, 14, '但是他们的心思迟钝，因为直到今日，他们诵读旧约的时候，这帕子仍然存在，没有揭开，唯有在基督里才能把这帕子废掉。'),
('CNV', '哥林多后书', 47, 3, 15, '可是直到今日，他们每逢诵读摩西的书的时候，这帕子还盖在他们的心上。'),
('CNV', '哥林多后书', 47, 3, 16, '但他们什么时候归向主，这帕子就什么时候除掉了。'),
('CNV', '哥林多后书', 47, 3, 17, '主就是那灵；主的灵在哪里，哪里就有自由。'),
('CNV', '哥林多后书', 47, 3, 18, '我们众人脸上的帕子既然已经揭开，反映主的荣光（“反映主的荣光”或译：“对着镜子看见主的荣光”），就变成主那样的形象，大有荣光。这是主所作成的，他就是那灵。'),
('CNV', '哥林多后书', 47, 4, 1, '所以，我们既然蒙了怜悯，得着这职分，就不沮丧，'),
('CNV', '哥林多后书', 47, 4, 2, '却把暗昧可耻的事弃绝了；不行诡诈，不掺混神的道，反而藉着显扬真理，在神面前把自己推荐给众人的良心。'),
('CNV', '哥林多后书', 47, 4, 3, '如果我们的福音被蒙蔽了，那是对灭亡的人才蒙蔽的。'),
('CNV', '哥林多后书', 47, 4, 4, '这些不信的人被这世代的神弄瞎了他们的心眼，使他们看不见基督荣耀的福音的光；基督就是神的形象。'),
('CNV', '哥林多后书', 47, 4, 5, '我们并不是传扬自己，而是传扬耶稣基督是主，并且为了耶稣的缘故成了你们的仆人。'),
('CNV', '哥林多后书', 47, 4, 6, '因为那说“要有光从黑暗里照出来”的神，已经照在我们的心里，要我们把神的荣光照出去，就是使人可以认识那在基督脸上的荣光。'),
('CNV', '哥林多后书', 47, 4, 7, '我们有这宝贝在瓦器里，是要显明这极大的能力是属于神，不是出于我们。'),
('CNV', '哥林多后书', 47, 4, 8, '我们虽然四面受压，却没有压碎；心里作难，却不至绝望，'),
('CNV', '哥林多后书', 47, 4, 9, '受到迫害，却没有被丢弃；打倒了，却不至死亡。'),
('CNV', '哥林多后书', 47, 4, 10, '我们身上常常带着耶稣的死，好让耶稣的生也在我们的身上显明出来。'),
('CNV', '哥林多后书', 47, 4, 11, '我们这些活着的人，为耶稣的缘故常常被人置于死地，好让耶稣的生也在我们必死的身上显明出来。'),
('CNV', '哥林多后书', 47, 4, 12, '这样看来，死在我们身上运行，生却在你们的身上运行。'),
('CNV', '哥林多后书', 47, 4, 13, '经上记着说：“我信，所以我说话。”我们既然有同样的信心（“信心”原文作“信心的灵”），也就信，所以也说话，'),
('CNV', '哥林多后书', 47, 4, 14, '因为知道那使主耶稣复活的，也必定使我们与耶稣一同复活，并且把我们和你们呈献在他的面前。'),
('CNV', '哥林多后书', 47, 4, 15, '这一切都是为了你们，好使恩惠既然因着许多人而增多，感恩的心也更加增多了，使荣耀归给神。'),
('CNV', '哥林多后书', 47, 4, 16, '所以，我们并不沮丧，我们外面的人虽然渐渐朽坏，但里面的人却日日更新，'),
('CNV', '哥林多后书', 47, 4, 17, '因为我们短暂轻微的患难，是要为我们成就极大无比、永远的荣耀。'),
('CNV', '哥林多后书', 47, 4, 18, '我们所顾念的，不是看得见的，而是看不见的；因为看得见的是暂时的，看不见的是永远的。'),
('CNV', '哥林多后书', 47, 5, 1, '我们知道，如果我们在地上的帐棚拆毁了，我们必得着从神而来的居所。那不是人手所造的，而是天上永存的房屋。'),
('CNV', '哥林多后书', 47, 5, 2, '我们现今在这帐棚里面叹息，渴望迁到那天上的住处，好像换上新的衣服；'),
('CNV', '哥林多后书', 47, 5, 3, '如果穿上了，就不会赤身出现了。'),
('CNV', '哥林多后书', 47, 5, 4, '我们这些在帐棚里面的人，劳苦叹息，是由于不愿意脱去这个，却愿意穿上那个，使这必死的被生命吞灭。'),
('CNV', '哥林多后书', 47, 5, 5, '那在我们身上完成了工作，使我们达成这目标的，就是神。他已经把圣灵赐给我们作凭据。'),
('CNV', '哥林多后书', 47, 5, 6, '我们既然一向都是坦然无惧的，又知道住在身内就是与主分开（'),
('CNV', '哥林多后书', 47, 5, 7, '因为我们行事是凭着信心，不是凭着眼见），'),
('CNV', '哥林多后书', 47, 5, 8, '现在还是坦然无惧，宁愿与身体分开，与主同住。'),
('CNV', '哥林多后书', 47, 5, 9, '因此，我们立定志向，无论住在身内或是与身体分开，都要讨主的喜悦。'),
('CNV', '哥林多后书', 47, 5, 10, '因为我们众人都必须在基督的审判台前显露出来，使各人按着本身所行的，或善或恶，受到报应。'),
('CNV', '哥林多后书', 47, 5, 11, '我们既然知道主是可畏的，就劝勉众人。我们在神面前是显明的，我盼望在你们的良心里也是显明的。'),
('CNV', '哥林多后书', 47, 5, 12, '我们不是又再向你们推荐自己，而是给你们机会以我们为乐，使你们可以应付那些只夸外貌不夸内心的人。'),
('CNV', '哥林多后书', 47, 5, 13, '如果我们疯狂，那是为了神；如果我们清醒，那是为了你们。'),
('CNV', '哥林多后书', 47, 5, 14, '原来基督的爱催逼着我们，因为我们断定一个人替众人死了，众人就都死了。'),
('CNV', '哥林多后书', 47, 5, 15, '他替众人死了，为的是要使活着的人不再为自己活着，却为那替他们死而复活的主而活。'),
('CNV', '哥林多后书', 47, 5, 16, '所以，从今以后，我们不再按照人的看法认识人；虽然我们曾经按照人的看法认识基督，但现在不再这样了。'),
('CNV', '哥林多后书', 47, 5, 17, '如果有人在基督里，他就是新造的人，旧事已经过去，你看，都变成新的了！'),
('CNV', '哥林多后书', 47, 5, 18, '这一切都是出于神，他藉着基督使我们与他自己和好，并且把这和好的职分赐给我们，'),
('CNV', '哥林多后书', 47, 5, 19, '就是神在基督里使世人与他自己和好，不再追究他们的过犯，并且把和好的道理托付了我们。'),
('CNV', '哥林多后书', 47, 5, 20, '因此，我们就是基督的使者，神藉着我们劝告世人。我们代替基督请求你们：跟神和好吧！'),
('CNV', '哥林多后书', 47, 5, 21, '神使那无罪的替我们成为有罪的，使我们在他里面成为神的义。'),
('CNV', '哥林多后书', 47, 6, 1, '我们这些与神同工的，也劝你们不要白受神的恩典。'),
('CNV', '哥林多后书', 47, 6, 2, '因为他说：“在悦纳的时候，我应允了你；在拯救的日子，我帮助了你。”看哪！现在就是悦纳的时候，现在就是拯救的日子。'),
('CNV', '哥林多后书', 47, 6, 3, '我们凡事都没有妨碍人，不让这职分受到毁谤，'),
('CNV', '哥林多后书', 47, 6, 4, '反而在各样的事上，表明自己是神的仆人，就如持久的忍耐、患难、贫乏、困苦、'),
('CNV', '哥林多后书', 47, 6, 5, '鞭打、监禁、扰乱、劳苦、不睡觉、禁食、'),
('CNV', '哥林多后书', 47, 6, 6, '纯洁、知识、容忍、恩慈、圣灵、无伪的爱心、'),
('CNV', '哥林多后书', 47, 6, 7, '真理的道、神的大能等事上；并且是藉着左右两手中公义的武器，'),
('CNV', '哥林多后书', 47, 6, 8, '藉着荣耀和羞辱、坏名声和好名誉。我们好像是骗人的，却是真诚的，'),
('CNV', '哥林多后书', 47, 6, 9, '好像是人所不知的，却是人所共知的；好像是必死的，你看，我们却是活着的；好像是受惩罚的，却没有处死；'),
('CNV', '哥林多后书', 47, 6, 10, '好像忧愁，却是常常喜乐的；好像贫穷，却使很多人富足；好像是什么都没有，却是样样都有。'),
('CNV', '哥林多后书', 47, 6, 11, '哥林多人哪！我们对你们，口是坦率的，心是宽宏的。'),
('CNV', '哥林多后书', 47, 6, 12, '并不是我们对你们器量小，而是你们自己心胸狭窄。'),
('CNV', '哥林多后书', 47, 6, 13, '你们也要照样以宽宏的心对待我们，这话正象是我对儿女说的。'),
('CNV', '哥林多后书', 47, 6, 14, '你们和不信的人不可共负一轭，义和不法有什么相同呢？光明和黑暗怎能相通呢？'),
('CNV', '哥林多后书', 47, 6, 15, '基督和彼列（“彼列”是撒但的别名）怎能和谐呢？信的和不信的有什么联系呢？'),
('CNV', '哥林多后书', 47, 6, 16, '神的殿和偶像怎能协调呢？我们就是永生神的殿，正如神说：“我要住在他们中间，在他们中间来往；我要作他们的神，他们要作我的子民。”'),
('CNV', '哥林多后书', 47, 6, 17, '所以，“主说：你们要从他们中间出来，和他们分开，不可触摸不洁净的东西，我就收纳你们。”'),
('CNV', '哥林多后书', 47, 6, 18, '“我要作你们的父亲，你们要作我的儿女。这是全能的主说的。”'),
('CNV', '哥林多后书', 47, 7, 1, '所以，亲爱的，我们有了这些应许，就应该洁净自己，除去身体和心灵上的一切污秽，存着敬畏神的心，达到成圣的地步。'),
('CNV', '哥林多后书', 47, 7, 2, '你们的心要容得下我们。我们没有亏负过谁，没有损害过谁，也没有占过谁的便宜。'),
('CNV', '哥林多后书', 47, 7, 3, '我这样说，不是要定你们的罪，因为我从前说过，你们常在我们心里，甚至可以同生共死。'),
('CNV', '哥林多后书', 47, 7, 4, '我对你们大有信心，因你们而感到十分光荣；我心里满有安慰，在我们的一切患难中，格外充满喜乐。'),
('CNV', '哥林多后书', 47, 7, 5, '我们从前到了马其顿的时候，身体一点安宁也没有，反而处处遭受患难，外面有争战，里面有恐惧。'),
('CNV', '哥林多后书', 47, 7, 6, '但那安慰灰心的人的神，藉着提多来到，安慰了我们；'),
('CNV', '哥林多后书', 47, 7, 7, '不但藉着他来，也藉着他从你们所得的安慰，安慰了我们。他把你们的渴望、你们的哀恸和你们对我的热诚，都告诉了我们，因此我就更加欢喜了。'),
('CNV', '哥林多后书', 47, 7, 8, '虽然我在那封信上使你们忧伤，但我现在并不后悔；其实我曾经有点后悔，因为知道那封信使你们忧伤，虽然只是暂时的。'),
('CNV', '哥林多后书', 47, 7, 9, '现在我快乐，不是因为你们忧伤，而是因为你们的忧伤带来了悔改。你们依照神的意思忧伤，凡事就不会因我们受到亏损。'),
('CNV', '哥林多后书', 47, 7, 10, '因为依照神的意思而有的忧伤，可以生出没有懊悔的悔改，以致得救；世俗的忧伤却会招致死亡。'),
('CNV', '哥林多后书', 47, 7, 11, '看哪，你们依照神的意思忧伤，在你们中间就产生了怎样的热情、申诉、愤慨、战兢、渴望、热诚、正义；你们在各方面都表明了自己在那事上是清白的。'),
('CNV', '哥林多后书', 47, 7, 12, '因此，从前我虽然写过信给你们，却不是为了那亏负人的，也不是为了那受害的，而是在神面前把你们对我们的热情，向你们显现出来。'),
('CNV', '哥林多后书', 47, 7, 13, '因此，我们得了安慰。在这安慰之外，我们因提多的喜乐就更加欢喜，因为他的心从你们众人那里得到畅快。'),
('CNV', '哥林多后书', 47, 7, 14, '我若对他夸奖过你们什么，也不觉得惭愧。我们对你们所说的是真话，照样，我们在提多面前夸奖你们的也是真的。'),
('CNV', '哥林多后书', 47, 7, 15, '并且他想起你们众人的服从，怎样恐惧战兢地接待他，他怀念你们的心就更加热切了。'),
('CNV', '哥林多后书', 47, 7, 16, '现在我很欢喜，因为在一切事上我对你们都有信心。'),
('CNV', '哥林多后书', 47, 8, 1, '弟兄们，我现在把神赐给马其顿众教会的恩典告诉你们：'),
('CNV', '哥林多后书', 47, 8, 2, '他们在患难中受到极大的考验的时候，他们满溢的喜乐和极度的贫乏，汇流出丰厚的慷慨来。'),
('CNV', '哥林多后书', 47, 8, 3, '我可以作证，他们是按着能力，并且是超过了能力，自愿地'),
('CNV', '哥林多后书', 47, 8, 4, '再三恳求我们，准许他们在供应圣徒的事上有分。'),
('CNV', '哥林多后书', 47, 8, 5, '他们超过了我们所期望的，照着神的旨意，先把自己献给主，然后献给我们。'),
('CNV', '哥林多后书', 47, 8, 6, '因此，我们勉励提多，既然开始了这慈善的事，就应当在你们那里把这事办好。'),
('CNV', '哥林多后书', 47, 8, 7, '你们在一切事上，就如信心、口才、知识、热情和爱我们的心，既然都是富足的，那么，在这慈善的事上，也要显出你们是富足的。'),
('CNV', '哥林多后书', 47, 8, 8, '我这样说，不是吩咐你们，而是藉着别人的热心来考验你们的爱心是否真实。'),
('CNV', '哥林多后书', 47, 8, 9, '你们是知道我们的主耶稣基督的恩典的：他本来富足，却为你们成了贫穷，要使你们因他的贫穷成为富足。'),
('CNV', '哥林多后书', 47, 8, 10, '我在这里表示我的意见，这对你们是有益的：你们不仅一年前就在办这事，而且早就想这样作了，'),
('CNV', '哥林多后书', 47, 8, 11, '现在就应当把这事办好；这样，你们既然有愿意作的心，因着你们尽了自己所能的，就可以完成。'),
('CNV', '哥林多后书', 47, 8, 12, '因为人要是有愿意作的心，按照他所有的，必蒙悦纳，不是按照他所没有的。'),
('CNV', '哥林多后书', 47, 8, 13, '这不是要别人轻省，你们受累，而是要大家都均等。'),
('CNV', '哥林多后书', 47, 8, 14, '现在你们富裕，就要补助他们的缺乏，到了他们富裕的时候，也可以补助你们的缺乏，这样就均等了；'),
('CNV', '哥林多后书', 47, 8, 15, '正如经上所记：“多的，没有剩余，少的，也不缺乏。”'),
('CNV', '哥林多后书', 47, 8, 16, '感谢神，他把我对你们那样的热情，放在提多的心里。'),
('CNV', '哥林多后书', 47, 8, 17, '提多一方面接受了劝勉，但他自己更加热心，自愿到你们那里去。'),
('CNV', '哥林多后书', 47, 8, 18, '我们还派了一位弟兄和他同去，（这人在福音的事工上，得到了众教会的称赞。'),
('CNV', '哥林多后书', 47, 8, 19, '不但这样，众教会更选派了他作我们的旅伴。我们办理这慈善的事，是为了主的荣耀，也是为了我们的心愿。）'),
('CNV', '哥林多后书', 47, 8, 20, '免得有人因为我们经管的捐款太多，就毁谤我们。'),
('CNV', '哥林多后书', 47, 8, 21, '因为我们努力去作的，不仅是主认为是美的事，也是众人认为是美的事。'),
('CNV', '哥林多后书', 47, 8, 22, '我们还派了另一位弟兄与他们同去；我们在许多的事上多次考验过他，知道他很热心；现在他对你们大有信心，就更加热心了。'),
('CNV', '哥林多后书', 47, 8, 23, '至于提多，他是我的同伴，为你们的缘故作了我的同工；还有我们那两位弟兄，他们是众教会所派的，是基督的荣耀。'),
('CNV', '哥林多后书', 47, 8, 24, '所以，你们要在众教会面前，向他们证明你们的爱心和我们所夸耀你们的。'),
('CNV', '哥林多后书', 47, 9, 1, '关于供应圣徒的事，我本来没有写信给你们的必要，'),
('CNV', '哥林多后书', 47, 9, 2, '因为我知道你们有这个心愿。我对马其顿人称赞你们，说：“亚该亚人去年已经预备好了。”你们的热心就激励了许多的人。'),
('CNV', '哥林多后书', 47, 9, 3, '我派了那几位弟兄前来，为了要使我们在这事上对你们的称赞不至落空，好让你们可以照着我所说的准备妥当，'),
('CNV', '哥林多后书', 47, 9, 4, '免得一旦马其顿人和我一同来到的时候，见你们还没有准备好，我们就因为这样信任你们而感到羞愧，你们就更不用说了。'),
('CNV', '哥林多后书', 47, 9, 5, '因此，我认为必须劝那几位弟兄先到你们那里去，使你们事先筹足从前所答应的捐款。那么，你们这样的准备，就是出于乐意的，不是勉强的。'),
('CNV', '哥林多后书', 47, 9, 6, '还有，少种的少收，多种的多收。'),
('CNV', '哥林多后书', 47, 9, 7, '各人要照着心里所决定的捐输，不要为难，不必勉强，因为捐得乐意的人，是神所喜爱的。'),
('CNV', '哥林多后书', 47, 9, 8, '神能把各样的恩惠多多地加给你们，使你们凡事常常充足，多作各样的善事。'),
('CNV', '哥林多后书', 47, 9, 9, '如经上所说：“他广施钱财，周济穷人；他的仁义，存到永远。”'),
('CNV', '哥林多后书', 47, 9, 10, '但那赐种子给撒种的，又赐食物给人吃的神，必定把种子加倍地供给你们，也必增添你们的义果。'),
('CNV', '哥林多后书', 47, 9, 11, '你们既然凡事富裕，就可以慷慨地捐输，使众人藉着我们，对神生出感谢的心。'),
('CNV', '哥林多后书', 47, 9, 12, '因为这供应的事，不仅补足了圣徒的缺乏，也使许多人对神感谢的心格外增多。'),
('CNV', '哥林多后书', 47, 9, 13, '众圣徒因为你们承认和服从了基督的福音，并且慷慨地捐输给他们和众人，藉着你们在这供应的事上所得的凭据，就把荣耀归给神。'),
('CNV', '哥林多后书', 47, 9, 14, '因着神在你们身上的厚恩，他们就为你们祷告，切切地想念你们。'),
('CNV', '哥林多后书', 47, 9, 15, '感谢神，他的恩赐难以形容。'),
('CNV', '哥林多后书', 47, 10, 1, '我保罗与你们见面的时候是谦卑的，不在你们那里的时候，却是放胆的。现在我亲自以基督的谦逊温柔劝你们，'),
('CNV', '哥林多后书', 47, 10, 2, '求你们使我在你们那里的时候，不要满有自信地放胆对你们，我认为要以这样的自信，勇敢地对付那些以为我们是照着世俗的标准（“世俗的标准”原文作“肉体”）行事的人。'),
('CNV', '哥林多后书', 47, 10, 3, '我们虽然在世上行事，却不是按照世俗的方式作战，'),
('CNV', '哥林多后书', 47, 10, 4, '因为我们作战所用的兵器，不是属于这世界的，而是在神面前有能力的，可以攻陷坚固的堡垒，'),
('CNV', '哥林多后书', 47, 10, 5, '攻破诡辩，和做来阻挡人认识神的一切高墙，并且把一切心意夺回来，顺服基督。'),
('CNV', '哥林多后书', 47, 10, 6, '我们已经准备好了，等你们完全顺服的时候，就惩罚所有不顺从的人。'),
('CNV', '哥林多后书', 47, 10, 7, '你们看事情，只看表面。如果有人自信是属于基督的，他就应该再想一想：他是属于基督的，同样，我们也是属于基督的。'),
('CNV', '哥林多后书', 47, 10, 8, '主把权柄赐给我们，是为了要造就你们，不是要破坏你们，就算我为这权柄夸口过分了一点，也不会觉得惭愧。'),
('CNV', '哥林多后书', 47, 10, 9, '不要以为我写信是用来吓你们。'),
('CNV', '哥林多后书', 47, 10, 10, '因为有人说：“他的信又严厉又强硬，他本人却其貌不扬，言语粗俗。”'),
('CNV', '哥林多后书', 47, 10, 11, '说这话的人要想一想，我们不在你们那里的时候，信上怎样写，我们来到的时候也会怎样作。'),
('CNV', '哥林多后书', 47, 10, 12, '我们不敢和那些自我推荐的人相提并论；他们拿自己来量自己，拿自己来比自己，实在不大聪明。'),
('CNV', '哥林多后书', 47, 10, 13, '我们所夸的，并没有越过范围，而是在神量给我们的界限之内；这界限一直延伸到你们那里。'),
('CNV', '哥林多后书', 47, 10, 14, '如果我们没有到过你们那里，现在就自夸得过分了；但事实上，我们早就把基督的福音传到你们那里了。'),
('CNV', '哥林多后书', 47, 10, 15, '我们并没有越过范围，拿别人的劳苦来夸口。我们盼望随着你们信心的增长，我们的界限就因你们而大大扩展，'),
('CNV', '哥林多后书', 47, 10, 16, '使我们可以把福音传到你们以外的地方。别人在他的界限以内所完成的工作，我们不会拿来夸口的。'),
('CNV', '哥林多后书', 47, 10, 17, '夸口的应当靠着主夸口，'),
('CNV', '哥林多后书', 47, 10, 18, '因为蒙悦纳的，不是自我推荐的人，而是主所推荐的人。'),
('CNV', '哥林多后书', 47, 11, 1, '请你们容忍我这一点点的愚昧，其实你们本来就是容忍我的。'),
('CNV', '哥林多后书', 47, 11, 2, '我以神的热爱爱你们，因为我把你们献给基督，好像把贞洁的童女许配给一个丈夫。'),
('CNV', '哥林多后书', 47, 11, 3, '我只怕你们的心受到引诱，失去对基督的单纯和贞洁，好像蛇用诡计骗了夏娃一样。'),
('CNV', '哥林多后书', 47, 11, 4, '如果有人来传讲另一位耶稣，不是我们传过的，或者你们接受另一个不同的灵，不是你们领受过的，又或者接受另一个不同的福音，不是你们接受过的，你们倒可以容忍得下！'),
('CNV', '哥林多后书', 47, 11, 5, '但我认为自己没有一点比不上那些“超等使徒”；'),
('CNV', '哥林多后书', 47, 11, 6, '虽然我不善于辞令，却是有学问的，我们在各方面，已经向你们清楚显明了。'),
('CNV', '哥林多后书', 47, 11, 7, '我贬低自己，使你们高升，把神的福音白白地传给你们，我这样是犯罪吗？'),
('CNV', '哥林多后书', 47, 11, 8, '我为了服事你们，就接受了别的教会的供应，也可以说是剥削了他们。'),
('CNV', '哥林多后书', 47, 11, 9, '我在你们那里有缺乏的时候，并没有连累任何人，因为从马其顿来的弟兄们，补足了我的缺乏。我在各方面都不让自己成为你们的重担，将来也是一样。'),
('CNV', '哥林多后书', 47, 11, 10, '我有基督的真理在我里面，在亚该亚一带没有人能阻止我这样夸口。'),
('CNV', '哥林多后书', 47, 11, 11, '为什么呢？是我不爱你们吗？神是知道的。'),
('CNV', '哥林多后书', 47, 11, 12, '我现在所作的，将来还要作，为了要断绝那些投机分子的机会，不让他们在所夸的事上，被人认为是跟我们一样的。'),
('CNV', '哥林多后书', 47, 11, 13, '这样的人是假使徒，是诡诈的工人，装成基督的使徒。'),
('CNV', '哥林多后书', 47, 11, 14, '这并不希奇，因为撒但自己也装作光明的天使，'),
('CNV', '哥林多后书', 47, 11, 15, '所以，撒但的仆役装成公义的仆役，也不必大惊小怪。他们的结局必按他们所作的而定。'),
('CNV', '哥林多后书', 47, 11, 16, '我再说，谁也不要以为我是愚昧的；就算这样，也要接纳我这个愚昧的人，使我可以稍微地夸口。'),
('CNV', '哥林多后书', 47, 11, 17, '我这样满有自信地夸口，不是照着主所吩咐的，而是好像愚昧人在说话。'),
('CNV', '哥林多后书', 47, 11, 18, '既然有许多人按着世俗的标准夸口，我也要夸口。'),
('CNV', '哥林多后书', 47, 11, 19, '你们那么精明，竟然乐意容忍愚昧的人。'),
('CNV', '哥林多后书', 47, 11, 20, '如果有人奴役你们，侵吞、榨取你们，向你们趾高气扬，打你们的脸，你们就容忍吧！'),
('CNV', '哥林多后书', 47, 11, 21, '说来惭愧，我们太软弱了。说句愚昧的话，如果有人在什么事上是勇敢的，我也是勇敢的。'),
('CNV', '哥林多后书', 47, 11, 22, '他们是希伯来人吗？我也是。他们是以色列人吗？我也是。他们是亚伯拉罕的后裔吗？我也是。'),
('CNV', '哥林多后书', 47, 11, 23, '他们是基督的仆人吗？说句狂话，我更是。我受更多的劳苦，更多的坐监，受了过量的鞭打，常常有生命的危险。'),
('CNV', '哥林多后书', 47, 11, 24, '我被犹太人打过五次，每次四十下减去一下，'),
('CNV', '哥林多后书', 47, 11, 25, '被棍打过三次，被石头打过一次，三次遇着船坏，在深海里飘了一昼一夜；'),
('CNV', '哥林多后书', 47, 11, 26, '多次行远路，遇着江河的危险、强盗的危险、同族的危险、外族的危险、城中的危险、旷野的危险、海上的危险、假弟兄的危险；'),
('CNV', '哥林多后书', 47, 11, 27, '劳碌辛苦，多次不得睡觉，又饥又渴，多次缺粮，赤身挨冷。'),
('CNV', '哥林多后书', 47, 11, 28, '除了这些外面的事，还有为各教会挂心的事，天天压在我的身上。'),
('CNV', '哥林多后书', 47, 11, 29, '有谁软弱，我不软弱呢？有谁陷在罪里，我不焦急呢？'),
('CNV', '哥林多后书', 47, 11, 30, '如果必须夸口，我就夸自己的弱点。'),
('CNV', '哥林多后书', 47, 11, 31, '主耶稣的父神是应当永远受称颂的，他知道我没有说谎。'),
('CNV', '哥林多后书', 47, 11, 32, '在大马士革，亚里达王手下的总督把守着大马士革城，要拘捕我，'),
('CNV', '哥林多后书', 47, 11, 33, '我就被人放在一个大篮子里，从城墙的窗户缒下来，逃脱了他的手。'),
('CNV', '哥林多后书', 47, 12, 1, '夸口固然无益，却也是必要的。现在我要说说主的异象和启示。'),
('CNV', '哥林多后书', 47, 12, 2, '我认识一个在基督里的人，他十四年前被提到第三层天上去。（是带着身体被提的呢？我不知道，是离开了身体呢？我也不知道，只有神知道。）'),
('CNV', '哥林多后书', 47, 12, 3, '我认识这个人，（是带着身体被提，还是在身体以外被提，我都不知道，只有神知道。）'),
('CNV', '哥林多后书', 47, 12, 4, '他被提到乐园里去，听见了难以言喻的话，那是人不可以说的。'),
('CNV', '哥林多后书', 47, 12, 5, '为了这个人，我要夸口，但为了我自己，除了我的软弱以外，我没有可夸的。'),
('CNV', '哥林多后书', 47, 12, 6, '即使我想夸口，也不算愚妄，因为我要说的是真话。但我闭口不提，免得有人把我看得太高，过于他在我身上所见所闻的。'),
('CNV', '哥林多后书', 47, 12, 7, '又因为我所得的启示太大，恐怕会高抬自己，所以就有一根刺加在我的身上，就是撒但的差役来攻击我，免得我高抬自己。'),
('CNV', '哥林多后书', 47, 12, 8, '为了这事，我曾经三次求主，使这根刺离开我。'),
('CNV', '哥林多后书', 47, 12, 9, '他却对我说：“我的恩典是够你用的，因为我的能力在人的软弱上显得完全。”所以，我更喜欢夸自己的软弱，好让基督的能力临到我的身上。'),
('CNV', '哥林多后书', 47, 12, 10, '因此，我为基督的缘故，就以软弱、凌辱、艰难、迫害、困苦为喜乐，因为我什么时候软弱，什么时候就刚强了。'),
('CNV', '哥林多后书', 47, 12, 11, '我成了愚妄的人，是你们逼成的。其实你们应该称赞我，因为我虽然算不得什么，却没有一点比不上那些“超等使徒”。'),
('CNV', '哥林多后书', 47, 12, 12, '我在你们中间，以各种忍耐，用神迹、奇事和大能，作为使徒的凭据。'),
('CNV', '哥林多后书', 47, 12, 13, '除了我自己没有成为你们的重担以外，你们还有什么比不上别的教会呢？这一点委屈，请原谅我吧！'),
('CNV', '哥林多后书', 47, 12, 14, '好了，我打算第三次到你们那里去，这一次也不会成为你们的重担，因为我所要的不是你们的东西，而是你们自己。儿女不需要为父母积财，父母却应该为儿女积财。'),
('CNV', '哥林多后书', 47, 12, 15, '至于我，我甘心乐意为你们的灵魂付上一切，鞠躬尽瘁。难道我越爱你们，就越得不到你们的爱吗？'),
('CNV', '哥林多后书', 47, 12, 16, '算了！我没有成为你们的重担，却是个狡猾的人，用诡计牢笼你们。'),
('CNV', '哥林多后书', 47, 12, 17, '我派到你们那里去的人，我藉着谁占过你们的便宜？'),
('CNV', '哥林多后书', 47, 12, 18, '我劝提多到你们那里去，又派了那位弟兄一同去。提多占过你们的便宜吗？我们行事，不是同一个心灵吗？不是同样的步伐吗？'),
('CNV', '哥林多后书', 47, 12, 19, '你们一直以为我们是在向你们申辩吗？我们是在基督里，当着神面前说话的。亲爱的，一切事都是为了建立你们。'),
('CNV', '哥林多后书', 47, 12, 20, '我怕我来的时候，见你们不如我所想的，你们见我也不如你们所想的。又怕有纷争、嫉妒、恼怒、自私、毁谤、谗言、狂傲、混乱的事。'),
('CNV', '哥林多后书', 47, 12, 21, '又怕我再来的时候，我的神使我在你们面前羞愧；并且我要为许多从前犯罪的人哀痛，因为他们行了污秽、奸淫、邪荡的事，却不肯悔改。'),
('CNV', '哥林多后书', 47, 13, 1, '这是我第三次到你们那里去，各样事情必须凭两三个证人的口，才能确定。'),
('CNV', '哥林多后书', 47, 13, 2, '我第二次到你们那里去的时候说过，现今不在你们那里，再预先对那些从前犯了罪的和其余的人说：我若再来，必不宽容，'),
('CNV', '哥林多后书', 47, 13, 3, '因为你们在找基督藉着我说话的凭据。基督对你们不是软弱的，相反地，在你们身上是有能力的。'),
('CNV', '哥林多后书', 47, 13, 4, '他因着软弱被钉死了，却靠着神的大能活着。我们在他里面也是软弱的，但靠着神向你们所显的大能，也必与他一同活着。'),
('CNV', '哥林多后书', 47, 13, 5, '你们应当察验自己是不是持守着信仰，也应当考验自己。难道不晓得基督耶稣是在你们里面吗？（除非你们是经不起考验的人。）'),
('CNV', '哥林多后书', 47, 13, 6, '我盼望你们晓得，我们不是经不起考验的人。'),
('CNV', '哥林多后书', 47, 13, 7, '我们祈求神，使你们不作什么恶事。这并不是要显明我们是经得起考验的，而是要你们行善；我们呢，就让我们作经不起考验的人好了！'),
('CNV', '哥林多后书', 47, 13, 8, '我们不能作什么事违背真理，只能维护真理。'),
('CNV', '哥林多后书', 47, 13, 9, '当我们软弱、你们刚强的时候，我们就欢喜；我们所求的，就是要你们完全。'),
('CNV', '哥林多后书', 47, 13, 10, '因此，我趁着不在你们那里的时候，把这些话写给你们，到我来了，就不必凭着主所给我的权柄严厉地对待你们。这权柄不是要拆毁你们，而是要建立你们。'),
('CNV', '哥林多后书', 47, 13, 11, '最后，弟兄们，你们要喜乐，要完全，要受安慰，要同心，要和睦。这样，施慈爱赐平安的神必与你们同在。'),
('CNV', '哥林多后书', 47, 13, 12, '你们要用圣洁的亲吻彼此问安。'),
('CNV', '哥林多后书', 47, 13, 13, '众圣徒都问候你们。'),
('CNV', '哥林多后书', 47, 13, 14, '愿主耶稣基督的恩惠，神的慈爱，圣灵的契通，常与你们众人同在。'),
('CNV', '加拉太书', 48, 1, 1, '作使徒的保罗（不是由于人，也不是藉着人，而是藉着耶稣基督和那使他从死人中复活的父神），'),
('CNV', '加拉太书', 48, 1, 2, '和所有与我在一起的弟兄，写信给加拉太的众教会。'),
('CNV', '加拉太书', 48, 1, 3, '愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '加拉太书', 48, 1, 4, '基督照着我们父神的旨意，曾经为我们的罪舍己，为的是要救我们脱离现在这邪恶的世代。'),
('CNV', '加拉太书', 48, 1, 5, '愿荣耀归给他，直到永永远远。阿们。'),
('CNV', '加拉太书', 48, 1, 6, '我很惊奇，你们这么快就离开了藉着基督的恩呼召你们的那一位，去归向别的福音。'),
('CNV', '加拉太书', 48, 1, 7, '其实那并不是另一个福音，只是有些搅扰你们的人，想把基督的福音改变。'),
('CNV', '加拉太书', 48, 1, 8, '但无论是我们，或是从天上来的使者，如果传给你们的和我们以前传给你们的福音不同，他就该受咒诅。'),
('CNV', '加拉太书', 48, 1, 9, '我们已经说过，现在我要再说，如果有人传给你们的和你们以前所领受的福音不同，他就该受咒诅。'),
('CNV', '加拉太书', 48, 1, 10, '我现在是要得人的欢心，还是要得神的欢心呢？难道我想讨人欢喜吗？如果我仍然要讨人欢喜，就不是基督的仆人了。'),
('CNV', '加拉太书', 48, 1, 11, '弟兄们，我要你们知道，我所传的福音，并不是照着人的意思，'),
('CNV', '加拉太书', 48, 1, 12, '因为这福音我不是从人领受的，也不是人教导我的，而是藉着耶稣基督的启示来的。'),
('CNV', '加拉太书', 48, 1, 13, '你们听过我从前在犹太教中所行的：怎样极力逼迫残害神的教会，'),
('CNV', '加拉太书', 48, 1, 14, '怎样在犹太教中比许多本族同辈的人更激进，为我祖先的传统分外热心。'),
('CNV', '加拉太书', 48, 1, 15, '然而，当我在母腹里就把我分别出来，又用他的恩呼召我的那一位，'),
('CNV', '加拉太书', 48, 1, 16, '既然乐意把自己的儿子启示给我，使我可以在外族人中传扬他，我就没有和任何人（“人”原文作“肉和血”）商量，'),
('CNV', '加拉太书', 48, 1, 17, '也没有上耶路撒冷见那些比我先作使徒的，却去了阿拉伯，然后再回到大马士革。'),
('CNV', '加拉太书', 48, 1, 18, '过了三年，我才上耶路撒冷去见矶法，和他住了十五天。'),
('CNV', '加拉太书', 48, 1, 19, '至于其余的使徒，除了主的弟弟雅各以外，我都没有见过。'),
('CNV', '加拉太书', 48, 1, 20, '在神面前我敢说，我写给你们的都不是谎话。'),
('CNV', '加拉太书', 48, 1, 21, '后来，我到了叙利亚和基利家一带的地方。'),
('CNV', '加拉太书', 48, 1, 22, '那时，在基督里的犹太众教会还没有见过我的面，'),
('CNV', '加拉太书', 48, 1, 23, '不过听说“那个从前迫害我们的，现在竟然传扬他以前所残害的信仰”，'),
('CNV', '加拉太书', 48, 1, 24, '他们就因着我的缘故颂赞神。'),
('CNV', '加拉太书', 48, 2, 1, '过了十四年，我再次上耶路撒冷去，这次是和巴拿巴，并且带着提多一同去的。'),
('CNV', '加拉太书', 48, 2, 2, '我是顺从启示去的；在那里我对他们说明我在外族人中所传的福音，私下讲了给那些有名望的人听，免得我从前或现在都白跑了。'),
('CNV', '加拉太书', 48, 2, 3, '与我同行的提多，虽然是希腊人，也没有强迫他受割礼；'),
('CNV', '加拉太书', 48, 2, 4, '这是因为有些混进来的假弟兄，暗暗地来侦查我们在基督耶稣里享有的自由，为的是要辖制我们。'),
('CNV', '加拉太书', 48, 2, 5, '对这些人，我们一点也没有让步妥协，为了要使福音的真理存留在你们中间。'),
('CNV', '加拉太书', 48, 2, 6, '至于那些被认为有名望的人（无论他们从前怎么样，都与我无关；神不以外貌取人），他们并没有给我增加什么；'),
('CNV', '加拉太书', 48, 2, 7, '反而因为看见我受托传福音给没有受割礼的人，就像彼得受托传福音给受割礼的人一样，'),
('CNV', '加拉太书', 48, 2, 8, '（因为运行在彼得里面，使他作受割礼者的使徒的那一位，也运行在我里面，使我作外族人的使徒，）'),
('CNV', '加拉太书', 48, 2, 9, '又知道我蒙了神的恩，那几位被誉为柱石的雅各、矶法和约翰，就向我和巴拿巴伸出右手互相许诺，我们要到外族人那里去传福音，他们要到受割礼的人那里去传福音；'),
('CNV', '加拉太书', 48, 2, 10, '只是要我们记念穷人，这本来也是我一向热心作的。'),
('CNV', '加拉太书', 48, 2, 11, '可是，矶法到了安提阿的时候，因为他有该责备的地方，我就当面反对他。'),
('CNV', '加拉太书', 48, 2, 12, '从雅各那里来的人还没有到以前，他和外族人一同吃饭；但他们来到了，他因为怕那些守割礼的人，就从外族人中退出来，和他们分开。'),
('CNV', '加拉太书', 48, 2, 13, '其余的犹太人也和他一同装假，甚至连巴拿巴也受了影响，跟着他们装假。'),
('CNV', '加拉太书', 48, 2, 14, '但我一见他们所行的不合福音的真理，就当众对矶法说：“你是犹太人，生活既然像外族人而不像犹太人，怎么还勉强外族人跟随犹太人的规矩呢？”'),
('CNV', '加拉太书', 48, 2, 15, '我们生来是犹太人，不是外族中的罪人；'),
('CNV', '加拉太书', 48, 2, 16, '既然知道人称义不是靠行律法，而是因信耶稣基督，我们也就信了基督耶稣，使我们因信基督称义，不是靠行律法；因为没有人能靠行律法称义。'),
('CNV', '加拉太书', 48, 2, 17, '如果我们寻求在基督里称义，却仍然是罪人，难道基督是使人犯罪的吗？绝对不是。'),
('CNV', '加拉太书', 48, 2, 18, '我若重建我所拆毁的，就证明自己是个有过犯的人。'),
('CNV', '加拉太书', 48, 2, 19, '我藉着律法已经向律法死了，使我可以向神活着。'),
('CNV', '加拉太书', 48, 2, 20, '我已经与基督同钉十字架；现在活着的，不再是我，而是基督活在我里面；如今在肉身中活着的我，是因信神的儿子而活的；他爱我，为我舍己。'),
('CNV', '加拉太书', 48, 2, 21, '我不废弃神的恩；如果义是藉着律法而来的，基督就白白地死了。'),
('CNV', '加拉太书', 48, 3, 1, '无知的加拉太人哪！耶稣基督钉十字架，已经活现在你们眼前，谁又迷惑了你们呢？'),
('CNV', '加拉太书', 48, 3, 2, '我只想问你们这一点：你们接受了圣灵，是靠着行律法，还是因为信所听见的福音呢？'),
('CNV', '加拉太书', 48, 3, 3, '你们是这样的无知吗？你们既然靠着圣灵开始，现在还要靠着肉体成全吗？'),
('CNV', '加拉太书', 48, 3, 4, '你们受了这么多的苦，都是白受的吗？恐怕真是白受的了。'),
('CNV', '加拉太书', 48, 3, 5, '那么，神赐圣灵给你们，又在你们中间行神迹，是因为你们行律法，还是因为你们信所听见的福音呢？'),
('CNV', '加拉太书', 48, 3, 6, '正如亚伯拉罕信神，这就算为他的义。'),
('CNV', '加拉太书', 48, 3, 7, '所以你们要知道，有信心的人，就是亚伯拉罕的子孙。'),
('CNV', '加拉太书', 48, 3, 8, '圣经既然预先看见神要使外族人因信称义，就预先把好信息传给亚伯拉罕：“万国都必因你得福。”'),
('CNV', '加拉太书', 48, 3, 9, '这样看来，有信心的人，必定和有信心的亚伯拉罕一同得福。'),
('CNV', '加拉太书', 48, 3, 10, '凡是靠行律法称义的，都在咒诅之下，因为经上记着：“凡不常常照着律法书上所写的一切去行的，都被咒诅。”'),
('CNV', '加拉太书', 48, 3, 11, '很明显，在神面前，没有一个人可以靠着律法称义，因为“义人必因信得生”（“义人必因信得生”或译：“因信称义的人，必定得生”）。'),
('CNV', '加拉太书', 48, 3, 12, '律法本来不是出于信，而是说：“遵行这些事的人，就必因这些事而活。”'),
('CNV', '加拉太书', 48, 3, 13, '基督替我们受了咒诅，就救赎我们脱离了律法的咒诅，因为经上记着：“凡挂在木头上的，都是受咒诅的。”'),
('CNV', '加拉太书', 48, 3, 14, '这样，亚伯拉罕所蒙的福，就在耶稣基督里临到外族人，使我们因着信，可以领受所应许的圣灵。'),
('CNV', '加拉太书', 48, 3, 15, '弟兄们，我照着人的常理说：一个立好了的约，虽然是人所立的，却没有人可以废弃或增加。'),
('CNV', '加拉太书', 48, 3, 16, '那些应许本来是给亚伯拉罕和他的后裔的。神并没有说“给众后裔”，好像指着多数；而是说“给你的一个后裔”，指着一个，就是基督。'),
('CNV', '加拉太书', 48, 3, 17, '我要这样说，神预先立好的约，那四百三十年后才有的律法，不能把它废掉，使那应许落空。'),
('CNV', '加拉太书', 48, 3, 18, '因为所承受的，如果是出于律法，就不是出于应许；但神是凭着应许赐给了亚伯拉罕。'),
('CNV', '加拉太书', 48, 3, 19, '那么，为什么要有律法呢？是为了过犯的缘故才加上的，直到那得应许的后裔来到。律法是藉着天使经中保的手设立的；'),
('CNV', '加拉太书', 48, 3, 20, '中保不是为单方面的，但神却是一位。'),
('CNV', '加拉太书', 48, 3, 21, '这样，律法和神的应许是对立的吗？绝对不是。如果所赐下的律法能使人得生命，义就真的是出于律法了。'),
('CNV', '加拉太书', 48, 3, 22, '但圣经把所有的人都圈在罪中，好把那因信耶稣基督而来的应许，赐给相信的人。'),
('CNV', '加拉太书', 48, 3, 23, '但信的道理还没有来到以前，我们在律法下被囚禁、被围困，直到那要来的信的道理显明出来。'),
('CNV', '加拉太书', 48, 3, 24, '这样，律法成了我们的启蒙教师，领我们到基督那里，使我们可以因信称义。'),
('CNV', '加拉太书', 48, 3, 25, '但信的道理既然来到，我们就不再在启蒙教师之下了。'),
('CNV', '加拉太书', 48, 3, 26, '你们因着信，在基督耶稣里都作了神的儿子。'),
('CNV', '加拉太书', 48, 3, 27, '你们所有受洗归入基督的人，都是披戴基督的，'),
('CNV', '加拉太书', 48, 3, 28, '并不分犹太人或希腊人，作奴仆的或自由人，男的或女的，因为你们在基督耶稣里都成为一体了。'),
('CNV', '加拉太书', 48, 3, 29, '如果你们属于基督，就是亚伯拉罕的后裔，是按照应许承受产业的了。'),
('CNV', '加拉太书', 48, 4, 1, '我说，那承受产业的，虽然是全部产业的主人，但在孩童的时期，却和奴仆没有分别。'),
('CNV', '加拉太书', 48, 4, 2, '他是在监护人和管家之下，直到父亲预先指定的时候。'),
('CNV', '加拉太书', 48, 4, 3, '我们也是这样，作孩童的时候，被世俗的言论所奴役；'),
('CNV', '加拉太书', 48, 4, 4, '但到了时机成熟，神就差遣他的儿子，由女人所生，而且生在律法之下，'),
('CNV', '加拉太书', 48, 4, 5, '要把律法之下的人救赎出来，好让我们得着嗣子的名分。'),
('CNV', '加拉太书', 48, 4, 6, '你们既然是儿子，神就差遣他儿子的灵进入我们心里，呼叫“阿爸、父！”'),
('CNV', '加拉太书', 48, 4, 7, '这样，你不再是奴仆，而是儿子；既然是儿子，就靠着神承受产业了。'),
('CNV', '加拉太书', 48, 4, 8, '从前你们不认识神的时候，是给那些本来不是神的作奴仆；'),
('CNV', '加拉太书', 48, 4, 9, '现在你们既然认识神，更可以说是神所认识的，怎么还回到那些软弱贫乏的言论，情愿再作它们的奴仆呢？'),
('CNV', '加拉太书', 48, 4, 10, '你们严守日子、月份、节期、年份；'),
('CNV', '加拉太书', 48, 4, 11, '我为你们担心，恐怕我在你们身上的劳苦是白费了。'),
('CNV', '加拉太书', 48, 4, 12, '弟兄们，我请求你们要像我一样，因为我也像你们一样。你们并没有亏负过我。'),
('CNV', '加拉太书', 48, 4, 13, '你们知道，我第一次传福音给你们，是因为身体有病。'),
('CNV', '加拉太书', 48, 4, 14, '虽然我的身体对你们是个试炼，你们却没有轻看，也没有厌弃，反而接纳我，好像神的天使，也好像基督耶稣。'),
('CNV', '加拉太书', 48, 4, 15, '现在，你们的欢乐在哪里呢？我可以为你们作证，那时如果可能，你们甚至愿意把你们的眼睛剜出来给我哩！'),
('CNV', '加拉太书', 48, 4, 16, '现在我把真理告诉你们，反而成了你们的仇敌吗？'),
('CNV', '加拉太书', 48, 4, 17, '那些人热心待你们，并不是出于好意，而是想你们和我疏远，好使你们热心待他们。'),
('CNV', '加拉太书', 48, 4, 18, '常常在善事上热心，总是好的；只是不要我在你们那里的时候才是这样。'),
('CNV', '加拉太书', 48, 4, 19, '我的孩子们，为了你们我再受生产的痛苦，直到基督在你们里面成形。'),
('CNV', '加拉太书', 48, 4, 20, '我恨不得现今就在你们那里，改变我的语气，因为我为你们十分困扰。'),
('CNV', '加拉太书', 48, 4, 21, '你们这愿意在律法之下的人哪！请告诉我，你们没有听过律法吗？'),
('CNV', '加拉太书', 48, 4, 22, '经上记着说，亚伯拉罕有两个儿子，一个出于婢女，一个出于自由的妇人。'),
('CNV', '加拉太书', 48, 4, 23, '但那出于婢女的，是按着肉体生的；那出于自由的妇人的，是凭着应许生的。'),
('CNV', '加拉太书', 48, 4, 24, '这都是寓意的说法：那两个妇人就是两个约，一个是出于西奈山，生子作奴仆，这是夏甲。'),
('CNV', '加拉太书', 48, 4, 25, '这夏甲是指着阿拉伯的西奈山，相当于现在的耶路撒冷，她和她的儿女都是作奴仆的。'),
('CNV', '加拉太书', 48, 4, 26, '那在上面的耶路撒冷是自由的，她是我们的母亲，'),
('CNV', '加拉太书', 48, 4, 27, '因为经上记着说：“不能生育、没有生养的啊，你要欢欣！没有受过生产痛苦的啊，你要呼喊，大声呼叫！因为弃妇比有夫之妇有更多儿子。”'),
('CNV', '加拉太书', 48, 4, 28, '可是，弟兄们，你们是按着应许作儿女的，好像以撒一样。'),
('CNV', '加拉太书', 48, 4, 29, '不过，当时那按着肉体生的，迫害那按着圣灵生的，现在也是这样。'),
('CNV', '加拉太书', 48, 4, 30, '然而经上怎样说呢？“把婢女和她的儿子赶出去，因为婢女的儿子，绝对不可以和自由的妇人的儿子一同承受产业。”'),
('CNV', '加拉太书', 48, 4, 31, '所以，弟兄们，我们不是婢女的儿女，而是自由的妇人的儿女了。'),
('CNV', '加拉太书', 48, 5, 1, '基督释放了我们，为了要使我们得自由。所以你们要站立得稳，不要再被奴役的轭控制。'),
('CNV', '加拉太书', 48, 5, 2, '我保罗现在告诉你们，如果你们受割礼，基督对你们就毫无益处了。'),
('CNV', '加拉太书', 48, 5, 3, '我再对所有受割礼的人郑重声明：他有责任遵行全部的律法。'),
('CNV', '加拉太书', 48, 5, 4, '你们这些靠律法称义的人，是和基督隔绝，从恩典中坠落了。'),
('CNV', '加拉太书', 48, 5, 5, '我们靠着圣灵，凭着信，热切等候所盼望的义。'),
('CNV', '加拉太书', 48, 5, 6, '因为在基督耶稣里，受割礼或不受割礼，都没有用处，唯有那藉着爱表达出来的信，才有用处。'),
('CNV', '加拉太书', 48, 5, 7, '你们向来跑得好，谁拦阻了你们，使你们不顺从真理呢？'),
('CNV', '加拉太书', 48, 5, 8, '这种劝诱不是出于那召你们的。'),
('CNV', '加拉太书', 48, 5, 9, '一点面酵能使全团面发起来。'),
('CNV', '加拉太书', 48, 5, 10, '我在主里深信你们不会存别的意念；但那搅扰你们的，无论是谁，必定要受刑罚。'),
('CNV', '加拉太书', 48, 5, 11, '弟兄们，如果我仍旧传割礼，我为什么还受迫害呢？若是这样，十字架绊倒人的地方就没有了。'),
('CNV', '加拉太书', 48, 5, 12, '我恨不得那些扰乱你们的人把自己阉割了！'),
('CNV', '加拉太书', 48, 5, 13, '弟兄们，你们蒙召得了自由；只是不可把这自由当作放纵情欲的机会，总要凭着爱心互相服事。'),
('CNV', '加拉太书', 48, 5, 14, '因为全部的律法，都在“爱人如己”这一句话里面成全了。'),
('CNV', '加拉太书', 48, 5, 15, '你们要谨慎，如果相咬相吞，恐怕彼此都要毁灭了。'),
('CNV', '加拉太书', 48, 5, 16, '我是说，你们应当顺着圣灵行事，这样就一定不会去满足肉体的私欲了。'),
('CNV', '加拉太书', 48, 5, 17, '因为肉体的私欲和圣灵敌对，圣灵也和肉体敌对；这两样互相敌对，使你们不能作自己愿意作的。'),
('CNV', '加拉太书', 48, 5, 18, '但你们若被圣灵引导，就不在律法以下了。'),
('CNV', '加拉太书', 48, 5, 19, '肉体所行的都是显而易见的，就如淫乱、污秽、邪荡、'),
('CNV', '加拉太书', 48, 5, 20, '拜偶像、行邪术、仇恨、争竞、忌恨、忿怒、自私、分党、结派、'),
('CNV', '加拉太书', 48, 5, 21, '嫉妒、醉酒、荒宴，和类似的事。我从前早就告诉过你们，现在又事先告诉你们：行这些事的人，必定不能承受神的国。'),
('CNV', '加拉太书', 48, 5, 22, '但圣灵的果子是仁爱、喜乐、平安、忍耐、恩慈、良善、信实、'),
('CNV', '加拉太书', 48, 5, 23, '温柔、节制；这样的事，是没有律法禁止的。'),
('CNV', '加拉太书', 48, 5, 24, '属基督耶稣的人，是已经把肉体和邪情私欲都钉在十字架上了。'),
('CNV', '加拉太书', 48, 5, 25, '如果我们靠圣灵活着，就应该顺着圣灵行事。'),
('CNV', '加拉太书', 48, 5, 26, '我们不可贪图虚荣，彼此触怒，互相嫉妒。'),
('CNV', '加拉太书', 48, 6, 1, '弟兄们，如果有人陷在一些过犯里，你们属灵的人，要用温柔的心使他回转过来，自己却要小心，免得也被引诱。'),
('CNV', '加拉太书', 48, 6, 2, '你们各人的重担要互相担当，这样就成全了基督的律法。'),
('CNV', '加拉太书', 48, 6, 3, '如果有人本来没有什么了不起，却自以为是了不起的，就是欺骗自己。'),
('CNV', '加拉太书', 48, 6, 4, '各人应该省察自己所作的，这样，他引以为荣的，就只在自己而不在别人了；'),
('CNV', '加拉太书', 48, 6, 5, '因为各人的担子，是要自己担当的。'),
('CNV', '加拉太书', 48, 6, 6, '在圣道上受教的，应该和施教的人分享自己的一切美物。'),
('CNV', '加拉太书', 48, 6, 7, '不要自欺，神是不可轻慢的。人种的是什么，收的也是什么：'),
('CNV', '加拉太书', 48, 6, 8, '顺着自己的肉体撒种的，必定从肉体收取败坏；顺着圣灵撒种的，必定从圣灵收取永生。'),
('CNV', '加拉太书', 48, 6, 9, '我们行善，不要觉得厌烦；如果不松懈，到了适当的时候，就有收成。'),
('CNV', '加拉太书', 48, 6, 10, '所以，我们一有机会，就应该对众人行善，对信徒更要这样。'),
('CNV', '加拉太书', 48, 6, 11, '请看，我亲手写给你们的字是多么的大。'),
('CNV', '加拉太书', 48, 6, 12, '那些在外表上要体面的人，他们勉强你们受割礼，不过是怕为了基督的十字架受迫害。'),
('CNV', '加拉太书', 48, 6, 13, '那些受割礼的人，自己也不遵守律法，反而要你们受割礼，为的是要藉着你们的肉身夸口。'),
('CNV', '加拉太书', 48, 6, 14, '至于我，我绝不以别的夸口，只夸我们主耶稣基督的十字架。藉着这十字架，在我来说，世界已经钉在十字架上了；就世界来说，我也已经钉在十字架上了。'),
('CNV', '加拉太书', 48, 6, 15, '受割礼或不受割礼，都算不得什么，要紧的是作新造的人。'),
('CNV', '加拉太书', 48, 6, 16, '所有照这准则而行的人，愿平安怜悯临到他们，就是临到神的以色列。'),
('CNV', '加拉太书', 48, 6, 17, '从今以后，谁也不要搅扰我，因为我身上带着耶稣的烙痕。'),
('CNV', '加拉太书', 48, 6, 18, '弟兄们，愿我们主耶稣基督的恩惠与你们同在（“与你们同在”原文作“与你们的心灵同在”）。阿们。'),
('CNV', '以弗所书', 49, 1, 1, '奉神旨意作基督耶稣使徒的保罗，写信给住在以弗所，在基督耶稣里忠心的圣徒。'),
('CNV', '以弗所书', 49, 1, 2, '愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '以弗所书', 49, 1, 3, '我们主耶稣基督的父神是应当称颂的。他在基督里，曾经把天上各种属灵的福分赐给我们：'),
('CNV', '以弗所书', 49, 1, 4, '就如创立世界以前，他在基督里拣选了我们，使我们因着爱，在他面前成为圣洁，没有瑕疵。'),
('CNV', '以弗所书', 49, 1, 5, '他又按着自己旨意所喜悦的，预定我们藉着耶稣基督得儿子的名分，'),
('CNV', '以弗所书', 49, 1, 6, '好使他恩典的荣耀得着颂赞。这恩典是他在爱子里赐给我们的。'),
('CNV', '以弗所书', 49, 1, 7, '我们在他爱子里，藉着他的血蒙了救赎，过犯得到赦免，都是按着他丰盛的恩典。'),
('CNV', '以弗所书', 49, 1, 8, '这恩典是他用各样的智慧和聪明，充充足足地赐给我们的；'),
('CNV', '以弗所书', 49, 1, 9, '他照着自己在基督里预先安排的美意，使我们知道他旨意的奥秘，'),
('CNV', '以弗所书', 49, 1, 10, '到了所计划的时机成熟，就使天上地上的万有，都在基督里同归于一。'),
('CNV', '以弗所书', 49, 1, 11, '那凭着自己旨意所计划而行万事的，按着他预先所安排的，预定我们在基督里得基业（“得基业”或译：“成为神的产业”），'),
('CNV', '以弗所书', 49, 1, 12, '藉着我们这在基督里首先有盼望的人，使他的荣耀得着颂赞。'),
('CNV', '以弗所书', 49, 1, 13, '你们既然听了真理的道，就是使你们得救的福音，也信了基督，就在他里面受了所应许的圣灵作为印记。'),
('CNV', '以弗所书', 49, 1, 14, '这圣灵是我们得基业的凭据，直到神的产业得赎，使他的荣耀得着颂赞。'),
('CNV', '以弗所书', 49, 1, 15, '因此，我听到你们在主耶稣里的信心，和对众圣徒的爱心，'),
('CNV', '以弗所书', 49, 1, 16, '就不住地为你们献上感谢。我祷告的时候，常常提到你们，'),
('CNV', '以弗所书', 49, 1, 17, '求我们主耶稣基督的神，荣耀的父，赐给你们智慧和启示的灵，使你们充分地认识他，'),
('CNV', '以弗所书', 49, 1, 18, '并且使你们心灵的眼睛明亮，可以知道他的呼召有怎样的盼望；他基业的荣耀，在圣徒中是多么的丰盛；')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '以弗所书', 49, 1, 19, '神照着他强大的力量，向我们信他的人显出的能力，是何等的浩大。'),
('CNV', '以弗所书', 49, 1, 20, '这力量运行在基督身上，使他从死人中复活，并且在天上坐在自己的右边，'),
('CNV', '以弗所书', 49, 1, 21, '远超过一切执政的、掌权的、有能的、作主的，和今生来世所能举出的一切名衔。'),
('CNV', '以弗所书', 49, 1, 22, '神又使万有都归服在他的脚下，并且赐他给教会作万有的元首。'),
('CNV', '以弗所书', 49, 1, 23, '教会是他的身体，是那充满万有者所完全充满的。'),
('CNV', '以弗所书', 49, 2, 1, '你们因着自己的过犯和罪恶，原是死的。'),
('CNV', '以弗所书', 49, 2, 2, '那时你们在过犯和罪恶中行事为人，随着时代的潮流，也服从空中掌权的首领，就是现今在悖逆的人身上运行的灵。'),
('CNV', '以弗所书', 49, 2, 3, '我们从前也都和他们在一起，放纵肉体的私欲，随着肉体和心意所喜好的去行；我们与别人一样，生来都是可怒的儿女。'),
('CNV', '以弗所书', 49, 2, 4, '然而神满有怜悯，因着他爱我们的大爱，'),
('CNV', '以弗所书', 49, 2, 5, '就在我们因过犯死了的时候，使我们与基督一同活过来，（你们得救是靠着恩典，）'),
('CNV', '以弗所书', 49, 2, 6, '又使我们在基督耶稣里，与他一同复活，一同坐在天上，'),
('CNV', '以弗所书', 49, 2, 7, '为的是要在将来的世代中，显明他在基督耶稣里赐给我们的恩典，是多么的丰盛。'),
('CNV', '以弗所书', 49, 2, 8, '你们得救是靠着恩典，藉着信心。这不是出于自己，而是神所赐的；'),
('CNV', '以弗所书', 49, 2, 9, '这也不是出于行为，免得有人自夸。'),
('CNV', '以弗所书', 49, 2, 10, '我们原是神所作成的，是在基督耶稣里创造的，为的是要我们行各样的善事，就是神预先所安排的。'),
('CNV', '以弗所书', 49, 2, 11, '你们应当记得，你们从前按肉体来说是外族人；那些所谓在肉体上受过人手所行的割礼的人，称你们为未受割礼的。'),
('CNV', '以弗所书', 49, 2, 12, '那时，你们是在基督以外，与以色列国无分，在带有应许的约上是外人，在世上没有盼望，没有神。'),
('CNV', '以弗所书', 49, 2, 13, '你们从前远离的人，现今在基督耶稣里，靠着他的血已经可以亲近了。'),
('CNV', '以弗所书', 49, 2, 14, '基督就是我们的和平：他使双方合而为一，拆毁了隔在中间的墙，就是以自己的身体除掉双方的仇恨，'),
('CNV', '以弗所书', 49, 2, 15, '并且废掉了律法的规条，使两者在他里面成为一个新人，这样就缔造了和平。'),
('CNV', '以弗所书', 49, 2, 16, '基督既然藉着十字架消灭了仇恨，就藉着十字架使双方与神和好，成为一体，'),
('CNV', '以弗所书', 49, 2, 17, '并且他来把和平的福音传给你们在远处的人，也给在近处的人。'),
('CNV', '以弗所书', 49, 2, 18, '我们双方都藉着他，在同一位圣灵里，可以进到父面前。'),
('CNV', '以弗所书', 49, 2, 19, '这样看来，你们不再是外人和客旅，而是与圣徒一同作国民，是神家里的人了，'),
('CNV', '以弗所书', 49, 2, 20, '并且建造在使徒和先知的根基上，基督耶稣自己就是奠基石，'),
('CNV', '以弗所书', 49, 2, 21, '整座建筑都靠着他连接配合，渐渐增长成为在主里面的圣所。'),
('CNV', '以弗所书', 49, 2, 22, '你们在他里面也一同被建造，成为神藉着圣灵居住的所在。'),
('CNV', '以弗所书', 49, 3, 1, '因此，我这为你们外族人的缘故，作了为基督耶稣被囚禁的保罗，为你们祈求─'),
('CNV', '以弗所书', 49, 3, 2, '想必你们听过神恩惠的计划，他为你们的缘故赐恩给我，'),
('CNV', '以弗所书', 49, 3, 3, '藉着启示使我可以知道这奥秘，就像我以前在信中略略提过的。'),
('CNV', '以弗所书', 49, 3, 4, '你们读了，就可以知道我深深地明白基督的奥秘。'),
('CNV', '以弗所书', 49, 3, 5, '这奥秘在以前的世代并没有让世人知道，不像现在藉着圣灵启示了圣使徒和先知那样。'),
('CNV', '以弗所书', 49, 3, 6, '这奥秘就是外族人在基督耶稣里，藉着福音可以同作后嗣，同为一体，同蒙应许。'),
('CNV', '以弗所书', 49, 3, 7, '我作了福音的仆役，是照着神的恩赐（“恩赐”或译：“恩赏”）；这恩赐是按着他大能的作为赐给我的。'),
('CNV', '以弗所书', 49, 3, 8, '我本来比圣徒中最小的还小，神还是赐给我这恩典，要我把基督那测不透的丰富传给外族人，'),
('CNV', '以弗所书', 49, 3, 9, '并且使众人明白那奥秘的救世计划是什么（这奥秘是历代以来隐藏在创造万有的神里面的），'),
('CNV', '以弗所书', 49, 3, 10, '为了要使天上执政的和掌权的，现在藉着教会都可以知道神各样的智慧。'),
('CNV', '以弗所书', 49, 3, 11, '这都是照着神在我们主基督耶稣里所成就的永恒的旨意。'),
('CNV', '以弗所书', 49, 3, 12, '我们因信基督，就在他里面坦然无惧，满有把握地进到神面前。'),
('CNV', '以弗所书', 49, 3, 13, '因此，我恳求你们，不要因着我为你们所受的苦难而沮丧，这原是你们的光荣。'),
('CNV', '以弗所书', 49, 3, 14, '因此，我在父面前屈膝，'),
('CNV', '以弗所书', 49, 3, 15, '（天上地上所有的家族都是由他命名的，）'),
('CNV', '以弗所书', 49, 3, 16, '求他按着他荣耀的丰盛，藉着他的灵，用大能使你们内在的人刚强起来，'),
('CNV', '以弗所书', 49, 3, 17, '使基督藉着你们的信，住在你们心里，使你们既然在爱中扎根建基，'),
('CNV', '以弗所书', 49, 3, 18, '就能和众圣徒一同领悟基督的爱是多么的长阔高深，'),
('CNV', '以弗所书', 49, 3, 19, '并且知道他的爱是超过人所能理解的，使你们被充满，得着神的一切丰盛。'),
('CNV', '以弗所书', 49, 3, 20, '愿荣耀归给神，就是归给那能照着运行在我们里面的大能，充充足足地成就一切，超过我们所求所想的。'),
('CNV', '以弗所书', 49, 3, 21, '愿荣耀在教会中和基督耶稣里归给他，直到万代，永世无穷。阿们。'),
('CNV', '以弗所书', 49, 4, 1, '因此，我这为主被囚禁的劝你们：行事为人，要配得上你们所蒙的呼召，'),
('CNV', '以弗所书', 49, 4, 2, '凡事谦虚、温柔、忍耐，用爱心彼此宽容；'),
('CNV', '以弗所书', 49, 4, 3, '以和睦联系，竭力持守圣灵所赐的合一。'),
('CNV', '以弗所书', 49, 4, 4, '身体只有一个，圣灵只有一位，就像你们蒙召只是藉着一个盼望。'),
('CNV', '以弗所书', 49, 4, 5, '主只有一位，信仰只有一个，洗礼只有一种；'),
('CNV', '以弗所书', 49, 4, 6, '神只有一位，就是万有的父。他超越万有，贯彻万有，并且在万有之中。'),
('CNV', '以弗所书', 49, 4, 7, '我们各人蒙恩，是照着基督量给我们的恩赐。'),
('CNV', '以弗所书', 49, 4, 8, '所以他说：“他升上高天的时候，掳了许多俘虏，把赏赐给了人。”'),
('CNV', '以弗所书', 49, 4, 9, '（“他升上”这句话是什么意思呢？他不是也曾降到地上吗？'),
('CNV', '以弗所书', 49, 4, 10, '那降下的，就是那升到诸天之上的，为了要使他充满万有。）'),
('CNV', '以弗所书', 49, 4, 11, '他所赐的，有作使徒的，有作先知的，有作传福音的，也有作牧养和教导的，'),
('CNV', '以弗所书', 49, 4, 12, '为的是要装备圣徒，去承担圣工，建立基督的身体；'),
('CNV', '以弗所书', 49, 4, 13, '直到我们众人对神的儿子都有一致的信仰和认识，可以长大成人，达到基督丰盛长成的身量；'),
('CNV', '以弗所书', 49, 4, 14, '使我们不再作小孩子，中了人的诡计和骗人的手段，给异教之风摇撼，飘来飘去，'),
('CNV', '以弗所书', 49, 4, 15, '却要在爱中过诚实的生活，在各方面长进，达到基督的身量。他是教会的头，'),
('CNV', '以弗所书', 49, 4, 16, '全身靠着他，藉着每一个关节的支持，照着每部分的功用，配合联系起来，使身体渐渐长大，在爱中建立自己。'),
('CNV', '以弗所书', 49, 4, 17, '所以，我要这样说，并且要在主里肯定地说：你们行事为人不要再像教外人，存着虚妄的意念。'),
('CNV', '以弗所书', 49, 4, 18, '他们的心思昏昧，因为自己无知，心里刚硬，就与神所赐的生命隔绝了。'),
('CNV', '以弗所书', 49, 4, 19, '他们既然麻木不仁，就任凭自己放纵情欲，贪行各样污秽的事。'),
('CNV', '以弗所书', 49, 4, 20, '但是你们从基督所学的，却不是这样。'),
('CNV', '以弗所书', 49, 4, 21, '如果你们听了他，在他里面受过教导，（因为真理是在耶稣里的，）'),
('CNV', '以弗所书', 49, 4, 22, '就要除去你们那照着从前生活方式而活的旧人。这旧人是随着迷惑人的私欲渐渐败坏的。'),
('CNV', '以弗所书', 49, 4, 23, '你们要把心灵更换一新，'),
('CNV', '以弗所书', 49, 4, 24, '并且穿上新人。这新人是照着神的形象，在公义和真实的圣洁里创造的。'),
('CNV', '以弗所书', 49, 4, 25, '所以，你们要除掉谎言，各人要与邻舍说真话，因为我们彼此是肢体。'),
('CNV', '以弗所书', 49, 4, 26, '生气却不要犯罪；含怒不可到日落。'),
('CNV', '以弗所书', 49, 4, 27, '不可给魔鬼留地步。'),
('CNV', '以弗所书', 49, 4, 28, '偷窃的，不要再偷，却要作工，亲手作正当的事，使自己可以把所得到的，分给缺乏的人。'),
('CNV', '以弗所书', 49, 4, 29, '一句坏话也不可出口，却要适当地说造就人的好话，使听见的人得益处。'),
('CNV', '以弗所书', 49, 4, 30, '不可让神的圣灵忧伤，因为你们受了他的印记，等候得赎的日子。'),
('CNV', '以弗所书', 49, 4, 31, '一切苛刻、恼怒、暴戾、嚷闹、毁谤，连同一切恶毒，都应当从你们中间除掉。'),
('CNV', '以弗所书', 49, 4, 32, '要互相友爱，存温柔的心，彼此饶恕，就像神在基督里饶恕了你们一样。'),
('CNV', '以弗所书', 49, 5, 1, '因此，你们既然是蒙爱的儿女，就应当效法神。'),
('CNV', '以弗所书', 49, 5, 2, '要凭着爱心行事，好像基督爱我们，为我们舍己，当作馨香的供品和祭物献给神。'),
('CNV', '以弗所书', 49, 5, 3, '至于淫乱和任何污秽或贪心的事，在你们中间连提都不可提，才合圣徒的体统。'),
('CNV', '以弗所书', 49, 5, 4, '更不要讲淫秽和愚妄的话，或下流的笑话，这些都与你们不相称；却要说感谢的话。'),
('CNV', '以弗所书', 49, 5, 5, '因为你们确实知道，无论是淫乱的、污秽的或贪心的（贪心就是拜偶像），都得不到在基督和神的国里的基业。'),
('CNV', '以弗所书', 49, 5, 6, '不要给别人用空言欺骗了你们，正因为这些事，神的震怒必定临到那些悖逆的人。'),
('CNV', '以弗所书', 49, 5, 7, '所以，不要与他们同流合污。'),
('CNV', '以弗所书', 49, 5, 8, '你们从前是黑暗的，现今在主里却是光明的，行事为人就应当像光明的儿女。'),
('CNV', '以弗所书', 49, 5, 9, '光明所结的果子，就是一切良善、公义、诚实。'),
('CNV', '以弗所书', 49, 5, 10, '你们要察验什么是主所喜悦的。'),
('CNV', '以弗所书', 49, 5, 11, '不要参与暗昧无益的事，倒要把它揭露出来，'),
('CNV', '以弗所书', 49, 5, 12, '因为他们暗中所作的事，连提起来也是羞耻的。'),
('CNV', '以弗所书', 49, 5, 13, '凡被光揭露的，都是显而易见的。'),
('CNV', '以弗所书', 49, 5, 14, '因为一切显露出来的就是光，所以有话说：“睡了的人哪，醒过来，从死人中起来吧！基督必要照亮你。”'),
('CNV', '以弗所书', 49, 5, 15, '所以，你们行事为人要谨慎，不要像愚昧人，却要像聪明人。'),
('CNV', '以弗所书', 49, 5, 16, '要把握时机，因为这时代邪恶。'),
('CNV', '以弗所书', 49, 5, 17, '因此，不要作糊涂人，要明白什么是主的旨意。'),
('CNV', '以弗所书', 49, 5, 18, '不要醉酒，醉酒能使人放荡乱性，却要让圣灵充满。'),
('CNV', '以弗所书', 49, 5, 19, '应当用诗章、圣诗、灵歌，彼此呼应，口唱心和地赞美主。'),
('CNV', '以弗所书', 49, 5, 20, '凡事要奉我们主耶稣基督的名，常常感谢父神，'),
('CNV', '以弗所书', 49, 5, 21, '还要存敬畏基督的心，彼此顺服。'),
('CNV', '以弗所书', 49, 5, 22, '你们作妻子的，要顺服自己的丈夫，好像顺服主一样，'),
('CNV', '以弗所书', 49, 5, 23, '因为丈夫是妻子的头，好像基督是教会的头；基督又是教会全体的救主。'),
('CNV', '以弗所书', 49, 5, 24, '教会怎样顺服基督，妻子也要照样凡事顺服丈夫。'),
('CNV', '以弗所书', 49, 5, 25, '你们作丈夫的，要爱妻子，好像基督爱教会，为教会舍己，'),
('CNV', '以弗所书', 49, 5, 26, '为的是要用水藉着道把教会洗净，成为圣洁，'),
('CNV', '以弗所书', 49, 5, 27, '可以作荣耀的教会归给自己，什么污点皱纹等也没有，而是圣洁没有瑕疵的。'),
('CNV', '以弗所书', 49, 5, 28, '丈夫也应当这样爱妻子，好像爱自己的身体一样。爱妻子的，就是爱自己了。'),
('CNV', '以弗所书', 49, 5, 29, '从来没有人恨恶自己的身体，总是保养顾惜，好像基督对教会一样，'),
('CNV', '以弗所书', 49, 5, 30, '因为我们是他身上的肢体。'),
('CNV', '以弗所书', 49, 5, 31, '为了这缘故，人要离开父母，与妻子结合，二人成为一体。'),
('CNV', '以弗所书', 49, 5, 32, '这是极大的奥秘，但我是指着基督和教会说的。'),
('CNV', '以弗所书', 49, 5, 33, '无论怎样，你们各人都要爱自己的妻子，好像爱自己一样。妻子也应当敬重丈夫。'),
('CNV', '以弗所书', 49, 6, 1, '你们作儿女的，要在主里听从父母，因为这是理所当然的。'),
('CNV', '以弗所书', 49, 6, 2, '“要孝敬父母，使你得福，在世长寿。”这是第一条带着应许的诫命。'),
('CNV', '以弗所书', 49, 6, 4, '你们作父亲的，不要激怒儿女，却要照着主的教训和劝戒，养育他们。'),
('CNV', '以弗所书', 49, 6, 5, '你们作仆人的，要存着敬畏、战兢和真诚的心，听从世上的主人，好像听从基督一样。'),
('CNV', '以弗所书', 49, 6, 6, '作事不要只作给人看，像那些讨人欢心的一样，却要像基督的仆人，从心里遵行神的旨意，'),
('CNV', '以弗所书', 49, 6, 7, '甘心服务，象是服事主，不是服事人。'),
('CNV', '以弗所书', 49, 6, 8, '你们知道，无论是奴仆或自由的人，如果作了什么善事，都必从主那里得到赏赐。'),
('CNV', '以弗所书', 49, 6, 9, '你们作主人的，也要照样对待奴仆，不要威吓他们；你们知道，他们和你们在天上同有一位主，他并不偏待人。'),
('CNV', '以弗所书', 49, 6, 10, '最后，你们要靠主的大能大力，在他里面刚强。'),
('CNV', '以弗所书', 49, 6, 11, '要穿戴神所赐的全副军装，使你们能抵挡魔鬼的诡计。'),
('CNV', '以弗所书', 49, 6, 12, '因为我们的争战，对抗的不是有血有肉的人，而是执政的、掌权的、管辖这黑暗世界的和天上的邪灵。'),
('CNV', '以弗所书', 49, 6, 13, '所以要穿起神所赐的全副军装，使你们在这邪恶的时代里可以抵挡得住，并且在作完了一切之后，还能站立得稳。'),
('CNV', '以弗所书', 49, 6, 14, '因此，你们要站稳，用真理当带子束腰，披上公义的胸甲，'),
('CNV', '以弗所书', 49, 6, 15, '把和平的福音预备好了，当作鞋子，穿在脚上，'),
('CNV', '以弗所书', 49, 6, 16, '拿起信心的盾牌，用来扑灭那恶者所有的火箭；'),
('CNV', '以弗所书', 49, 6, 17, '并且要戴上救恩的头盔，拿起圣灵的宝剑，就是神的道，'),
('CNV', '以弗所书', 49, 6, 18, '藉着各样的祷告和祈求，随时在圣灵里祈祷，并且要在这事上恒久警醒，为众圣徒祈求。'),
('CNV', '以弗所书', 49, 6, 19, '也要为我祈求，使我传讲的时候，得着当说的话，可以坦然无惧地讲明福音的奥秘，'),
('CNV', '以弗所书', 49, 6, 20, '（我为这奥秘作了被捆锁的使者），也使我按着应当说的，放胆宣讲这福音的奥秘。'),
('CNV', '以弗所书', 49, 6, 21, '亲爱的推基古弟兄是主里忠心的仆人，他会把我的一切都告诉你们，使你们可以知道我的景况。'),
('CNV', '以弗所书', 49, 6, 22, '为了这缘故，我就差他到你们那里去，好让你们明白我们的近况，并且叫他安慰你们的心。'),
('CNV', '以弗所书', 49, 6, 23, '愿平安、慈爱、信心，从父神和主耶稣基督临到众弟兄。'),
('CNV', '以弗所书', 49, 6, 24, '愿一切以不朽的爱爱我们主耶稣基督的人，都蒙恩惠。'),
('CNV', '腓立比书', 50, 1, 1, '基督耶稣的仆人保罗和提摩太，写信给所有住在腓立比，在基督耶稣里的圣徒、监督和执事。'),
('CNV', '腓立比书', 50, 1, 2, '愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '腓立比书', 50, 1, 3, '我每逢想到你们，就感谢我的神；'),
('CNV', '腓立比书', 50, 1, 4, '每次为你们大家祈求的时候，总是欢欢喜喜地祈求。'),
('CNV', '腓立比书', 50, 1, 5, '为了你们从头一天直到现在都在福音的事工上有分，我就感谢我的神。'),
('CNV', '腓立比书', 50, 1, 6, '我深信那在你们中间开始了美好工作的，到了基督耶稣的日子，必成全这工作。'),
('CNV', '腓立比书', 50, 1, 7, '为你们众人我有这样的思想是很恰当的，因为你们常常在我的心里，无论我是在捆锁之中，或是在辩护和证实福音的时候，你们都和我一同分享神的恩典。'),
('CNV', '腓立比书', 50, 1, 8, '我是怎样以基督耶稣的心肠，切切地想念你们众人，这是神可以为我作证的。'),
('CNV', '腓立比书', 50, 1, 9, '我所祷告的，是要你们的爱心，在充足的知识和各样的见识上，多而又多，'),
('CNV', '腓立比书', 50, 1, 10, '使你们可以辨别是非，成为真诚无可指摘的人，直到基督的日子，'),
('CNV', '腓立比书', 50, 1, 11, '靠着耶稣基督结满了公义的果子，使神得着荣耀和赞美。'),
('CNV', '腓立比书', 50, 1, 12, '弟兄们，我愿意你们知道，我所遭遇的反而使福音更加兴旺了，'),
('CNV', '腓立比书', 50, 1, 13, '以致整个宫里的卫队和其余一切的人，都知道我是为了基督才受捆锁的；'),
('CNV', '腓立比书', 50, 1, 14, '而且大多数主内的弟兄，因我所受的捆锁，就笃信不疑，毫无畏惧，更勇敢地传讲神的道。'),
('CNV', '腓立比书', 50, 1, 15, '有些人传扬基督是出于嫉妒和纷争，但也有些人是出于好意。'),
('CNV', '腓立比书', 50, 1, 16, '这些人是出于爱心，知道我是派来为福音辩护的。'),
('CNV', '腓立比书', 50, 1, 17, '那些人传讲基督却是出于自私，动机并不纯正，只想加重我在捆锁中的烦恼。'),
('CNV', '腓立比书', 50, 1, 18, '那有什么关系呢？真心也好，假意也好，无论怎么样，基督总被传开了，为此我就欢喜；并且我还要欢喜，'),
('CNV', '腓立比书', 50, 1, 19, '因为我知道，藉着你们的祈求和耶稣基督的灵的帮助，我一定会得到释放。'),
('CNV', '腓立比书', 50, 1, 20, '我所热切期待和盼望的，就是在凡事上我都不会羞愧，只要满有胆量，不论生死，总要让基督在我身上照常被尊为大。'),
('CNV', '腓立比书', 50, 1, 21, '因为我活着就是基督，我死了就有益处。'),
('CNV', '腓立比书', 50, 1, 22, '但如果我仍在世上活着，能够使我的工作有成果，我就不知道应该怎样选择了！'),
('CNV', '腓立比书', 50, 1, 23, '我处于两难之间，情愿离世与基督同在，因为那是好得无比的。'),
('CNV', '腓立比书', 50, 1, 24, '可是为了你们，我更需要活在世上。'),
('CNV', '腓立比书', 50, 1, 25, '我既然这样深信，就知道还要活下去，并且要继续和你们大家在一起，使你们在信心上有长进，有喜乐，'),
('CNV', '腓立比书', 50, 1, 26, '以致你们因为我要再到你们那里去，就在基督耶稣里更加以我为荣。'),
('CNV', '腓立比书', 50, 1, 27, '不过，你们行事为人（“行事为人”原文也可译作“作公民”）应当和基督的福音相配。这样，无论我来见你们或是不在你们中间，都可以听到你们的情况，就是你们有同一的心志，站立得稳，为了福音的信仰齐心努力，'),
('CNV', '腓立比书', 50, 1, 28, '什么事都不怕有反对你们的人，这就证明他们要灭亡，你们要得救，这都是出于神。'),
('CNV', '腓立比书', 50, 1, 29, '因为神为了基督的缘故赐恩给你们，使你们不单是信基督，也是要为他受苦；'),
('CNV', '腓立比书', 50, 1, 30, '你们面对的争战，和你们在我身上所见过，现在又听到的是一样的。'),
('CNV', '腓立比书', 50, 2, 1, '所以，你们在基督里若有什么鼓励，有什么爱心的安慰，有什么灵里的契通，有什么慈悲和怜悯，'),
('CNV', '腓立比书', 50, 2, 2, '就应当有同样的思想，同样的爱心，要心志相同，思想一致，使我充满喜乐。'),
('CNV', '腓立比书', 50, 2, 3, '不要自私自利，也不要贪图虚荣，只要谦卑，看别人比自己强；'),
('CNV', '腓立比书', 50, 2, 4, '各人不要单顾自己的事，也要顾别人的事。'),
('CNV', '腓立比书', 50, 2, 5, '你们应当有这样的思想，这也是基督耶稣的思想。（全节或译：“你们当以基督耶稣的心为心。”）'),
('CNV', '腓立比书', 50, 2, 6, '他本来有神的形象，却不坚持自己与神平等的地位，'),
('CNV', '腓立比书', 50, 2, 7, '反而倒空自己，取了奴仆的形象，成为人的样式；'),
('CNV', '腓立比书', 50, 2, 8, '既然有人的样子，就自甘卑微，顺服至死，而且死在十字架上。'),
('CNV', '腓立比书', 50, 2, 9, '因此神把他升为至高，并且赐给他超过万名之上的名。'),
('CNV', '腓立比书', 50, 2, 10, '使天上、地上和地底下的一切，因着耶稣的名，都要屈膝，'),
('CNV', '腓立比书', 50, 2, 11, '并且口里承认耶稣基督为主，使荣耀归给父神。'),
('CNV', '腓立比书', 50, 2, 12, '这样看来，我所亲爱的，你们素来是顺服的，（不但我在你们那里的时候是这样，现今我不在，你们更要顺服，）就应当恐惧战兢地作成自己的救恩。'),
('CNV', '腓立比书', 50, 2, 13, '神为了成全自己的美意，就在你们里面动工，使你们可以立志和行事。'),
('CNV', '腓立比书', 50, 2, 14, '无论作什么，都不要发怨言、起争论，'),
('CNV', '腓立比书', 50, 2, 15, '好使你们无可指摘、纯真无邪，在这弯曲乖谬的世代中，作神没有瑕疵的儿女；你们要在这世代中发光，好像天上的光体一样，'),
('CNV', '腓立比书', 50, 2, 16, '把生命的道显扬出来，使我在基督的日子可以夸耀我没有空跑，也没有徒劳。'),
('CNV', '腓立比书', 50, 2, 17, '即使把我浇奠在你们信心的祭物和供奉上，我也喜乐，并且和你们大家一同喜乐。'),
('CNV', '腓立比书', 50, 2, 18, '照样，你们也要喜乐，并且要和我一同喜乐。'),
('CNV', '腓立比书', 50, 2, 19, '我靠着主耶稣，希望不久就会差提摩太到你们那里去，使我们知道你们的情况，可以得到鼓励。'),
('CNV', '腓立比书', 50, 2, 20, '没有人与我同心，真正关心你们的事，'),
('CNV', '腓立比书', 50, 2, 21, '因为大家只顾自己的事，而不理耶稣基督的事。'),
('CNV', '腓立比书', 50, 2, 22, '不过，你们知道提摩太已证明了他的为人，他和我一同为了福音服事主，就像儿子跟父亲一样。'),
('CNV', '腓立比书', 50, 2, 23, '所以，等我看出自己的事会怎样了结之后，我希望立刻差他去；'),
('CNV', '腓立比书', 50, 2, 24, '而且靠着主，我相信自己不久也会去。'),
('CNV', '腓立比书', 50, 2, 25, '然而我认为必须差以巴弗提到你们那里去，他是我的弟兄，与我一同作工一同作战的，也是你们为我的需要差来服事我的。'),
('CNV', '腓立比书', 50, 2, 26, '他一直在想念你们众人，并且因为你们听见他病了，他就非常难过。'),
('CNV', '腓立比书', 50, 2, 27, '事实上他病得几乎要死，然而神怜悯了他；不但怜悯他，也怜悯我，免得我忧上加忧。'),
('CNV', '腓立比书', 50, 2, 28, '所以，我更急着差他去，让你们再见到他，就可以喜乐，也可以减少我的挂虑。'),
('CNV', '腓立比书', 50, 2, 29, '因此，你们要在主里欢欢喜喜地接待他，也要尊重这样的人，'),
('CNV', '腓立比书', 50, 2, 30, '因他为了基督的工作，冒着生命的危险，差一点丧了命，为的是要补满你们服事我不足的地方。'),
('CNV', '腓立比书', 50, 3, 1, '最后，我的弟兄们，你们要靠着主喜乐。我写这些话给你们，在我并不困难，对你们却是妥当的。'),
('CNV', '腓立比书', 50, 3, 2, '你们要提防那些“狗”，提防作恶的，提防行割礼的。'),
('CNV', '腓立比书', 50, 3, 3, '其实我们这些靠神的灵来敬拜，在基督耶稣里夸口而不倚靠肉体的人，才是受割礼的，'),
('CNV', '腓立比书', 50, 3, 4, '虽然我有理由可以倚靠肉体。如果别人认为可以倚靠肉体，我就更加可以了；'),
('CNV', '腓立比书', 50, 3, 5, '我第八天受割礼，属于以色列民族便雅悯支派，是希伯来人所生的希伯来人。按着律法来说，我是个法利赛人；'),
('CNV', '腓立比书', 50, 3, 6, '按着热诚来说，我是迫害教会的；按着律法上的义来说，我是无可指摘的。'),
('CNV', '腓立比书', 50, 3, 7, '然而以前对我有益的，现在因着基督的缘故，我都当作是有损的。'),
('CNV', '腓立比书', 50, 3, 8, '不但这样，我也把万事当作是有损的，因为我以认识我主基督耶稣为至宝。为了他，我把万事都抛弃了，看作废物，为了要得着基督。'),
('CNV', '腓立比书', 50, 3, 9, '并且得以在他里面，不是有自己因律法而得的义，而是有因信基督而得的义，就是基于信心，从神而来的义，'),
('CNV', '腓立比书', 50, 3, 10, '使我认识基督和他复活的大能，并且在他所受的苦上有分，受他所受的死；'),
('CNV', '腓立比书', 50, 3, 11, '这样，我也许可以从死人中复活。'),
('CNV', '腓立比书', 50, 3, 12, '这并不是说我已经得着了，已经完全了，而是竭力追求，好使我可以得着基督耶稣所以得着我的（“所以得着我的”或译：“要我得着的”）。'),
('CNV', '腓立比书', 50, 3, 13, '弟兄们，我不以为自己已经得着了，我只有一件事，就是忘记背后，努力前面的事，'),
('CNV', '腓立比书', 50, 3, 14, '向着目标竭力追求，为要得着神在基督耶稣里召我往上去得的奖赏。'),
('CNV', '腓立比书', 50, 3, 15, '所以，我们中间凡是成熟的人，都应当这样思想。即使你们不是这样思想，神也会把这事指示你们。'),
('CNV', '腓立比书', 50, 3, 16, '不过，我们到了什么程度，就要照着什么程度去行。'),
('CNV', '腓立比书', 50, 3, 17, '弟兄们，你们要一同效法我，也要留意那些照着我们给你们的榜样而行的人。'),
('CNV', '腓立比书', 50, 3, 18, '我常常告诉你们，现在又流着泪说，有许多人行事为人，是基督十字架的仇敌，'),
('CNV', '腓立比书', 50, 3, 19, '他们的结局是灭亡，他们的神是自己的肚腹，他们以自己的羞辱为荣耀，所思想的都是地上的事。'),
('CNV', '腓立比书', 50, 3, 20, '但我们是天上的公民，切望救主，就是主耶稣基督，从天上降临；'),
('CNV', '腓立比书', 50, 3, 21, '他要运用那使万有归服自己的大能，改变我们这卑贱的身体，和他荣耀的身体相似。'),
('CNV', '腓立比书', 50, 4, 1, '我所想念亲爱的弟兄们，你们就是我的喜乐、我的冠冕。所以，亲爱的，你们应当靠着主站立得稳。'),
('CNV', '腓立比书', 50, 4, 2, '我劝友阿嫡，也劝循都基，要在主里有同样的思想。'),
('CNV', '腓立比书', 50, 4, 3, '我真诚的同道啊，我也求你帮助她们。这两个女人，还有革利免和其余的同工，都跟我在福音的事工上一同劳苦，他们的名字都在生命册上。'),
('CNV', '腓立比书', 50, 4, 4, '你们要靠着主常常喜乐，我再说，你们要喜乐。'),
('CNV', '腓立比书', 50, 4, 5, '要使大家看出你们谦和的心。主已经近了。'),
('CNV', '腓立比书', 50, 4, 6, '应当毫无忧虑，只要凡事藉着祷告祈求，带着感恩的心，把你们所要的告诉神。'),
('CNV', '腓立比书', 50, 4, 7, '这样，神所赐超过人能了解的平安，必在基督耶稣里，保守你们的心思意念。'),
('CNV', '腓立比书', 50, 4, 8, '最后，弟兄们，凡是真实的、庄重的、公正的、纯洁的、可爱的、声誉好的，无论是什么美德，什么称赞，这些事你们都应当思念。'),
('CNV', '腓立比书', 50, 4, 9, '你们在我身上所学习、所领受、所听见、所看见的，这些事你们都应当实行；那么，赐平安的神就必与你们同在。'),
('CNV', '腓立比书', 50, 4, 10, '我在主里大大地喜乐，因为你们现在又再想起我来；其实你们一向都在想念我，只是没有机会表示。'),
('CNV', '腓立比书', 50, 4, 11, '我并不是因为缺乏才这样说：我已经学会了，无论在什么情况之下都可以知足。'),
('CNV', '腓立比书', 50, 4, 12, '我知道怎样处卑贱，也知道怎样处富裕；我已经得了秘诀，无论在任何情况之下，或是饱足，或是饥饿，或是富裕，或是缺乏，都可以知足。'),
('CNV', '腓立比书', 50, 4, 13, '我靠着那加给我能力的，凡事都能作。'),
('CNV', '腓立比书', 50, 4, 14, '然而，你们一同分担了我的患难，实在是好的。'),
('CNV', '腓立比书', 50, 4, 15, '腓立比的弟兄们，你们也知道，在我传福音的初期，离开马其顿的时候，除了你们以外，我没有收过任何教会的供给。'),
('CNV', '腓立比书', 50, 4, 16, '我在帖撒罗尼迦的时候，你们还是一而再把我所需用的送来。'),
('CNV', '腓立比书', 50, 4, 17, '我并不求礼物，只求你们的果子不断增加，归在你们的帐上。'),
('CNV', '腓立比书', 50, 4, 18, '你们所送的我都全数收到了，而且绰绰有余；我已经足够了，因我从以巴弗提收到你们所送的，好像馨香之气，是神所接纳所喜悦的祭物。'),
('CNV', '腓立比书', 50, 4, 19, '我的神必照他在基督耶稣里荣耀的丰富，满足你们的一切需要。'),
('CNV', '腓立比书', 50, 4, 20, '愿荣耀归给我们的父神，直到永远。阿们。'),
('CNV', '腓立比书', 50, 4, 21, '问候在基督耶稣里的各位圣徒。同我在一起的弟兄们问候你们。'),
('CNV', '腓立比书', 50, 4, 22, '众圣徒，特别是凯撒家里的人，都问候你们。'),
('CNV', '腓立比书', 50, 4, 23, '愿主耶稣基督的恩惠与你们同在（“与你们同在”原文作“与你们的心灵同在”）。'),
('CNV', '歌罗西书', 51, 1, 1, '奉神旨意作基督耶稣使徒的保罗，和提摩太弟兄，'),
('CNV', '歌罗西书', 51, 1, 2, '写信给在歌罗西的圣徒，和在基督里忠心的弟兄。愿恩惠平安从我们的父神临到你们。'),
('CNV', '歌罗西书', 51, 1, 3, '我们为你们祈祷的时候，常常感谢神我们主耶稣基督的父，'),
('CNV', '歌罗西书', 51, 1, 4, '因为听见你们在基督耶稣里的信心，和对众圣徒的爱心。'),
('CNV', '歌罗西书', 51, 1, 5, '这都是由于那给你们存在天上的盼望，这盼望是你们从前在福音真理的道上听过的。'),
('CNV', '歌罗西书', 51, 1, 6, '这福音传到你们那里，也传到全世界；你们听了福音，因着真理确实认识了神的恩典之后，这福音就在你们中间不断地结果和增长，在全世界也是一样。'),
('CNV', '歌罗西书', 51, 1, 7, '这福音也就是你们从我们亲爱的、一同作仆人（“仆人”或译：“执事”）的以巴弗那里学到的。他为你们作了基督忠心的仆役，'),
('CNV', '歌罗西书', 51, 1, 8, '也把你们在圣灵里的爱心告诉了我们。'),
('CNV', '歌罗西书', 51, 1, 9, '因此，我们从听见的那天起，就不停地为你们祷告祈求，愿你们藉着一切属灵的智慧和悟性，可以充分明白神的旨意，'),
('CNV', '歌罗西书', 51, 1, 10, '使你们行事为人对得起主，凡事蒙他喜悦；在一切善事上多结果子，更加认识神；'),
('CNV', '歌罗西书', 51, 1, 11, '依照他荣耀的大能得着一切能力，带着喜乐的心，凡事忍耐宽容；'),
('CNV', '歌罗西书', 51, 1, 12, '并且感谢父，他使你们有资格分享圣徒在光明中的基业。'),
('CNV', '歌罗西书', 51, 1, 13, '他救我们脱离了黑暗的权势，把我们迁入他爱子的国里。'),
('CNV', '歌罗西书', 51, 1, 14, '我们在爱子里蒙了救赎，罪得赦免。'),
('CNV', '歌罗西书', 51, 1, 15, '这爱子是那看不见的神的形象，是首先的，在一切被造的之上。'),
('CNV', '歌罗西书', 51, 1, 16, '因为天上地上的万有：看得见的和看不见的，无论是坐王位的，或是作主的，或是执政的，或是掌权的，都是本着他造的；万有都是藉着他，又是为着他而造的。'),
('CNV', '歌罗西书', 51, 1, 17, '他在万有之先；万有也一同靠着他而存在。'),
('CNV', '歌罗西书', 51, 1, 18, '他是身体的头，这身体就是教会。他是元始，是死人中首先复生的，好让他在凡事上居首位；'),
('CNV', '歌罗西书', 51, 1, 19, '因为神乐意使所有的丰盛都住在爱子里面，'),
('CNV', '歌罗西书', 51, 1, 20, '并且藉着他在十字架上所流的血成就了和平，使万有，无论是地上天上的，都藉着他与神和好了。'),
('CNV', '歌罗西书', 51, 1, 21, '虽然你们从前也是和神隔绝，心思上与他为敌，行为邪恶，'),
('CNV', '歌罗西书', 51, 1, 22, '但现今神在爱子的肉身上，藉着他的死，使你们与神和好了，为了要把你们这些圣洁、无瑕疵、无可指摘的人，呈献在他面前。'),
('CNV', '歌罗西书', 51, 1, 23, '只是你们要常存信心，根基稳固，不受动摇偏离福音的盼望。这福音你们听过了，也传给了天下万民；我保罗也作了这福音的仆役。'),
('CNV', '歌罗西书', 51, 1, 24, '现在我为你们受苦，我觉得喜乐；为了基督的身体，就是为了教会，我要在自己的肉身上，补满基督苦难的不足。'),
('CNV', '歌罗西书', 51, 1, 25, '我照着神为你们而赐给我的管家职分，作了教会的仆役，要把神的道，就是历世历代隐藏的奥秘，传得完备。现在这奥秘已经向他的众圣徒显明了。'),
('CNV', '歌罗西书', 51, 1, 27, '神愿意使他们知道这奥秘在外族人中有多么荣耀的丰盛，这奥秘就是基督在你们里面成了荣耀的盼望。'),
('CNV', '歌罗西书', 51, 1, 28, '我们传扬他，是用各样的智慧，劝戒各人，教导各人，为了要使各人在基督里得到完全。'),
('CNV', '歌罗西书', 51, 1, 29, '我也为了这事劳苦，按着他用大能在我心中运行的动力，竭力奋斗。'),
('CNV', '歌罗西书', 51, 2, 1, '我愿意你们知道，我为你们和在老底嘉的人，以及所有没有跟我见过面的人，是怎样竭力奋斗，'),
('CNV', '歌罗西书', 51, 2, 2, '为的是要他们的心得着勉励，在爱中彼此联系，可以得着凭悟性、因确信而来的一切丰盛，也可以充分认识神的奥秘，这奥秘就是基督；'),
('CNV', '歌罗西书', 51, 2, 3, '一切智慧和知识的宝库都蕴藏在基督里面。'),
('CNV', '歌罗西书', 51, 2, 4, '我说这些话，免得有人用花言巧语欺骗你们。'),
('CNV', '歌罗西书', 51, 2, 5, '我虽然不在你们那里，心却与你们同在。我看见你们循规蹈矩，并且对基督有坚定的信心，就欢喜了。'),
('CNV', '歌罗西书', 51, 2, 6, '你们怎样接受了基督耶稣为主，就当照样在他里面行事为人，'),
('CNV', '歌罗西书', 51, 2, 7, '按着你们所领受的教导，在他里面扎根、建造，信心坚定，满有感谢的心。'),
('CNV', '歌罗西书', 51, 2, 8, '你们要谨慎，免得有人不照着基督，而照着人的传统，和世俗的言论，藉着哲学和骗人的空谈，把你们掳去。'),
('CNV', '歌罗西书', 51, 2, 9, '因为神本性的一切丰盛，都有形有体地住在基督里面，'),
('CNV', '歌罗西书', 51, 2, 10, '你们也是在他里面得了丰盛。他是一切执政掌权者的元首。'),
('CNV', '歌罗西书', 51, 2, 11, '你们也在他里面受了不是由人手所行的割礼，而是受了基督的割礼，就是除掉你们的罪身。'),
('CNV', '歌罗西书', 51, 2, 12, '你们在洗礼中已经与他一同埋葬，也在洗礼中，因信那使基督从死人中复活的神所运行的动力，与他一同复活了。'),
('CNV', '歌罗西书', 51, 2, 13, '你们因着过犯和肉体未受割礼，原是死的，然而神赦免了我们的一切过犯，使你们与基督一同活过来，'),
('CNV', '歌罗西书', 51, 2, 14, '涂抹了那写在规条上反对我们、与我们为敌的字句，并且把这字句从我们中间拿去，钉在十字架上。'),
('CNV', '歌罗西书', 51, 2, 15, '他既然靠着十字架胜过了一切执政掌权的，废除了他们的权势，就在凯旋的行列中，把他们公开示众。'),
('CNV', '歌罗西书', 51, 2, 16, '所以不要让人因着饮食、节期、月朔、安息日批评你们，'),
('CNV', '歌罗西书', 51, 2, 17, '这些不过是将来的事的影子，那真体却是属于基督的。'),
('CNV', '歌罗西书', 51, 2, 18, '不要让人夺去你们的奖赏，他们以故意谦卑，敬拜天使为乐；迷于自己所见过的；凭着肉体的意念，无故地自高自大；'),
('CNV', '歌罗西书', 51, 2, 19, '不与头紧密相连。其实全身都是藉着关节和筋络从头得着供应和联系，就照着神所要求的，生长起来。'),
('CNV', '歌罗西书', 51, 2, 20, '你们若与基督一同死了，脱离了世俗的言论，为什么仍然好像活在世俗中一样，拘守那“不可摸、不可尝、不可触”的规条呢？'),
('CNV', '歌罗西书', 51, 2, 22, '（这一切东西，一经使用，就都朽坏了。）这些规条是照着人的命令和教训而定的，'),
('CNV', '歌罗西书', 51, 2, 23, '在随着己意敬拜，故作谦卑，和苦待己身等事上，似乎是智慧之言，其实只能叫人放纵肉体，再没有任何价值。'),
('CNV', '歌罗西书', 51, 3, 1, '所以，你们既然与基督一同复活，就应当寻求天上的事，那里有基督坐在神的右边。'),
('CNV', '歌罗西书', 51, 3, 2, '你们要思念的，是天上的事，不是地上的事。'),
('CNV', '歌罗西书', 51, 3, 3, '因为你们已经死了，你们的生命与基督一同隐藏在神里面。'),
('CNV', '歌罗西书', 51, 3, 4, '基督就是你们的生命，他显现的时候，你们也要和他一同在荣耀里显现。'),
('CNV', '歌罗西书', 51, 3, 5, '所以要治死你们在地上的肢体，就如淫乱、污秽、邪情、恶欲和贪心，贪心就是拜偶像。'),
('CNV', '歌罗西书', 51, 3, 6, '因着这些事，神的忿怒必要临到悖逆的人（有些抄本无“悖逆的人”）。'),
('CNV', '歌罗西书', 51, 3, 7, '你们从前在其中生活的时候，也曾经这样行过。'),
('CNV', '歌罗西书', 51, 3, 8, '但现在你们要除去忿怒、恼怒、恶毒、毁谤，以及粗言秽语这一切事。'),
('CNV', '歌罗西书', 51, 3, 9, '不要彼此说谎，因为你们已经脱去了旧人和旧人的行为，'),
('CNV', '歌罗西书', 51, 3, 10, '穿上了新人。这新人照着他的创造者的形象渐渐更新，能够充分认识主。'),
('CNV', '歌罗西书', 51, 3, 11, '在这一方面，并不分希腊人和犹太人，受割礼的和未受割礼的，未开化的人和西古提人，奴隶和自由人，唯有基督是一切，也在一切之内。'),
('CNV', '歌罗西书', 51, 3, 12, '所以，你们既然是神所拣选的，是圣洁、蒙爱的人，就要存怜悯的心肠、恩慈、谦卑、温柔和忍耐。'),
('CNV', '歌罗西书', 51, 3, 13, '如果有人对别人有嫌隙，总要彼此宽容，互相饶恕；主怎样饶恕了你们，你们也要照样饶恕人。'),
('CNV', '歌罗西书', 51, 3, 14, '在这一切之上，还要有爱心，爱心是联系全德的。'),
('CNV', '歌罗西书', 51, 3, 15, '又要让基督的平安在你们心里作主；你们蒙召归为一体，也是为了这个缘故。你们要有感谢的心。'),
('CNV', '歌罗西书', 51, 3, 16, '你们要让基督的道丰丰富富地住在你们心里，以各样的智慧，彼此教导，互相劝戒，用诗章、圣诗、灵歌，怀着感恩的心歌颂神。'),
('CNV', '歌罗西书', 51, 3, 17, '凡你们所作的，无论是言语或行为，都要奉主耶稣的名，藉着他感谢父神。'),
('CNV', '歌罗西书', 51, 3, 18, '你们作妻子的，要顺服丈夫，这在主里是合宜的。'),
('CNV', '歌罗西书', 51, 3, 19, '你们作丈夫的，要爱妻子，不可苦待她们。'),
('CNV', '歌罗西书', 51, 3, 20, '你们作儿女的，要凡事听从父母，因为这在主里是可喜悦的。'),
('CNV', '歌罗西书', 51, 3, 21, '你们作父亲的，不要激怒儿女，免得他们灰心丧志。'),
('CNV', '歌罗西书', 51, 3, 22, '你们作仆人的，要凡事听从世上的主人，作事不要只作给人看，像那些讨人欢心的一样，却要以真诚的心敬畏主。'),
('CNV', '歌罗西书', 51, 3, 23, '无论你们作什么，都要从心里去作，象是为主作的，不是为人作的，'),
('CNV', '歌罗西书', 51, 3, 24, '因为你们知道，你们一定会从主那里得到基业为赏赐。你们应当服事主基督，'),
('CNV', '歌罗西书', 51, 3, 25, '但那些不义的人，必按他所行的不义受报应。主并不偏待人。'),
('CNV', '歌罗西书', 51, 4, 1, '你们作主人的，要公平地对待仆人，因为知道你们也有一位主在天上。'),
('CNV', '歌罗西书', 51, 4, 2, '你们要恒切祷告，在祷告的时候存着感恩的心警醒；'),
('CNV', '歌罗西书', 51, 4, 3, '也要为我们祷告，求神为我们开传道的门，宣讲基督的奥秘（我就是为了这个缘故被捆锁），'),
('CNV', '歌罗西书', 51, 4, 4, '使我照着我所应当说的，把这奥秘显明出来。'),
('CNV', '歌罗西书', 51, 4, 5, '你们要把握时机，用智慧与外人来往。'),
('CNV', '歌罗西书', 51, 4, 6, '你们的话要常常温和，好像是用盐调和的，使你们知道应当怎样回答各人。'),
('CNV', '歌罗西书', 51, 4, 7, '我的一切景况，推基古会告诉你们。他是我所爱的弟兄，是忠心的仆役，也是在主里同作仆人的。'),
('CNV', '歌罗西书', 51, 4, 8, '我派他到你们那里去，使你们知道我们的景况，并且安慰你们的心。'),
('CNV', '歌罗西书', 51, 4, 9, '他是跟欧尼西慕一同去的。欧尼西慕是忠心的亲爱的弟兄，是你们那里的人。他们会把这里的一切告诉你们。'),
('CNV', '歌罗西书', 51, 4, 10, '与我一同坐监的亚里达古，和巴拿巴的表弟马可，问候你们。（关于马可，你们已经受了吩咐：他若到你们那里，你们要接待他。）'),
('CNV', '歌罗西书', 51, 4, 11, '别号犹士都的耶数，也问候你们。在受过割礼的人中，只有这几位是为神的国与我同工的，他们也成了我的安慰。'),
('CNV', '歌罗西书', 51, 4, 12, '以巴弗问候你们，他是你们那里的人，是基督耶稣的仆人；他祷告的时候，常常竭力为你们祈求，好使你们在神的一切旨意中完全站稳，满有坚定的信念。'),
('CNV', '歌罗西书', 51, 4, 13, '我可以为他作证，他为了你们和在老底嘉、希拉波立的人，多受劳苦。'),
('CNV', '歌罗西书', 51, 4, 14, '亲爱的路加医生和底马问候你们。'),
('CNV', '歌罗西书', 51, 4, 15, '请问候在老底嘉的弟兄和宁法，以及在她家里的教会。'),
('CNV', '歌罗西书', 51, 4, 16, '这封信你们宣读了以后，也要交给老底嘉的教会宣读；你们也要读老底嘉的那封信。'),
('CNV', '歌罗西书', 51, 4, 17, '你们要对亚基布说：“你要留心在主里领受的职分，好把它完成。”'),
('CNV', '歌罗西书', 51, 4, 18, '我保罗亲笔问候你们。你们要记念我的捆锁。愿恩惠与你们同在。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 1, '保罗、西拉和提摩太，写信给帖撒罗尼迦、在父神和主耶稣基督里的教会。愿恩惠平安临到你们。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 2, '我们常常为你们众人感谢神，祷告的时候提到你们，'),
('CNV', '帖撒罗尼迦前书', 52, 1, 3, '在我们的父神面前，不住地记念你们信心的工作，爱心的劳苦和因盼望我们主耶稣基督而有的坚忍。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 4, '神所爱的弟兄们，我们知道你们是蒙拣选的，'),
('CNV', '帖撒罗尼迦前书', 52, 1, 5, '因为我们的福音传到你们那里，不单是藉着言语，也是藉着权能，藉着圣灵和充足的信心。为了你们的缘故，我们在你们中间为人怎样，这是你们知道的。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 6, '你们效法了我们，也效法了主，在大患难中，带着圣灵的喜乐接受了真道。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 7, '这样，你们就成了马其顿和亚该亚所有信徒的榜样。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 8, '因为不单主的道从你们那里传遍了马其顿和亚该亚，就是你们对神的信心也传遍了各处，所以我们不用再说什么了。'),
('CNV', '帖撒罗尼迦前书', 52, 1, 9, '他们都述说你们是怎样接待我们，而且怎样离弃偶像归向神，要服事这位又真又活的神，'),
('CNV', '帖撒罗尼迦前书', 52, 1, 10, '并且等候他的儿子从天降临。这就是神使他从死人中复活，救我们脱离将来的忿怒的那位耶稣。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 1, '弟兄们，你们都知道，我们进到你们那里，并不是白费工夫的。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 2, '我们从前在腓立比虽然受了苦，又被凌辱，可是靠着我们的神，在强烈的反对之下，仍然放胆向你们述说神的福音，这是你们知道的。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 3, '我们的呼吁，不是错谬的，不是污秽的，也没有诡诈。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 4, '相反地，神既然考验过我们，把福音委托给我们，我们就传讲，不象是讨人欢心的，而是讨那察验我们心思的神的喜悦。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 5, '我们从来不说奉承的话，这是你们知道的，神可以作证，我们并没有借故起贪心，'),
('CNV', '帖撒罗尼迦前书', 52, 2, 6, '也没有向你们或别人求取人的荣誉。我们身为基督使徒的，虽然有权利受人尊敬，但我们在你们中间却是谦和的，就像母亲乳养自己的孩子。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 8, '我们这样疼爱你们，不但乐意把神的福音传给你们，连自己的性命也乐意给你们，因为你们是我们所爱的。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 9, '弟兄们，你们应该记得我们的辛苦和劳碌；我们把神的福音传给你们的时候，怎样昼夜作工，免得你们有人受累。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 10, '我们对你们信的人是多么圣洁、公义、无可指摘，这是你们和神都可以作证的。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 11, '正如你们知道的，我们是怎样好像父亲对待儿女一样对待你们各人：'),
('CNV', '帖撒罗尼迦前书', 52, 2, 12, '劝勉你们，鼓励你们，叮嘱你们，要你们行事为人，配得上那召你们进入他的国和荣耀的神。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 13, '我们也为这缘故不住感谢神，因为你们接受了我们所传的神的道，不认为这是人的道，而认为这确实是神的道。这道也运行在你们信的人里面。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 14, '弟兄们，你们好像犹太地在基督耶稣里神的众教会一样，他们怎样遭受犹太人的迫害，你们也照样遭受同族人的迫害。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 15, '这些犹太人杀了主耶稣和众先知，又把我们赶出来。他们得不到神的喜悦，并且和所有的人作对，'),
('CNV', '帖撒罗尼迦前书', 52, 2, 16, '阻挠我们向外族人传道，不让他们得救，以致恶贯满盈。神的忿怒终必临到他们身上。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 17, '弟兄们，我们被迫暂时离开你们，不过是身体离开，心却没有离开。我们非常渴望再见到你们。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 18, '因此，我们很想到你们那里去，我保罗也一再想去，只是撒但阻挡了我们。'),
('CNV', '帖撒罗尼迦前书', 52, 2, 19, '我们主耶稣再来的时候，我们在他面前的盼望、喜乐或所夸耀的冠冕是什么呢？不就是你们吗？'),
('CNV', '帖撒罗尼迦前书', 52, 2, 20, '是的，你们就是我们的荣耀，我们的喜乐。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 1, '我们既然不能再忍下去，就决定留在雅典，'),
('CNV', '帖撒罗尼迦前书', 52, 3, 2, '派我们的弟兄，就是在基督的福音上和神同工的提摩太去，为了要在你们的信仰上坚定你们，劝慰你们，'),
('CNV', '帖撒罗尼迦前书', 52, 3, 3, '免得有人在各样的患难中动摇了。你们自己知道，我们受患难原是命定的。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 4, '我们在你们那里的时候，早已对你们说过，我们将会遭受患难。后来应验了，这是你们知道的。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 5, '因此，我既然不能再忍下去，就派人去打听你们的信心怎样；恐怕那试探人的诱惑了你们，以致我们的劳苦白费了。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 6, '提摩太刚刚从你们那里回来，把你们信心和爱心的好消息带给我们。他还说，你们常常怀念我们，切切想见我们，好像我们想见你们一样。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 7, '所以弟兄们，我们在这一切困苦患难中，因着你们的信心就得了安慰。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 8, '如果你们在主里站立得稳，我们就可以活下去了。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 9, '我们因你们的缘故，在我们的神面前满有喜乐；为这一切喜乐，我们可以为你们向神献上怎么样的感谢呢！'),
('CNV', '帖撒罗尼迦前书', 52, 3, 10, '我们昼夜迫切祈求，要见你们的面，并且要补满你们信心的不足。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 11, '愿我们的父神自己和我们的主耶稣为我们开路，使我们可以到你们那里去。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 12, '又愿主叫你们彼此相爱的心，和爱众人的心，都充充足足，多而又多，好像我们爱你们一样。'),
('CNV', '帖撒罗尼迦前书', 52, 3, 13, '也愿他坚定你们的心，好叫你们在我们主耶稣和众圣徒再来的时候，在我们的父神面前，完全圣洁，无可指摘。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 1, '此外，弟兄们，我们在主耶稣里求你们，劝你们，你们既然接受了我们的教训，知道应该怎样行事为人，并且怎样讨神喜悦，就要照你们现在所行的更进一步。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 2, '我们凭着主耶稣传给你们的是什么命令，你们是知道的。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 3, '神的旨意是要你们圣洁，远避淫行；'),
('CNV', '帖撒罗尼迦前书', 52, 4, 4, '要你们各人晓得怎样用圣洁尊贵的方法保守自己的身体（“身体”原文作“器皿”）；'),
('CNV', '帖撒罗尼迦前书', 52, 4, 5, '不要放纵邪情私欲，像那些不认识神的外族人一样；'),
('CNV', '帖撒罗尼迦前书', 52, 4, 6, '谁也不要在这事上越轨，占弟兄的便宜，因为这一类的事，主必报应。这是我们从前告诉过你们，又严严警戒过你们的。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 7, '神呼召我们，不是要我们沾染污秽，而是要我们圣洁。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 8, '所以那弃绝这命令的，不是弃绝人，而是弃绝把他自己的圣灵赐给你们的那位神。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 9, '论到弟兄相爱，用不着人写什么给你们，因为你们自己受了神的教导，要彼此相爱。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 10, '其实，你们向全马其顿所有的弟兄，已经这样行了。但是，弟兄们，我们劝你们要更加彼此相爱；'),
('CNV', '帖撒罗尼迦前书', 52, 4, 11, '又要立志过安静的生活，办自己的事，亲手作工，正如我们从前吩咐过你们，'),
('CNV', '帖撒罗尼迦前书', 52, 4, 12, '使你们行事为人可以得到外人的尊敬，自己也不会有什么缺乏了。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 13, '弟兄们，论到睡了的人，我们不愿意你们不知道，免得你们忧伤，像那些没有盼望的人一样。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 14, '我们若信耶稣死了，又复活了，照样，也应该相信那些靠着耶稣已经睡了的人，神必定把他们和耶稣一同带来。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 15, '我们现在照着主的话告诉你们：我们这些活着存留到主再来的人，绝不能在那些睡了的人以先。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 16, '因为主必亲自从天降临，那时，有发令的声音，有天使长的呼声，还有神的号声，那些在基督里死了的人必先复活；'),
('CNV', '帖撒罗尼迦前书', 52, 4, 17, '然后，我们还活着存留的人，必和他们一同被提到云里，在空中与主相会。这样，我们就要和主常常同在。'),
('CNV', '帖撒罗尼迦前书', 52, 4, 18, '所以，你们应该用这些话彼此劝慰。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 1, '弟兄们，论到时候和日期，不用写什么给你们了。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 2, '因为你们自己清楚知道，主的日子来到，就像夜间的贼来到一样。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 3, '人正在说平安稳妥的时候，毁灭性的灾祸就突然临到他们，好像生产的痛苦临到怀胎的妇人一样，他们绝不能逃脱。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 4, '但是弟兄们，你们不在黑暗里，以致那日子会临到你们像贼来到一样。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 5, '你们都是光明之子、白昼之子；我们不是属于黑夜的，也不是属于黑暗的。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 6, '所以，我们不要沉睡像别人一样，总要警醒谨慎。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 7, '因为睡觉的人是在晚上睡，醉酒的人是在晚上醉；'),
('CNV', '帖撒罗尼迦前书', 52, 5, 8, '但我们既然属于白昼，就应当谨慎，披上信和爱的胸甲，戴上救恩的盼望作头盔。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 9, '因为神不是定意要我们受刑罚（“刑罚”原文作“忿怒”），而是要我们藉着我们的主耶稣基督得着救恩。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 10, '基督替我们死，使我们无论是醒着或睡着，都和他一同活着。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 11, '所以，你们应该彼此劝慰，互相造就，正如你们一向所行的。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 12, '弟兄们，我们求你们要敬重那些在你们中间劳苦的人，就是在主里面治理你们、劝戒你们的人。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 13, '又因为他们的工作，你们要用爱心格外尊重他们。你们应当彼此和睦。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 14, '弟兄们，我们劝你们，要警戒游手好闲的人，勉励灰心丧志的人，扶助软弱无力的人，也要容忍所有的人。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 15, '你们要注意，不管是谁都不要以恶报恶，却要在彼此相处和对待众人这方面，常常追求良善。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 16, '要常常喜乐，'),
('CNV', '帖撒罗尼迦前书', 52, 5, 17, '不住祷告，'),
('CNV', '帖撒罗尼迦前书', 52, 5, 18, '凡事谢恩；这就是神在基督耶稣里给你们的旨意。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 19, '不要熄灭圣灵的感动。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 20, '不要藐视先知的话语。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 21, '凡事都要察验，好的要持守，'),
('CNV', '帖撒罗尼迦前书', 52, 5, 22, '各样的恶事要远离。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 23, '愿赐平安的神亲自使你们完全成圣，又愿你们整个人：灵、魂和身体都得蒙保守，在我们的主耶稣基督再来的时候，无可指摘。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 24, '那呼召你们的是信实的，他必成就这事。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 25, '弟兄们，请为我们祷告。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 26, '要用圣洁的亲吻问候众弟兄。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 27, '我凭着主吩咐你们，要把这封信读给众弟兄听。'),
('CNV', '帖撒罗尼迦前书', 52, 5, 28, '愿我们主耶稣基督的恩惠与你们同在。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 1, '保罗、西拉和提摩太，写信给帖撒罗尼迦、在我们的父神和主耶稣基督里的教会。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 2, '愿恩惠平安从父神和主耶稣基督临到你们。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 3, '弟兄们，我们应该常常为你们感谢神，这是合适的。因为你们的信心格外长进，你们众人彼此相爱的心也在增加。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 4, '所以我们在神的众教会里，亲自夸奖你们，因为你们在所受的一切迫害患难中，仍然存着坚忍和信心。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 5, '这正是神公义判断的明证，使你们可以算是配得上他的国；你们也是为了神的国而受苦。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 6, '神既然是公义的，主耶稣和他有能力的天使从天上显现在火焰中的时候，就使你们这些受灾难的人，可以和我们同享安息；却以灾难报应那些把灾难加给你们的人。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 8, '又要报应那些不认识神、不听从我们主耶稣的福音的人。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 9, '当主来的时候，他们要受永远沉沦的惩罚，就是离开主的面和他权能的荣光。在那一天，他要在圣徒身上得着荣耀，又要在所有信徒身上受到尊崇（你们也在他们当中，因为你们信了我们向你们所作的见证）。'),
('CNV', '帖撒罗尼迦后书', 53, 1, 11, '因此，我们常常为你们祷告，愿我们的神看你们是配得上所蒙的召，又用大能成就你们所羡慕的一切良善和信心的工作，'),
('CNV', '帖撒罗尼迦后书', 53, 1, 12, '使我们主耶稣的名，照着我们的神和主耶稣基督的恩，在你们身上得着荣耀，你们也在他身上得着荣耀。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 1, '弟兄们，关于我们主耶稣基督的再来，和我们到他那里聚集的事，我们求你们：'),
('CNV', '帖撒罗尼迦后书', 53, 2, 2, '无论有灵、有话、有冒我们的名的书信，说主的日子现在到了，你们都不要轻易动心，也不要惊慌。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 3, '不要让人用任何方法迷惑了你们，因为主的日子来到以前，必定有背道的事，并且那不法的人，就是那沉沦之子，必定显露出来。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 4, '他抵挡神，抬举自己，高过一切称为神或受人敬拜的，甚至坐在神的殿中，自称为神。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 5, '我还在你们那里的时候，曾经把这些事告诉你们，你们不记得吗？'),
('CNV', '帖撒罗尼迦后书', 53, 2, 6, '现在你们也知道，那箝制他，使他到了时候才可以显露出来的是什么。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 7, '因为那不法的潜力已经发动，只是现在有一个箝制他的在那里，直等到那箝制解除了，'),
('CNV', '帖撒罗尼迦后书', 53, 2, 8, '那时，这不法的人必要显露出来。主耶稣要用自己口中的气除掉他，以自己再来所显现的光辉消灭他。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 9, '这不法的人来到，是照着撒但的行动，行各样的异能奇迹和荒诞的事，'),
('CNV', '帖撒罗尼迦后书', 53, 2, 10, '并且在那些沉沦的人身上，行各样不义的欺诈，因为他们不领受爱真理的心，使他们得救。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 11, '因此，神就使错谬的思想运行在他们当中，让他们相信虚谎，'),
('CNV', '帖撒罗尼迦后书', 53, 2, 12, '叫所有不信真理倒喜爱不义的人，都被定罪。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 13, '主所爱的弟兄们，我们应该常常为你们感谢神，因为他从起初就拣选了你们，藉着圣灵成圣的工作，和你们对真道的信心，使你们可以得救。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 14, '因此，神藉着我们所传的福音呼召你们，使你们得着我们主耶稣基督的荣耀。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 15, '所以弟兄们，你们要站立得稳；你们所领受的教训，无论是我们口传的，或是信上写的，都要持守。'),
('CNV', '帖撒罗尼迦后书', 53, 2, 16, '愿我们的主耶稣基督自己，和那爱我们、开恩把永远的安慰和美好的盼望赐给我们的父神，'),
('CNV', '帖撒罗尼迦后书', 53, 2, 17, '安慰你们的心，并且在一切善行善言上，坚定你们。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 1, '最后，弟兄们，请为我们祷告，好叫主的道也像在你们那里一样快快传开，得着荣耀，'),
('CNV', '帖撒罗尼迦后书', 53, 3, 2, '也使我们能够脱离那些不讲理的恶人，因为不是人人都有信心。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 3, '主是信实的，他必坚定你们，保护你们脱离那恶者。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 4, '我们靠着主深深相信，你们现在以及将来都会遵行我们所吩咐的，'),
('CNV', '帖撒罗尼迦后书', 53, 3, 5, '愿主引导你们的心，使你们有神的爱和基督的坚忍。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 6, '弟兄们，我们奉主耶稣基督的名吩咐你们，凡是游手好闲的弟兄，不按着你们从我们所领受的教训去行，就应当远离他。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 7, '你们自己本来就知道应当怎样效法我们，因为我们在你们中间并没有游手好闲，'),
('CNV', '帖撒罗尼迦后书', 53, 3, 8, '也没有白吃过谁的饭，反而辛苦劳碌，昼夜作工，免得加重你们任何一人的负担。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 9, '这不是因为我们没有权利，而是要给你们作榜样，好让你们效法我们。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 10, '我们在你们那里的时候，曾经吩咐过你们，如果有人不肯作工，就不可吃饭。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 11, '因为我们听说，你们中间有人游手好闲，什么工也不作，反倒专管闲事。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 12, '我们靠着主耶稣基督，吩咐劝戒这样的人，要安静作工，自食其力。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 13, '弟兄们，你们行善不可灰心。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 14, '如果有人不听从我们这封信上的训勉，要把这个人记下来，不可和他来往，好叫他自己觉得惭愧。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 15, '但不要把他看作仇敌，却要劝他好像劝弟兄一样。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 16, '愿赐平安的主亲自随时随地赐平安给你们。愿主与你们众人同在。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 17, '我保罗亲笔问候你们。这是我每一封信的记号；我的笔迹就是这样。'),
('CNV', '帖撒罗尼迦后书', 53, 3, 18, '愿我们主耶稣基督的恩惠与你们众人同在。'),
('CNV', '提摩太前书', 54, 1, 1, '奉我们的救主神，和我们的盼望基督耶稣的命令，作基督耶稣使徒的保罗，'),
('CNV', '提摩太前书', 54, 1, 2, '写信给因信主而作我真儿子的提摩太。愿恩惠、怜悯、平安从父神和我们的主基督耶稣临到你。'),
('CNV', '提摩太前书', 54, 1, 3, '我往马其顿去的时候，曾经劝你留在以弗所，为要嘱咐某些人，不可传别的教义，'),
('CNV', '提摩太前书', 54, 1, 4, '也不可沉迷于无稽之谈和无穷的家谱；这些事只能引起争论，对于神在信仰上所定的计划是毫无帮助的。'),
('CNV', '提摩太前书', 54, 1, 5, '这嘱咐的目的是出于爱；这爱是发自纯洁的心、无愧的良心和无伪的信心。'),
('CNV', '提摩太前书', 54, 1, 6, '有些人偏离了这些，就转向无意义的辩论，'),
('CNV', '提摩太前书', 54, 1, 7, '想要作律法教师，却不明白自己讲的是什么，主张的又是什么。'),
('CNV', '提摩太前书', 54, 1, 8, '我们知道律法是好的，只要应用得恰当。'),
('CNV', '提摩太前书', 54, 1, 9, '要知道律法本来不是为义人设立的，而是为那些无法无天和放荡不羁的、不敬虔和犯罪的、不圣洁和世俗的、弒父母和杀人的、'),
('CNV', '提摩太前书', 54, 1, 10, '淫乱的、亲男色的、拐带人口的、说谎话的、发假誓的，以及为其他抵挡纯正教训的人设立的。'),
('CNV', '提摩太前书', 54, 1, 11, '这是照着可称颂之神所交托我的荣耀福音说的。'),
('CNV', '提摩太前书', 54, 1, 12, '我感谢那赐我能力的、我们的主基督耶稣，因为他认为我有忠心，派我服事他。'),
('CNV', '提摩太前书', 54, 1, 13, '我从前是亵渎神的、迫害人的、凌辱人的，然而我还蒙了怜悯，因为我是在不信的时候，由于无知而作的。'),
('CNV', '提摩太前书', 54, 1, 14, '我们主的恩典，随着在基督耶稣里的信心和爱心，在我身上越发增加。'),
('CNV', '提摩太前书', 54, 1, 15, '“基督耶稣降世，为要拯救罪人。”这话是可信的，是值得完全接纳的。在罪人中我是个罪魁。'),
('CNV', '提摩太前书', 54, 1, 16, '可是，我竟然蒙了怜悯，好让基督耶稣在我这个罪魁身上，显明他完全的忍耐，给后来信他得永生的人作榜样。'),
('CNV', '提摩太前书', 54, 1, 17, '但愿尊贵荣耀归给万世的君王，就是那不朽坏、人不能见、独一的神，直到永永远远。阿们。'),
('CNV', '提摩太前书', 54, 1, 18, '我儿提摩太啊！我照着从前关于你的预言，把这命令交托你，为的是要叫你藉着这些预言打那美好的仗。'),
('CNV', '提摩太前书', 54, 1, 19, '常常存着信心和无愧的良心。有些人丢弃良心，就在信仰上失落了。'),
('CNV', '提摩太前书', 54, 1, 20, '他们当中有许米乃和亚历山大，我已经把他们交给撒但，使他们受管教不再亵渎。'),
('CNV', '提摩太前书', 54, 2, 1, '因此，我劝你最重要的是要为万人、君王和一切有权位的恳求、祷告、代求和感恩，好让我们可以敬虔庄重地过平静安稳的日子。'),
('CNV', '提摩太前书', 54, 2, 3, '在我们的救主神看来，这是美好的，可蒙悦纳的。'),
('CNV', '提摩太前书', 54, 2, 4, '他愿意万人得救，并且充分认识真理。'),
('CNV', '提摩太前书', 54, 2, 5, '因为神只有一位，在神和人中间也只有一位中保，就是降世为人的基督耶稣。'),
('CNV', '提摩太前书', 54, 2, 6, '他舍了自己作万人的赎价，到了适当的时候，这事就证实了。'),
('CNV', '提摩太前书', 54, 2, 7, '为了这事，我也被派作传道的和使徒（我说的是真话，不是谎言），在信仰和真理上作外族人的教师。'),
('CNV', '提摩太前书', 54, 2, 8, '因此，我愿意男人没有忿怒，没有争论，举起圣洁的手随处祷告。'),
('CNV', '提摩太前书', 54, 2, 9, '照样，我也愿意女人以端正、娴淑、自律为装饰；不要以鬈发、金饰、珠宝，或名贵衣裳为装饰，'),
('CNV', '提摩太前书', 54, 2, 10, '却要以善行作装饰，这才配称为敬畏神的女人。'),
('CNV', '提摩太前书', 54, 2, 11, '女人应该安静而又完全顺服地学习。'),
('CNV', '提摩太前书', 54, 2, 12, '我不准女人教导，或辖制男人；女人总要安静。'),
('CNV', '提摩太前书', 54, 2, 13, '因为先造的是亚当，后造的是夏娃；'),
('CNV', '提摩太前书', 54, 2, 14, '不是亚当受了引诱，而是女人受了引诱，陷在过犯里面。'),
('CNV', '提摩太前书', 54, 2, 15, '然而女人要是常常存着信心、爱心、圣洁自律，在她生育的事上必定得救。'),
('CNV', '提摩太前书', 54, 3, 1, '“如果有人渴慕监督的职分，他就是爱慕善工。”这话是可信的。'),
('CNV', '提摩太前书', 54, 3, 2, '所以作监督的，必须无可指摘，只作一个妻子的丈夫，有节制，自律，庄重，乐意接待客旅，善于教导，'),
('CNV', '提摩太前书', 54, 3, 3, '不好酒，不打人，只要温和，与人无争，不贪财，'),
('CNV', '提摩太前书', 54, 3, 4, '好好管理自己的家，使儿女凡事敬重顺服。'),
('CNV', '提摩太前书', 54, 3, 5, '（人若不知道怎样管理自己的家，怎能照料神的教会呢？）'),
('CNV', '提摩太前书', 54, 3, 6, '初信主的不可作监督，恐怕他骄傲，就落在魔鬼所受的刑罚里。'),
('CNV', '提摩太前书', 54, 3, 7, '作监督的也必须在教外有好声誉，免得他被人毁谤，就落在魔鬼的陷阱里。'),
('CNV', '提摩太前书', 54, 3, 8, '照样，执事也必须庄重，不一口两舌，不酗酒，不贪不义之财，'),
('CNV', '提摩太前书', 54, 3, 9, '用清洁的良心持守信仰的奥秘。'),
('CNV', '提摩太前书', 54, 3, 10, '他们也必须先受考验，若没有可责之处，然后才让他们作执事。'),
('CNV', '提摩太前书', 54, 3, 11, '照样，他们的妻子（“他们的妻子”可解作“女执事”）也要庄重，不说谗言，有节制，凡事忠心。'),
('CNV', '提摩太前书', 54, 3, 12, '执事只可以作一个妻子的丈夫，善于管理儿女和自己的家。'),
('CNV', '提摩太前书', 54, 3, 13, '那善于作执事的，就为自己得了好的位分，也因着相信基督耶稣得到大大的胆量。'),
('CNV', '提摩太前书', 54, 3, 14, '我把这些事写给你，希望不久可以到你那里去；'),
('CNV', '提摩太前书', 54, 3, 15, '假如我来迟了，你也可以知道在神的家里应该怎样行。这家就是永活神的教会、真理的柱石和根基。'),
('CNV', '提摩太前书', 54, 3, 16, '敬虔的奥秘真伟大啊，这是众人所公认的，就是：“他在肉身显现，在圣灵里称义（“在圣灵里称义”或译：“被圣灵称义”），被天使看见；被传于列国，被世人信服，被接到荣耀里。”'),
('CNV', '提摩太前书', 54, 4, 1, '圣灵明明地说，日后必有人离弃信仰，跟从虚谎的邪灵和鬼魔的教训。'),
('CNV', '提摩太前书', 54, 4, 2, '这教训是出于说谎的人的虚伪，他们的良心好像被烧红的铁烙了一般。'),
('CNV', '提摩太前书', 54, 4, 3, '他们禁止嫁娶，禁戒食物。食物本是神所造的，是给信主和认识真理的人存感谢的心领受的。'),
('CNV', '提摩太前书', 54, 4, 4, '因为凡神所造的，都是好的，只要存感谢的心领受，没有一样是可以弃绝的；'),
('CNV', '提摩太前书', 54, 4, 5, '都因着神的道和人的祈求成为圣洁了。'),
('CNV', '提摩太前书', 54, 4, 6, '你若把这些事提醒弟兄们，就是基督耶稣的好仆役，常在信仰的话语上，和你所遵从美善的教训上得着培养。'),
('CNV', '提摩太前书', 54, 4, 7, '总要弃绝世俗以及老妇的无稽之谈；要操练自己达到敬虔的地步。'),
('CNV', '提摩太前书', 54, 4, 8, '因为操练身体，益处还少；唯独操练敬虔，凡事有益，享有今生和来世的应许。'),
('CNV', '提摩太前书', 54, 4, 9, '这话是可信的，是值得完全接纳的。'),
('CNV', '提摩太前书', 54, 4, 10, '我们也是为这缘故劳苦努力，因为我们的盼望在于永活的神。他是万人的救主，更是信徒的救主。'),
('CNV', '提摩太前书', 54, 4, 11, '这些事你要嘱咐人，教导人。'),
('CNV', '提摩太前书', 54, 4, 12, '不要叫人小看你年轻，总要在言语、行为、爱心、信心和纯洁上，都作信徒的榜样。'),
('CNV', '提摩太前书', 54, 4, 13, '在我来以前，你要专心宣读圣经、劝勉和教导。'),
('CNV', '提摩太前书', 54, 4, 14, '不要忽略你所得的恩赐，就是众长老按手时藉着预言赐给你的。'),
('CNV', '提摩太前书', 54, 4, 15, '这些事你要认真实行，专心去作，使众人看出你的长进来。'),
('CNV', '提摩太前书', 54, 4, 16, '你要谨慎自己，留心自己的教训。在这些事上要有恒心，因为你这样作，不但能救自己，也能救那些听你的人。'),
('CNV', '提摩太前书', 54, 5, 1, '不要严厉责备老年人，却要劝他好像劝父亲；劝青年人好像劝弟兄；'),
('CNV', '提摩太前书', 54, 5, 2, '劝年老的妇人好像劝母亲；存着纯洁的心，劝青年女子好像劝姊妹。'),
('CNV', '提摩太前书', 54, 5, 3, '要敬重供养那些无依无靠的寡妇。'),
('CNV', '提摩太前书', 54, 5, 4, '寡妇若有儿孙，就应当让儿孙先在自己家里学习孝道，报答亲恩，因为这在神面前是蒙悦纳的。'),
('CNV', '提摩太前书', 54, 5, 5, '那无依无靠独居的寡妇，她们仰望神，昼夜不住地祈求祷告。'),
('CNV', '提摩太前书', 54, 5, 6, '寡妇若奢侈宴乐，虽然活着也是死的。'),
('CNV', '提摩太前书', 54, 5, 7, '这些事你要嘱咐她们，使她们无可指摘。'),
('CNV', '提摩太前书', 54, 5, 8, '人若不看顾自己的人，尤其不看顾自己一家的人，就是背弃信仰，比不信的人还坏。'),
('CNV', '提摩太前书', 54, 5, 9, '寡妇登记，年纪必须到达六十岁，只作过一个丈夫的妻子，'),
('CNV', '提摩太前书', 54, 5, 10, '并且要有善行的见证：就如养育儿女，接待客旅，替圣徒洗脚，救济困苦的人，尽力行各样的善事等。'),
('CNV', '提摩太前书', 54, 5, 11, '至于年轻的寡妇，不要给她们登记，因为她们一旦情欲冲动而背弃基督的时候，就想结婚。'),
('CNV', '提摩太前书', 54, 5, 12, '她们被定罪，是因为丢弃了起初的信誓。'),
('CNV', '提摩太前书', 54, 5, 13, '同时，她们懒惰惯了，挨家闲游；不但懒惰，而且好说闲话，好管闲事，说不该说的话。'),
('CNV', '提摩太前书', 54, 5, 14, '因此，我愿年轻的寡妇结婚，生儿育女，管理家务，不给敌人有辱骂的机会；'),
('CNV', '提摩太前书', 54, 5, 15, '因为有些人已经转去跟从撒但了。'),
('CNV', '提摩太前书', 54, 5, 16, '如果信主的妇女家中有寡妇，她就应该救济她们，不要让教会受累。这样，教会就可以救济那些无依无靠的寡妇了。'),
('CNV', '提摩太前书', 54, 5, 17, '那些善于治理教会的长老，尤其是那些在讲道和教导上劳苦的长老，你们应当看他们是配受加倍的敬重和供奉的。'),
('CNV', '提摩太前书', 54, 5, 18, '因为经上说：“牛踹谷的时候，不可笼住它的嘴。”又说：“作工的配得工价。”'),
('CNV', '提摩太前书', 54, 5, 19, '控诉长老的事，除非有两三个证人，否则不要受理。'),
('CNV', '提摩太前书', 54, 5, 20, '常常犯罪的，你要当众责备他们，使其余的人也有所惧怕。'),
('CNV', '提摩太前书', 54, 5, 21, '我在神和基督耶稣以及蒙拣选的天使面前叮嘱你，要毫无成见地持守这些话，行事也不要偏心。'),
('CNV', '提摩太前书', 54, 5, 22, '不要匆匆忙忙地替别人按手，也不要在别人的罪上有分，要保守自己清洁。'),
('CNV', '提摩太前书', 54, 5, 23, '因为你的胃不好，而且身体常常软弱，不要单单喝水，可以稍微用点酒。'),
('CNV', '提摩太前书', 54, 5, 24, '有些人的罪是明显的，就先受审判；有些人的罪是后来才显露出来的。'),
('CNV', '提摩太前书', 54, 5, 25, '照样，善行也是明显的，就算不明显，也不能隐藏。'),
('CNV', '提摩太前书', 54, 6, 1, '凡负轭作奴仆的，应当看自己的主人是配受十分的敬重，免得神的名和道理被人亵渎。'),
('CNV', '提摩太前书', 54, 6, 2, '奴仆有信主的主人，不可因为他们是弟兄而轻看他们；倒要加意服事他们，因为这些受到服事的益处的，是信主蒙爱的人。你要把这些事教导人，劝勉人。'),
('CNV', '提摩太前书', 54, 6, 3, '如果有人传别的教义，不接受我们的主耶稣基督纯正的话语，和那敬虔的道理，'),
('CNV', '提摩太前书', 54, 6, 4, '他是自高自大，一无所知，反而专好问难争辩，由此产生妒忌、纷争、毁谤、恶意的猜疑，'),
('CNV', '提摩太前书', 54, 6, 5, '就和那些心术败坏，丧失真理的人不断地争吵。他们视敬虔为得利的门路。'),
('CNV', '提摩太前书', 54, 6, 6, '其实敬虔而又知足，就是得大利的途径，'),
('CNV', '提摩太前书', 54, 6, 7, '因为我们没有带什么到世上来，也不能带什么去。'),
('CNV', '提摩太前书', 54, 6, 8, '只要有衣有食，就应当知足。'),
('CNV', '提摩太前书', 54, 6, 9, '但那些想要发财的人，就落在试探中和陷阱里；又落在许多无知而有害的私欲里，使人沉沦在败坏和灭亡中；'),
('CNV', '提摩太前书', 54, 6, 10, '因为贪财是万恶之根。有人贪爱钱财，就被引诱离开真道，用许多痛苦把自己刺透了。'),
('CNV', '提摩太前书', 54, 6, 11, '但你这属神的人啊，应该逃避这些事，要追求公义、敬虔、信心、爱心、忍耐和温柔。'),
('CNV', '提摩太前书', 54, 6, 12, '要为信仰打那美好的仗，持定永生；你是为这永生而蒙召的，又在许多的证人面前承认过美好的信仰。'),
('CNV', '提摩太前书', 54, 6, 13, '我在赐生命给万物的神面前，并那在本丢．彼拉多面前见证过美好的信仰的基督耶稣面前嘱咐你，'),
('CNV', '提摩太前书', 54, 6, 14, '你当毫无玷污，无可指摘地持守这命令，直到我们主耶稣基督的显现。'),
('CNV', '提摩太前书', 54, 6, 15, '到了适当的时候，那可称颂的、独一的全能者，万王之王，万主之主，必把基督的显现表明出来。'),
('CNV', '提摩太前书', 54, 6, 16, '只有他永远不死，住在不能接近的光里，没有人见过他，人也不能看见他。愿尊荣和永远的权能都归给他。阿们。'),
('CNV', '提摩太前书', 54, 6, 17, '你要嘱咐那些今世富有的人，叫他们不要心高气傲，也不要寄望在浮动的财富上，却要仰望那厚赐百物给我们享用的神。'),
('CNV', '提摩太前书', 54, 6, 18, '又要嘱咐他们行善，在善事上富足，慷慨好施。'),
('CNV', '提摩太前书', 54, 6, 19, '这样，就为自己在来世积聚财富，作美好的基础，好叫他们能够得着那真正的生命。'),
('CNV', '提摩太前书', 54, 6, 20, '提摩太啊，你要保守所交托你的，避免世俗的空谈和冒称是知识的那种反调；'),
('CNV', '提摩太前书', 54, 6, 21, '有些人自称有这知识，就偏离了真道。愿恩惠与你们同在。'),
('CNV', '提摩太后书', 55, 1, 1, '奉神旨意，凭着在基督耶稣里的生命的应许，作基督耶稣使徒的保罗，'),
('CNV', '提摩太后书', 55, 1, 2, '写信给亲爱的儿子提摩太，愿恩惠、怜悯、平安从父神和我们的主基督耶稣临到你。'),
('CNV', '提摩太后书', 55, 1, 3, '我感谢神，就是我像我祖先一样，以清洁的良心所事奉的神，在祷告中昼夜不断地记念你；'),
('CNV', '提摩太后书', 55, 1, 4, '一想起你流的眼泪，我就渴望见你，好叫我满有喜乐。'),
('CNV', '提摩太后书', 55, 1, 5, '我记得你心里无伪的信心，这信心原先是在你外祖母罗以和你母亲友尼基心里的，我深信也在你的心里。'),
('CNV', '提摩太后书', 55, 1, 6, '为了这缘故，我提醒你，要把神藉着我按手给你的恩赐，像火一样再挑旺起来。'),
('CNV', '提摩太后书', 55, 1, 7, '因为神所赐给我们的，不是胆怯的灵，而是有能力、仁爱、自律的灵。'),
('CNV', '提摩太后书', 55, 1, 8, '所以，不要以给我们的主作见证当作羞耻，也不要以我这为主被囚的当作羞耻，却要为了福音的缘故，靠着神的大能，与我同受磨难。'),
('CNV', '提摩太后书', 55, 1, 9, '神救了我们，以圣召呼召我们，不是按照我们的行为，却是按照他自己的计划和恩典；这恩典是在万世以前，在基督耶稣里赐给了我们的，'),
('CNV', '提摩太后书', 55, 1, 10, '但现在藉着我们救主基督耶稣的显现，才表明出来。他废掉了死亡，藉着福音把生命和不朽彰显出来。'),
('CNV', '提摩太后书', 55, 1, 11, '为这福音，我被派作传道的、使徒和教师。'),
('CNV', '提摩太后书', 55, 1, 12, '为了这缘故，我也受这些苦，但我不以为耻，因为我知道我所信的是谁，也深信他能保守我所交托他的（“我所交托他的”或译：“他所交托我的”），直到那日。'),
('CNV', '提摩太后书', 55, 1, 13, '你要靠着在基督耶稣里的信心和爱心，常常坚守从我这里听过的话，作为纯正话语的模范；'),
('CNV', '提摩太后书', 55, 1, 14, '又要靠着那住在我们里面的圣灵，保守所交托你的善道。'),
('CNV', '提摩太后书', 55, 1, 15, '你知道所有在亚西亚的人都离弃了我，他们当中有腓吉路和黑摩其尼。'),
('CNV', '提摩太后书', 55, 1, 16, '愿主赐怜悯给阿尼色弗一家的人，因为他多次使我畅快，也不以我的锁链为耻；'),
('CNV', '提摩太后书', 55, 1, 17, '他竟然来到罗马，迫切地寻找我，结果找到了。'),
('CNV', '提摩太后书', 55, 1, 18, '（愿主在那日使他从主那里得着怜悯。）你也清楚知道他在以弗所是怎样多方服事我。'),
('CNV', '提摩太后书', 55, 2, 1, '所以，我儿啊，你应当在基督耶稣的恩典里刚强起来，'),
('CNV', '提摩太后书', 55, 2, 2, '又应当把你在许多见证人面前从我这里听见的，交托给那些又忠心又能够教导别人的人。'),
('CNV', '提摩太后书', 55, 2, 3, '你应当和我同受磨难，好像基督耶稣的精兵。'),
('CNV', '提摩太后书', 55, 2, 4, '当兵的人不让世务缠身，为要使那招兵的人欢喜。'),
('CNV', '提摩太后书', 55, 2, 5, '竞赛的人若不遵守规则，就不能得冠冕。'),
('CNV', '提摩太后书', 55, 2, 6, '劳力的农夫理当先尝果实。'),
('CNV', '提摩太后书', 55, 2, 7, '你要想想我的话，因为凡事主必给你领悟力。'),
('CNV', '提摩太后书', 55, 2, 8, '你要记得那从死人中复活的耶稣基督，他是大卫的后裔所生的，这就是我所传的福音。'),
('CNV', '提摩太后书', 55, 2, 9, '我为了这福音受了磨难，甚至像犯人一样被捆绑起来；可是，神的话却不被捆绑。'),
('CNV', '提摩太后书', 55, 2, 10, '因此，我为了选民忍受一切，好叫他们也可以得着在基督耶稣里的救恩，和永远的荣耀。'),
('CNV', '提摩太后书', 55, 2, 11, '“我们若与基督同死，就必与他同活；'),
('CNV', '提摩太后书', 55, 2, 12, '我们若能坚忍，就必与他一同作王；我们若不认他，他必不认我们；'),
('CNV', '提摩太后书', 55, 2, 13, '我们纵然不信，他仍然是信实的，因为他不能否定自己。”这话是可信的。'),
('CNV', '提摩太后书', 55, 2, 14, '你要在神面前把这些事提醒众人，叮嘱他们不要作无益的争辩；这只能败坏听见的人。'),
('CNV', '提摩太后书', 55, 2, 15, '你应当竭力在神面前作一个蒙称许、无愧的工人，正确地讲解真理的道。'),
('CNV', '提摩太后书', 55, 2, 16, '总要远避世俗的空谈，因为这些必会引人进到更不敬虔的地步。'),
('CNV', '提摩太后书', 55, 2, 17, '他们的话好像毒瘤一样蔓延；他们当中有许米乃和腓理徒。'),
('CNV', '提摩太后书', 55, 2, 18, '他们偏离了真道，说复活的事已经过去了，于是毁坏了一些人的信心。'),
('CNV', '提摩太后书', 55, 2, 19, '然而，神坚固的根基已经立定，上面刻着这样的印：“主认识属于他的人”和“凡称呼主名的人都应当离开不义”。'),
('CNV', '提摩太后书', 55, 2, 20, '在富贵人的家里（“富贵人的家里”原文作“大房子”），不但有金器、银器，也有木器、瓦器；有贵重的，也有卑贱的。'),
('CNV', '提摩太后书', 55, 2, 21, '人若自洁，离开卑贱的事，就必作贵重的器皿，成为圣洁，合主使用，预备行各样的善事。'),
('CNV', '提摩太后书', 55, 2, 22, '你应当逃避年轻人的私欲，要和那些以清洁的心求告主的人，一同追求公义、信心、爱心、和平。'),
('CNV', '提摩太后书', 55, 2, 23, '你要拒绝愚蠢无知的问难；你知道这些事会引起争论。'),
('CNV', '提摩太后书', 55, 2, 24, '但主的仆人却不可争论，总要待人温和，善于教导，存心忍耐，'),
('CNV', '提摩太后书', 55, 2, 25, '以温柔劝导那些对抗的人，或许神给他们悔改的心，可以认识真理。'),
('CNV', '提摩太后书', 55, 2, 26, '他们虽然曾经被魔鬼掳去，随从他的意思而行，或许也能醒悟过来，脱离魔鬼的陷阱。'),
('CNV', '提摩太后书', 55, 3, 1, '你应当知道，末后的日子必有艰难的时期来到。'),
('CNV', '提摩太后书', 55, 3, 2, '那时，人会专爱自己、贪爱钱财、自夸、高傲、亵渎、悖逆父母、忘恩负义、不圣洁、'),
('CNV', '提摩太后书', 55, 3, 3, '没有亲情、不肯和解、恶言中伤、不能自律、横蛮凶暴、不爱良善、'),
('CNV', '提摩太后书', 55, 3, 4, '卖主卖友、容易冲动、傲慢自大、爱享乐过于爱神，'),
('CNV', '提摩太后书', 55, 3, 5, '有敬虔的形式，却否定敬虔的能力；这些人你应当避开。'),
('CNV', '提摩太后书', 55, 3, 6, '他们中间有人潜入别人的家里，操纵无知的妇女。这些妇女被罪压住，又被各种私欲拖累，'),
('CNV', '提摩太后书', 55, 3, 7, '虽然常常学习，总不能充分明白真理。'),
('CNV', '提摩太后书', 55, 3, 8, '从前阎儡和阎悖怎样反对摩西，这些人也怎样反对真理。他们的心思败坏，信仰也经不起考验。'),
('CNV', '提摩太后书', 55, 3, 9, '然而他们不能再这样下去了，因为他们的愚昧终必在众人面前显露出来，好像那两个人一样。'),
('CNV', '提摩太后书', 55, 3, 10, '但是，你已经了解我的教训、品行、志向、信心、宽容、爱心和忍耐，'),
('CNV', '提摩太后书', 55, 3, 11, '以及我在安提阿、以哥念、路司得所受的苦和迫害。我所忍受的是怎样的迫害；这一切主都救我脱离了。'),
('CNV', '提摩太后书', 55, 3, 12, '其实，所有立志在基督耶稣里过敬虔生活的，都必遭受迫害。'),
('CNV', '提摩太后书', 55, 3, 13, '但恶人和骗子必越来越坏，他们欺骗人，也必受欺骗。'),
('CNV', '提摩太后书', 55, 3, 14, '你应当遵守所学和确信的；你知道是跟谁学的，'),
('CNV', '提摩太后书', 55, 3, 15, '并且知道自己从小就明白圣经，这圣经能够使你有智慧，可以因信基督耶稣得着救恩。'),
('CNV', '提摩太后书', 55, 3, 16, '全部圣经都是神所默示的，在教训、责备、矫正和公义的训练各方面，都是有益的，'),
('CNV', '提摩太后书', 55, 3, 17, '为要使属神的人装备好，可以完成各样的善工。'),
('CNV', '提摩太后书', 55, 4, 1, '我在神面前，并且在那将要审判活人死人的基督耶稣面前，凭着他的显现和国度叮嘱你：'),
('CNV', '提摩太后书', 55, 4, 2, '务要传道；无论时机是否适合，都要常作准备；要以多方的忍耐和教训责备人、警戒人、劝勉人。'),
('CNV', '提摩太后书', 55, 4, 3, '因为时候快要到了，人必容不下纯正的道理，反而耳朵发痒，随着自己的私欲，增添许多教师，'),
('CNV', '提摩太后书', 55, 4, 4, '而且转离不听真理，反倒趋向无稽之谈。'),
('CNV', '提摩太后书', 55, 4, 5, '你却要凡事谨慎，忍受磨难、作传福音者的工作，完成你的职务。'),
('CNV', '提摩太后书', 55, 4, 6, '我已经被浇奠；我离世的时候也到了。'),
('CNV', '提摩太后书', 55, 4, 7, '那美好的仗我已经打过了，当跑的路我已经跑尽了，所持的信仰我已经守住了。'),
('CNV', '提摩太后书', 55, 4, 8, '从此以后，有公义的冠冕为我存留，就是按公义审判的主在那日要赏给我的；不但赏给我，也赏给所有爱慕他显现的人。'),
('CNV', '提摩太后书', 55, 4, 9, '你要尽快到我这里来。'),
('CNV', '提摩太后书', 55, 4, 10, '因为底马贪爱现今的世界，就离弃我到帖撒罗尼迦去了。革勒士去了加拉太，提多去了达马太。'),
('CNV', '提摩太后书', 55, 4, 11, '只有路加在我这里。你找到了马可，就把他带来，因为他在圣工上对我有益。'),
('CNV', '提摩太后书', 55, 4, 12, '我差派了推基古到以弗所去。'),
('CNV', '提摩太后书', 55, 4, 13, '我在特罗亚留在加布那里的外衣，你来的时候要把它带来，还有那些书卷，特别是那些羊皮卷，也要带来。'),
('CNV', '提摩太后书', 55, 4, 14, '铜匠亚历山大作了许多恶事陷害我，主必按着他所行的报应他。'),
('CNV', '提摩太后书', 55, 4, 15, '你也要提防他，因为他极力抵挡我们的话。'),
('CNV', '提摩太后书', 55, 4, 16, '我第一次申辩的时候，没有一个人支持我，反而离弃我。但愿这罪不要归在他们身上。'),
('CNV', '提摩太后书', 55, 4, 17, '然而主站在我旁边，加给我力量，使福音的信息藉着我尽都传开，万国的人都可以听见；他并且把我从狮子口中救出来。'),
('CNV', '提摩太后书', 55, 4, 18, '主必救我脱离一切邪恶的事，也必救我进入他天上的国。愿荣耀归给他，直到永永远远。阿们。'),
('CNV', '提摩太后书', 55, 4, 19, '问候百基拉、亚居拉和阿尼色弗一家的人。'),
('CNV', '提摩太后书', 55, 4, 20, '以拉都在哥林多住下了。特罗非摩病了，我就留他在米利都。'),
('CNV', '提摩太后书', 55, 4, 21, '你要赶紧在冬天以前到我这里来。友布罗、布田、利奴、革老底亚和众弟兄都问候你。'),
('CNV', '提摩太后书', 55, 4, 22, '主与你同在。愿恩惠与你们同在。'),
('CNV', '提多书', 56, 1, 1, '神的仆人、耶稣基督的使徒保罗（这是为着神选民的信心，和那合乎敬虔真理的知识；'),
('CNV', '提多书', 56, 1, 2, '这都是根据永生的盼望，这永生就是没有谎言的神在万世以前所应许的。'),
('CNV', '提多书', 56, 1, 3, '到了适当的时候，神就藉着福音的宣讲，把他的道显明出来。照着神我们救主的命令，这宣讲的使命交托了我），'),
('CNV', '提多书', 56, 1, 4, '写信给提多，就是那在共同的信仰上作我真儿子的。愿恩惠平安从父神和我们的救主基督耶稣临到你。'),
('CNV', '提多书', 56, 1, 5, '我从前留你在克里特岛，是要你办好没有办完的事，并且照我所吩咐的，在各城设立长老。'),
('CNV', '提多书', 56, 1, 6, '如果有人无可指摘，只作一个妻子的丈夫，儿女都信主，也没有人控告他们放荡或不受约束，才可以作长老。'),
('CNV', '提多书', 56, 1, 7, '因为监督是神的管家，所以必须无可指摘、不任性、不随便动怒、不好酒、不打人、不贪不义之财；'),
('CNV', '提多书', 56, 1, 8, '却要接待客旅、喜爱良善、自律、公正、圣洁、自制，'),
('CNV', '提多书', 56, 1, 9, '坚守那合乎教义、可靠的真道，好使他能够用纯正的道理劝勉人，并且能够折服反对的人。'),
('CNV', '提多书', 56, 1, 10, '因为有许多不受约束、好讲空话和欺骗人的，尤其是那些守割礼的人，'),
('CNV', '提多书', 56, 1, 11, '他们为了可耻的利益，教训一些不应该教导的事，败坏人的全家，你务要堵住他们的嘴。'),
('CNV', '提多书', 56, 1, 12, '有一个克里特本地的先知说过：“克里特人是常常说谎的，是恶兽，好吃懒作。”'),
('CNV', '提多书', 56, 1, 13, '这见证是真的。为了这缘故，你要严厉地责备他们，好使他们在信仰上健全，'),
('CNV', '提多书', 56, 1, 14, '不再理会犹太人的无稽之谈和偏离正道的人的规条。'),
('CNV', '提多书', 56, 1, 15, '在清洁的人，一切都是清洁的；但在污秽和不信的人，没有一样是清洁的，连他们的意念和良心都污秽了。'),
('CNV', '提多书', 56, 1, 16, '他们声称认识神，却在行为上否认他。他们是可憎的、悖逆的，在各样的善事上，是毫无用处的。'),
('CNV', '提多书', 56, 2, 1, '至于你，你应当讲合乎纯正的道理。'),
('CNV', '提多书', 56, 2, 2, '劝年老的男人要有节制、庄重、自律，在信心、爱心、忍耐上都要健全。'),
('CNV', '提多书', 56, 2, 3, '照样，劝年老的妇女行为要敬虔，不说谗言，不被酒奴役，用善道教导人，'),
('CNV', '提多书', 56, 2, 4, '好提醒年轻的妇女爱丈夫爱儿女，'),
('CNV', '提多书', 56, 2, 5, '并且自律、贞洁、理家、善良、顺从自己的丈夫，免得神的道受毁谤。'),
('CNV', '提多书', 56, 2, 6, '照样，劝年轻的男子要自律。'),
('CNV', '提多书', 56, 2, 7, '无论在什么事上你都要显出好行为的榜样，在教导上要纯全，要庄重，'),
('CNV', '提多书', 56, 2, 8, '言词要纯正，无可指摘，使反对的人因为无从毁谤，就自觉惭愧。'),
('CNV', '提多书', 56, 2, 9, '作奴仆的，要凡事顺服自己的主人，讨他欢喜，不要顶嘴。'),
('CNV', '提多书', 56, 2, 10, '不要私取财物，却要显示绝对的诚实，好使我们救主神的道理，在凡事上都得着尊荣。'),
('CNV', '提多书', 56, 2, 11, '神拯救万人的恩典已经显明出来了。'),
('CNV', '提多书', 56, 2, 12, '这恩典训练我们除去不敬虔的心，和属世的私欲，在今生过着自律、公正、敬虔的生活，'),
('CNV', '提多书', 56, 2, 13, '等候那有福的盼望，就是我们伟大的神，救主耶稣基督荣耀的显现。'),
('CNV', '提多书', 56, 2, 14, '他为我们舍己，为的是要救赎我们脱离一切不法的事，并且洁净我们作他自己的子民，热心善工。'),
('CNV', '提多书', 56, 2, 15, '你要传讲这些事，运用各样的权柄去劝戒人，责备人；不要让人轻看你。'),
('CNV', '提多书', 56, 3, 1, '你要提醒他们服从执政的和掌权的，听从他们，随时准备作各种善工。'),
('CNV', '提多书', 56, 3, 2, '不可毁谤人，要与人无争，谦恭有礼，向众人表现充分温柔的心。'),
('CNV', '提多书', 56, 3, 3, '我们从前也是无知、不顺服、受了迷惑、被各种私欲和逸乐所奴役，生活在恶毒和嫉妒之中，是可憎可恶的，并且互相仇视。'),
('CNV', '提多书', 56, 3, 4, '然而，到了神我们的救主显明他的恩慈和怜爱的时候，'),
('CNV', '提多书', 56, 3, 5, '他就救了我们，并不是由于我们所行的义，而是照着他的怜悯，藉着重生的洗和圣灵的更新。'),
('CNV', '提多书', 56, 3, 6, '圣灵就是神藉着我们的救主耶稣基督丰丰富富浇灌在我们身上的，'),
('CNV', '提多书', 56, 3, 7, '使我们既然因着他的恩典得称为义，就可以凭着永生的盼望成为后嗣。'),
('CNV', '提多书', 56, 3, 8, '这话是可信的，我愿你确实地强调这些事，使信神的人常常留心作善工；这些都是美事，并且是对人有益的。'),
('CNV', '提多书', 56, 3, 9, '你要远避愚昧的辩论、家谱、纷争和律法上的争执，因为这都是虚妄无益的。'),
('CNV', '提多书', 56, 3, 10, '分门结党的人，警戒一两次之后，就要和他绝交。'),
('CNV', '提多书', 56, 3, 11, '你知道这种人已经背道，常常犯罪，定了自己的罪。'),
('CNV', '提多书', 56, 3, 12, '我派亚提马或推基古到你那里去的时候，你要赶快到尼哥波立来见我，因为我已决定在那里过冬。'),
('CNV', '提多书', 56, 3, 13, '你要尽力资助西纳律师和亚波罗的旅程，使他们不致缺乏。'),
('CNV', '提多书', 56, 3, 14, '我们自己的人也应当学习作善工，供应日常的需要，免得不结果子。'),
('CNV', '提多书', 56, 3, 15, '同我在一起的人都向你问安。请你问候那些因信而爱我们的人。愿恩惠与你们众人同在。'),
('CNV', '腓利门书', 57, 1, 1, '为基督耶稣被囚禁的保罗，和提摩太弟兄，写信给我们所爱的，又一同作工的腓利门，'),
('CNV', '腓利门书', 57, 1, 2, '和亚腓亚姊妹，并我们的战友亚基布，以及在你家里的教会。'),
('CNV', '腓利门书', 57, 1, 3, '愿恩惠平安从我们的父神和主耶稣基督临到你们。'),
('CNV', '腓利门书', 57, 1, 4, '我听见你对主耶稣和众圣徒有爱心和信心，我每逢祷告提到你的时候，就常常感谢我的神。'),
('CNV', '腓利门书', 57, 1, 6, '愿你与众人分享你的信心的时候，会产生功效，使我们可以知道在我们中间的一切善事，都是为基督作的。'),
('CNV', '腓利门书', 57, 1, 7, '弟兄啊，众圣徒的心既然从你得到舒畅，我也因你的爱心，得到更大的喜乐和安慰。'),
('CNV', '腓利门书', 57, 1, 8, '我在基督里虽然可以放胆吩咐你作应作的事，'),
('CNV', '腓利门书', 57, 1, 9, '然而像我这上了年纪的保罗，现在又是为基督耶稣被囚禁的，宁愿凭着爱心请求你，'),
('CNV', '腓利门书', 57, 1, 10, '就是为我在囚禁时所生的儿子欧尼西慕求你；'),
('CNV', '腓利门书', 57, 1, 11, '他从前对你没有什么好处，但现在对你我都有好处。'),
('CNV', '腓利门书', 57, 1, 12, '我现在打发他亲自回到你那里去；他是我所心爱的。'),
('CNV', '腓利门书', 57, 1, 13, '我本来想把他留在我这里，使他在我为福音被囚禁时，可以替你服事我。'),
('CNV', '腓利门书', 57, 1, 14, '但还没有得到你的同意，我就不愿意这样作，好叫你的善行不是出于勉强，而是出于甘心。'),
('CNV', '腓利门书', 57, 1, 15, '也许他暂时离开你，正是为了使你永远得着他，'),
('CNV', '腓利门书', 57, 1, 16, '不再是奴隶，而是高过奴隶，是亲爱的弟兄。对我固然是这样，对你来说，不论按肉身或在主内的关系，更是这样。'),
('CNV', '腓利门书', 57, 1, 17, '所以，你要是把我看作同伴，就接纳他好像接纳我一样。'),
('CNV', '腓利门书', 57, 1, 18, '如果他使你受了损失，或欠你什么，都记在我的帐上。'),
('CNV', '腓利门书', 57, 1, 19, '“我必偿还”，这是我保罗亲手写的。用不着我说，甚至你的生命，你也是欠我的。'),
('CNV', '腓利门书', 57, 1, 20, '所以弟兄啊！让我在主里得到你的帮助，使我的心在基督里得着畅快。'),
('CNV', '腓利门书', 57, 1, 21, '我深信你会听从，也知道你所作的必超过我所说的，因此才写信给你。'),
('CNV', '腓利门书', 57, 1, 22, '同时，还请你为我预备住的地方，因为我盼望藉着你们的祷告，可以获得释放到你们那里去。'),
('CNV', '腓利门书', 57, 1, 23, '为基督耶稣的缘故和我一同坐监的以巴弗，'),
('CNV', '腓利门书', 57, 1, 24, '以及我的同工马可、亚里达古、底马、路加都问候你。'),
('CNV', '腓利门书', 57, 1, 25, '愿主耶稣基督的恩惠常与你们同在。（“与你们同在”原文作“与你们的心灵同在”；好些抄本在这书末有“阿们”一词。）'),
('CNV', '希伯来书', 58, 1, 1, '神在古时候，曾经多次用种种方法，藉着先知向我们的祖先说话；'),
('CNV', '希伯来书', 58, 1, 2, '在这末后的日子，却藉着他的儿子向我们说话。神已经立他作万有的承受者，并且藉着他创造了宇宙（“宇宙”或译：“诸世界”或“众世代”）。'),
('CNV', '希伯来书', 58, 1, 3, '他是神荣耀的光辉，是神本质的真象，用自己带有能力的话掌管万有；他作成了洁净罪恶的事，就坐在高天至尊者的右边。'),
('CNV', '希伯来书', 58, 1, 4, '他所承受的名比天使的名更尊贵，所以他远比天使崇高。'),
('CNV', '希伯来书', 58, 1, 5, '神曾对哪一个天使说过：“你是我的儿子，我今日生了你”呢？或者说：“我要作他的父亲，他要作我的儿子”呢？'),
('CNV', '希伯来书', 58, 1, 6, '神差遣长子到世上来的时候，又说：“神所有的天使都要拜他。”'),
('CNV', '希伯来书', 58, 1, 7, '论到天使，说：“神以他的天使为风，以他的仆役为火焰。”'),
('CNV', '希伯来书', 58, 1, 8, '但是论到儿子，却说：“神啊！你的宝座是永永远远的，你国的权杖，是公平的权杖。'),
('CNV', '希伯来书', 58, 1, 9, '你喜爱公义，恨恶不法，所以，神，就是你的神，用喜乐的油膏抹你，胜过膏抹你的同伴。”'),
('CNV', '希伯来书', 58, 1, 10, '又说：“主啊！你起初立了地的根基，天也是你手的工作。'),
('CNV', '希伯来书', 58, 1, 11, '天地都要毁灭，你却长存；天地都要像衣服一样渐渐残旧，'),
('CNV', '希伯来书', 58, 1, 12, '你要把天地像外套一样卷起来，天地就像衣服一样被更换；只有你永不改变，你的年数也没有穷尽。”'),
('CNV', '希伯来书', 58, 1, 13, '神可曾向哪一个天使说：“你坐在我的右边，等我使你的仇敌作你的脚凳”呢？'),
('CNV', '希伯来书', 58, 1, 14, '天使不都是服役的灵，奉差遣为那些要承受救恩的人效劳吗？'),
('CNV', '希伯来书', 58, 2, 1, '因此，我们必须更加密切注意所听过的道理，免得我们随流失去。'),
('CNV', '希伯来书', 58, 2, 2, '那透过天使所传讲的信息既然是确定的，所有干犯和不听从的，都受了应得的报应。'),
('CNV', '希伯来书', 58, 2, 3, '如果我们忽略了这么大的救恩，怎么能逃罪呢？这救恩起初是由主亲自宣讲的，后来听见的人给我们证实了。'),
('CNV', '希伯来书', 58, 2, 4, '神又照着自己的旨意，用神迹、奇事和各样异能，以及圣灵的恩赐，与他们一同作见证。'),
('CNV', '希伯来书', 58, 2, 5, '神并没有把我们所说的“将来的世界”，交给天使管辖；'),
('CNV', '希伯来书', 58, 2, 6, '但是有人在圣经上某一处证实说：“人算什么，你竟记念他？世人算什么，你竟眷顾他？'),
('CNV', '希伯来书', 58, 2, 7, '你使他暂时成了比天使卑微（“暂时成了比天使卑微”或译：“比天使稍低微一点”），却赐给他荣耀尊贵作冠冕，（有些古卷在此有“并立他统管你手所造的一切”一句）'),
('CNV', '希伯来书', 58, 2, 8, '使万物都服在他的脚下。”既然万有都服了他，就没有剩下一样不服他的了。但是现在我们还没有看见万有都服他。'),
('CNV', '希伯来书', 58, 2, 9, '不过，我们看见那位暂时成了比天使卑微（“暂时成了比天使卑微”或译：“比天使稍低微一点”）的耶稣，因为受了死的痛苦，就得了荣耀尊贵作冠冕，好叫他因着神的恩典，为万人尝了死味。'),
('CNV', '希伯来书', 58, 2, 10, '万有因他而有、藉他而造的那位，为了要带领许多儿子进入荣耀里去，使救他们的元首藉着受苦而得到成全，本是合适的。'),
('CNV', '希伯来书', 58, 2, 11, '因为那位使人成圣的，和那些得到成圣的，同是出于一个源头；所以他称他们为弟兄也不以为耻。'),
('CNV', '希伯来书', 58, 2, 12, '他说：“我要向我的弟兄宣扬你的名，我要在聚会中歌颂你。”'),
('CNV', '希伯来书', 58, 2, 13, '又说：“我要信靠他。”又说：“看哪，我和神所赐给我的孩子们。”'),
('CNV', '希伯来书', 58, 2, 14, '孩子们既然同有血肉之体，他自己也照样成为血肉之体，为要藉着死，消灭那掌握死权的魔鬼，'),
('CNV', '希伯来书', 58, 2, 15, '并且要释放那些因为怕死而终身作奴仆的人。'),
('CNV', '希伯来书', 58, 2, 16, '其实，他并没有救援天使，只救援亚伯拉罕的后裔。'),
('CNV', '希伯来书', 58, 2, 17, '所以，他必须在各方面和他的弟兄们相同，为了要在神的事上，成为仁慈忠信的大祭司，好为人民赎罪。'),
('CNV', '希伯来书', 58, 2, 18, '因为他自己既然经过试探，受了苦，就能够帮助那些被试探的人。'),
('CNV', '希伯来书', 58, 3, 1, '因此，同蒙天召的圣洁的弟兄啊！你们应该想想耶稣，就是作使徒、作我们所宣认的大祭司的那一位。'),
('CNV', '希伯来书', 58, 3, 2, '他忠于那位委派他的，好像摩西在神的全家尽忠一样。'),
('CNV', '希伯来书', 58, 3, 3, '他比摩西配得更大的荣耀，好像建造房屋的人比房屋配得更大的尊贵一样。'),
('CNV', '希伯来书', 58, 3, 4, '因为每一间房屋都是人建造的，只有万物是神建造的。'),
('CNV', '希伯来书', 58, 3, 5, '摩西不过是个仆人，在神的全家尽忠，为以后要传讲的事作证；'),
('CNV', '希伯来书', 58, 3, 6, '但是基督却是儿子，管理自己的家。如果我们把坦然无惧的心和可夸的盼望持守到底，我们就是他的家了。'),
('CNV', '希伯来书', 58, 3, 7, '所以，就像圣灵所说的：“如果你们今天听从他的声音，'),
('CNV', '希伯来书', 58, 3, 8, '就不要硬着心，好像在旷野惹他发怒、试探他的日子一样；'),
('CNV', '希伯来书', 58, 3, 9, '在那里，你们的祖先以试验来试探我，观看我的作为有四十年之久。'),
('CNV', '希伯来书', 58, 3, 10, '所以，我向那个世代的人发怒，说：‘他们心里常常迷误，不认识我的道路。’'),
('CNV', '希伯来书', 58, 3, 11, '我就在烈怒中起誓，说：‘他们绝不可进入我的安息。’”'),
('CNV', '希伯来书', 58, 3, 12, '弟兄们，你们要小心，免得你们中间有人存着邪恶、不信的心，以致离弃了永活的神；'),
('CNV', '希伯来书', 58, 3, 13, '趁着还有叫作“今天”的时候，总要天天互相劝勉，免得你们中间有人受了罪恶的诱惑，心里就刚硬了。'),
('CNV', '希伯来书', 58, 3, 14, '如果我们把起初的信念坚持到底，就是有分于基督的人了。'),
('CNV', '希伯来书', 58, 3, 15, '经上说：“如果你们今天听从他的声音，就不要硬着心，像惹他发怒的时候一样。”'),
('CNV', '希伯来书', 58, 3, 16, '那时，听了他的话而惹他发怒的是谁呢？不就是摩西从埃及领出来的那些人吗？'),
('CNV', '希伯来书', 58, 3, 17, '四十年之久，神向谁发怒呢？不就是向那些犯了罪陈尸旷野的人吗？'),
('CNV', '希伯来书', 58, 3, 18, '他又向谁起誓说，他们绝对不可以进入他的安息呢？不就是向那些不顺从的人吗？'),
('CNV', '希伯来书', 58, 3, 19, '这样看来，他们不能进入安息，是因为不信的缘故。'),
('CNV', '希伯来书', 58, 4, 1, '所以，那进入安息的应许，既然还给我们留着，我们就应该战战兢兢，恐怕我们中间有人象是被淘汰了。'),
('CNV', '希伯来书', 58, 4, 2, '因为有福音传给我们，像传给他们一样，只是他们所听见的道，对他们没有益处，因为他们没有用信心与所听见的打成一片（“没有用信心与所听见的打成一片”，有古卷作“没有用信心与听从这道的人打成一片”）。'),
('CNV', '希伯来书', 58, 4, 3, '然而我们信了的人，就可以进入那安息。正如神所说：“我在烈怒中起誓说，他们绝不可进入我的安息！”其实神的工作，从创立世界以来已经完成了。'),
('CNV', '希伯来书', 58, 4, 4, '因为论到第七日，他在圣经某一处说：“在第七日神歇了他的一切工作。”'),
('CNV', '希伯来书', 58, 4, 5, '但在这里又说：“他们绝不可进入我的安息。”'),
('CNV', '希伯来书', 58, 4, 6, '既然这安息还留着要让一些人进去，但那些以前听过福音的人，因为不顺从不得进去；'),
('CNV', '希伯来书', 58, 4, 7, '所以神就再定一个日子，就是过了很久以后，藉着大卫所说的“今天”，就像前面引用过的：“如果你们今天听从他的声音，就不要硬着心。”'),
('CNV', '希伯来书', 58, 4, 8, '如果约书亚已经使他们享受了安息，神后来就不会再提到别的日子了。'),
('CNV', '希伯来书', 58, 4, 9, '这样看来，为了神的子民，必定另外有一个“安息日”的安息保留下来。'),
('CNV', '希伯来书', 58, 4, 10, '因为那进入神安息的人，就歇了自己的工作，好像神歇了自己的工作一样。'),
('CNV', '希伯来书', 58, 4, 11, '所以，我们要竭力进入那安息，免得有人随着那不顺从的样子就跌倒了。'),
('CNV', '希伯来书', 58, 4, 12, '因为神的道是活的，是有效的，比一切两刃的剑更锋利，甚至可以刺入剖开魂与灵，关节与骨髓，并且能够辨明心中的思想和意念。'),
('CNV', '希伯来书', 58, 4, 13, '被造的在神面前没有一样不是显明的，万有在他的眼前都是赤露敞开的；我们必须向他交帐。'),
('CNV', '希伯来书', 58, 4, 14, '我们既然有一位伟大的、经过了众天的大祭司，就是神的儿子耶稣，就应该坚持所宣认的信仰。'),
('CNV', '希伯来书', 58, 4, 15, '因为我们的大祭司并不是不能同情我们的软弱，他像我们一样，也曾在各方面受过试探，只是他没有犯罪。'),
('CNV', '希伯来书', 58, 4, 16, '所以，我们只管坦然无惧地来到施恩的宝座前，为的是要领受怜悯，得到恩惠，作为及时的帮助。'),
('CNV', '希伯来书', 58, 5, 1, '每一个大祭司都是从人间选出来，奉派替人办理与神有关的事，为的是要献上礼物和赎罪的祭物。'),
('CNV', '希伯来书', 58, 5, 2, '他能够温和地对待那些无知和迷误的人，因为他自己也被软弱所困。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '希伯来书', 58, 5, 3, '因此，他怎样为人民的罪献祭，也应该怎样为自己的罪献祭。'),
('CNV', '希伯来书', 58, 5, 4, '没有人可以自己取得这大祭司的尊荣，只有像亚伦一样，蒙神选召的才可以。'),
('CNV', '希伯来书', 58, 5, 5, '照样，基督也没有自己争取作大祭司的尊荣，而是曾经对他说：“你是我的儿子，我今日生了你”的神荣耀了他；'),
('CNV', '希伯来书', 58, 5, 6, '就像他在另一处说：“你是照着麦基洗德的体系，永远作祭司的。”'),
('CNV', '希伯来书', 58, 5, 7, '基督在世的时候，曾经流泪大声祷告恳求那位能救他脱离死亡的神；因着他的敬虔，就蒙了应允。'),
('CNV', '希伯来书', 58, 5, 8, '他虽然是儿子，还是因着所受的苦难学会了顺从。'),
('CNV', '希伯来书', 58, 5, 9, '他既然顺从到底（“他既然顺从到底”或译：“他既然达到完全”），就成了所有顺从他的人得到永远救恩的根源；'),
('CNV', '希伯来书', 58, 5, 10, '而且蒙神照着麦基洗德的体系，称他为大祭司。'),
('CNV', '希伯来书', 58, 5, 11, '论到这些事，我们有很多话要说，可是很难解释；因为你们已经迟钝了，听不进去。'),
('CNV', '希伯来书', 58, 5, 12, '到这个时候，你们应该已经作老师了；可是你们还需要有人再把神道理的初步教导你们。你们成了只能吃奶而不能吃干粮的人！'),
('CNV', '希伯来书', 58, 5, 13, '凡是吃奶的，还是个婴孩，对公义的道理没有经历；'),
('CNV', '希伯来书', 58, 5, 14, '只有长大成人的，才能吃干粮，他们的官能因为操练纯熟，就能分辨是非了。'),
('CNV', '希伯来书', 58, 6, 1, '所以，我们应当离开基督初步的道理，努力进到成熟的地步，不必在懊悔致死的行为，信靠神，洗礼，按手礼，死人复活，和永远审判的教训上再立根基。'),
('CNV', '希伯来书', 58, 6, 3, '只要神允许，我们就这样作。'),
('CNV', '希伯来书', 58, 6, 4, '因为那些曾经蒙了光照，尝过属天的恩赐的滋味，与圣灵有分，'),
('CNV', '希伯来书', 58, 6, 5, '并且尝过神美善的道和来世的权能的人，'),
('CNV', '希伯来书', 58, 6, 6, '如果偏离了正道，就不可能再使他们重新悔改了。因为他们亲自把神的儿子再钉在十字架上，公然羞辱他。'),
('CNV', '希伯来书', 58, 6, 7, '这就像一块地，吸收了常常下在它上面的雨水，如果长出对种植的人有用的菜蔬，就从神那里得福。'),
('CNV', '希伯来书', 58, 6, 8, '但如果这块地长出荆棘和蒺藜来，就被废弃，近于咒诅，结局就是焚烧。'),
('CNV', '希伯来书', 58, 6, 9, '不过，亲爱的弟兄们，我们虽然这样说，但对于你们，我们却深信你们有更好的表现，结局就是得救。'),
('CNV', '希伯来书', 58, 6, 10, '因为神并不是不公义，以致忘记了你们的工作，和你们为他的名所表现的爱心，就是你们以前服事圣徒，现在还是服事他们。'),
('CNV', '希伯来书', 58, 6, 11, '我们深愿你们各人都表现同样的热诚，一直到底，使你们的盼望可以完全实现，'),
('CNV', '希伯来书', 58, 6, 12, '并且不要懒惰，却要效法那些凭着信心和忍耐承受应许的人。'),
('CNV', '希伯来书', 58, 6, 13, '神应许亚伯拉罕的时候，因为没有比自己更大的可以指着起誓，他就指着自己起誓，'),
('CNV', '希伯来书', 58, 6, 14, '说：“我必定赐福给你，必定使你的后裔繁多。”'),
('CNV', '希伯来书', 58, 6, 15, '这样，亚伯拉罕耐心等待，终于获得了所应许的。'),
('CNV', '希伯来书', 58, 6, 16, '因为人起誓都是指着比自己大的起誓。这誓言就了结了他们中间的一切纠纷，作为保证。'),
('CNV', '希伯来书', 58, 6, 17, '照样，神定意向那些承受应许的人，更清楚地表明他的旨意是不更改的，就用起誓作保证。'),
('CNV', '希伯来书', 58, 6, 18, '这两件事是不能更改的，因为神是决不说谎的。因此，我们这些逃进避难所的人，就大得安慰，抓紧那摆在我们面前的盼望。'),
('CNV', '希伯来书', 58, 6, 19, '我们有这盼望，就像灵魂的锚，又稳当又坚固，通过幔子直进到里面。'),
('CNV', '希伯来书', 58, 6, 20, '耶稣已经为我们作先锋进入了幔子里面；他是照着麦基洗德的体系，成了永远的大祭司。'),
('CNV', '希伯来书', 58, 7, 1, '这麦基洗德就是撒冷王，又是至高神的祭司。亚伯拉罕杀败众王回来的时候，麦基洗德迎接他，并且给他祝福。'),
('CNV', '希伯来书', 58, 7, 2, '亚伯拉罕也把自己得来的一切，拿出十分之一来给他。麦基洗德这名字翻译出来，头一个意思就是“公义的王”；其次是“撒冷王”，就是“平安的王”的意思。'),
('CNV', '希伯来书', 58, 7, 3, '他没有父亲，没有母亲，没有族谱，也没有生死的记录，而是与神的儿子相似，永远作祭司。'),
('CNV', '希伯来书', 58, 7, 4, '你们想一想这人是多么伟大啊！祖先亚伯拉罕也要从上等的掳物中，拿出十分之一来给了他。'),
('CNV', '希伯来书', 58, 7, 5, '那些领受祭司职分的利未子孙，奉命按照律法向人民，就是自己的弟兄，收取十分之一；虽然他们都是出于亚伯拉罕的。'),
('CNV', '希伯来书', 58, 7, 6, '可是那不与他们同谱系的麦基洗德，反而收纳了亚伯拉罕的十分之一，并且给这蒙受应许的人祝福。'),
('CNV', '希伯来书', 58, 7, 7, '向来都是位分大的给位分小的祝福，这是毫无疑问的。'),
('CNV', '希伯来书', 58, 7, 8, '在这里，收取十分之一的，都是必死的；但在那里，收纳十分之一的，却被证实是一位活着的。'),
('CNV', '希伯来书', 58, 7, 9, '并且可以这样说，连那收取十分之一的利未，也透过亚伯拉罕缴纳了十分之一。'),
('CNV', '希伯来书', 58, 7, 10, '因为麦基洗德迎接亚伯拉罕的时候，利未还在他祖先的身体里面。'),
('CNV', '希伯来书', 58, 7, 11, '这样看来，如果藉着利未人的祭司制度能达到完全的地步（人民是在这制度下领受律法的），为什么还需要照着麦基洗德的体系，另外兴起一位祭司，而不照着亚伦的体系呢？'),
('CNV', '希伯来书', 58, 7, 12, '祭司的制度既然更改了，律法也必须更改。'),
('CNV', '希伯来书', 58, 7, 13, '因为这些话所指的那位，原是属于另外一个支派的，这支派向来没有人在祭坛前供职。'),
('CNV', '希伯来书', 58, 7, 14, '我们的主明明是从犹大支派出来的，关于这个支派，摩西并没有提及祭司的事。'),
('CNV', '希伯来书', 58, 7, 15, '如果有另一位像麦基洗德那样的祭司兴起来，那么，这里所说的就更明显了。'),
('CNV', '希伯来书', 58, 7, 16, '他成了祭司，不是按着律法上肉身的条例，却是按着不能毁坏的生命的大能。'),
('CNV', '希伯来书', 58, 7, 17, '因为有为他作证的说：“你永远作祭司，是照着麦基洗德的体系。”'),
('CNV', '希伯来书', 58, 7, 18, '一方面，从前的条例因为软弱，没有用处，就废弃了；'),
('CNV', '希伯来书', 58, 7, 19, '（因为律法从来没有使什么得到完全，）另一方面，它却带来了更美的盼望，藉着这盼望，我们就可以亲近神。'),
('CNV', '希伯来书', 58, 7, 20, '此外，还有关于誓言的事。其他成为祭司的，并不是用誓言立的；'),
('CNV', '希伯来书', 58, 7, 21, '只有耶稣是用誓言立的，因为那立他的对他说：“主已经起了誓，决不改变，你永远作祭司。”'),
('CNV', '希伯来书', 58, 7, 22, '耶稣既然是用誓言立的，就成了更美好的约的保证。'),
('CNV', '希伯来书', 58, 7, 23, '一方面，从前那些作祭司的，因为受死亡的限制，不能长久留任，所以人数众多。'),
('CNV', '希伯来书', 58, 7, 24, '另一方面，因为耶稣是永远长存的，就拥有他永不更改的祭司职位。'),
('CNV', '希伯来书', 58, 7, 25, '因此，那些靠着他进到神面前的人，他都能拯救到底；因为他长远活着，为他们代求。'),
('CNV', '希伯来书', 58, 7, 26, '这样的一位大祭司，对我们本是合适的。他是圣洁、没有邪恶、没有玷污、从罪人中分别出来、高过众天的。'),
('CNV', '希伯来书', 58, 7, 27, '他不必像那些大祭司，天天先为自己的罪献祭，然后为人民的罪献祭；因为他献上了自己，就把这事一次而永远的成全了。'),
('CNV', '希伯来书', 58, 7, 28, '律法所立的大祭司，都是软弱的人；可是在律法以后，用誓言所立的儿子，却是成为完全直到永远的。'),
('CNV', '希伯来书', 58, 8, 1, '我们所讲论的重点，就是我们有这样的一位大祭司，他已经坐在众天之上至尊者的宝座右边，'),
('CNV', '希伯来书', 58, 8, 2, '在至圣所和真会幕里供职；这真会幕是主支搭的，不是人支搭的。'),
('CNV', '希伯来书', 58, 8, 3, '所有大祭司都是为了献礼物和祭品而设立的，所以这位大祭司，也必须有所献上的。'),
('CNV', '希伯来书', 58, 8, 4, '如果他在地上，就不会作祭司，因为已经有按照律法献礼物的祭司了。'),
('CNV', '希伯来书', 58, 8, 5, '这些祭司所供奉的职事，不过是天上的事物的副本和影像，就如摩西将要造会幕的时候，神曾经警告他说：“你要留心，各样物件，都要照着在山上指示你的样式去作。”'),
('CNV', '希伯来书', 58, 8, 6, '但是现在耶稣得了更尊贵的职分，正好像他是更美的约的中保，这约是凭着更美的应许立的。'),
('CNV', '希伯来书', 58, 8, 7, '如果头一个约没有缺点，就没有寻求另一个约的必要了。'),
('CNV', '希伯来书', 58, 8, 8, '可是神指责他们，说：“看哪，主说，日子要到了，我要与以色列家和犹大家订立新约。'),
('CNV', '希伯来书', 58, 8, 9, '这新约不像从前我拉他们祖先的手，领他们出埃及的日子与他们所立的约。因为他们没有遵守我的约，我就不理会他们。这是主说的。'),
('CNV', '希伯来书', 58, 8, 10, '主说：‘因为在那些日子以后，我要与以色列家所立的约是这样：我要把我的律法放在他们的心思里面，写在他们的心上。我要作他们的神，他们要作我的子民。'),
('CNV', '希伯来书', 58, 8, 11, '他们各人必不用教导自己的邻居，和自己的同胞，说：你要认识主。因为所有的人，从最小到最大的，都必认识我。'),
('CNV', '希伯来书', 58, 8, 12, '我也要宽恕他们的不义，决不再记着他们的罪恶。’”'),
('CNV', '希伯来书', 58, 8, 13, '神既然说到新的约，就是把前约当作旧的了；那变成陈旧衰老的，就快要消逝了。'),
('CNV', '希伯来书', 58, 9, 1, '前约也有它敬拜的规例，和属世界的圣所。'),
('CNV', '希伯来书', 58, 9, 2, '因为有一个支搭好了的会幕，第一进叫作圣所，里面有灯台、桌子和陈设饼。'),
('CNV', '希伯来书', 58, 9, 3, '在第二层幔子后面还有一个会幕，叫作至圣所，'),
('CNV', '希伯来书', 58, 9, 4, '里面有金香坛，有全部包金的约柜，柜里有盛着吗哪的金罐、亚伦那发过芽的杖和两块约板。'),
('CNV', '希伯来书', 58, 9, 5, '柜的上面有荣耀的基路伯罩着施恩座，关于这一切，现在不能一一细说了。'),
('CNV', '希伯来书', 58, 9, 6, '这一切物件都这样预备好了，祭司就常常进入第一进会幕，执行敬拜的事。'),
('CNV', '希伯来书', 58, 9, 7, '至于第二进会幕，只有大祭司一年一次独自进去，并且非带着血不可，好为自己和人民的愚妄把血献上。'),
('CNV', '希伯来书', 58, 9, 8, '圣灵藉着这事表明，当第一进会幕存在的时候，进入至圣所的路，还没有显明出来。'),
('CNV', '希伯来书', 58, 9, 9, '这第一进会幕是现今的时代的预表，其实所献的礼物和祭品，都不能使敬拜的人在良心上得到完全。'),
('CNV', '希伯来书', 58, 9, 10, '这些只是关于饮食和各样洁净的礼仪，是在“更新的时候”来到之前，为肉体立的规例。'),
('CNV', '希伯来书', 58, 9, 11, '但基督已经来了，作了已经实现的美好事物的大祭司；他经过更大、更完备的会幕（不是人手所做的，也就是不属于这被造的世界的）。'),
('CNV', '希伯来书', 58, 9, 12, '他不是用山羊和牛犊的血，而是用自己的血，只一次进了至圣所，就得到了永远的救赎。'),
('CNV', '希伯来书', 58, 9, 13, '如果山羊和公牛的血，以及母牛犊的灰，洒在不洁的人身上，尚且可以使他们成为圣洁，身体洁净，'),
('CNV', '希伯来书', 58, 9, 14, '何况基督的血呢？他藉着永远的灵，把自己无瑕无疵的献给神，他的血不是更能洁净我们的良心脱离致死的行为，使我们可以事奉永活的神吗？'),
('CNV', '希伯来书', 58, 9, 15, '因此，他作了新约的中保，藉着他的死，使人在前约之下的过犯得到救赎，就叫那些蒙召的人，得着永远基业的应许。'),
('CNV', '希伯来书', 58, 9, 16, '凡有遗嘱（“遗嘱”或译：“约”，与17节同），必须证实立遗嘱的人死了；'),
('CNV', '希伯来书', 58, 9, 17, '因为人死了，遗嘱才能确立，立遗嘱的人还活着的时候，遗嘱决不生效。'),
('CNV', '希伯来书', 58, 9, 18, '因此，前约并不是没有用血立的：'),
('CNV', '希伯来书', 58, 9, 19, '当日摩西按照律法，向所有人民宣布了各样的诫命，就拿牛犊（好些抄本在此有“和山羊”）的血和水，用朱红色的羊毛与牛膝草，洒在律法书上和人民身上，'),
('CNV', '希伯来书', 58, 9, 20, '说：“这就是神规定你们立约的血。”'),
('CNV', '希伯来书', 58, 9, 21, '他照样把血洒在会幕和各样应用的器皿上。'),
('CNV', '希伯来书', 58, 9, 22, '按着律法，几乎所有都是用血洁净的，如果没有流血，就没有赦免。'),
('CNV', '希伯来书', 58, 9, 23, '照着天上样式作的既然必须这样去洁净，天上物体的本身，就应该用更美的祭品去洁净了。'),
('CNV', '希伯来书', 58, 9, 24, '因为基督不是进了人手所做的圣所（那不过是真圣所的表象），而是进到天上，现在替我们显露在神的面前。'),
('CNV', '希伯来书', 58, 9, 25, '他不必多次把自己献上，好像大祭司每年带着不是自己的血进入至圣所一样。'),
('CNV', '希伯来书', 58, 9, 26, '如果这样，他从创世以来，就必须受许多次的苦了。可是现在他在这世代的终结，只显现一次，把自己作为祭品献上，好除掉罪。'),
('CNV', '希伯来书', 58, 9, 27, '按着定命，人人都要死一次，死后还有审判。'),
('CNV', '希伯来书', 58, 9, 28, '照样，基督为了担当许多人的罪，也曾经一次把自己献上；将来他还要再一次显现，不是为担当罪，而是要向那些热切期待他的人成全救恩。'),
('CNV', '希伯来书', 58, 10, 1, '律法既然是以后要来的美好事物的影子，不是本体的真象，就不能凭着每年献同样的祭品，使那些进前来的人得到完全。'),
('CNV', '希伯来书', 58, 10, 2, '如果敬拜的人一次得洁净，良心就不再觉得有罪，那么，献祭的事不是早就停止了吗？'),
('CNV', '希伯来书', 58, 10, 3, '可是那些祭品，却使人每年都想起罪来，'),
('CNV', '希伯来书', 58, 10, 4, '因为公牛和山羊的血不能把罪除去。'),
('CNV', '希伯来书', 58, 10, 5, '所以，基督到世上来的时候，就说：“祭品和礼物不是你所要的，你却为我预备了身体。'),
('CNV', '希伯来书', 58, 10, 6, '燔祭和赎罪祭，不是你所喜悦的；'),
('CNV', '希伯来书', 58, 10, 7, '那时我说：‘看哪！我来了，经卷上已经记载我的事，神啊！我来是要遵行你的旨意。’”'),
('CNV', '希伯来书', 58, 10, 8, '前面说：“祭品和礼物，燔祭和赎罪祭，不是你所要的，也不是你所喜悦的。”这些都是按照律法献的；'),
('CNV', '希伯来书', 58, 10, 9, '接着又说：“看哪！我来了，是要遵行你的旨意。”可见他废除那先前的，为要建立那后来的。'),
('CNV', '希伯来书', 58, 10, 10, '我们凭着这旨意，藉着耶稣基督一次献上他的身体，就已经成圣。'),
('CNV', '希伯来书', 58, 10, 11, '所有的祭司都是天天站着事奉，多次献上同样的祭品，那些祭品永远不能把罪除去。'),
('CNV', '希伯来书', 58, 10, 12, '唯有基督献上了一次永远有效的赎罪祭，就在神的右边坐下来。'),
('CNV', '希伯来书', 58, 10, 13, '此后，只是等待神把他的仇敌放在他的脚下，作他的脚凳。'),
('CNV', '希伯来书', 58, 10, 14, '因为他献上了一次的祭，就使那些成圣的人永远得到完全。'),
('CNV', '希伯来书', 58, 10, 15, '圣灵也向我们作见证，因为后来他说过：'),
('CNV', '希伯来书', 58, 10, 16, '“主说：‘在那些日子以后，我要与他们所立的约是这样：我要把我的律法放在他们的心思里面，写在他们的心上。’”'),
('CNV', '希伯来书', 58, 10, 17, '又说：“我决不再记着他们的罪恶，和不法的行为。”'),
('CNV', '希伯来书', 58, 10, 18, '这一切既然都赦免了，就不必再为罪献祭了。'),
('CNV', '希伯来书', 58, 10, 19, '所以，弟兄们！我们凭着耶稣的血，可以坦然无惧地进入至圣所。'),
('CNV', '希伯来书', 58, 10, 20, '这进入的路，是他给我们开辟的，是一条通过幔子、又新又活的路，这幔子就是他的身体。'),
('CNV', '希伯来书', 58, 10, 21, '我们既然有一位伟大的祭司治理神的家，'),
('CNV', '希伯来书', 58, 10, 22, '我们良心的邪恶既然被洒净，身体也用清水洗净了，那么，我们就应该怀着真诚的心和完备的信，进到神面前；'),
('CNV', '希伯来书', 58, 10, 23, '又应该坚持我们所宣认的盼望，毫不动摇，因为那应许我们的是信实的。'),
('CNV', '希伯来书', 58, 10, 24, '我们又应该彼此关心，激发爱心，勉励行善。'),
('CNV', '希伯来书', 58, 10, 25, '我们不可放弃聚会，好像有些人的习惯一样；却要互相劝勉。你们既然知道那日子临近，就更应该这样。'),
('CNV', '希伯来书', 58, 10, 26, '如果我们领受了真理的知识以后，还是故意犯罪，就再没有留下赎罪的祭品了；'),
('CNV', '希伯来书', 58, 10, 27, '只好恐惧地等待着审判，和那快要吞灭众仇敌的烈火。'),
('CNV', '希伯来书', 58, 10, 28, '如果有人干犯了摩西的律法，凭着两三个证人，他尚且得不到怜悯而死；'),
('CNV', '希伯来书', 58, 10, 29, '何况是践踏神的儿子，把那使他成圣的立约的血当作俗物，又侮辱施恩的圣灵的人，你们想想，他不是应该受更严厉的刑罚吗？'),
('CNV', '希伯来书', 58, 10, 30, '因为我们知道谁说过：“伸冤在我，我必报应。”又说：“主必定审判他自己的子民。”'),
('CNV', '希伯来书', 58, 10, 31, '落在永活的神手里，真是可怕的。'),
('CNV', '希伯来书', 58, 10, 32, '你们要回想从前的日子，那时，你们蒙了光照，忍受了许多痛苦的煎熬；'),
('CNV', '希伯来书', 58, 10, 33, '有时在众人面前被辱骂，遭患难；有时却成了遭遇同样情形的人的同伴。'),
('CNV', '希伯来书', 58, 10, 34, '你们同情那些遭监禁的人；你们的家业被抢夺的时候，又以喜乐的心接受，因为知道自己有更美长存的家业。'),
('CNV', '希伯来书', 58, 10, 35, '所以，你们不可丢弃坦然无惧的心，这样的心是带有大赏赐的。'),
('CNV', '希伯来书', 58, 10, 36, '你们还需要忍耐，好使你们行完了神的旨意，可以领受所应许的。'),
('CNV', '希伯来书', 58, 10, 37, '因为：“还有一点点的时候，那要来的就来，并不迟延。'),
('CNV', '希伯来书', 58, 10, 38, '我的义人必因信得生，如果他后退，我的心就不喜悦他。”'),
('CNV', '希伯来书', 58, 10, 39, '但我们不是那些后退以致灭亡的人，而是有信心以致保全生命的人。'),
('CNV', '希伯来书', 58, 11, 1, '信就是对所盼望的事的把握，是还看不见之事的明证。'),
('CNV', '希伯来书', 58, 11, 2, '因着这信心，古人得到了称许。'),
('CNV', '希伯来书', 58, 11, 3, '因着信，我们就明白宇宙（“宇宙”或译：“诸世界”或“众世代”）是因着神的话造成的。这样，那看得见的就是从那看不见的造出来的。'),
('CNV', '希伯来书', 58, 11, 4, '因着信，亚伯比该隐献上更美的祭品给神；藉着这信心，他被神称许为义人，这是神指着他的礼物所作的见证；他虽然死了，却藉着信仍然说话。'),
('CNV', '希伯来书', 58, 11, 5, '因着信，以诺被迁去了，使他不至于死，人也找不着他，因为神把他迁去了。原来在迁去以前，他已经得了神喜悦他的明证。'),
('CNV', '希伯来书', 58, 11, 6, '没有信，就不能得到神的喜悦；因为来到神面前的人，必须信神存在，并且信他会赏赐那些寻求他的人。'),
('CNV', '希伯来书', 58, 11, 7, '因着信，挪亚在还没有看见的事上，得了神的警告，就动了敬畏的心，做了一艘方舟，使他全家得救。藉着这信心，他就定了那世代的罪，自己也承受了那因信而来的义。'),
('CNV', '希伯来书', 58, 11, 8, '因着信，亚伯拉罕在蒙召的时候，就听命往他将要承受为业的地方去；他出去的时候，还不知道要往哪里去。'),
('CNV', '希伯来书', 58, 11, 9, '因着信，他在应许之地寄居，好像是在异乡，与承受同样应许的以撒、雅各一样住在帐棚里。'),
('CNV', '希伯来书', 58, 11, 10, '因为他等待那座有根基的城，就是神所设计所建造的。'),
('CNV', '希伯来书', 58, 11, 11, '因着信，甚至撒拉，她虽然过了生育的年龄，还是能够怀孕，因为她认为那应许她的是信实的。'),
('CNV', '希伯来书', 58, 11, 12, '所以从一个好像已死的人，竟然生出许多子孙来，仿佛天上的星那么众多，海边的沙那么无数。'),
('CNV', '希伯来书', 58, 11, 13, '这些人都是存着信心死了的，还没有得着所应许的，只不过是从远处看见，就表示欢迎，又承认他们在世上是异乡人，是客旅。'),
('CNV', '希伯来书', 58, 11, 14, '因为说这样话的人，是表明他们在寻求一个家乡。'),
('CNV', '希伯来书', 58, 11, 15, '如果他们怀念已经离开了的地方，还有可以回去的机会。'),
('CNV', '希伯来书', 58, 11, 16, '但是现在他们所向往的，是一个更美的、在天上的家乡。所以，神不以他们称他为神而觉得羞耻；因为他已经为他们预备了一座城。'),
('CNV', '希伯来书', 58, 11, 17, '因着信，亚伯拉罕在受试验的时候，就把以撒献上；这就是那欢喜领受应许的人，献上了自己的独生子；'),
('CNV', '希伯来书', 58, 11, 18, '论到这个儿子，曾经有话说：“以撒生的，才可以称为你的后裔。”'),
('CNV', '希伯来书', 58, 11, 19, '亚伯拉罕认定，神能使人从死人中复活，因此，就喻意说，他的确从死里得回他的儿子。'),
('CNV', '希伯来书', 58, 11, 20, '因着信，以撒给雅各和以扫祝福，论到将来的事。'),
('CNV', '希伯来书', 58, 11, 21, '因着信，雅各临死的时候，分别为约瑟的儿子祝福，又倚着杖头敬拜神。'),
('CNV', '希伯来书', 58, 11, 22, '因着信，约瑟临终的时候，提到以色列子民出埃及的事，并且为自己的骸骨留下遗言。'),
('CNV', '希伯来书', 58, 11, 23, '因着信，摩西的父母在摩西生下来以后，因为看见孩子俊美，就把他藏了三个月，不怕王的命令。'),
('CNV', '希伯来书', 58, 11, 24, '因着信，摩西长大了以后，就拒绝被称为法老女儿的儿子。'),
('CNV', '希伯来书', 58, 11, 25, '他宁愿选择和神的子民一同受苦，也不肯享受罪恶中暂时的快乐。'),
('CNV', '希伯来书', 58, 11, 26, '在他看来，为着基督受的凌辱，比埃及的财物更宝贵，因为他注视将来的赏赐。'),
('CNV', '希伯来书', 58, 11, 27, '因着信，他离开了埃及，不怕王的忿怒；因为他坚定不移，就像看见了人不能看见的神。'),
('CNV', '希伯来书', 58, 11, 28, '因着信，他立了逾越节和洒血的礼，免得那灭命的侵犯以色列人的长子。'),
('CNV', '希伯来书', 58, 11, 29, '因着信，他们走过了红海，好像走过旱地一样；埃及人也试着要过去，就被淹没了。'),
('CNV', '希伯来书', 58, 11, 30, '因着信，耶利哥的城墙被围绕了七天，就倒塌了。'),
('CNV', '希伯来书', 58, 11, 31, '因着信，妓女喇合和和平平接待了侦察的人，就没有和那些不顺从的人一起灭亡。'),
('CNV', '希伯来书', 58, 11, 32, '我还要再说什么呢？如果再要述说基甸、巴拉、参孙、耶弗他、大卫、撒母耳和众先知的事，时间就不够了。'),
('CNV', '希伯来书', 58, 11, 33, '他们藉着信，就战胜了敌国，伸张了正义，得到了应许，堵住了狮子的口，'),
('CNV', '希伯来书', 58, 11, 34, '消灭了烈火的威力，逃脱了刀剑的锋刃，软弱变成刚强，在战争中显出大能，把外国的军队击退。'),
('CNV', '希伯来书', 58, 11, 35, '有些妇女得回从死里复活的亲人；但也有些人忍受了酷刑，不肯接受释放，为的是要得着更美的复活。'),
('CNV', '希伯来书', 58, 11, 36, '又有些人遭受了戏弄、鞭打，甚至捆锁、监禁；'),
('CNV', '希伯来书', 58, 11, 37, '被石头打死，被锯锯死，（后期抄本在此加上“受试探”）被刀杀死。他们披着绵羊山羊的皮到处奔跑、受穷乏、遭患难、被虐待；'),
('CNV', '希伯来书', 58, 11, 38, '原是这世界不配有的人。他们飘流无定，在旷野、山岭、石洞和地穴栖身。'),
('CNV', '希伯来书', 58, 11, 39, '所有这些人都藉着信得了称许，却还没有得着所应许的；'),
('CNV', '希伯来书', 58, 11, 40, '因为神已经为我们预备了更美的事，使他们若不跟我们在一起，就不能完全。'),
('CNV', '希伯来书', 58, 12, 1, '所以，我们既然有这么多的见证人，像云彩围绕着我们，就应该脱下各样的拖累，和容易缠住我们的罪，以坚忍的心奔跑那摆在我们面前的赛程；'),
('CNV', '希伯来书', 58, 12, 2, '专一注视耶稣，就是那位信心的创造者和完成者。他因为那摆在面前的喜乐，就忍受了十字架，轻看了羞辱，现在就坐在神宝座的右边。'),
('CNV', '希伯来书', 58, 12, 3, '这位忍受罪人那样顶撞的耶稣，你们要仔细思想，免得疲倦灰心。'),
('CNV', '希伯来书', 58, 12, 4, '你们与罪恶斗争，还没有对抗到流血的地步；'),
('CNV', '希伯来书', 58, 12, 5, '你们又忘记了那劝你们好像劝儿子的话，说：“我儿！你不可轻看主的管教，受责备的时候也不要灰心；'),
('CNV', '希伯来书', 58, 12, 6, '因为主所爱的，他必管教，他又鞭打所收纳的每一个儿子。”'),
('CNV', '希伯来书', 58, 12, 7, '为了接受管教，你们要忍受，因为神待你们好像待儿子一样；哪有儿子不受父亲管教的呢？'),
('CNV', '希伯来书', 58, 12, 8, '作儿子的都受过管教。如果你们没有受管教，就是私生子，不是儿子了。'),
('CNV', '希伯来书', 58, 12, 9, '还有，肉身的父亲管教我们，我们尚且敬重他们；何况那万灵的父，我们不是更要顺服他而得生吗？'),
('CNV', '希伯来书', 58, 12, 10, '肉身的父亲照着自己的意思管教我们，只有短暂的日子；唯有神管教我们，是为着我们的好处，使我们在他的圣洁上有分。'),
('CNV', '希伯来书', 58, 12, 11, '但是一切管教，在当时似乎不觉得快乐，反觉得痛苦；后来却为那些经过这种操练的人，结出平安的果子来，就是义。'),
('CNV', '希伯来书', 58, 12, 12, '所以，你们要把下垂的手和发软的腿挺直起来；'),
('CNV', '希伯来书', 58, 12, 13, '也要把你们所走的道路修直，使瘸子不至于扭脚，反而得到复原。'),
('CNV', '希伯来书', 58, 12, 14, '你们要竭力寻求与众人和睦，并且要竭力追求圣洁。如果没有圣洁，谁也不能见主。'),
('CNV', '希伯来书', 58, 12, 15, '你们要小心，免得有人失去了神的恩典；免得有苦根长起来缠绕你们，因而污染了许多人；'),
('CNV', '希伯来书', 58, 12, 16, '又免得有人成为淫乱的和贪恋世俗的，好像以扫一样，为了一点点食物，竟把自己长子的名分出卖了。'),
('CNV', '希伯来书', 58, 12, 17, '你们知道，后来以扫想要承受祝福，却被拒绝了；他虽然带着眼泪寻求，还是没有反悔的余地。'),
('CNV', '希伯来书', 58, 12, 18, '你们不是来到那座摸得着的山。那里有烈火、密云、幽暗、暴风、'),
('CNV', '希伯来书', 58, 12, 19, '号筒的响声和说话的声音；那些听见这声音的人，都请求神不要再向他们多说话；'),
('CNV', '希伯来书', 58, 12, 20, '因为他们担当不起那命令：“就是走兽挨近这山，也要用石头把它打死。”'),
('CNV', '希伯来书', 58, 12, 21, '当时，显出的景象是那么可怕，连摩西也说：“我非常恐惧战兢。”'),
('CNV', '希伯来书', 58, 12, 22, '你们却是来到锡安山和永活的神的城，就是天上的耶路撒冷；在那里有千万的天使聚集，'),
('CNV', '希伯来书', 58, 12, 23, '有名字登记在天上众长子的教会，有审判众人的神，有被成全的义人的灵魂，'),
('CNV', '希伯来书', 58, 12, 24, '有新约的中保耶稣，还有他所洒的血。这血所传的信息比亚伯的血所传的更美。'),
('CNV', '希伯来书', 58, 12, 25, '你们要谨慎，不要弃绝那位说话的，因为从前的人弃绝了那位在地上警戒他们的，尚且不能逃罪；何况现在我们背弃那位从天上警戒我们的呢？'),
('CNV', '希伯来书', 58, 12, 26, '当时他的声音震动了地；现在他却应许说：“下一次，我不但要震动地，还要震动天。”'),
('CNV', '希伯来书', 58, 12, 27, '“下一次”这句话，是表明那些被震动的，要像被造之物那样被除去，好使那些不能震动的可以留存，'),
('CNV', '希伯来书', 58, 12, 28, '因此，我们既然领受了不能震动的国，就应该感恩，照着神所喜悦的，用虔诚敬畏的心事奉他；'),
('CNV', '希伯来书', 58, 12, 29, '因为我们的神是烈火。'),
('CNV', '希伯来书', 58, 13, 1, '你们总要保持弟兄的爱。'),
('CNV', '希伯来书', 58, 13, 2, '不要忘了用爱心接待人，有人就是这样作，在无意中就款待了天使。'),
('CNV', '希伯来书', 58, 13, 3, '你们要记念那些被囚禁的人，好像跟他们一起被囚禁；也要记念那些受虐待的人，好像你们也亲自受过。'),
('CNV', '希伯来书', 58, 13, 4, '人人都应该尊重婚姻，婚床也不要玷污，因为神一定审判淫乱的和奸淫的人。'),
('CNV', '希伯来书', 58, 13, 5, '你们为人不要贪爱钱财，要以现在所有的为满足；因为神亲自说过：“我决不撇下你，也不离弃你。”'),
('CNV', '希伯来书', 58, 13, 6, '所以我们可以放胆说：“主是我的帮助，我决不害怕，人能把我怎么样呢？”'),
('CNV', '希伯来书', 58, 13, 7, '你们要记念那些领导过你们，把神的道传给你们的人；你们要观察他们一生的成果，要效法他们的信心。'),
('CNV', '希伯来书', 58, 13, 8, '耶稣基督昨天、今天、一直到永远都是一样的。'),
('CNV', '希伯来书', 58, 13, 9, '你们不要被各样怪异的教训勾引去了。人心靠着恩典，而不是靠着食物得到坚定，才是好的；因为那些拘守食物的人，从来没有得过益处。'),
('CNV', '希伯来书', 58, 13, 10, '我们有一座祭坛，坛上的祭物，是那些在会幕中供职的人没有权利吃的。'),
('CNV', '希伯来书', 58, 13, 11, '那些祭牲的血，由大祭司带进圣所作赎罪祭，祭牲的身体却要在营外焚烧。'),
('CNV', '希伯来书', 58, 13, 12, '所以耶稣也是这样在城门外受苦，为的是要藉着自己的血使人民成圣。'),
('CNV', '希伯来书', 58, 13, 13, '那么，让我们也出到营外到他那里去，担当他的凌辱。'),
('CNV', '希伯来书', 58, 13, 14, '因为在这里我们没有长存的城，我们却是寻求那将要来的城。'),
('CNV', '希伯来书', 58, 13, 15, '所以，我们要藉着耶稣，常常把颂赞的祭品献给神，这就是承认他的名的人嘴唇的果子。'),
('CNV', '希伯来书', 58, 13, 16, '你们也不要忘记行善和捐输，这样的祭是神所喜悦的。'),
('CNV', '希伯来书', 58, 13, 17, '你们要听从那些领导你们的人，也要顺服他们；因为他们为你们的灵魂警醒，好像要交帐的人一样。你们要使他们交帐的时候快快乐乐，不至于叹息；如果他们叹息，对你们就没有好处了。'),
('CNV', '希伯来书', 58, 13, 18, '请为我们祷告，因为我们深信自己良心无亏，愿意凡事遵行正道。'),
('CNV', '希伯来书', 58, 13, 19, '我更加要求你们为我们祷告，好使我们能够快点回到你们那里去。'),
('CNV', '希伯来书', 58, 13, 20, '愿赐平安的神，就是那凭着永约的血，把群羊的大牧人我们的主耶稣，从死人中领出来的那一位，'),
('CNV', '希伯来书', 58, 13, 21, '在一切善事上成全你们，好使你们遵行他的旨意；又藉着耶稣基督在我们里面，行他所喜悦的事。愿荣耀归给他，直到永永远远。阿们。'),
('CNV', '希伯来书', 58, 13, 22, '弟兄们，我劝你们耐心接受我这劝勉的话，因为我只是简略地写给你们。'),
('CNV', '希伯来书', 58, 13, 23, '你们要知道，我们的弟兄提摩太已经释放了；如果他来得早，我就跟他一起去看你们。'),
('CNV', '希伯来书', 58, 13, 24, '请问候所有领导你们的人和所有圣徒。从意大利来的人也问候你们。'),
('CNV', '希伯来书', 58, 13, 25, '愿恩惠与你们众人同在。'),
('CNV', '雅各书', 59, 1, 1, '神和主耶稣基督的仆人雅各，向散居各地的十二支派问安。'),
('CNV', '雅各书', 59, 1, 2, '我的弟兄们，你们遭遇各种试炼的时候，都要看为喜乐；'),
('CNV', '雅各书', 59, 1, 3, '因为知道你们的信心经过考验，就产生忍耐。'),
('CNV', '雅各书', 59, 1, 4, '但忍耐要坚持到底（“坚持到底”原文作“有完全的功效”），使你们可以完全，毫无缺乏。'),
('CNV', '雅各书', 59, 1, 5, '你们中间若有人缺少智慧，就当向那厚赐众人，而且不斥责人的神祈求，他就必得着。'),
('CNV', '雅各书', 59, 1, 6, '可是，他应该凭着信心祈求，不要有疑惑；因为疑惑的人，就像被风吹荡翻腾的海浪。'),
('CNV', '雅各书', 59, 1, 7, '那样的人，不要想从主得到什么；'),
('CNV', '雅各书', 59, 1, 8, '因为三心两意的人，在他的一切道路上，都摇摆不定。'),
('CNV', '雅各书', 59, 1, 9, '卑微的弟兄应当以高升为荣；'),
('CNV', '雅各书', 59, 1, 10, '富足的也不应该以降卑为辱；因为他如同草上的花，必要过去。'),
('CNV', '雅各书', 59, 1, 11, '太阳一出，热风一吹，草必枯干，花必凋谢，它的美容就消失了；富足的人也必在他的奔波经营中这样衰落。'),
('CNV', '雅各书', 59, 1, 12, '能忍受试炼的人，是有福的；因为他经过考验之后，必得着生命的冠冕，这冠冕是主应许给爱他的人的。'),
('CNV', '雅各书', 59, 1, 13, '人被试探，不可说“我被神试探”；因为神不能被恶试探，他也不试探任何人。'),
('CNV', '雅各书', 59, 1, 14, '每一个人受试探，都是被自己的私欲所勾引诱惑的。'),
('CNV', '雅各书', 59, 1, 15, '私欲怀了胎，就生出罪；罪长成了，就产生死亡。'),
('CNV', '雅各书', 59, 1, 16, '我亲爱的弟兄们，不要看错了。'),
('CNV', '雅各书', 59, 1, 17, '各样美好的赏赐，各样完备的恩赐，都是从上面、从众光之父降下来的，他本身并没有改变，也没有转动的影子。'),
('CNV', '雅各书', 59, 1, 18, '他凭着自己的旨意，藉着真理的道生了我们，使我们作他所造的万物中初熟的果子。'),
('CNV', '雅各书', 59, 1, 19, '我亲爱的弟兄们，你们要知道，人人都应该快快地听，慢慢地说，慢一点动怒；'),
('CNV', '雅各书', 59, 1, 20, '因为人的忿怒并不能成全神的义。'),
('CNV', '雅各书', 59, 1, 21, '所以你们应当摆脱一切污秽和所有的邪恶，以温柔的心领受神栽种的道；这道能救你们的灵魂。'),
('CNV', '雅各书', 59, 1, 22, '你们应该作行道的人，不要单作听道的人，自己欺骗自己；'),
('CNV', '雅各书', 59, 1, 23, '因为人若只作听道的人，不作行道的人，他就像一个人对着镜子看自己本来的面貌，'),
('CNV', '雅各书', 59, 1, 24, '看过走开以后，马上就忘记自己的样子。'),
('CNV', '雅各书', 59, 1, 25, '唯有详细察看那使人自由的全备的律法，并且时常遵守的人，他不是听了就忘记，而是实行出来，就必因自己所作的蒙福。'),
('CNV', '雅各书', 59, 1, 26, '如果有人自以为虔诚，却不约束他的舌头，反而自己欺骗自己，这人的虔诚是没有用的。'),
('CNV', '雅各书', 59, 1, 27, '在父神看来，纯洁无玷污的虔诚，就是照顾患难中的孤儿寡妇，并且保守自己不被世俗所污染。'),
('CNV', '雅各书', 59, 2, 1, '我的弟兄们，你们既然对我们荣耀的主耶稣基督有信心，就不应该凭外貌待人。'),
('CNV', '雅各书', 59, 2, 2, '如果有一个手戴金戒指、身穿华丽衣服的人，进入你们的会堂；又有一个衣衫褴褛的穷人，也进去了。'),
('CNV', '雅各书', 59, 2, 3, '你们就看重那穿华丽衣服的人，说：“请坐在这好位上。”又对那个穷人说：“你站在那里。”或说：“坐在我的脚凳下边。”'),
('CNV', '雅各书', 59, 2, 4, '这不是你们对人有歧视，成了心怀恶意的审判官吗？'),
('CNV', '雅各书', 59, 2, 5, '我亲爱的弟兄们，请听：神不是拣选了在世上被认为贫穷的人吗？这些人却在信心上富足，而且是承受神的国的人。这国是神应许赐给爱他的人的。'),
('CNV', '雅各书', 59, 2, 6, '然而你们却侮辱穷人。其实，那些欺压你们，拉你们上法庭的，不就是富足的人吗？'),
('CNV', '雅各书', 59, 2, 7, '难道不是他们亵渎那召你们的尊名吗？（或译：“难道不是他们毁谤你们蒙召的美名吗？”）'),
('CNV', '雅各书', 59, 2, 8, '你们若照着圣经所说“要爱人如己”这话，去完成这至尊的律法，你们就作对了。'),
('CNV', '雅各书', 59, 2, 9, '如果你们凭外貌待人，就是犯罪，律法就要裁定你们是犯法的。'),
('CNV', '雅各书', 59, 2, 10, '因为凡是遵守全部律法的，只要在一条上失足，就违犯所有的了。'),
('CNV', '雅各书', 59, 2, 11, '就像那说“不可奸淫”的，也说“不可杀人”；你纵然不奸淫，却杀人，还是犯法的。'),
('CNV', '雅各书', 59, 2, 12, '你们既然按着使人自由的律法受审判，就应照着这律法说话行事。'),
('CNV', '雅各书', 59, 2, 13, '因为对不行怜悯的人，审判他们的时候就没有怜悯；怜悯胜过审判。'),
('CNV', '雅各书', 59, 2, 14, '我的弟兄们，人若说他有信心，却没有行为，有什么益处呢？这信心能救他吗？'),
('CNV', '雅各书', 59, 2, 15, '如果有弟兄或姊妹缺衣少食，'),
('CNV', '雅各书', 59, 2, 16, '而你们中间有人对他们说：“平平安安地去吧！愿你们穿得暖，吃得饱。”却不给他们身体所需用的，那有什么用处呢？'),
('CNV', '雅各书', 59, 2, 17, '照样，如果只有信心，没有行为，这信心就是死的。'),
('CNV', '雅各书', 59, 2, 18, '也许有人要说，你有信心，我有行为；请把你没有行为的信心指给我看，我就藉着我的行为，把我的信心指给你看。'),
('CNV', '雅各书', 59, 2, 19, '你信神只有一位，你信的不错；就连鬼魔也信，却是战兢。'),
('CNV', '雅各书', 59, 2, 20, '愚昧的人哪，你愿意知道没有行为的信心是没有用的吗？'),
('CNV', '雅各书', 59, 2, 21, '我们的祖先亚伯拉罕，把他的儿子以撒献在祭坛上，不是因行为称义吗？'),
('CNV', '雅各书', 59, 2, 22, '你看，他的信心与行为是一致的，信心就因着行为得到完全了；'),
('CNV', '雅各书', 59, 2, 23, '这正应验了经上所说的：“亚伯拉罕信神，这就算为他的义。”他也被称为神的朋友。'),
('CNV', '雅各书', 59, 2, 24, '可见人称义是因着行为，不仅是因着信心。'),
('CNV', '雅各书', 59, 2, 25, '照样，妓女喇合接待了探子，又从另一条路把他们送走，不也是因行为称义吗？'),
('CNV', '雅各书', 59, 2, 26, '身体没有灵魂是死的，照样，信心没有行为也是死的。'),
('CNV', '雅各书', 59, 3, 1, '我的弟兄们，你们不应该有太多人作教师，因为知道我们作教师的将受更严厉的审判。'),
('CNV', '雅各书', 59, 3, 2, '我们在许多的事上都有过错，假如有人在言语上没有过错，他就是完全的人，也能够控制全身。'),
('CNV', '雅各书', 59, 3, 3, '我们若把嚼环扣入马嘴，使它们驯服，就能驾驭它们的全身。'),
('CNV', '雅各书', 59, 3, 4, '试看，船只虽然甚大，又被狂风催逼，舵手只用小小的舵，就可以随意操纵。'),
('CNV', '雅各书', 59, 3, 5, '照样，舌头虽然是个小肢体，却会说夸大的话。试看，星星之火，可以燎原；'),
('CNV', '雅各书', 59, 3, 6, '舌头就是火，在我们百体中，是个不义的世界，能污秽全身，把整个生命在运转中焚烧起来，而且是被地狱之火点燃的。'),
('CNV', '雅各书', 59, 3, 7, '各类飞禽、走兽、昆虫、水族，都可以驯服，而且都已经被人类制伏了；'),
('CNV', '雅各书', 59, 3, 8, '可是没有人能够制伏舌头；它是喋喋不休的恶物，充满了致命的毒素。'),
('CNV', '雅各书', 59, 3, 9, '我们用它来称颂我们的主和天父，又用它来咒诅照神的形象被造的人。'),
('CNV', '雅各书', 59, 3, 10, '同一张嘴竟然又称颂主，又咒诅人；我的弟兄们，这是不应该的！'),
('CNV', '雅各书', 59, 3, 11, '泉源能够从同一个出口涌出甜水和苦水来吗？'),
('CNV', '雅各书', 59, 3, 12, '我的弟兄们，无花果树能结橄榄吗？葡萄树能长无花果吗？咸水也不能发出甜水来。'),
('CNV', '雅各书', 59, 3, 13, '你们中间谁是有智慧、有见识的呢？他就应当有美好的生活，用明智的温柔，把自己的行为表现出来。'),
('CNV', '雅各书', 59, 3, 14, '如果你们心中存着刻薄的嫉妒和自私，就不可夸口，也不可说谎抵挡真理。'),
('CNV', '雅各书', 59, 3, 15, '这种智慧不是从天上来的，而是属地的、属血气的和属鬼魔的。'),
('CNV', '雅各书', 59, 3, 16, '因为凡有嫉妒和自私的地方，就必有扰乱和各样的坏事。'),
('CNV', '雅各书', 59, 3, 17, '至于从天上来的智慧，首先是纯洁的，其次是和平的，温柔的，谦逊的，满有恩慈和善果，没有偏袒，没有虚伪。'),
('CNV', '雅各书', 59, 3, 18, '这是缔造和平的人，用和平所培植出来的义果。'),
('CNV', '雅各书', 59, 4, 1, '你们中间的争执和打斗是从哪里来的呢？不是从你们肢体中好斗的私欲来的吗？'),
('CNV', '雅各书', 59, 4, 2, '你们放纵贪欲，如果得不到，就杀人；你们嫉妒，如果一无所得，就打斗争执。你们得不到，因为你们不求；'),
('CNV', '雅各书', 59, 4, 3, '你们求也得不到，因为你们的动机不良，要把所得的耗费在你们的私欲上。'),
('CNV', '雅各书', 59, 4, 4, '淫乱的人哪，你们不知道与世俗为友，就是与神为敌吗？所以与世俗为友的，就成了神的仇敌。'),
('CNV', '雅各书', 59, 4, 5, '圣经说：“神爱他那安置在我们里面的灵，爱到嫉妒的地步”（或译：“神安置在我们里面的灵，爱到嫉妒的地步”），你们想这话是徒然的吗？'),
('CNV', '雅各书', 59, 4, 6, '但神所赐的恩更大；所以圣经上说：“神对抗骄傲的人，赐恩给谦卑的人。”'),
('CNV', '雅各书', 59, 4, 7, '你们应当顺服神，抵挡魔鬼，魔鬼就逃避你们。'),
('CNV', '雅各书', 59, 4, 8, '你们应当亲近神，神就亲近你们。罪人啊，要洁净你们的手；三心两意的人哪，要清洁你们的心。'),
('CNV', '雅各书', 59, 4, 9, '你们要愁苦、悲哀、哭泣，把欢笑变为伤痛，把快乐变为忧愁。'),
('CNV', '雅各书', 59, 4, 10, '你们务要在主面前谦卑，他就使你们高升。'),
('CNV', '雅各书', 59, 4, 11, '弟兄们，不要互相毁谤；人若毁谤弟兄，或判断弟兄，就是毁谤律法、判断律法了。如果你判断律法，就不是实行律法的人，而是审判官了。'),
('CNV', '雅各书', 59, 4, 12, '立法的，审判的，只有一位，就是那能拯救人，也能毁灭人的神；你这判断邻舍的，你是谁呢？'),
('CNV', '雅各书', 59, 4, 13, '你们说：“今天或明天，我们要到某城去，在那里住一年，作生意赚钱。”'),
('CNV', '雅各书', 59, 4, 14, '其实明天怎样，你们并不知道。你们的生命是什么呢？你们本来是过眼云烟，转瞬之间就消逝了。'),
('CNV', '雅各书', 59, 4, 15, '你们倒不如说：“主若愿意，我们就可以活着，作这事或作那事。”'),
('CNV', '雅各书', 59, 4, 16, '但现在你们竟然张狂自夸；这一切自夸，都是邪恶的。'),
('CNV', '雅各书', 59, 4, 17, '人若知道该行善事，却不去行，这就是他的罪了。'),
('CNV', '雅各书', 59, 5, 1, '你们富有的人哪，应当为那将要临到你们的灾祸哭泣哀号。'),
('CNV', '雅各书', 59, 5, 2, '你们的财物朽坏了，你们的衣服给蛀了，'),
('CNV', '雅各书', 59, 5, 3, '你们的金银生锈，这锈要成为控告你们的铁证，又要像火一样吞吃你们的肉。你们竟然在这末后的日子积聚财宝。'),
('CNV', '雅各书', 59, 5, 4, '看哪，工人为你们收割庄稼，你们竟然克扣他们的工资；那工资必为他们呼冤；收割者的呼声，已经达到万军之主的耳中了。'),
('CNV', '雅各书', 59, 5, 5, '你们在世上穷奢极侈，养肥了自己，竟不知屠宰的日子到了。'),
('CNV', '雅各书', 59, 5, 6, '你们把义人定罪杀害，但他并没有反抗。'),
('CNV', '雅各书', 59, 5, 7, '所以，弟兄们，你们应当忍耐，直到主来。看哪，农夫等待着地里宝贵的出产，为它忍耐，直到获得秋霖春雨。'),
('CNV', '雅各书', 59, 5, 8, '你们也应当忍耐，坚定自己的心；因为主再来的日子近了。'),
('CNV', '雅各书', 59, 5, 9, '弟兄们，不要彼此抱怨，免得你们受审判。看哪，审判的主已经站在门前了。'),
('CNV', '雅各书', 59, 5, 10, '弟兄们，你们应当效法奉主的名说话的先知，以他们为受苦忍耐的榜样。'),
('CNV', '雅各书', 59, 5, 11, '看哪，那些忍耐的人，我们称他们是有福的；你们听过约伯的忍耐，也看见了主赐给他的结局，知道主是满有怜悯和仁慈的。'),
('CNV', '雅各书', 59, 5, 12, '我的弟兄们，最要紧的是不可起誓：不可指着天起誓，也不可指着地起誓，任何的誓都当禁绝。你们的话，是就说是，不是就说不是；免得你们落在审判之下。'),
('CNV', '雅各书', 59, 5, 13, '你们中间有人受苦吗？他就应该祷告。有人心情愉快吗？他就应该歌颂。'),
('CNV', '雅各书', 59, 5, 14, '你们中间有人患病吗？他就应该请教会的长老来，让他们奉主的名为他抹油祈祷。'),
('CNV', '雅各书', 59, 5, 15, '出于信心的祈祷，可以使病人康复，主必叫他起来；他若犯了罪，也必蒙赦免。'),
('CNV', '雅各书', 59, 5, 16, '所以你们应当彼此认罪，互相代求，这样你们就可以痊愈。义人祈祷所发出的力量，是大有功效的。'),
('CNV', '雅各书', 59, 5, 17, '以利亚是与我们性情相同的人；他恳切祈求不要下雨，地上就三年零六个月没有雨；'),
('CNV', '雅各书', 59, 5, 18, '他又祈祷，天就下雨，地就生出土产来。'),
('CNV', '雅各书', 59, 5, 19, '我的弟兄们，你们中间若有人被骗离开了真道，如果有人使他回头，'),
('CNV', '雅各书', 59, 5, 20, '你们应该知道，那使罪人从歧途上转回的，就会拯救他的灵魂脱离死亡，也会遮盖许多罪恶。'),
('CNV', '彼得前书', 60, 1, 1, '耶稣基督的使徒彼得，写信给那分散在本都、加拉太、加帕多家、亚西亚、庇推尼寄居的人，'),
('CNV', '彼得前书', 60, 1, 2, '就是照着父神的预知蒙拣选，藉着圣灵得成圣洁，因而顺服，并且被耶稣基督的血洒过的人。愿恩惠平安多多地加给你们。'),
('CNV', '彼得前书', 60, 1, 3, '我们主耶稣基督的父神是应当称颂的。他照着自己的大怜悯，藉着耶稣基督从死人中复活，重生了我们，使我们有永活的盼望，'),
('CNV', '彼得前书', 60, 1, 4, '可以得着不能朽坏、不能玷污、不能衰残，为你们存留在天上的基业，'),
('CNV', '彼得前书', 60, 1, 5, '就是你们这因信蒙神能力保守的人，得着预备在末世要显现的救恩。'),
('CNV', '彼得前书', 60, 1, 6, '因此，你们要喜乐。然而，你们现今在各种试炼中或许暂时会难过，'),
('CNV', '彼得前书', 60, 1, 7, '是要叫你们的信心经过试验，就比那被火炼过，仍会朽坏的金子更宝贵，可以在耶稣基督显现的时候，得著称赞、荣耀和尊贵。'),
('CNV', '彼得前书', 60, 1, 8, '你们虽然没有见过他，却爱他；现在虽然不能看见他，却信他。因此，你们就有无法形容、满有荣耀的大喜乐，'),
('CNV', '彼得前书', 60, 1, 9, '得到你们信心的效果，就是灵魂得救。'),
('CNV', '彼得前书', 60, 1, 10, '论到这救恩，那预言你们要得恩典的众先知，都寻求考察过，'),
('CNV', '彼得前书', 60, 1, 11, '就是把他们心里基督的灵所预先见证，关于基督要受苦难后来得荣耀，是在什么时候和怎样的情况加以考察。'),
('CNV', '彼得前书', 60, 1, 12, '他们蒙了启示，为这些事效力，并不是为自己，而是为你们。现在，藉着传福音给你们的人，靠着从天上差来的圣灵，把这些事传给了你们；甚至天使也很想详细察看这些事。'),
('CNV', '彼得前书', 60, 1, 13, '所以要准备好你们的心，警醒谨慎，专心盼望耶稣基督显现的时候所要带给你们的恩典。'),
('CNV', '彼得前书', 60, 1, 14, '你们既是顺服的儿女，就不要再效法从前无知的时候放纵私欲的生活。'),
('CNV', '彼得前书', 60, 1, 15, '那召你们的既是圣洁的，你们在一切所行的事上也要圣洁。'),
('CNV', '彼得前书', 60, 1, 16, '因为圣经上记着说：“你们要圣洁，因为我是圣洁的。”'),
('CNV', '彼得前书', 60, 1, 17, '你们既称那不偏待人、按各人行为审判的主为父，就当存敬畏的心，过你们寄居的日子；'),
('CNV', '彼得前书', 60, 1, 18, '因为知道你们得赎，脱去你们祖先传下的妄行，不是凭着能坏的金银等物，'),
('CNV', '彼得前书', 60, 1, 19, '而是凭着基督的宝血，就像无瑕疵无玷污的羊羔的血。'),
('CNV', '彼得前书', 60, 1, 20, '基督是在创立世界以前，是神所预知的，却在这末后的世代才为你们显现出来。'),
('CNV', '彼得前书', 60, 1, 21, '藉着他，你们信那使他从死人中复活、又给他荣耀的神，叫你们的信心和盼望都在于神。'),
('CNV', '彼得前书', 60, 1, 22, '你们既因顺从真理，洁净了自己的心灵，以致能真诚地爱弟兄，就应当从清洁的心里彼此切实相爱。'),
('CNV', '彼得前书', 60, 1, 23, '你们得了重生，并不是由于能坏的种子，却是由于不能朽坏的，就是藉着神永活长存的道。'),
('CNV', '彼得前书', 60, 1, 24, '因为“所有的人（“人”原文作“肉体”），尽都如草，他们的荣美，都像草上的花；草必枯干，花必凋谢，'),
('CNV', '彼得前书', 60, 1, 25, '唯有主的道，永远长存。”所传给你们的福音就是这道。'),
('CNV', '彼得前书', 60, 2, 1, '所以要除去一切恶毒、一切诡诈、虚伪、嫉妒和一切毁谤的话，'),
('CNV', '彼得前书', 60, 2, 2, '像初生婴孩爱慕那纯净的灵奶，好叫你们靠它长大，进入救恩；'),
('CNV', '彼得前书', 60, 2, 3, '因为你们已经体验过主是美善的。'),
('CNV', '彼得前书', 60, 2, 4, '主是活石，虽然被人弃绝，却是神所拣选所珍贵的；你们到他面前来，'),
('CNV', '彼得前书', 60, 2, 5, '也就像活石，被建造成为灵宫，作圣洁的祭司，藉着耶稣基督献上蒙神悦纳的灵祭。'),
('CNV', '彼得前书', 60, 2, 6, '因为经上记着：“看哪，我在锡安放了一块石头，就是所拣选所珍贵的房角石，信靠他的人，必不致失望。”'),
('CNV', '彼得前书', 60, 2, 7, '所以这石头，对你们信的人是宝贵的，但对那不信的人，却是“建筑工人所弃的石头，成了房角的主要石头。”'),
('CNV', '彼得前书', 60, 2, 8, '它又“作了绊脚的石头，使人跌倒的磐石。”他们跌倒是因为不顺从这道，他们这样是必然的。'),
('CNV', '彼得前书', 60, 2, 9, '然而你们是蒙拣选的族类，是君尊的祭司，是圣洁的国民，是属神的子民，为要叫你们宣扬那召你们出黑暗入奇妙光明者的美德。'),
('CNV', '彼得前书', 60, 2, 10, '“你们从前不是子民，现在却是神的子民；从前未蒙怜恤，现在却蒙了怜恤。”'),
('CNV', '彼得前书', 60, 2, 11, '亲爱的，我劝你们作客旅和寄居的人，要禁戒肉体的私欲，这私欲是与灵魂争战的。'),
('CNV', '彼得前书', 60, 2, 12, '你们在教外人中，应当品行端正，使那些人，虽然毁谤你们是作恶的，但因为看见你们的好行为，就要在鉴察的日子颂赞神。'),
('CNV', '彼得前书', 60, 2, 13, '你们为主的缘故，要顺服人的一切制度，无论是至尊的君王，'),
('CNV', '彼得前书', 60, 2, 14, '或是君王所派赏善罚恶的官员；'),
('CNV', '彼得前书', 60, 2, 15, '因为这是神的旨意，要藉着你们的善行，塞住糊涂无知人的口。'),
('CNV', '彼得前书', 60, 2, 16, '你们是自由的人，但不要用自由来掩饰邪恶，总要像神的仆人。'),
('CNV', '彼得前书', 60, 2, 17, '要尊重众人，爱护弟兄，敬畏神，尊敬君王。'),
('CNV', '彼得前书', 60, 2, 18, '你们作仆人的，要凡事敬畏顺服主人，不单是对善良温和的，就是乖僻的也要顺服。'),
('CNV', '彼得前书', 60, 2, 19, '因为人若在神面前为良心的缘故，忍受冤屈的苦楚，是有福的。'),
('CNV', '彼得前书', 60, 2, 20, '你们若因犯罪受责打而能忍耐，有什么可夸的呢？但你们若因行善而受苦，能忍耐，在神看来，这是有福的。'),
('CNV', '彼得前书', 60, 2, 21, '你们就是为此蒙召，因基督也为你们受过苦，给你们留下榜样，叫你们跟随他的脚踪行。'),
('CNV', '彼得前书', 60, 2, 22, '“他从来没有犯过罪，口里也找不到诡诈。”'),
('CNV', '彼得前书', 60, 2, 23, '他被骂的时候不还嘴，受苦的时候也不说恐吓的话；只把自己交托给那公义的审判者。'),
('CNV', '彼得前书', 60, 2, 24, '他在木头上亲身担当了我们的罪，使我们既然不活在罪中，就可以为义而活。因他受的鞭伤，你们就得了医治。'),
('CNV', '彼得前书', 60, 2, 25, '你们从前好像迷路的羊，但现在已经回到你们灵魂的牧人和监督那里了。'),
('CNV', '彼得前书', 60, 3, 1, '照样，你们作妻子的，要顺服自己的丈夫，好使不信道的丈夫受到感动，不是因着你们的言语，而是因着你们的生活，'),
('CNV', '彼得前书', 60, 3, 2, '因为他们看见了你们敬畏和纯洁的生活。'),
('CNV', '彼得前书', 60, 3, 3, '不要单注重外表的装饰，就如鬈头发、戴金饰、穿华丽衣服；'),
('CNV', '彼得前书', 60, 3, 4, '却要在里面存着温柔安静的心灵，作不能毁坏的装饰，这在神面前是极宝贵的。'),
('CNV', '彼得前书', 60, 3, 5, '因为古时仰望神的圣洁妇女，正是这样装饰自己，顺服丈夫，'),
('CNV', '彼得前书', 60, 3, 6, '像撒拉听从亚伯拉罕，称他为主一样；你们若行善，不怕任何恐吓，就是撒拉的女儿了。'),
('CNV', '彼得前书', 60, 3, 7, '照样，你们作丈夫的，也要合情合理的与妻子同住。要体谅她比你软弱，要尊敬她，因为她是和你一同承受生命的恩典的。这样，就使你们的祷告不受拦阻。'),
('CNV', '彼得前书', 60, 3, 8, '总括来说，你们要彼此同心，互相体恤，亲爱像弟兄，满有温柔，存心谦卑。'),
('CNV', '彼得前书', 60, 3, 9, '不要以恶报恶，以辱骂还辱骂，倒要祝福，因为你们就是为此蒙召，好叫你们承受福气。'),
('CNV', '彼得前书', 60, 3, 10, '因为“凡希望享受人生，要看见好日子的，就要禁止舌头不出恶言，嘴唇不说诡诈的话；'),
('CNV', '彼得前书', 60, 3, 11, '也要离恶行善，寻找并追求和睦。'),
('CNV', '彼得前书', 60, 3, 12, '因为主的眼睛看顾义人，他的耳朵垂听他们的呼求；但主的脸敌对作恶的人。”'),
('CNV', '彼得前书', 60, 3, 13, '如果你们热心行善，有谁能害你们呢？'),
('CNV', '彼得前书', 60, 3, 14, '就算你们要为义受苦，也是有福的。“不要怕人的恐吓，也不要畏惧。”'),
('CNV', '彼得前书', 60, 3, 15, '只要心里尊基督为圣，以他为主；常常作好准备，去回答那些问你们为什么怀有盼望的人，'),
('CNV', '彼得前书', 60, 3, 16, '但要用温柔敬畏的心回答。当存无愧的良心，使那些诬赖你们这在基督里有好品行的人，在毁谤你们的事上蒙羞。'),
('CNV', '彼得前书', 60, 3, 17, '如果神的旨意是要你们受苦，那么为行善受苦，总比为行恶受苦好。'),
('CNV', '彼得前书', 60, 3, 18, '因为基督也曾一次为你们的罪死了，就是义的代替不义的，为要领你们到神面前。就肉体的方面说，他曾死去；就灵的方面说，他复活了；'),
('CNV', '彼得前书', 60, 3, 19, '他藉这灵也曾去向那些在监管中的灵宣讲，'),
('CNV', '彼得前书', 60, 3, 20, '他们就是挪亚建造方舟的日子、神容忍等待的时候，那些不顺从的人。当时进入方舟、藉着水得救的人不多，只有八个。'),
('CNV', '彼得前书', 60, 3, 21, '这水预表的洗礼，现在也拯救你们：不是除去肉体的污秽，而是藉着耶稣基督的复活，向神许愿常存纯洁的良心。'),
('CNV', '彼得前书', 60, 3, 22, '基督已进到天上，在神右边，众天使、有权势的、有能力的，都服从了他。'),
('CNV', '彼得前书', 60, 4, 1, '基督既然在肉身受过苦，你们也应当以同样的心志装备自己（因为在肉身受过苦的，就已经与罪断绝了），'),
('CNV', '彼得前书', 60, 4, 2, '好叫你们不再随从人的私欲，只顺从神的旨意，在世上度余下的光阴。'),
('CNV', '彼得前书', 60, 4, 3, '因为你们过去随从教外人的心意，行邪淫、私欲、醉酒、荒宴、狂饮和可憎拜偶像的事，时候已经够了。'),
('CNV', '彼得前书', 60, 4, 4, '他们见你们不再与他们同奔那纵情放荡的路，就觉得奇怪，毁谤你们。'),
('CNV', '彼得前书', 60, 4, 5, '他们必要向那位预备要审判活人死人的主交帐。'),
('CNV', '彼得前书', 60, 4, 6, '因此，那些死人也曾有福音传给他们，好使他们的肉体受了人要受的审判，他们的灵却靠神活着。'),
('CNV', '彼得前书', 60, 4, 7, '万物的结局近了，所以你们要谨慎警醒地祷告。'),
('CNV', '彼得前书', 60, 4, 8, '最重要的是要彼此切实相爱，因为爱能遮盖许多的罪。'),
('CNV', '彼得前书', 60, 4, 9, '你们要互相接待，不发怨言。'),
('CNV', '彼得前书', 60, 4, 10, '你们要作神各样恩赐的好管家，各人照着所领受的恩赐彼此服事。'),
('CNV', '彼得前书', 60, 4, 11, '讲道的，应当按着神的圣言讲；服事的，应当按着神所赐的力量服事，为要在一切事上，使神藉耶稣基督得荣耀。荣耀、权能都是他的，直到永永远远。阿们。'),
('CNV', '彼得前书', 60, 4, 12, '亲爱的，有火炼的试验临到你们，不要以为奇怪，好像是遭遇非常的事，'),
('CNV', '彼得前书', 60, 4, 13, '倒要欢喜，因为你们既然在基督的受苦上有分，就在他荣耀显现的时候，可以欢喜快乐。'),
('CNV', '彼得前书', 60, 4, 14, '你们要是为基督的名受辱骂，就有福了！因为神荣耀的灵，住在你们身上。'),
('CNV', '彼得前书', 60, 4, 15, '你们中间不可有人因为杀人、或偷窃、或行恶、或好管闲事而受苦。'),
('CNV', '彼得前书', 60, 4, 16, '如果因为作基督徒而受苦，不要以为羞耻，倒要藉着这名字荣耀神。'),
('CNV', '彼得前书', 60, 4, 17, '因为审判从神的家开始，就在这时候了。如果先从我们起头，那不信从神福音的人，结局将要怎样呢？'),
('CNV', '彼得前书', 60, 4, 18, '“如果义人仅仅得救，不敬虔和犯罪的人，又会变成怎样呢（“不敬虔和犯罪的人，又会变成怎样呢？”直译作“不敬虔的人和犯罪的人将出现在何处呢？”）？”'),
('CNV', '彼得前书', 60, 4, 19, '所以那顺着神的旨意而受苦的人，要继续地行善，把自己的生命交托那信实的创造者。'),
('CNV', '彼得前书', 60, 5, 1, '我这同作长老，也是为基督受苦作见证，又是同享将来所要显现的荣耀的，劝你们当中作长老的：'),
('CNV', '彼得前书', 60, 5, 2, '务要牧养在你们中间的神的羊群，按着神的旨意看顾他们。不是出于勉强，而是出于甘心；不是因为贪财，而是出于热诚；'),
('CNV', '彼得前书', 60, 5, 3, '也不是要辖制托付你们的羊群，而是作他们的榜样。'),
('CNV', '彼得前书', 60, 5, 4, '到了牧长显现的时候，你们必定得着那永不衰残的荣耀冠冕。'),
('CNV', '彼得前书', 60, 5, 5, '照样，你们青年人要顺服年长的。就是你们各人也要彼此以谦卑为装束，因为“神对抗骄傲的人，赐恩给谦卑的人。”'),
('CNV', '彼得前书', 60, 5, 6, '所以你们要谦卑，服在神大能的手下，到了时候，他必叫你们升高。'),
('CNV', '彼得前书', 60, 5, 7, '你们要把一切忧虑卸给神，因为他顾念你们。'),
('CNV', '彼得前书', 60, 5, 8, '你们要谨守、警醒。你们的仇敌魔鬼，好像吼叫的狮子走来走去，寻找可以吞吃的人；'),
('CNV', '彼得前书', 60, 5, 9, '你们要用坚强的信心抵挡他，因为知道你们在世上的弟兄，也经历过同样的苦难。'),
('CNV', '彼得前书', 60, 5, 10, '但满有恩典的神，就是在基督里召你们进入他永远荣耀的那一位，在你们受了短暂的苦难之后，必定亲自成全你们，坚固你们，赐力量给你们，建立你们。'),
('CNV', '彼得前书', 60, 5, 11, '愿权能归给他，直到永远。阿们。'),
('CNV', '彼得前书', 60, 5, 12, '我藉着我认为忠心的弟兄西拉，简略地写了这封信劝勉你们，又向你们证实这是神真正的恩典；你们要在这恩典上站立得住。'),
('CNV', '彼得前书', 60, 5, 13, '在巴比伦与你们同蒙拣选的，和我儿子马可都问候你们。'),
('CNV', '彼得前书', 60, 5, 14, '你们要用爱心彼此亲吻问安。愿平安归与你们所有在基督里的人。'),
('CNV', '彼得后书', 61, 1, 1, '耶稣基督的仆人和使徒西门．彼得，写信给那靠着我们的神和救主耶稣基督的义，得着和我们同样宝贵信心的人。'),
('CNV', '彼得后书', 61, 1, 2, '愿恩惠平安，因你们确实认识神和我们的主耶稣，多多加给你们。'),
('CNV', '彼得后书', 61, 1, 3, '神以他神圣的能力，因着我们确实认识那位用自己的荣耀和美善呼召我们的，把一切有关生命和敬虔的事，都赐给了我们。'),
('CNV', '彼得后书', 61, 1, 4, '藉着这些，他把又宝贵又极大的应许赐给了我们，好叫你们既然逃脱世上因私欲而来的败坏，就可以分享神的本性。'),
('CNV', '彼得后书', 61, 1, 5, '正因这缘故，你们要多多努力：有了信心，又要增添美德；有了美德，又要增添知识；'),
('CNV', '彼得后书', 61, 1, 6, '有了知识，又要增添节制；有了节制，又要增添忍耐；有了忍耐，又要增添敬虔；'),
('CNV', '彼得后书', 61, 1, 7, '有了敬虔，又要增添弟兄的爱；有了弟兄的爱，还要增添神圣的爱。'),
('CNV', '彼得后书', 61, 1, 8, '因为你们有了这几样，并且继续增长，就必叫你们在确实认识我们的主耶稣基督上，不至于闲懒不结果子。'),
('CNV', '彼得后书', 61, 1, 9, '人若没有这几样，就是近视，简直是瞎眼的，忘记他过去的罪已经得了洁净。'),
('CNV', '彼得后书', 61, 1, 10, '所以弟兄们，要更加努力，使你们所蒙的呼召和拣选坚定不移；你们若实行这几样，就决不会跌倒。'),
('CNV', '彼得后书', 61, 1, 11, '这样，你们就得着充分的装备，可以进入我们的主和救主耶稣基督永远的国。'),
('CNV', '彼得后书', 61, 1, 12, '因此，你们虽然已经知道这些事，又在你们已有的真道上得到坚固，我还要时常提醒你们。'),
('CNV', '彼得后书', 61, 1, 13, '趁着我还在世上（“在世上”原文作“在这帐棚”）的时候，我认为应当提醒你们，使你们常常警醒，'),
('CNV', '彼得后书', 61, 1, 14, '因为我知道我离世（“离世”原文作“离开这帐棚”）的时候快到了，正如我们的主耶稣基督清楚指示我的。'),
('CNV', '彼得后书', 61, 1, 15, '我也要努力，使你们在我去世以后，还时常追念这些事。'),
('CNV', '彼得后书', 61, 1, 16, '我们从前把我们主耶稣基督的大能和降临的事告诉你们，并不是随从巧妙捏造传奇的故事，我们却是亲眼看见过他威荣的人。'),
('CNV', '彼得后书', 61, 1, 17, '因为他从父神得着尊贵荣耀的时候，在极显赫的荣光中，有这样的声音对他说：“这是我的爱子，我所喜悦的。”'),
('CNV', '彼得后书', 61, 1, 18, '这从天上发出来的声音，是我们和他同在圣山上的时候，亲自听见过的。'),
('CNV', '彼得后书', 61, 1, 19, '我们还有先知的话，是更确实的。你们要特别注意它，好像注意照在暗处的明灯，直到天将破晓，晨星在你们心里出现的时候。'),
('CNV', '彼得后书', 61, 1, 20, '最要紧的，你们应当知道：圣经所有的预言，都不是先知自己的见解，'),
('CNV', '彼得后书', 61, 1, 21, '因为预言不是出于人意的，而是人受圣灵的感动，说出从神而来的话。'),
('CNV', '彼得后书', 61, 2, 1, '从前在人民中，曾有假先知出来；照样，将来在你们中间，也必有假教师出现。他们偷偷把使人灭亡的异端引进来，甚至否认那曾经买赎他们的主，迅速地自取灭亡。'),
('CNV', '彼得后书', 61, 2, 2, '许多人会随从他们的淫行，因此真理的道，就因他们的缘故被人毁谤。'),
('CNV', '彼得后书', 61, 2, 3, '他们因为有贪心，就用捏造的话，想在你们身上图利；惩罚他们的，自古以来就没有松懈；毁灭他们的，也不会打盹。'),
('CNV', '彼得后书', 61, 2, 4, '神没有姑息犯罪的天使，反而把他们丢入地狱，囚禁在幽暗的坑里，等候审判。'),
('CNV', '彼得后书', 61, 2, 5, '神也没有姑息上古的世界，反而使洪水临到那不敬虔的世人，只保存了传义道的挪亚一家八口。'),
('CNV', '彼得后书', 61, 2, 6, '神判定了所多玛、蛾摩拉二城的罪，把它们倾覆，烧成灰烬，作为后世不敬虔的人的鉴戒；'),
('CNV', '彼得后书', 61, 2, 7, '只救了那因恶人的淫行而常受委屈的义人罗得；'),
('CNV', '彼得后书', 61, 2, 8, '（因为这义人住在他们中间，天天看见和听见他们不法的事，他正直的心就感到伤痛。）'),
('CNV', '彼得后书', 61, 2, 9, '主知道怎样搭救敬虔的人脱离试探，又把不义的人留下来，等候在审判的日子受刑罚，'),
('CNV', '彼得后书', 61, 2, 10, '尤其是那些随从肉体，生活在污秽的私欲中，和轻蔑当权的，更是这样。他们胆大任性，毫无畏惧地毁谤在尊位的。'),
('CNV', '彼得后书', 61, 2, 11, '就是天使，虽有更大的力量与权能，尚且不用毁谤的话在主面前控告他们。'),
('CNV', '彼得后书', 61, 2, 12, '但这些人，好像没有理性的牲畜，生下来就是给人捉去宰杀的；他们毁谤自己所不知道的事，必在自己的败坏中灭亡。'),
('CNV', '彼得后书', 61, 2, 13, '他们行不义，就得了不义的工价。他们在白昼纵情作乐，满了污点与瑕疵，和你们一同吃饭的时候，就因自己的诡诈而沾沾自喜。'),
('CNV', '彼得后书', 61, 2, 14, '他们满眼淫色，而且不住地犯罪。他们引诱心志不坚固的人。他们的心习惯了贪婪，是应当受咒诅的族类。'),
('CNV', '彼得后书', 61, 2, 15, '他们离弃正路，走入歧途，跟从了比珥的儿子巴兰的道路。这巴兰贪爱不义的工价，'),
('CNV', '彼得后书', 61, 2, 16, '他曾经因着自己的过犯受了责备：不能说话的驴，竟用人的声音说出话来，制止了这先知的狂妄。'),
('CNV', '彼得后书', 61, 2, 17, '这些人是无水的泉源，是暴风催逼的雾气，有漆黑的幽暗为他们存留。'),
('CNV', '彼得后书', 61, 2, 18, '因为他们说虚妄夸大的话，用肉体的私欲和邪荡的事，引诱那些刚刚逃脱了错谬生活的人。'),
('CNV', '彼得后书', 61, 2, 19, '他们应许给人自由，自己却作了败坏的奴仆；因为人给谁制伏了，就作谁的奴仆。'),
('CNV', '彼得后书', 61, 2, 20, '如果他们因为认识我们的主、救主耶稣基督，可以脱离世上的污秽，后来又在其中被缠住、受制伏，他们末了的景况，就比先前的更不好了。'),
('CNV', '彼得后书', 61, 2, 21, '既然认识了义路，竟又背弃传给他们的圣诫命，对他们来说，倒不如不认识好得多了。'),
('CNV', '彼得后书', 61, 2, 22, '他们的情形，正像俗语所说的：“狗转过来，又吃自己所吐的；猪洗净了，又到污泥中去打滚。”'),
('CNV', '彼得后书', 61, 3, 1, '亲爱的，我现在写给你们的是第二封信。在这两封信中，我都用提醒的话来激发你们真诚的心，'),
('CNV', '彼得后书', 61, 3, 2, '叫你们记起圣先知说过的话，和主救主藉着使徒传给你们的诫命。'),
('CNV', '彼得后书', 61, 3, 3, '最重要的，你们应当知道：在末后的日子，必定有好讥笑的人出来，随着自己的私欲讥笑说：'),
('CNV', '彼得后书', 61, 3, 4, '“他要降临的应许在哪里呢？因为自从列祖睡了以来，万物依然存在，与起初创造的时候一样。”'),
('CNV', '彼得后书', 61, 3, 5, '他们故意忘记这事：在太古的时候，因着神的话，就有了天，和从水而出、藉水而成的地。'),
('CNV', '彼得后书', 61, 3, 6, '当时的世界，因被水淹没而消灭了。'),
('CNV', '彼得后书', 61, 3, 7, '但现在的天地，还是因着同样的话可以存留，直到不敬虔的人受审判和遭灭亡的日子，用火焚烧。'),
('CNV', '彼得后书', 61, 3, 8, '亲爱的，这一件事你们不可忘记：在主看来，一日如千年，千年如一日。'),
('CNV', '彼得后书', 61, 3, 9, '主决不耽延他的应许，像有些人以为他是耽延的一样；其实他是宽容你们，不愿有一人灭亡，却愿人人都悔改。'),
('CNV', '彼得后书', 61, 3, 10, '但主的日子必要像贼一样来到。在那日，天必轰然一声地消失，所有元素都因烈火而融化；地和地上所有的，都要被烧毁（“被烧毁”有不少古抄本作“被发现”）。'),
('CNV', '彼得后书', 61, 3, 11, '这一切既然都要这样融化，你们应当怎样为人，过着圣洁和敬虔的生活，'),
('CNV', '彼得后书', 61, 3, 12, '等候并催促神的日子降临呢？因为在那日，天要被火焚烧就融化了，所有元素都因烈火而融解！'),
('CNV', '彼得后书', 61, 3, 13, '但是我们按照他所应许的，等候新天新地，有公义在那里居住。'),
('CNV', '彼得后书', 61, 3, 14, '所以，亲爱的，你们既然等候这些事，就当殷勤努力，使你们没有污点，没有瑕疵，安然见主。'),
('CNV', '彼得后书', 61, 3, 15, '并且要以我们的主恒久忍耐为给人得救的机会，就如我们所亲爱的弟兄保罗，按照所赐给他的智慧，写给你们的一样；'),
('CNV', '彼得后书', 61, 3, 16, '他在一切书信上，都讲论这些事。在这些书信中，有些难明白的地方，那不学无术和不稳定的人加以曲解，好像曲解别的经书一样，就自取灭亡。'),
('CNV', '彼得后书', 61, 3, 17, '所以，亲爱的，你们既然预先知道了，就要谨慎，免得受恶人的错谬引导，就从自己坚固的地步上坠落。'),
('CNV', '彼得后书', 61, 3, 18, '你们却要在我们的主、救主耶稣基督的恩典和知识上长进。愿荣耀归给他，从现在直到永远。阿们。'),
('CNV', '约翰一书', 62, 1, 1, '论到太初就已经存在的生命之道，就是我们所听见，亲眼所看见，仔细观察过，亲手摸过的；'),
('CNV', '约翰一书', 62, 1, 2, '这生命已经显现出来，我们见过了，现在也作见证，并且向你们宣扬这本来与父同在，又向我们显现过的永远的生命。'),
('CNV', '约翰一书', 62, 1, 3, '我们把所看见所听见的向你们宣扬，使你们也可以和我们彼此相通。我们是与父和他的儿子耶稣基督彼此相通的。'),
('CNV', '约翰一书', 62, 1, 4, '我们写这些事，是要使我们的喜乐充足。'),
('CNV', '约翰一书', 62, 1, 5, '神是光，在他里面毫无黑暗；这就是我们从他那里听见，现在传给你们的信息。'),
('CNV', '约翰一书', 62, 1, 6, '我们若说自己与他彼此相通，却行在黑暗里，就是说谎话，不实行真理了。'),
('CNV', '约翰一书', 62, 1, 7, '我们若行在光中，像他在光中一样，就彼此相通，他儿子耶稣的血也洁净我们脱离一切罪。'),
('CNV', '约翰一书', 62, 1, 8, '我们若说自己没有罪，就是自欺，真理就不在我们里面了。'),
('CNV', '约翰一书', 62, 1, 9, '我们若承认自己的罪，神是信实的、公义的，必定赦免我们的罪，洁净我们脱离一切不义。'),
('CNV', '约翰一书', 62, 1, 10, '我们若说自己没有犯过罪，就是把神当作说谎的，他的道就不在我们心里了。'),
('CNV', '约翰一书', 62, 2, 1, '我的孩子们，我写这些给你们，是要你们不犯罪。如果有人犯了罪，在父的面前我们有一位维护者，就是那义者耶稣基督。'),
('CNV', '约翰一书', 62, 2, 2, '他为我们的罪作了赎罪祭，不仅为我们的罪，也为全人类的罪。'),
('CNV', '约翰一书', 62, 2, 3, '我们若遵守神的命令，这样，就知道我们已经认识他。'),
('CNV', '约翰一书', 62, 2, 4, '凡是说“我已经认识他”，却不遵守他命令的，就是说谎的人，真理就不在他里面了。'),
('CNV', '约翰一书', 62, 2, 5, '然而凡是遵守他的道的，他爱神的心就的确在他里面完全了。这样，我们就知道我们是在神里面了。'),
('CNV', '约翰一书', 62, 2, 6, '凡说自己是住在他里面的，就应该照着他所行的去行。'),
('CNV', '约翰一书', 62, 2, 7, '亲爱的，我写给你们的，不是一条新命令，而是你们本来就有的旧命令。这旧命令就是你们听过的道。'),
('CNV', '约翰一书', 62, 2, 8, '然而，因为黑暗渐渐消逝，真光已在照耀，我写给你们的也是一条新命令，这在神和在你们来说，都是真的。'),
('CNV', '约翰一书', 62, 2, 9, '凡是说自己在光明中，却恨他的弟兄的，他到现在还在黑暗里。'),
('CNV', '约翰一书', 62, 2, 10, '凡是爱弟兄的，就是住在光明中，在光明中他就不会跌倒。'),
('CNV', '约翰一书', 62, 2, 11, '凡是恨弟兄的，就是在黑暗里，也在黑暗里行事。他不知道往哪里去，因为黑暗弄瞎了他的眼睛。'),
('CNV', '约翰一书', 62, 2, 12, '孩子们，我写信给你们，因为你们的罪因着主的名已经得到赦免。'),
('CNV', '约翰一书', 62, 2, 13, '父老们，我写信给你们，因为你们认识太初就存在的那一位。青年们，我写信给你们，因为你们已经胜过那恶者。'),
('CNV', '约翰一书', 62, 2, 14, '孩子们，我写信给你们，因为你们认识父。父老们，我写信给你们，因为你们认识太初就存在的那一位。青年们，我写信给你们，因为你们强壮，神的道在你们心里，你们也胜过了那恶者。'),
('CNV', '约翰一书', 62, 2, 15, '不要爱世界和世上的东西。人若爱世界，爱父的心就不在他里面了。'),
('CNV', '约翰一书', 62, 2, 16, '原来世上的一切，就如肉体的私欲，眼目的私欲和今生的骄傲，都不是出于父，而是从世界来的。'),
('CNV', '约翰一书', 62, 2, 17, '这世界和世上的私欲都要渐渐过去，但那遵行神旨意的却存到永远。'),
('CNV', '约翰一书', 62, 2, 18, '孩子们，现在是末世的时候了。你们听过敌基督者要来，现在已经有不少敌基督起来了；因此我们就知道这是末世的时候了。'),
('CNV', '约翰一书', 62, 2, 19, '他们从我们中间离去，这就表明他们是不属于我们的。其实他们并不属于我们，如果真的属于我们，就一定会留在我们中间。'),
('CNV', '约翰一书', 62, 2, 20, '你们从那圣者得着膏抹，这是你们都知道的。'),
('CNV', '约翰一书', 62, 2, 21, '我写信给你们，不是因为你们不明白真理，而是因为你们明白，又因为谎言绝不会出于真理的。'),
('CNV', '约翰一书', 62, 2, 22, '那么，谁是说谎的呢？不就是那否认耶稣是基督的吗？否认父和子的，他就是敌基督的。'),
('CNV', '约翰一书', 62, 2, 23, '凡否认子的，就没有父；承认子的，连父也有了。'),
('CNV', '约翰一书', 62, 2, 24, '至于你们，总要把起初所听见的存记在你们心里；你们若把起初所听见的存记在心里，你们也就住在子和父里面了。'),
('CNV', '约翰一书', 62, 2, 25, '他应许给我们的，就是永远的生命。'),
('CNV', '约翰一书', 62, 2, 26, '我把这些事写给你们，是指着那些欺骗你们的人说的。'),
('CNV', '约翰一书', 62, 2, 27, '你们既然在你们里面有从主领受的膏抹，就不需要别人教导你们了，因为在一切事上有主的膏抹教导你们；这膏抹是真的，不是假的，你们应该按着他所教导的住在他里面。'),
('CNV', '约翰一书', 62, 2, 28, '孩子们，你们要住在主里面。这样，他若显现，我们就可以坦然无惧；他来的时候，我们也不至惭愧地躲避他了。'),
('CNV', '约翰一书', 62, 2, 29, '你们既然晓得神是公义的，就应当知道所有行公义的都是从他生的。'),
('CNV', '约翰一书', 62, 3, 1, '你们看，父赐给我们的是怎样的爱，就是让我们可以称为神的儿女，我们也真是他的儿女。因此，世人不认识我们，是因为他们不认识父。'),
('CNV', '约翰一书', 62, 3, 2, '亲爱的，现在我们是神的儿女，将来怎样，还没有显明；然而我们知道：主若显现，我们必要像他，因为我们必要看见他本来是怎样的。'),
('CNV', '约翰一书', 62, 3, 3, '凡对他存着这盼望的，就洁净自己，像他一样的洁净。'),
('CNV', '约翰一书', 62, 3, 4, '凡是犯罪的，就是作了不法的事；罪就是不法。'),
('CNV', '约翰一书', 62, 3, 5, '你们知道主曾经显现，为要除掉罪，他自己却没有罪。'),
('CNV', '约翰一书', 62, 3, 6, '凡是住在他里面的，就不犯罪；凡犯罪的，是未曾见过他，也不认识他。'),
('CNV', '约翰一书', 62, 3, 7, '孩子们，不要受人欺骗，行义的才是义人，正如主是公义的。'),
('CNV', '约翰一书', 62, 3, 8, '犯罪的是出于魔鬼，因为魔鬼从起初就犯罪。因此，神的儿子显现了，是要除灭魔鬼的作为。'),
('CNV', '约翰一书', 62, 3, 9, '凡是从神生的，就不犯罪，因为神的生命（“神的生命”原文作“种子”）在他里面；他也不能犯罪，因为他是从神生的。'),
('CNV', '约翰一书', 62, 3, 10, '这样，谁是神的儿女，谁是魔鬼的儿女，就很明显了。凡不行义的，就不是出于神，不爱弟兄的，也是这样。'),
('CNV', '约翰一书', 62, 3, 11, '我们应当彼此相爱，因为这是你们从起初听见的信息。'),
('CNV', '约翰一书', 62, 3, 12, '不要像该隐，他是属于那恶者的，他又杀了自己的弟弟。为什么杀他呢？因为他自己的行为是恶的，弟弟的行为是义的。'),
('CNV', '约翰一书', 62, 3, 13, '弟兄们，世人若恨你们，不要希奇。'),
('CNV', '约翰一书', 62, 3, 14, '我们因为爱弟兄，就知道我们已经出死入生了；不爱弟兄的，仍然住在死中。'),
('CNV', '约翰一书', 62, 3, 15, '凡恨弟兄的，就是杀人的。你们知道，杀人的在他里面没有永生。'),
('CNV', '约翰一书', 62, 3, 16, '主为我们舍命，这样，我们就知道什么是爱；我们也应当为弟兄舍命。'),
('CNV', '约翰一书', 62, 3, 17, '凡有世上财物的，看见弟兄穷乏，却硬着心肠不理，他怎能说他心里有神的爱呢？'),
('CNV', '约翰一书', 62, 3, 18, '孩子们，我们爱人，不要只在言语和舌头上，总要在行动和真诚上表现出来。'),
('CNV', '约翰一书', 62, 3, 19, '这样，我们就知道我们是属于真理的。即使我们的心责备我们，在神面前我们也可以心安理得，因为他比我们的心大，他知道一切。'),
('CNV', '约翰一书', 62, 3, 21, '亲爱的，我们的心若不责备我们，在神面前我们就可以坦然无惧了。'),
('CNV', '约翰一书', 62, 3, 22, '凡我们所求的，就必从他得着，因为我们遵守他的命令，作他所喜悦的事。'),
('CNV', '约翰一书', 62, 3, 23, '神的命令，就是要我们信他的儿子耶稣基督的名，并且照着他的吩咐彼此相爱。'),
('CNV', '约翰一书', 62, 3, 24, '凡是遵守神命令的，就住在神里面，神也住在他里面。凭着神所赐给我们的圣灵，我们就可以知道神住在我们里面。'),
('CNV', '约翰一书', 62, 4, 1, '亲爱的，不要每个灵都信，总要试验那些灵是否出于神，因为有许多假先知已经来到世上了。'),
('CNV', '约翰一书', 62, 4, 2, '你们可以这样认出神的灵：凡是承认耶稣基督是成了肉身来的，那灵就是出于神。'),
('CNV', '约翰一书', 62, 4, 3, '凡是不承认耶稣基督是成了肉身来的，那灵就不是出于神，而是敌基督者的灵；你们听过他要来，现在他已经在世上了。'),
('CNV', '约翰一书', 62, 4, 4, '孩子们，你们是属于神的，并且已经胜过他们，因为那在你们里面的比那在世上的更大。'),
('CNV', '约翰一书', 62, 4, 5, '他们是属于世界的，因此讲论属世的事，世界也就听从他们。'),
('CNV', '约翰一书', 62, 4, 6, '我们是属于神的，认识神的就听从我们，不属于神的就不听从我们。这样，我们就可以辨别真理的灵和谬妄的灵了。'),
('CNV', '约翰一书', 62, 4, 7, '亲爱的，我们应当彼此相爱，因为爱是从神那里来的。凡是爱人的，都是从神生的，并且认识神。'),
('CNV', '约翰一书', 62, 4, 8, '不爱人的，就不认识神，因为神就是爱。'),
('CNV', '约翰一书', 62, 4, 9, '神差遣他的独生子到世上来，要使我们藉着他而活；神的爱就在我们中间显明了。'),
('CNV', '约翰一书', 62, 4, 10, '不是我们爱神，而是神爱我们，差遣他的儿子为我们的罪作了赎罪祭，这就是爱了。'),
('CNV', '约翰一书', 62, 4, 11, '亲爱的，神既然这样爱我们，我们也应当彼此相爱。'),
('CNV', '约翰一书', 62, 4, 12, '从来没有人见过神，我们若彼此相爱，神就住在我们里面，他的爱也在我们里面得到成全了。'),
('CNV', '约翰一书', 62, 4, 13, '神把他的灵赐给我们，我们就知道我们是住在他里面，他也住在我们里面。'),
('CNV', '约翰一书', 62, 4, 14, '父差遣子作世人的救主，这是我们见过的，并且现在作见证。'),
('CNV', '约翰一书', 62, 4, 15, '凡承认耶稣是神的儿子的，神就住在他里面，他也住在神里面。'),
('CNV', '约翰一书', 62, 4, 16, '神对我们的爱，我们已经明白了，而且相信了。神就是爱；住在爱里面的，就住在神里面，神也住在他里面。'),
('CNV', '约翰一书', 62, 4, 17, '这样，爱在我们里面就得到成全，使我们在审判的日子，可以坦然无惧。因为他怎样，我们在这世上也怎样。'),
('CNV', '约翰一书', 62, 4, 18, '爱里没有惧怕，完全的爱可以把惧怕驱除，因为惧怕含有刑罚，惧怕的人在爱里还没有完全。'),
('CNV', '约翰一书', 62, 4, 19, '我们爱，因为神先爱我们。'),
('CNV', '约翰一书', 62, 4, 20, '人若说“我爱神”，却恨他的弟兄，就是说谎的。不爱看得见的弟兄，就不能爱看不见的神。'),
('CNV', '约翰一书', 62, 4, 21, '爱神的，也应当爱弟兄，这就是我们从神领受的命令。'),
('CNV', '约翰一书', 62, 5, 1, '凡信耶稣是基督的，都是从神生的，凡爱那生他的，也必爱那从他而生的。'),
('CNV', '约翰一书', 62, 5, 2, '我们若爱神，并且遵行他的命令，就知道我们是爱神的儿女了。'),
('CNV', '约翰一书', 62, 5, 3, '我们遵守神的命令，就是爱他了；而且他的命令是不难遵守的，'),
('CNV', '约翰一书', 62, 5, 4, '因为凡从神生的就胜过世界。使我们胜过世界的，就是我们的信心。'),
('CNV', '约翰一书', 62, 5, 5, '胜过世界的是谁呢？不就是那信耶稣是神的儿子的吗？'),
('CNV', '约翰一书', 62, 5, 6, '那藉着水和血来的就是耶稣基督，不是单用水，而是用水又用血；作见证的是圣灵，因为圣灵就是真理。'),
('CNV', '约翰一书', 62, 5, 7, '原来作见证的有三样，'),
('CNV', '约翰一书', 62, 5, 8, '就是圣灵、水和血，这三样是一致的。'),
('CNV', '约翰一书', 62, 5, 9, '我们若接受人的见证，神的见证就更强而有力了，因为这是神为他的儿子作的见证。'),
('CNV', '约翰一书', 62, 5, 10, '信神的儿子的，就有这见证在他心里；不信神的，就是把神当作说谎的，因为他不信神为他儿子所作的见证。'),
('CNV', '约翰一书', 62, 5, 11, '这见证就是神已经把永远的生命赐给我们，这生命是在他儿子里面的。'),
('CNV', '约翰一书', 62, 5, 12, '凡有神儿子的，就有生命；没有神儿子的，就没有生命。'),
('CNV', '约翰一书', 62, 5, 13, '我把这些事写给你们信神的儿子之名的人，是要你们知道自己有永生。'),
('CNV', '约翰一书', 62, 5, 14, '如果我们照着神的旨意祈求，他必听我们；这就是我们对神所存的坦然无惧的心。'),
('CNV', '约翰一书', 62, 5, 15, '既然我们知道他听我们的祈求，我们就知道，我们无论求什么，他必赐给我们。'),
('CNV', '约翰一书', 62, 5, 16, '如果有人看见弟兄犯了不至于死的罪，他就要祈求，神必因他的缘故，把生命赐给那些犯了不至于死的罪的人；有至于死的罪，我不说他应当为那罪祈求。'),
('CNV', '约翰一书', 62, 5, 17, '一切不义都是罪，但也有不至于死的罪。'),
('CNV', '约翰一书', 62, 5, 18, '我们知道凡从神生的就不犯罪，而且从神生的那一位也必保守他，连那恶者也不能碰他。'),
('CNV', '约翰一书', 62, 5, 19, '我们知道我们是属于神的，而整个世界是伏在那恶者手下。'),
('CNV', '约翰一书', 62, 5, 20, '我们知道神的儿子已经来了，并且赐给我们悟性，使我们能认识那位真实者。我们也在那位真实者里面，就是在他儿子耶稣基督里面。这一位就是真神，也是永远的生命。'),
('CNV', '约翰一书', 62, 5, 21, '孩子们，你们要保守自己远离偶像。'),
('CNV', '约翰二书', 63, 1, 1, '我这作长老的，写信给蒙拣选的夫人和她的儿女。你们是我在真理中所爱的；不单是我，凡认识真理的，'),
('CNV', '约翰二书', 63, 1, 2, '也因为真理的缘故爱你们。这真理在我们里面，也必与我们同在，直到永远。'),
('CNV', '约翰二书', 63, 1, 3, '愿恩惠、怜悯、平安，从父神和他儿子耶稣基督在真理和爱中与我们同在。'),
('CNV', '约翰二书', 63, 1, 4, '我看见你的儿女中，有人照着我们从父领受的命令在真理中行事，我就非常欣慰。'),
('CNV', '约翰二书', 63, 1, 5, '夫人哪，我现在请求你，我们要彼此相爱。我写给你的，不是一条新命令，而是我们从起初就有的。'),
('CNV', '约翰二书', 63, 1, 6, '我们要照着他的命令行事，这就是爱。你们从起初所听见的那命令，就是要你们凭着爱心行事。'),
('CNV', '约翰二书', 63, 1, 7, '有许多欺骗人的已经在世上出现，他们否认耶稣基督是成了肉身来的；这就是那骗人的和敌基督的。'),
('CNV', '约翰二书', 63, 1, 8, '你们要小心，不要拆毁我们已经完成的工作，却要得着美满的赏赐。'),
('CNV', '约翰二书', 63, 1, 9, '凡越过基督的教训又不持守的，就没有神；持守这教训的，就有父和子了。'),
('CNV', '约翰二书', 63, 1, 10, '如果有人到你们那里，不传这教训，你们就不要接待他到家里，也不要问候他；'),
('CNV', '约翰二书', 63, 1, 11, '因为问候他的，就在他的恶事上有分了。'),
('CNV', '约翰二书', 63, 1, 12, '我还有许多话要写给你们，可是我不想借用纸墨，只是盼望到你们那里当面谈谈，好让我们的喜乐充足。'),
('CNV', '约翰二书', 63, 1, 13, '你那蒙拣选的姊妹的儿女都问候你。'),
('CNV', '约翰三书', 64, 1, 1, '我这作长老的写信给亲爱的该犹，就是我在真理中所爱的。'),
('CNV', '约翰三书', 64, 1, 2, '亲爱的，我祝你凡事亨通，身体健壮，正如你的灵魂安泰一样。'),
('CNV', '约翰三书', 64, 1, 3, '有些弟兄来到，证实你心中存有真理，就是你按真理行事，我就非常欣慰。'),
('CNV', '约翰三书', 64, 1, 4, '我听见我的儿女按真理行事，我的喜乐没有比这更大的了。'),
('CNV', '约翰三书', 64, 1, 5, '亲爱的，你向弟兄所行的，特别是向外地来的弟兄所行的，都是出于忠心。'),
('CNV', '约翰三书', 64, 1, 6, '他们在教会面前证实了你的爱；你照着神所喜悦的，资助他们的旅程，这样是好的。'),
('CNV', '约翰三书', 64, 1, 7, '因为他们为主的名出外，并没有从教外人接受什么。'),
('CNV', '约翰三书', 64, 1, 8, '所以我们应当接待这样的人，好让我们为了真理成为同工。'),
('CNV', '约翰三书', 64, 1, 9, '我曾经略略写信给你那里的教会，但他们中间那好作领袖的丢特腓不接待我们。'),
('CNV', '约翰三书', 64, 1, 10, '因此，我来的时候，必要提起他所作的事，就是他用恶言中伤我们；这还不够，他不但不接待弟兄，还要阻止那些想要接待的人，甚至把他们赶出教会。'),
('CNV', '约翰三书', 64, 1, 11, '亲爱的，不要效法恶，应该效法善。行善的属于神，作恶的没有见过神。'),
('CNV', '约翰三书', 64, 1, 12, '低米丢行善，有众人为他作证，真理本身也为他作证。我们也为他作证，你知道我们的见证是真的。'),
('CNV', '约翰三书', 64, 1, 13, '我还有许多话要写给你，可是我不愿借用笔墨。'),
('CNV', '约翰三书', 64, 1, 14, '我盼望很快就见到你，当面谈谈。'),
('CNV', '约翰三书', 64, 1, 15, '愿你平安。这里的朋友都问候你。请你一一提名问候你那里的朋友。'),
('CNV', '犹大书', 65, 1, 1, '耶稣基督的仆人，雅各的兄弟犹大，写信给那些被召的人，就是在父神里蒙爱，并且为了耶稣基督而蒙保守的人。'),
('CNV', '犹大书', 65, 1, 2, '愿怜悯、平安、慈爱多多加给你们。'),
('CNV', '犹大书', 65, 1, 3, '亲爱的，尽管我曾经迫切地想写信给你们，论到我们共享的救恩；现在我更觉得必须写信劝勉你们，要竭力维护从前一次就全交给了圣徒的信仰，'),
('CNV', '犹大书', 65, 1, 4, '因为有人已经混进你们中间，他们就是早被判定受刑的不敬虔的人。这些人把我们神的恩典当作放纵情欲的借口，并且否认独一的主宰我们的主耶稣基督。'),
('CNV', '犹大书', 65, 1, 5, '虽然这一切事情你们都早已知道，我仍然要提醒你们：从前主从埃及地把人民救出来，跟着就把那些不信的人除灭了。'),
('CNV', '犹大书', 65, 1, 6, '还有，那不守本位擅离自己居所的天使，主就用永远的锁链把他们拘留在黑暗里，直到那大日子的审判。'),
('CNV', '犹大书', 65, 1, 7, '又像所多玛、蛾摩拉和周围城市的人，与他们一样的淫乱，随从逆性的情欲，以致遭受永火的刑罚，成了后世的鉴戒。'),
('CNV', '犹大书', 65, 1, 8, '虽然是这样，这些醉生梦死的人还是照样玷污身体，藐视主权，毁谤尊荣。'),
('CNV', '犹大书', 65, 1, 9, '就是天使长米迦勒为了摩西的尸体与魔鬼争论的时候，尚且不敢用毁谤的话定他的罪，只说：“主责备你！”'),
('CNV', '犹大书', 65, 1, 10, '但这些人毁谤他们所不知道的，他们只知道按本性所能领悟的事，好像没有理性的禽兽，就在这些事上败坏了自己。'),
('CNV', '犹大书', 65, 1, 11, '他们有祸了，因为他们走上了该隐的道路，又为了财利闯进巴兰的歧途，并且在可拉的背叛中灭亡了。'),
('CNV', '犹大书', 65, 1, 12, '这些人胆敢与你们同席，他们只顾喂饱（“喂饱”或译：“牧养”）自己，是你们爱筵中的暗礁；是无雨的浮云，随风飘荡；是秋天不结果子的树，连根拔起，死而又死；'),
('CNV', '犹大书', 65, 1, 13, '是海中的狂浪，溅起了自己可耻的泡沫；是流荡的星，有漆黑的幽暗永远为他们存留。'),
('CNV', '犹大书', 65, 1, 14, '亚当的第七世孙以诺，也曾经预言这些人说：“看，主必同他的千万圣者降临，'),
('CNV', '犹大书', 65, 1, 15, '要审判众人，又要定所有不敬虔的人的罪，因为他们妄行各样不敬虔的事，并且说了种种刚愎的话顶撞神。”'),
('CNV', '犹大书', 65, 1, 16, '这些人常发牢骚，怨天尤人，顺着自己的私欲行事，口说夸张的话，为了利益就不惜阿谀奉承。'),
('CNV', '犹大书', 65, 1, 17, '但你们呢，亲爱的，你们要记住我们主耶稣基督的使徒从前所说的话。'),
('CNV', '犹大书', 65, 1, 18, '他们曾经对你们说：“末世必有好讥笑人的人，随着自己不敬虔的私欲行事。”'),
('CNV', '犹大书', 65, 1, 19, '这些人分党结派，是属血气的，没有圣灵。'),
('CNV', '犹大书', 65, 1, 20, '但你们呢，亲爱的，你们要在至圣的信仰上建立自己，在圣灵里祷告，'),
('CNV', '犹大书', 65, 1, 21, '要保守自己在神的爱中，仰望我们主耶稣基督的怜悯，直到永生。'),
('CNV', '犹大书', 65, 1, 22, '有些人心里疑惑，你们要怜悯他们；'),
('CNV', '犹大书', 65, 1, 23, '有些人你们要拯救，把他们从火中抢救出来；又有些人你们要战战兢兢地怜悯他们，连染上情欲污渍的衣服也应当憎恶。'),
('CNV', '犹大书', 65, 1, 24, '愿荣耀、威严、能力、权柄，藉着我们的主耶稣基督，从万世以前，及现在，直到永永远远，归给独一的神我们的救主。他能保守你们不至跌倒，使你们毫无瑕疵、欢然站在他荣光之前。阿们。'),
('CNV', '启示录', 66, 1, 1, '耶稣基督的啓示，就是神赐给他，叫他把快要发生的事指示他的众仆人。他就差派天使显示给他的仆人约翰。'),
('CNV', '启示录', 66, 1, 2, '约翰把神的道，和耶稣基督的见证，凡是自己所看见的，都见证出来了。'),
('CNV', '启示录', 66, 1, 3, '读这书上预言的人，和那些听见这预言并且遵守书中记载的人，都是有福的！因为时候近了。'),
('CNV', '启示录', 66, 1, 4, '约翰写信给在亚西亚的七个教会。愿恩惠平安，从那位今在、昔在、以后要来的神，从他宝座前的七灵，'),
('CNV', '启示录', 66, 1, 5, '又从那信实的见证人、死人中首先复生的、地上众君王的统治者耶稣基督临到你们。他爱我们，用自己的血把我们从我们的罪中释放出来，'),
('CNV', '启示录', 66, 1, 6, '又使我们成为国度，作他父神的祭司。愿荣耀权能都归给他，直到永永远远。阿们。'),
('CNV', '启示录', 66, 1, 7, '看哪，他驾着云降临，每一个人都要看见他，连那些刺过他的人也要看见他，地上的万族都要因他哀号。这是必定的，阿们。'),
('CNV', '启示录', 66, 1, 8, '主神说：“我是阿拉法，我是俄梅格；我是今在、昔在、以后要来，全能的神。”'),
('CNV', '启示录', 66, 1, 9, '我约翰，就是你们的弟兄，在耶稣里跟你们一同分享患难、国度和忍耐的，为了神的道和耶稣的见证，曾经在那名叫拔摩的海岛上。'),
('CNV', '启示录', 66, 1, 10, '有一个主日，我在灵里，听见在我后边有一个大声音，好像号筒的响声，'),
('CNV', '启示录', 66, 1, 11, '说：“你所看见的，要写在书上，也要寄给以弗所、士每拿、别迦摩、推雅推拉、撒狄、非拉铁非、老底嘉七个教会。”'),
('CNV', '启示录', 66, 1, 12, '我转过身来要看看那跟我说话的声音是谁发的；一转过来，就看见七个金灯台。'),
('CNV', '启示录', 66, 1, 13, '灯台中间有一位好像人子的，身上穿着直垂到脚的长衣，胸间束着金带。'),
('CNV', '启示录', 66, 1, 14, '他的头和头发像白羊毛、像雪一样洁白，他的眼睛好像火焰，'),
('CNV', '启示录', 66, 1, 15, '他的两脚好像在炉中精炼过的发光的铜，他的声音好像众水的声音。'),
('CNV', '启示录', 66, 1, 16, '他的右手拿着七星，有一把两刃的利剑从他口中吐出来；他的脸发光好像正午的烈日。'),
('CNV', '启示录', 66, 1, 17, '我看见了他，就仆倒在他脚前，像死了一样。他用右手按着我，说：“不要怕！我是首先的，我是末后的，'),
('CNV', '启示录', 66, 1, 18, '又是永活的；我曾经死过，看哪，现在又活着，直活到永永远远，并且拿着死亡和阴间的钥匙。'),
('CNV', '启示录', 66, 1, 19, '所以，你要把所看见的，现在的，和今后将要发生的事都写下来。'),
('CNV', '启示录', 66, 1, 20, '你所看见在我右手中的七星和七个金灯台的奥秘就是这样：七星是七个教会的使者，七灯台是七个教会。”'),
('CNV', '启示录', 66, 2, 1, '“你要写信给在以弗所教会的使者，说：‘那右手拿着七星，在七个金灯台中间行走的，这样说：'),
('CNV', '启示录', 66, 2, 2, '我知道你的行为、你的劳苦、你的忍耐，也知道你不能容忍恶人。你也曾经试验那些自称是使徒，而其实不是使徒的人，看出他们是假的。'),
('CNV', '启示录', 66, 2, 3, '你有忍耐，曾为我的名的缘故忍受一切，并不困倦。'),
('CNV', '启示录', 66, 2, 4, '然而有一件事我要责备你，就是你已经离弃了你起初的爱。'),
('CNV', '启示录', 66, 2, 5, '所以，你应当回想你是从哪里坠落的，并且要悔改，作起初所作的事。你若不悔改，我就要来到你那里，把你的灯台从原处移去。'),
('CNV', '启示录', 66, 2, 6, '不过你有这一个优点，就是你恨恶尼哥拉党的作为，那也是我所恨恶的。'),
('CNV', '启示录', 66, 2, 7, '圣灵向众教会所说的话，有耳的就应当听。得胜的，我必定把神乐园里生命树的果子赐给他吃。’'),
('CNV', '启示录', 66, 2, 8, '“你要写信给在士每拿教会的使者，说：‘那首先的、末后的、曾经死去而又活过来的，这样说：'),
('CNV', '启示录', 66, 2, 9, '我知道你的患难和贫穷，但你却是富足的。我也知道那些自称是犹太人所说毁谤的话，其实他们不是犹太人，而是撒但的党徒。'),
('CNV', '启示录', 66, 2, 10, '你不要怕你将要受的苦。看哪！魔鬼将要把你们中间几个人下在监里，叫你们受试炼，你们要受患难十天。你要忠心至死，我就把那生命的冠冕赐给你。'),
('CNV', '启示录', 66, 2, 11, '圣灵向众教会所说的话，有耳的就应当听。得胜的，决不会受第二次死的害。’'),
('CNV', '启示录', 66, 2, 12, '“你要写信给在别迦摩教会的使者，说：‘那有一把两刃利剑的，这样说：'),
('CNV', '启示录', 66, 2, 13, '我知道你居住的地方，就是撒但王座所在的地方。当我忠心的见证人安提帕在你们那里，就是在撒但居住的地方被杀的那些日子，你还持守我的名，没有否认对我的信仰。'),
('CNV', '启示录', 66, 2, 14, '然而有几件事我要责备你，因为在你那里有些人持守巴兰的教训。这巴兰曾经教导巴勒把绊脚石放在以色列人面前，叫他们吃祭过偶像的食物，并且行淫乱。'),
('CNV', '启示录', 66, 2, 15, '同样，你也有些人持守尼哥拉党的教训。'),
('CNV', '启示录', 66, 2, 16, '所以，你应当悔改；如果不悔改，我就很快地来到你们那里，用我口中的剑跟他们作战。'),
('CNV', '启示录', 66, 2, 17, '圣灵向众教会所说的话，有耳的就应当听。得胜的，我必定把那隐藏的吗哪赐给他，并且赐他一块白石，石上写着新的名字，这名字除了那领受的人以外，是没有人能知道的。’'),
('CNV', '启示录', 66, 2, 18, '“你要写信给在推雅推拉教会的使者，说：‘神的儿子，那眼睛像火焰、两脚像光铜的，这样说：'),
('CNV', '启示录', 66, 2, 19, '我知道你的行为，你的爱心、信心、服侍和忍耐，也知道你后来所作的比先前的还要多。'),
('CNV', '启示录', 66, 2, 20, '然而有一件事我要责备你，就是你容让那自称是先知的妇人耶洗别，教导和引诱我的众仆人行淫乱，吃祭过偶像的食物。'),
('CNV', '启示录', 66, 2, 21, '我曾给她时间，让她悔改，她却不肯为她的淫行悔改。'),
('CNV', '启示录', 66, 2, 22, '看哪，我要把她抛在大患难的床上；那些跟她行淫乱的人，如果不为她的行为悔改，我也要把他们抛在大患难中。'),
('CNV', '启示录', 66, 2, 23, '我必以死亡击杀她的儿女；众教会就都知道我是察验人肺腑心肠的，我要照着你们的行为报应你们各人。'),
('CNV', '启示录', 66, 2, 24, '至于你们其余在推雅推拉的人，就是不跟从那教训，不认识所谓撒但深奥的事的人，我告诉你们，我不会把别的重担放在你们身上。'),
('CNV', '启示录', 66, 2, 25, '不过，你们要持守已经得着的，直到我来。'),
('CNV', '启示录', 66, 2, 26, '得胜的，又遵守我的旨意到底的，我必把统治列国的权柄赐给他，'),
('CNV', '启示录', 66, 2, 27, '他必用铁杖治理他们，好像打碎陶器一样粉碎他们，（“我必把……粉碎他们”引自诗2:8~9）好像我从父领受了权柄一样；'),
('CNV', '启示录', 66, 2, 28, '我还要把晨星赐给他。'),
('CNV', '启示录', 66, 2, 29, '圣灵向众教会所说的话，有耳的就应当听。’”'),
('CNV', '启示录', 66, 3, 1, '“你要写信给在撒狄教会的使者，说：‘那有神七灵和七星的这样说：我知道你的行为，你有名声，说你是活着的，其实你是死的。'),
('CNV', '启示录', 66, 3, 2, '你要警醒，把那些剩下来将要死的坚强起来；因为我见你的行为在我神面前是不完全的。'),
('CNV', '启示录', 66, 3, 3, '所以，你应当回想你是怎样领受、怎样听见的；应该遵守，也应该悔改。你若不警醒，我就要像贼来到一样。我什么时候来到你那里，你决不能知道。'),
('CNV', '启示录', 66, 3, 4, '然而在撒狄你还有几名是未曾玷污自己衣服的，他们要身穿白衣与我同行；因为他们是配得上的。'),
('CNV', '启示录', 66, 3, 5, '得胜的，也必这样身穿白衣，我决不从生命册上涂抹他的名，我还要在我父和他的众天使面前，承认他的名。'),
('CNV', '启示录', 66, 3, 6, '圣灵向众教会所说的话，有耳的就应当听。’'),
('CNV', '启示录', 66, 3, 7, '“你要写信给在非拉铁非教会的使者，说：‘那圣洁的、真实的，拿着大卫的钥匙，开了就没有人能关，关了就没有人能开的（“拿着大卫的钥匙……没有人能开的”引自赛22:22），这样说：'),
('CNV', '启示录', 66, 3, 8, '我知道你的行为，看哪！我已经在你面前给你一道开着的门，是没有人能关的；因为你有一点点力量，也遵守我的道，没有否认我的名。'),
('CNV', '启示录', 66, 3, 9, '看哪！从撒但的一党，就是自称是犹太人，其实不是犹太人，而是说谎的人中，我要使他们一些人来在你脚前下拜，并且知道我已经爱了你。'),
('CNV', '启示录', 66, 3, 10, '你既然遵守了我忍耐的道，我也必定保守你脱离那试炼的时候；这就是那将要临到普天下，来试炼住在地上的人的时候。'),
('CNV', '启示录', 66, 3, 11, '我必快来！你要持守你所有的，不要让人拿走你的冠冕。'),
('CNV', '启示录', 66, 3, 12, '得胜的，我要叫他在我神的圣所里作柱子，他决不再出去，我也要把我神的名，和我神的城的名，就是那从天上、从我神那里降下来的新耶路撒冷，以及我的新名，都写在他身上。'),
('CNV', '启示录', 66, 3, 13, '圣灵向众教会所说的话，有耳的就应当听。’'),
('CNV', '启示录', 66, 3, 14, '“你要写信给在老底嘉教会的使者，说：‘那位阿们的，忠信真实的见证人，神创造万有的根源，这样说：'),
('CNV', '启示录', 66, 3, 15, '我知道你的行为，你不冷也不热；我巴不得你或冷或热。'),
('CNV', '启示录', 66, 3, 16, '因为你好像温水，不热也不冷，所以我要把你从我口中吐出去。'),
('CNV', '启示录', 66, 3, 17, '你说：我是富足的，已经发了财，毫无缺乏。却不知你是困苦的、可怜的、贫穷的、瞎眼的、赤身的。'),
('CNV', '启示录', 66, 3, 18, '我劝你向我买精炼的金子，使你富足；又买白衣穿上，使你赤身的羞耻不会显露出来；也买眼药膏抹你的眼睛，使你可以看见。'),
('CNV', '启示录', 66, 3, 19, '凡是我所爱的，我就责备管教；所以你要热心，也要悔改。'),
('CNV', '启示录', 66, 3, 20, '看哪！我站在门外敲门；如果有人听见我的声音就开门的，我要进到他那里去，我要跟他在一起，他也要跟我在一起吃饭。'),
('CNV', '启示录', 66, 3, 21, '得胜的，我必定赐他和我一同坐在我的宝座上，正像我得了胜和我父一同坐在他的宝座上一样。'),
('CNV', '启示录', 66, 3, 22, '圣灵向众教会所说的话，有耳的就应当听。’”'),
('CNV', '启示录', 66, 4, 1, '这些事以后，我观看，见天上有一道门开着；并且有我第一次听见的那个好像号筒的声音，对我说：“你上这里来！我要把以后必定发生的事指示你。”'),
('CNV', '启示录', 66, 4, 2, '立刻，我在灵里，就看见有一个宝座，设立在天上，有一位坐在宝座上。'),
('CNV', '启示录', 66, 4, 3, '那位坐着的，看来好像碧玉和红宝石，又有彩虹围绕着宝座，看来好像绿宝石。'),
('CNV', '启示录', 66, 4, 4, '宝座的周围有二十四个座位，上面坐着二十四位长老，身穿白衣，头戴金冠。'),
('CNV', '启示录', 66, 4, 5, '有闪电、响声、雷轰从宝座中发出；又有七枝火炬在宝座前点着，这就是神的七灵。'),
('CNV', '启示录', 66, 4, 6, '宝座前有一个看来好像水晶的玻璃海。在宝座中间和宝座周围有四个活物，前后布满了眼睛。'),
('CNV', '启示录', 66, 4, 7, '第一个活物像狮子，第二个活物像牛犊，第三个活物的脸面像人，第四个活物像飞鹰。'),
('CNV', '启示录', 66, 4, 8, '四个活物各有六个翅膀，里外布满了眼睛。他们昼夜不停地说：“圣哉！圣哉！圣哉！主、全能的神，昔在、今在、以后要来的那一位。”'),
('CNV', '启示录', 66, 4, 9, '每逢四个活物把荣耀、尊贵、感谢献给那坐在宝座上，活到永永远远的那一位的时候，'),
('CNV', '启示录', 66, 4, 10, '二十四位长老就俯伏在坐在宝座上那一位的面前，敬拜那活到永永远远的，又把他们的冠冕放在宝座前，说：'),
('CNV', '启示录', 66, 4, 11, '“主、我们的神，你是配得荣耀、尊贵、权能的，因为你创造了万有，万有都是因着你的旨意而存在，而被造的。”'),
('CNV', '启示录', 66, 5, 1, '我看见那位坐在宝座上的，右手拿著书卷，这书卷的两面都写满了字，用七个印封着。'),
('CNV', '启示录', 66, 5, 2, '我又看见一位大力的天使，大声宣告说：“谁配展开那书卷，拆开它的封印呢？”'),
('CNV', '启示录', 66, 5, 3, '在天上、地上、地底下，没有一个能够展开书卷观看的。'),
('CNV', '启示录', 66, 5, 4, '因为没有人配展开观看书卷，我就大哭。'),
('CNV', '启示录', 66, 5, 5, '长老中有一位对我说：“不要哭！看哪，那从犹大支派出来的狮子，大卫的根，他已经得胜了，他能够展开那书卷，拆开它的七印。”'),
('CNV', '启示录', 66, 5, 6, '我又看见在宝座和四个活物中间，并且在众长老中间，有羊羔站着，象是被杀过的。他有七角七眼，就是神的七灵，奉差遣到全地去的。'),
('CNV', '启示录', 66, 5, 7, '羊羔走过去，从坐在宝座上那位的右手中取了书卷。'),
('CNV', '启示录', 66, 5, 8, '他拿了书卷之后，四个活物和二十四位长老就俯伏在羊羔面前，各拿着琴和盛满了香的金炉，这香就是众圣徒的祈祷。'),
('CNV', '启示录', 66, 5, 9, '他们唱着新歌，说：“你配取书卷，配拆开封印，因为你曾被杀，曾用你的血，从各支派、各方言、各民族、各邦国，把人买了来归给神，'),
('CNV', '启示录', 66, 5, 10, '使他们成为我们神的国度和祭司，他们要在地上执掌王权。”'),
('CNV', '启示录', 66, 5, 11, '我又观看，听见了千千万万天使的声音，他们都在宝座、活物和长老的四周，'),
('CNV', '启示录', 66, 5, 12, '大声说：“被杀的羊羔是配得权能、丰富、智慧、力量、尊贵、荣耀、颂赞的！”'),
('CNV', '启示录', 66, 5, 13, '我又听见在天上、地上、地底下和海里的一切被造之物，以及天地间的万有，都说：“愿颂赞、尊贵、荣耀、能力，都归给坐在宝座上的那一位和羊羔，直到永永远远！”'),
('CNV', '启示录', 66, 5, 14, '四个活物就说：“阿们！”众长老也俯伏敬拜。'),
('CNV', '启示录', 66, 6, 1, '羊羔揭开了七印的第一个印的时候，我观看，就听见四个活物中的一个，发出好像雷轰的声响，说：“你来！”'),
('CNV', '启示录', 66, 6, 2, '我观看，见有一匹白马；骑在马上的拿着弓，有冠冕赐给他，他就出去，得胜并且要再得胜。'),
('CNV', '启示录', 66, 6, 3, '羊羔揭开了第二个印的时候，我听见第二个活物说：“你来！”'),
('CNV', '启示录', 66, 6, 4, '就另有一匹红马出来，骑在马上的得了权柄，可以从地上夺去和平，使人互相残杀，又有一把大刀赐给他。'),
('CNV', '启示录', 66, 6, 5, '羊羔揭开了第三个印的时候，我听见第三个活物说：“你来！”我观看，见有一匹黑马；骑在马上的，手中拿着天平。'),
('CNV', '启示录', 66, 6, 6, '我听见在四个活物中间，仿佛有声音说：“一公升小麦卖一个银币，三公升大麦卖一个银币，油和酒也不可糟蹋。”'),
('CNV', '启示录', 66, 6, 7, '羊羔揭开了第四个印的时候，我听见第四个活物的声音说：“你来！”'),
('CNV', '启示录', 66, 6, 8, '我观看，见有一匹灰马；骑在马上的，名字叫作“死”。阴间也跟随着他。他们得了权柄可以管辖地上的四分之一，又要用刀剑、饥荒、瘟疫和地上的野兽去杀人。'),
('CNV', '启示录', 66, 6, 9, '羊羔揭开了第五个印的时候，我看见祭坛底下，有为了神的道，并且为了自己所作的见证而被杀的人的灵魂。'),
('CNV', '启示录', 66, 6, 10, '他们大声喊叫，说：“圣洁真实的主啊！你不审判住在地上的人，给我们伸流血的冤，要到几时呢？”'),
('CNV', '启示录', 66, 6, 11, '于是有白袍赐给他们各人，又有话吩咐他们要安息一会儿，等到那些与他们同作仆人和弟兄，像他们一样将要被杀的人，凑满了数目的时候。'),
('CNV', '启示录', 66, 6, 12, '羊羔揭开了第六个印的时候，我观看，大地震就发生了。太阳变黑，像粗糙的黑毛布；整个月亮变红，像血一样；'),
('CNV', '启示录', 66, 6, 13, '天上的星辰坠落在地上，像无花果树被大风摇动，落下还没有成熟的果子。'),
('CNV', '启示录', 66, 6, 14, '天隐退了，像书被卷起来一样；山岭和海岛都从原处移去了。'),
('CNV', '启示录', 66, 6, 15, '地上的君王、大臣、军长、财主、勇士和所有作奴隶的、自由的，都藏在山洞和岩穴里。'),
('CNV', '启示录', 66, 6, 16, '他们向山岭和岩石说：“倒在我们身上吧！把我们藏起来，躲避坐在宝座上那位的面，和羊羔的震怒！'),
('CNV', '启示录', 66, 6, 17, '因为他们震怒的大日子来到了，谁能站立得住呢？”'),
('CNV', '启示录', 66, 7, 1, '这事以后，我看见四位天使站在地的四极，掌握着地上的四风，不使风吹在地上、海上和任何树上。'),
('CNV', '启示录', 66, 7, 2, '我又看见另外一位天使，从日出之地上来，拿着永活神的印，向那四位得了权柄可以伤害地和海的天使，大声呼喊，'),
('CNV', '启示录', 66, 7, 3, '说：“你们不要伤害地、海和树木，等我们在神众仆人的额上先盖上了印。”'),
('CNV', '启示录', 66, 7, 4, '我听见被盖印的人的数目，以色列子孙各支派中被盖印的共有十四万四千人：'),
('CNV', '启示录', 66, 7, 5, '犹大支派中被盖印的，一万二千人；流本支派中，一万二千人；迦得支派中，一万二千人；'),
('CNV', '启示录', 66, 7, 6, '亚设支派中，一万二千人；拿弗他利支派中，一万二千人；玛拿西支派中，一万二千人；'),
('CNV', '启示录', 66, 7, 7, '西缅支派中，一万二千人；利未支派中，一万二千人；以萨迦支派中，一万二千人；'),
('CNV', '启示录', 66, 7, 8, '西布伦支派中，一万二千人；约瑟支派中，一万二千人；便雅悯支派中，一万二千人。'),
('CNV', '启示录', 66, 7, 9, '这些事以后，我观看，见有一大群人，没有人能数得过来，是从各邦国、各支派、各民族、各方言来的。他们都站在宝座和羊羔面前，身穿白袍，手里拿着棕树枝。'),
('CNV', '启示录', 66, 7, 10, '他们大声呼喊，说：“愿救恩归给那坐在宝座上我们的神，也归给羊羔！”'),
('CNV', '启示录', 66, 7, 11, '所有的天使都站在宝座、众长老和四个活物的四周。他们在宝座前，面伏在地上敬拜神，'),
('CNV', '启示录', 66, 7, 12, '说：“阿们！愿颂赞、荣耀、智慧、感谢、尊贵、权能、力量，都归给我们的神，直到永永远远。阿们！”'),
('CNV', '启示录', 66, 7, 13, '长老中有一位问我：“这些身穿白袍的是谁？他们是从哪里来的呢？”'),
('CNV', '启示录', 66, 7, 14, '我对他说：“我主啊，你是知道的。”他告诉我：“这些人是从大患难中出来的。他们用羊羔的血，把自己的衣袍洗洁白了。'),
('CNV', '启示录', 66, 7, 15, '因此，他们可以在神的宝座前，并且日夜在他的圣所里事奉他。那坐在宝座上的必展开帐幕覆庇他们。'),
('CNV', '启示录', 66, 7, 16, '他们必不再饿，也不再渴；太阳和一切炎热必不伤害他们。'),
('CNV', '启示录', 66, 7, 17, '因为在宝座中间的羊羔必牧养他们，领他们到生命水的泉源那里。神也必抹去他们的一切眼泪。”'),
('CNV', '启示录', 66, 8, 1, '羊羔揭开第七个印的时候，天上静默了大约半小时。'),
('CNV', '启示录', 66, 8, 2, '我看见站在神面前的七位天使，有七枝号筒赐给了他们。'),
('CNV', '启示录', 66, 8, 3, '另外有一位天使来了，拿着金香炉，站在祭坛前。有许多香赐给了他，好与所有圣徒的祈祷一同献在宝座前的金坛上。'),
('CNV', '启示录', 66, 8, 4, '那香的烟和众圣徒的祈祷，就从天使手中一同升到神面前。'),
('CNV', '启示录', 66, 8, 5, '天使拿着香炉，用坛上的火把它装满了，投在地上；于是就有雷轰、响声、闪电和地震。'),
('CNV', '启示录', 66, 8, 6, '拿着七枝号筒的七位天使，预备好了要吹号。'),
('CNV', '启示录', 66, 8, 7, '第一位天使吹号，就有冰雹和混杂着血的火，投在地上。地的三分之一烧掉了，树的三分之一烧掉了，所有的青草也烧掉了。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '启示录', 66, 8, 8, '第二位天使吹号，就有一座好像燃烧着的大山，投在海里。海的三分之一变成了血，'),
('CNV', '启示录', 66, 8, 9, '海里受造的活物死了三分之一，船只也毁坏了三分之一。'),
('CNV', '启示录', 66, 8, 10, '第三位天使吹号，就有一颗燃烧着的大星，好像火把一样，从天上落下来，落在江河的三分之一上，和众水的泉源上。'),
('CNV', '启示录', 66, 8, 11, '这星名叫“苦堇”。众水的三分之一变为“苦堇”，因水变苦，就有许多人因为这水而死了。'),
('CNV', '启示录', 66, 8, 12, '第四位天使吹号，太阳的三分之一、月亮的三分之一、星辰的三分之一，就都受到击打，以致日月星的三分之一都变黑了，白天的三分之一没有光，夜晚也是这样。'),
('CNV', '启示录', 66, 8, 13, '我观看，就听见一只在高空飞翔的鹰，大声说：“有祸了！有祸了！住在地上的人有祸了！因为还有三位天使将要吹其余的号。”'),
('CNV', '启示录', 66, 9, 1, '第五位天使吹号，我就看见一颗星从天上落到地上，有无底坑的钥匙赐给它。'),
('CNV', '启示录', 66, 9, 2, '它开了无底坑，就有烟从坑里冒出来，好像大火炉的烟，太阳和天空因这坑的烟就都变黑了。'),
('CNV', '启示录', 66, 9, 3, '有蝗虫从烟里出来到了地上；有能力赐给它们，好像地上蝎子的能力一样。'),
('CNV', '启示录', 66, 9, 4, '有话吩咐它们，不可伤害地上的草，和所有青翠的东西，以及所有的树木，只可伤害那些额上没有神印记的人。'),
('CNV', '启示录', 66, 9, 5, '蝗虫没有能力杀死他们，只可使他们受痛苦五个月。他们的痛苦就像人给蝎子螫了的痛苦一样。'),
('CNV', '启示录', 66, 9, 6, '在那些日子，人要求死，却决不得死；切愿要死，死却远离他们。'),
('CNV', '启示录', 66, 9, 7, '蝗虫的形象，好像是预备好了要上阵的战马一样。它们头上戴的好像金冠冕，脸像人的面孔，'),
('CNV', '启示录', 66, 9, 8, '它们的头发好像女人的头发，牙齿好像狮子的牙齿；'),
('CNV', '启示录', 66, 9, 9, '它们的胸甲像铁甲，它们翅膀的声音好像许多马车奔驰上阵的声音。'),
('CNV', '启示录', 66, 9, 10, '它们好像蝎子一样有尾巴和毒刺，它们的尾巴能伤害人五个月。'),
('CNV', '启示录', 66, 9, 11, '它们有无底坑的使者作王统治它们。这王的名字，希伯来话叫阿巴顿，希腊话叫阿波伦。'),
('CNV', '启示录', 66, 9, 12, '第一样灾祸过去了。看哪，以后还有两样灾祸要来！'),
('CNV', '启示录', 66, 9, 13, '第六位天使吹号，我听见有一个声音从神面前金坛的四角发出来，'),
('CNV', '启示录', 66, 9, 14, '对拿着号筒的第六位天使说：“把捆绑在幼发拉底大河的那四个使者放了吧！”'),
('CNV', '启示录', 66, 9, 15, '那四个使者就被释放了，他们已经预备好，要在某年某月某日某时杀害人类的三分之一。'),
('CNV', '启示录', 66, 9, 16, '马兵的数目有二万万；他们这个数目我听见了。'),
('CNV', '启示录', 66, 9, 17, '在异象中，我看见那些马和骑马的是这样：骑马的穿着火红紫青和硫磺色的胸甲，马的头好像狮子头，有火、烟和硫磺从马的口中喷出来。'),
('CNV', '启示录', 66, 9, 18, '马口中喷出来的火、烟和硫磺这三种灾害，杀死了人类的三分之一。'),
('CNV', '启示录', 66, 9, 19, '马的能力是在口中和尾巴上。它们的尾巴像蛇，并且有头用来伤人。'),
('CNV', '启示录', 66, 9, 20, '其余没有在这些灾难中被杀的人，仍然不为他们手所作的悔改，还是去拜鬼魔和那些金、银、铜、石头、木头做的，不能看、不能听、也不能走路的偶像。'),
('CNV', '启示录', 66, 9, 21, '他们也不为自己的凶杀、邪术、淫乱和偷盗悔改。'),
('CNV', '启示录', 66, 10, 1, '我又看见一位大力的天使从天上降下来，身披云彩，头上有彩虹，脸像太阳，两脚像火柱一样，'),
('CNV', '启示录', 66, 10, 2, '手里拿着展开的小书卷。他的右脚踏在海上，左脚踏在地上，'),
('CNV', '启示录', 66, 10, 3, '大声呼喊，好像狮子吼叫。他呼喊的时候，就有七雷发声说话。'),
('CNV', '启示录', 66, 10, 4, '七雷说话的时候，我正要写下来，就听见有声音从天上出来，说：“七雷所说的你要封住，不可写出来！”'),
('CNV', '启示录', 66, 10, 5, '我看见那站在海上和地上的天使，向天举起右手来，'),
('CNV', '启示录', 66, 10, 6, '指着那活到永永远远，创造天和天上之物、地和地上之物、海和海中之物的神起誓，说：“必不再延迟了！'),
('CNV', '启示录', 66, 10, 7, '到第七位天使吹号的时候，神向他的仆人众先知所宣告的奥秘，就要实现了。”'),
('CNV', '启示录', 66, 10, 8, '我先前听见那从天上来的声音又对我说：“你去，把那站在海上和地上的天使手中展开的书卷拿过来。”'),
('CNV', '启示录', 66, 10, 9, '我就走到天使那里，请他把小书卷给我。他对我说：“你拿着，吃下去。它必使你肚子苦涩，但是口里却好像蜜一样甘甜。”'),
('CNV', '启示录', 66, 10, 10, '我把小书卷从天使手中拿过来，吃了，在口里果然甘甜如蜜；但是吃完之后，我肚子就觉得苦涩。'),
('CNV', '启示录', 66, 10, 11, '他们又对我说：“论到许多民族、邦国、方言和君王，你必须再说预言。”'),
('CNV', '启示录', 66, 11, 1, '有一根好像量尺的芦苇赐给了我，又有话说：“你起来，把神的圣所和祭坛，以及在里面敬拜的人，都量一量、数一数。'),
('CNV', '启示录', 66, 11, 2, '但圣所外面的院子，不要量它，因为它已经给了外族人，他们要践踏圣城四十二个月。'),
('CNV', '启示录', 66, 11, 3, '我要赐能力给我那两个穿着麻衣的见证人，他们要传道一千二百六十天。”'),
('CNV', '启示录', 66, 11, 4, '他们就是站在全地之主面前的两棵橄榄树和两个灯台。'),
('CNV', '启示录', 66, 11, 5, '如果有人想要伤害他们，就有火从他们口中出来，吞灭他们的仇敌。凡是想要伤害他们的，都必这样被杀。'),
('CNV', '启示录', 66, 11, 6, '他们有权柄在他们传道的日子叫天闭塞不下雨，又有权柄掌管众水，使水变成血，并且有权柄可以随时随意用各样灾难击打全地。'),
('CNV', '启示录', 66, 11, 7, '他们作完了见证的时候，那从无底坑上来的兽要跟他们作战，胜过他们，把他们杀死。'),
('CNV', '启示录', 66, 11, 8, '他们的尸首要倒在大城的街道上。这城按着寓意叫所多玛，又叫埃及，就是他们的主被钉十字架的地方。'),
('CNV', '启示录', 66, 11, 9, '从各民族、各支派、各方言和各邦国中，都有人观看他们的尸首三天半，又不许人把尸首安放在坟墓里。'),
('CNV', '启示录', 66, 11, 10, '住在地上的人为了他们的缘故，就欢喜快乐，彼此送礼，因为这两位先知曾经使他们受痛苦。'),
('CNV', '启示录', 66, 11, 11, '过了三天半，有生命的气息从神那里来，进入他们里面，他们就站立起来，看见他们的人都非常惧怕。'),
('CNV', '启示录', 66, 11, 12, '他们听见从天上来的大声音，对他们说：“上这里来！”他们就驾着云上了天，他们的仇敌也看见了。'),
('CNV', '启示录', 66, 11, 13, '就在那时，大地震发生了，那座城倒塌了十分之一，因着地震而死的有七千人，其余的人都很害怕，就把荣耀归给天上的神。'),
('CNV', '启示录', 66, 11, 14, '第二样灾祸过去了。看哪，第三样灾祸快要到了！'),
('CNV', '启示录', 66, 11, 15, '第七位天使吹号，天上就有大声音说：“世上的国成了我们的主和他所立的基督的国，他要作王，直到永永远远！”'),
('CNV', '启示录', 66, 11, 16, '那在神面前，坐在自己座位上的二十四位长老，都面伏在地上敬拜神，'),
('CNV', '启示录', 66, 11, 17, '说：“主啊！全能的神，昔在今在的，我们感谢你！因为你执掌了大权，作王了！'),
('CNV', '启示录', 66, 11, 18, '列国忿怒了！你的震怒也临到了！时候已经到了！死人要受审判！你的众仆人、先知、圣徒，和所有老幼贵贱、敬畏你名的人，都要得赏赐！你也要毁灭那些败坏全地的人！”'),
('CNV', '启示录', 66, 11, 19, '于是，在天上神的圣所开了，他的约柜就在他的圣所中显现出来。随即有闪电、响声、雷轰、地震、大冰雹。'),
('CNV', '启示录', 66, 12, 1, '那时，天上出现了一个奇伟的景象：有一个妇人，身披太阳，脚踏月亮，头戴十二颗星的冠冕。'),
('CNV', '启示录', 66, 12, 2, '她怀了孕，在生产的痛苦中疼痛呼叫。'),
('CNV', '启示录', 66, 12, 3, '天上又出现了另一个景象。看哪！有一条大红龙，有七头十角，七头上戴着七个皇冠。'),
('CNV', '启示录', 66, 12, 4, '它的尾巴拖着天上三分之一的星辰，把它们摔在地上。龙站在那快要生产的妇人面前，等她生产了，就要吞吃她的孩子。'),
('CNV', '启示录', 66, 12, 5, '她生了一个男孩子，就是将来要用铁杖治理列国的。她的孩子被提取到神和他宝座那里去。'),
('CNV', '启示录', 66, 12, 6, '妇人就逃到旷野去了，那里有神为她预备的地方。她在那里得供养一千二百六十天。'),
('CNV', '启示录', 66, 12, 7, '天上发生了战争：米迦勒和他的天使与龙作战。龙和它的天使也起来应战，'),
('CNV', '启示录', 66, 12, 8, '龙却抵挡不住，天上再也没有它们的地方了。'),
('CNV', '启示录', 66, 12, 9, '于是那大龙被摔了下来。它就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的人的。它被摔在地上，它的天使也跟它一同被摔了下来。'),
('CNV', '启示录', 66, 12, 10, '我又听见天上有大声音说：“我们神的救恩、能力、国度和他所立的基督的权柄，现在都已经来到了！因为那昼夜在我们神面前控告我们弟兄的控告者，已经被摔下来了！'),
('CNV', '启示录', 66, 12, 11, '弟兄胜过它，是因着羊羔的血，也因着自己所见证的道，他们虽然至死，也不爱惜自己的性命。'),
('CNV', '启示录', 66, 12, 12, '所以，众天和住在其中的，你们都欢乐吧！可是地和海有祸了！因为魔鬼知道自己的时日无多，就大大发怒下到你们那里去了。”'),
('CNV', '启示录', 66, 12, 13, '龙见自己被摔在地上，就迫害那生了男孩子的妇人。'),
('CNV', '启示录', 66, 12, 14, '于是有大鹰的两个翅膀赐给了那妇人，使她可以飞到旷野，到自己的地方，在那里得供养一年两年半年，离开那蛇的面。'),
('CNV', '启示录', 66, 12, 15, '蛇在妇人后面，从口中吐出水来，好像江河一样，要把妇人冲去。'),
('CNV', '启示录', 66, 12, 16, '地却帮助了那妇人，张开口，把从龙口中吐出来的河水吞了。'),
('CNV', '启示录', 66, 12, 17, '龙就向妇人发怒，去和她其余的子孙作战，就是和那遵守神命令坚持耶稣见证的人作战。'),
('CNV', '启示录', 66, 12, 18, '那时，龙站在海边的沙上。'),
('CNV', '启示录', 66, 13, 1, '我又看见一只兽从海里上来，有十角七头，十角上戴着十个皇冠，七头上有亵渎的名号。'),
('CNV', '启示录', 66, 13, 2, '我所看见的兽，样子好像豹，脚像熊的脚，口像狮子的口。龙把自己的能力、王位和大权柄，都交给了它。'),
('CNV', '启示录', 66, 13, 3, '兽的七头中有一个似乎受了致命伤，但那致命伤却医好了。全地的人都很惊奇，跟从那兽。'),
('CNV', '启示录', 66, 13, 4, '因为龙把权柄交给了兽，大家就拜龙，也拜兽，说：“有谁可以跟这兽相比？有谁能与它作战呢？”'),
('CNV', '启示录', 66, 13, 5, '龙又给了那兽一张说夸大和亵渎话的嘴巴，也给了它权柄可以任意而行四十二个月。'),
('CNV', '启示录', 66, 13, 6, '兽就开口向神说亵渎的话，亵渎他的名和他的帐幕，以及那些住在天上的。'),
('CNV', '启示录', 66, 13, 7, '它得了允许能跟圣徒作战，并且能胜过他们；又有权柄给了它，可以管辖各支派、各民族、各方言、各邦国。'),
('CNV', '启示录', 66, 13, 8, '所有住在地上的人，名字没有记在创世以来被杀的羊羔之生命册上的，都要拜它。'),
('CNV', '启示录', 66, 13, 9, '凡有耳的，就应当听！'),
('CNV', '启示录', 66, 13, 10, '如果人应该被俘掳，就必被俘掳；如果人应该被刀杀，就必被刀杀。在这里圣徒要有忍耐和信心！'),
('CNV', '启示录', 66, 13, 11, '我又看见另一只兽从地里上来。它有两个角，好像羊羔，说话好像龙。'),
('CNV', '启示录', 66, 13, 12, '它在头一只兽面前，行使头一只兽的一切权柄。它使全地和住在地上的人，都拜那受过致命伤而医好了的头一只兽。'),
('CNV', '启示录', 66, 13, 13, '它又行大奇事，甚至在人面前叫火从天上降在地上。'),
('CNV', '启示录', 66, 13, 14, '它得了能力，在头一只兽面前能行奇事，迷惑了住在地上的人，吩咐住在地上的人，要为那受过刀伤而还活着的兽做个像。'),
('CNV', '启示录', 66, 13, 15, '又有能力赐给它，可以把气息给兽像，使兽像能够说话，并且能够杀害那些不拜兽像的人。'),
('CNV', '启示录', 66, 13, 16, '那从地里上来的兽，又要所有的人，无论大小贫富，自由的和作奴隶的，都在右手或额上，给自己作个记号。'),
('CNV', '启示录', 66, 13, 17, '这记号就是兽的名字或兽名的数字，除了那有记号的，谁也不能买，谁也不能卖。'),
('CNV', '启示录', 66, 13, 18, '在这里要有智慧。有悟性的人，就让他计算兽的数字，因为这是人的数字，它的数字是六百六十六。'),
('CNV', '启示录', 66, 14, 1, '我又观看，见羊羔站在锡安山上，跟他在一起的还有十四万四千人。他们的额上都写着他的名和他父的名。'),
('CNV', '启示录', 66, 14, 2, '我听见有声音从天上来，好像众水的声音，好像大雷的声音；我所听见的声音，又像琴师弹奏的琴声。'),
('CNV', '启示录', 66, 14, 3, '他们在宝座前，在四个活物和众长老面前唱新歌；除了从地上买来的那十四万四千人以外，没有人能学这歌。'),
('CNV', '启示录', 66, 14, 4, '这些人没有跟妇女在一起而使自己玷污，他们原是童身的。羊羔无论到哪里去，他们都跟随他。这些人是从世人中买来的，作初熟的果子归给神和羊羔。'),
('CNV', '启示录', 66, 14, 5, '在他们口中找不着谎言；他们是没有瑕疵的。'),
('CNV', '启示录', 66, 14, 6, '我又看见另一位天使在高空飞翔，有永远的福音要传给住在地上的人，就是各邦国、各支派、各方言、各民族的人。'),
('CNV', '启示录', 66, 14, 7, '他大声说：“应当敬畏神，把荣耀归给他！因为他审判的时候到了，应当敬拜创造天、地、海和众水泉源的那一位！”'),
('CNV', '启示录', 66, 14, 8, '又有第二位天使接着说：“倾倒了！大巴比伦倾倒了！它曾经叫列国喝它淫乱烈怒的酒。”'),
('CNV', '启示录', 66, 14, 9, '又有第三位天使接着他们大声说：“如果有人拜兽和兽像，又在自己的额上或手上受了记号，'),
('CNV', '启示录', 66, 14, 10, '他就必定喝神烈怒的酒：这酒是斟在神震怒的杯中，纯一不杂的。他必定在众天使和羊羔面前，在火与硫磺之中受痛苦。'),
('CNV', '启示录', 66, 14, 11, '他们受痛苦的烟往上冒，直到永永远远。那些拜兽和兽像的，以及接受它名字的记号的人，日夜得不到安息。”'),
('CNV', '启示录', 66, 14, 12, '在这里，那些遵守神的命令和耶稣的信仰的圣徒，要有忍耐。'),
('CNV', '启示录', 66, 14, 13, '我听见从天上有声音说：“你要写下来！从今以后，那在主里死去的人有福了！”圣灵说：“是的，他们脱离自己的劳苦，得享安息了，他们的作为也随着他们。”'),
('CNV', '启示录', 66, 14, 14, '我又观看，见有一片白云，云上坐着一位好像人子的，头上戴着金冠，手里拿着锋利的镰刀。'),
('CNV', '启示录', 66, 14, 15, '有另一位天使从圣所出来，对那坐在云上的大声呼喊：“伸出你的镰刀来收割吧！因为收割的时候已经到了，地上的庄稼已经熟透了。”'),
('CNV', '启示录', 66, 14, 16, '于是那坐在云上的向地上挥动镰刀，地上的庄稼就被收割了。'),
('CNV', '启示录', 66, 14, 17, '又有另一位天使从天上的圣所出来，他也拿着一把锋利的镰刀。'),
('CNV', '启示录', 66, 14, 18, '接着，又有一位天使从祭坛那里出来，是有权柄掌管火的；他向那拿着锋利镰刀的天使大声说：“伸出你锋利的镰刀来，收取地上葡萄树累累的果子吧！因为葡萄已经熟透了。”'),
('CNV', '启示录', 66, 14, 19, '于是，那天使向地上挥动镰刀，收取了地上的葡萄，把葡萄扔在神烈怒的大压酒池里。'),
('CNV', '启示录', 66, 14, 20, '那压酒池在城外被踹踏，就有血从压酒池流出来，涨到马的嚼环那么高，流到三百公里（“三百公里”原文作“一千六百司他町”）那么远。'),
('CNV', '启示录', 66, 15, 1, '我看见天上有另一个景象，又大又奇。有七位天使掌管着末后的七灾，因为神的烈怒在这七灾中发尽了。'),
('CNV', '启示录', 66, 15, 2, '我又看见好像有一个搀杂着火的玻璃海；也看见那些胜过了兽、兽像，以及兽名的数字的人。他们都站在玻璃海上，拿着神的琴。'),
('CNV', '启示录', 66, 15, 3, '他们唱着神仆人摩西的歌和羊羔的歌，说：“主啊！全能的神，你的作为又伟大又奇妙！万国的王啊，你的道路又公义又真实！'),
('CNV', '启示录', 66, 15, 4, '主啊！谁敢不敬畏你，不荣耀你的名呢？因为只有你是神圣的，万国都要来，在你面前下拜，因为你公义的作为已经显明出来了。”'),
('CNV', '启示录', 66, 15, 5, '这些事以后，我观看，见天上安放约柜（“约柜”原文作“见证的柜”）的帐幕的圣所开了。'),
('CNV', '启示录', 66, 15, 6, '那掌管着末后七灾的七位天使，从圣所出来，穿着清洁明亮的细麻衣，胸间束着金带。'),
('CNV', '启示录', 66, 15, 7, '四个活物中有一个，把盛满了活到永永远远之神的烈怒的七个金碗，交给了那七位天使。'),
('CNV', '启示录', 66, 15, 8, '因着神的荣耀和大能，圣所中充满了烟，在那七位天使降完七灾以前，没有人能进入圣所。'),
('CNV', '启示录', 66, 16, 1, '我听见有大声音从圣所里发出来，向那七位天使说：“你们去，把神烈怒的七碗倒在地上！”'),
('CNV', '启示录', 66, 16, 2, '第一位天使去了，把碗倒在地上，就有恶性的毒疮，生在那些有兽的记号和拜兽像的人身上。'),
('CNV', '启示录', 66, 16, 3, '第二位天使把碗倒在海里，海水就变成好像死人的血，海里的一切生物都死了。'),
('CNV', '启示录', 66, 16, 4, '第三位天使把碗倒在江河和众水的泉源里，水就变成了血。'),
('CNV', '启示录', 66, 16, 5, '我听见掌管众水的天使说：“今在昔在的圣者啊！你这样审判是公义的，'),
('CNV', '启示录', 66, 16, 6, '因为他们曾流圣徒和先知的血，现在你给他们血喝，这是他们该受的。”'),
('CNV', '启示录', 66, 16, 7, '我又听见祭坛中有声音说：“是的，主啊！全能的神，你的审判真实、公义！”'),
('CNV', '启示录', 66, 16, 8, '第四位天使把碗倒在太阳上，太阳就得了能力，可以用火烤人。'),
('CNV', '启示录', 66, 16, 9, '人被高热烧烤，就亵渎那有权柄掌管这些灾难的神的名，并不悔改，把荣耀归给他。'),
('CNV', '启示录', 66, 16, 10, '第五位天使把碗倒在兽的座位上，兽的国就黑暗了。人因为痛苦就咬自己的舌头。'),
('CNV', '启示录', 66, 16, 11, '他们又因为所受的痛苦和所生的疮，亵渎天上的神，并不为自己所作的悔改。'),
('CNV', '启示录', 66, 16, 12, '第六位天使把碗倒在幼发拉底大河上，河水就干了，为了要给那些从东方来的王预备道路。'),
('CNV', '启示录', 66, 16, 13, '我看见三个污灵，好像青蛙从龙口、兽口和假先知的口中出来。'),
('CNV', '启示录', 66, 16, 14, '他们原是鬼魔的灵，施行奇事；它们到普天下的众王那里去，叫他们在全能神的大日聚集作战。'),
('CNV', '启示录', 66, 16, 15, '（看哪，我来像贼一样！那警醒、看守自己衣服的是有福的！他就不至于赤身行走，让人看见他的羞耻。）'),
('CNV', '启示录', 66, 16, 16, '污灵就把众王聚集在一个地方，希伯来话叫哈米吉多顿。'),
('CNV', '启示录', 66, 16, 17, '第七位天使把碗倒在空中，就有大声音从圣所的宝座上发出来，说：“成了！”'),
('CNV', '启示录', 66, 16, 18, '于是有闪电、响声、雷轰和大地震，自从地上有人以来，没发生过这么大的地震，'),
('CNV', '启示录', 66, 16, 19, '那大城裂为三段，列国的城也都倒塌了。神也想起巴比伦大城来，要把自己烈怒的酒杯递给它。'),
('CNV', '启示录', 66, 16, 20, '各海岛都逃避了，众山也不见了。'),
('CNV', '启示录', 66, 16, 21, '有大冰雹从天上落在人的身上，每块重约四十公斤。由于这冰雹的灾，人就亵渎神，因为这灾太严重了。'),
('CNV', '启示录', 66, 17, 1, '拿着七碗的七位天使中，有一位来跟我讲话，说：“你来，我要把那坐在众水之上的大淫妇所要受的审判指示你。'),
('CNV', '启示录', 66, 17, 2, '地上的众王都跟她行过淫，住在地上的人也都喝她淫乱的酒醉了。”'),
('CNV', '启示录', 66, 17, 3, '我在灵里被天使带到旷野去，看见一个妇人，骑着朱红色的兽，这兽布满了亵渎的名号，有七头十角。'),
('CNV', '启示录', 66, 17, 4, '那妇人穿着紫色和朱红色的衣服，佩戴着金子、宝石和珍珠的装饰，手里拿着金杯，盛满了可憎的物，和她淫乱的污秽。'),
('CNV', '启示录', 66, 17, 5, '她额上写着一个名号：“奥秘，大巴比伦，地上的淫妇和可憎的物之母。”'),
('CNV', '启示录', 66, 17, 6, '我又看见那妇人喝圣徒的血，和那为耶稣作见证的人的血，喝醉了。我看见了她，就大大惊奇。'),
('CNV', '启示录', 66, 17, 7, '天使对我说：“你为什么惊奇呢？我要把这妇人的奥秘，和驮着她的那七头十角的兽的奥秘告诉你。'),
('CNV', '启示录', 66, 17, 8, '你看见的那兽，先前在、现今不在、将来要从无底坑上来，然后走向灭亡。住在世上的人，凡是名字在创世以来没有记在生命册上的，看见了那先前在、现今不在、将来还要出现的兽，就都要惊奇。'),
('CNV', '启示录', 66, 17, 9, '在这里需要有智慧的心。七头就是那妇人所坐的七座山，'),
('CNV', '启示录', 66, 17, 10, '也就是七位王：五位已经倒了，一位还在，另一位还没有来到；他来的时候，必须存留一会儿。'),
('CNV', '启示录', 66, 17, 11, '那先前在、现今不在的兽，就是第八位。他也是出于那七位中的一位的，并且正在走向灭亡。'),
('CNV', '启示录', 66, 17, 12, '你看见的那十角，就是十王，他们还没有取得王权；但要跟兽一同得着权柄，作王一个时期。'),
('CNV', '启示录', 66, 17, 13, '他们同心合意，把自己的权力权柄交给那兽。'),
('CNV', '启示录', 66, 17, 14, '他们要跟羊羔作战，羊羔必胜过他们，因为他是万主之主，万王之王。那些与羊羔同在、蒙召、被选、有忠心的，也必胜过他们。”'),
('CNV', '启示录', 66, 17, 15, '天使又对我说：“你所看见那淫妇坐着的众水，就是多种民族、群众、邦国，方言的人。'),
('CNV', '启示录', 66, 17, 16, '你看见的十角和那兽，都要恨那淫妇，使她荒凉赤身，又要吃她的肉，用火把她烧掉。'),
('CNV', '启示录', 66, 17, 17, '神要众王行他的旨意，就把意念放在他们心中，叫他们同心把自己的国献给那兽，直到神的话都实现为止。'),
('CNV', '启示录', 66, 17, 18, '你看见的那妇人，就是有权统治地上的众王的那座大城。”'),
('CNV', '启示录', 66, 18, 1, '这些事以后，我看见有另一位掌大权柄的天使，从天上降下来，他的荣光照亮了大地。'),
('CNV', '启示录', 66, 18, 2, '他用强有力的声音呼喊说：“倾倒了！大巴比伦倾倒了！成了鬼魔的住处，各样污灵的监狱，一切污秽可憎之雀鸟的牢笼，'),
('CNV', '启示录', 66, 18, 3, '因为各国都喝她淫乱烈怒的酒醉了；地上的君王与她行淫，世上的商人因她奢华挥霍就发了财。”'),
('CNV', '启示录', 66, 18, 4, '我听见另一个声音从天上来，说：“从那城出来吧，我的子民！免得在她的罪上有分，受她所受的灾难；'),
('CNV', '启示录', 66, 18, 5, '因为她的罪恶滔天，神已经想起她的不义来。'),
('CNV', '启示录', 66, 18, 6, '她怎样待人，你们也要怎样待她；照着她所作的，加倍报应她；用她调酒的杯，加倍调给她。'),
('CNV', '启示录', 66, 18, 7, '她怎样炫耀自己，怎样奢华挥霍，你们也要怎样给她痛苦悲哀。因为她心里常常说：‘我坐著作女王，我不是寡妇，决不会看见悲哀。’'),
('CNV', '启示录', 66, 18, 8, '因此，在一日之内她的灾难必然来到，就是死亡、悲哀和饥荒；她还要在火中被烧掉，因为审判她的主神是大有能力的。'),
('CNV', '启示录', 66, 18, 9, '“地上的众王，就是跟她一同行邪淫、骄奢无度的，看见焚烧她的烟的时候，就必为她痛哭捶胸。'),
('CNV', '启示录', 66, 18, 10, '他们因为害怕她所受的痛苦，就远远地站着，说：‘有祸了！有祸了！这大城，巴比伦，这坚固的城啊！一时之间你的审判就来到了！’'),
('CNV', '启示录', 66, 18, 11, '“地上的商人也为她悲哀痛哭，因为没有人再买他们的货物：'),
('CNV', '启示录', 66, 18, 12, '就是金、银、宝石、珍珠；细麻布、紫色布、丝绸、朱红色布；各样香木，各样象牙制品，各样极贵重的木器、铜器、铁器、大理石制品；'),
('CNV', '启示录', 66, 18, 13, '肉桂、荳蔻、香料、香膏、乳香；酒、油、面粉、麦子；牛、羊、马、车、奴仆、人口。'),
('CNV', '启示录', 66, 18, 14, '你所贪恋的果子离开你了！一切珍馐美味、华丽的美物，都从你那里消失，再也找不到了！'),
('CNV', '启示录', 66, 18, 15, '贩卖这些货物，藉着她发了财的商人，因为害怕她受的痛苦，就远远地站着，痛哭悲哀，'),
('CNV', '启示录', 66, 18, 16, '说：‘有祸了！有祸了！这大城啊！就是一向穿着细麻布、紫色、朱红色的衣服，佩戴着金子、宝石和珍珠装饰的，'),
('CNV', '启示录', 66, 18, 17, '一时之间，这么大的财富竟荡然无存！’“所有船长、旅客、水手，以及凡是靠海谋生的，都远远地站着。'),
('CNV', '启示录', 66, 18, 18, '他们看见了焚烧她的烟，就喊叫说：‘有哪一座城能与这大城相比呢？’'),
('CNV', '启示录', 66, 18, 19, '他们又把尘土撒在自己头上，痛哭悲哀，喊着说：‘有祸了！有祸了！这大城啊！凡是有船航行海上的，都因这城的财宝发了财；一时之间她竟成了荒场！’'),
('CNV', '启示录', 66, 18, 20, '天哪，你要因她欢喜！众圣徒、众使徒、众先知啊，你们也要因她欢喜！因为神已经在她身上为你们伸了冤。”'),
('CNV', '启示录', 66, 18, 21, '有一位大力的天使，把一块好像大磨石一样的石头，举起来抛在海里，说：“巴比伦大城也必这样被猛力地抛下去，决不能再找到了！'),
('CNV', '启示录', 66, 18, 22, '弹琴、奏乐、吹笛、吹号的声音，在你中间决不能再听到了！各样手艺技工，在你中间决不能再找到了！推磨的声音，在你中间决不能再听到了！'),
('CNV', '启示录', 66, 18, 23, '灯的亮光，在你中间决不能再照耀了！新郎新娘的声音，在你中间决不能再听到了！你的商人一向都是地上的大人物，万国都因你的邪术受了迷惑。'),
('CNV', '启示录', 66, 18, 24, '先知、圣徒和地上一切被杀的人的血，都在这城里找到了！”'),
('CNV', '启示录', 66, 19, 1, '这些事以后，我听见天上好像有一大群人大声说：“哈利路亚！救恩、荣耀、权能都属于我们的神，'),
('CNV', '启示录', 66, 19, 2, '因为他的审判是真实公义的。他审判了那大淫妇，那以淫乱败坏了世界的；并且为他的仆人向淫妇伸了流血的冤。”'),
('CNV', '启示录', 66, 19, 3, '他们再一次说：“哈利路亚！烧淫妇的烟往上冒，直到永永远远！”'),
('CNV', '启示录', 66, 19, 4, '那二十四位长老和四个活物，就俯伏敬拜那坐在宝座上的神，说：“阿们！哈利路亚！”'),
('CNV', '启示录', 66, 19, 5, '接着有声音从宝座发出来，说：“所有神的仆人哪！凡是敬畏他的，无论大小，你们都应当赞美我们的神！”'),
('CNV', '启示录', 66, 19, 6, '我又听见一个声音，好像一大群人的声音，像众水的声音，又像大雷的声音，说：“哈利路亚！因为主、我们全能的神作王了！'),
('CNV', '启示录', 66, 19, 7, '我们要欢喜快乐，把荣耀归给他！因为羊羔的婚期到了；他的新娘也自己预备好了。'),
('CNV', '启示录', 66, 19, 8, '并且有光洁的细麻衣，赐给她穿上；这细麻衣就是圣徒的义行。”'),
('CNV', '启示录', 66, 19, 9, '天使对我说：“你要写下来：‘被邀请赴羊羔婚筵的人有福了！’”他又对我说：“这都是神真实的话。”'),
('CNV', '启示录', 66, 19, 10, '我就俯伏在天使脚前要拜他。但他对我说：“千万不可以这样！我和你，以及你那些为耶稣作见证的弟兄，都是同作仆人的。你应当敬拜神！因为预言的精义，就是耶稣的见证。”'),
('CNV', '启示录', 66, 19, 11, '我观看，见天开了。有一匹白马，那骑马的称为“忠信”和“真实”；他按着公义审判和作战。'),
('CNV', '启示录', 66, 19, 12, '他的眼睛好像火焰，头上戴着许多皇冠，他身上写着一个名字，这名字除了他自己没有人认识。'),
('CNV', '启示录', 66, 19, 13, '他身穿一件浸过血的衣服，他的名字称为“神的道”。'),
('CNV', '启示录', 66, 19, 14, '天上的众军，都骑着白马，穿着洁白的细麻衣，跟随着他。'),
('CNV', '启示录', 66, 19, 15, '有一把利剑从他口中吐出来，他要用这剑击打列国，他必用铁杖治理他们；并且还要踹全能神烈怒的压酒池。'),
('CNV', '启示录', 66, 19, 16, '在他的衣服和大腿上，写着“万王之王，万主之主”的名号。'),
('CNV', '启示录', 66, 19, 17, '我又看见一位天使站在太阳中，向高空所有的飞鸟大声呼喊说：“你们来吧！齐集起来赴神的大筵席！'),
('CNV', '启示录', 66, 19, 18, '可以吃君王的肉、将领的肉、壮士的肉，马和骑士的肉，以及自由的、作奴隶的、大的、小的，所有人的肉。”'),
('CNV', '启示录', 66, 19, 19, '我看见那兽和地上的众王，以及他们的众军，都集合起来，要跟那骑白马的和他的众军作战。'),
('CNV', '启示录', 66, 19, 20, '那兽被捉住了；连同在兽面前用奇事迷惑人，使他们接受兽的记号，并且拜兽像的那假先知，也一起被捉住了。他们两个就活活地被抛在烧着硫磺的火湖里去。'),
('CNV', '启示录', 66, 19, 21, '其余的人都被那位骑白马的口中所吐出来的剑杀了。所有飞鸟都吃饱了他们的肉。'),
('CNV', '启示录', 66, 20, 1, '我又看见一位天使从天上降下来，手里拿着无底坑的钥匙和一条大锁链。'),
('CNV', '启示录', 66, 20, 2, '他捉住了那龙，那古蛇，就是魔鬼，撒但，把它捆绑了一千年。'),
('CNV', '启示录', 66, 20, 3, '天使把它抛在无底坑里，关起来，封上印，使它不能再迷惑列国，等到那一千年完了。以后，必须暂时释放它。'),
('CNV', '启示录', 66, 20, 4, '我又看见一些宝座，有人坐在上面，他们得了审判的权柄。我也看见那些因为替耶稣作见证，并且因为神的道而被斩首的人的灵魂。他们没有拜过兽或兽像，也没有在额上或手上受过兽的记号。他们都复活了，与基督一同作王一千年。'),
('CNV', '启示录', 66, 20, 5, '其余的死人还没有复活，等到那一千年完了。这是头一次的复活。'),
('CNV', '启示录', 66, 20, 6, '在头一次复活有分的人是有福的、圣洁的，第二次的死没有能力辖制他们。他们还要作神和基督的祭司，与他一同作王一千年。'),
('CNV', '启示录', 66, 20, 7, '那一千年完了，撒但就要从监牢里被释放出来。'),
('CNV', '启示录', 66, 20, 8, '他要出来迷惑地上四方的列国，就是歌革和玛各，使他们聚集争战。他们的人数好像海边的沙那么多。'),
('CNV', '启示录', 66, 20, 9, '他们上来遍满了全地，围住了圣徒的营和那蒙爱的城，就有火从天上降下来，毁灭了他们。'),
('CNV', '启示录', 66, 20, 10, '那迷惑他们的魔鬼，被抛在硫磺的火湖里，就是兽和假先知所在的地方。他们必昼夜受痛苦，直到永永远远。'),
('CNV', '启示录', 66, 20, 11, '我又看见一个白色的大宝座，和坐在上面的那位。天地都从他面前逃避，再也看不见了。'),
('CNV', '启示录', 66, 20, 12, '我又看见死了的人，无论大小，都站在宝座前。案卷都展开了，还有另一卷，就是生命册，也展开了。死了的人都凭着这些案卷所记载的，照着他们所行的受审判。'),
('CNV', '启示录', 66, 20, 13, '于是海把其中的死人交出来，死亡和阴间也把其中的死人交出来，他们都照着各人所行的受审判。'),
('CNV', '启示录', 66, 20, 14, '死亡和阴间也被抛在火湖里。这火湖就是第二次的死。'),
('CNV', '启示录', 66, 20, 15, '凡是名字没有记在生命册上的，他就被抛在火湖里。'),
('CNV', '启示录', 66, 21, 1, '我又看见一个新天新地，因为先前的天地都过去了，海也再没有了。'),
('CNV', '启示录', 66, 21, 2, '我又看见圣城，新耶路撒冷，从天上由神那里降下来，预备好了，好像打扮整齐等候丈夫的新娘。'),
('CNV', '启示录', 66, 21, 3, '我听见有大声音从宝座那里发出来，说：“看哪！神的帐幕在人间，他要与人同住，他们要作他的子民。神要亲自与他们同在，要作他们的神。'),
('CNV', '启示录', 66, 21, 4, '他要抹去他们的一切眼泪，不再有死亡，也不再有悲哀、哭号、痛苦，因为先前的事都过去了。”'),
('CNV', '启示录', 66, 21, 5, '坐在宝座上的那一位说：“看哪，我把一切都更新了！”又说：“你要写下来，因为这些话是可信的、真实的。”'),
('CNV', '启示录', 66, 21, 6, '他又对我说：“成了！我是阿拉法，是俄梅格；我是创始的，也是成终的。我要把生命的泉水，白白赐给口渴的人喝。'),
('CNV', '启示录', 66, 21, 7, '得胜的，必要承受这些福分。我要作他的神，他要作我的儿子。'),
('CNV', '启示录', 66, 21, 8, '只是那些胆怯的、不信的、可憎的、杀人的、淫乱的、行邪术的、拜偶像的和所有说谎的人，他们的分是在烧着硫磺的火湖里。这就是第二次的死。”'),
('CNV', '启示录', 66, 21, 9, '拿着七个盛满着末后七灾的碗的七位天使中，有一位走来对我说：“你来！我要把新娘，就是羊羔的妻子，指示你。”'),
('CNV', '启示录', 66, 21, 10, '我在灵里被那天使带到一座高大的山上，他把从天上由神那里降下来的圣城耶路撒冷指示我。'),
('CNV', '启示录', 66, 21, 11, '这城有神的荣耀，城的光辉好像极贵的宝石，又像晶莹的碧玉。'),
('CNV', '启示录', 66, 21, 12, '有高大的城墙，有十二个门，门口有十二位天使，门上写着以色列十二支派的名字。'),
('CNV', '启示录', 66, 21, 13, '东边有三个门，南边有三个门，西边有三个门，北边有三个门。'),
('CNV', '启示录', 66, 21, 14, '城墙有十二座根基，根基上有羊羔的十二使徒的名字。'),
('CNV', '启示录', 66, 21, 15, '那对我说话的天使拿着一根金的芦苇，要量那城、城门和城墙。'),
('CNV', '启示录', 66, 21, 16, '城是四方的，长宽都一样。天使用芦苇量那城，共有二千四百公里（“二千四百公里”原文作“一万二千司他町”），城的长、宽、高都一样；'),
('CNV', '启示录', 66, 21, 17, '又量了城墙，约有六十公尺（“六十公尺”原文作“一百四十四肘”）。天使用的标准，就是人量度的标准。'),
('CNV', '启示录', 66, 21, 18, '城墙是用碧玉做的，城是用明净像玻璃的纯金做的。'),
('CNV', '启示录', 66, 21, 19, '城墙的根基是用各样宝石装饰的：第一座根基是碧玉，第二座是蓝宝石，第三座是玛瑙，第四座是绿宝石，'),
('CNV', '启示录', 66, 21, 20, '第五座是红玛瑙，第六座是红宝石，第七座是黄璧玺，第八座是水苍玉，第九座是红璧玺，第十座是翡翠，第十一座是紫玛瑙，第十二座是紫晶。'),
('CNV', '启示录', 66, 21, 21, '十二个门是十二颗珍珠，每一个门是用一颗珍珠做的。城里的街道是纯金的，好像透明的玻璃。'),
('CNV', '启示录', 66, 21, 22, '我没有看见城里有圣所，因为主全能的神和羊羔就是城的圣所。'),
('CNV', '启示录', 66, 21, 23, '这城不需要日月照明，因为有神的荣耀照明，而羊羔就是城的灯。'),
('CNV', '启示录', 66, 21, 24, '列国要藉着城的光行走，地上的众王要把他们的荣华带到这城来。'),
('CNV', '启示录', 66, 21, 25, '城门白天决不关闭。在那里并没有黑夜。'),
('CNV', '启示录', 66, 21, 26, '列国的荣华尊贵都被带到这城。'),
('CNV', '启示录', 66, 21, 27, '所有不洁净的、行可憎的和说谎的，决不可以进入这城。只有名字记在羊羔生命册上的才可以进去。'),
('CNV', '启示录', 66, 22, 1, '天使又指示我一道明亮如水晶的生命水的河流，从神和羊羔的宝座那里流出来，'),
('CNV', '启示录', 66, 22, 2, '经过城里的街道。河的两边有生命树，结十二次果子，每月都结果子；树叶可以医治列国。'),
('CNV', '启示录', 66, 22, 3, '所有咒诅都不再有了。城里有神和羊羔的宝座，他的仆人都要事奉他，'),
('CNV', '启示录', 66, 22, 4, '也要见他的面。他的名字必写在他们的额上。'),
('CNV', '启示录', 66, 22, 5, '不再有黑夜了，他们也不需要灯光或日光了，因为主神要光照他们。他们要作王，直到永永远远。'),
('CNV', '启示录', 66, 22, 6, '天使对我说：“这些话是可信的、真实的！主，就是众先知之灵的神，差遣了他的天使，把那快要发生的事，指示他的仆人。”'),
('CNV', '启示录', 66, 22, 7, '“看哪！我必快来！那遵守这书上预言的人是有福的！”'),
('CNV', '启示录', 66, 22, 8, '听见又看见了这些事的，就是我约翰。我听见又看见了之后，就俯伏在指示我这些事的天使脚前要拜他。'),
('CNV', '启示录', 66, 22, 9, '他对我说：“千万不可以这样！我和你，以及你的弟兄众先知，还有那些遵守这书上的话的人，都是同作仆人的。你应当敬拜神。”'),
('CNV', '启示录', 66, 22, 10, '他又对我说：“不要封住这书上的预言，因为时候近了。'),
('CNV', '启示录', 66, 22, 11, '不义的，要他仍旧不义；污秽的，要他仍旧污秽；行义的，要他仍旧行义；圣洁的，要他仍旧圣洁。”'),
('CNV', '启示录', 66, 22, 12, '“看哪，我必快来！赏赐在我，我要照着各人所行的报应他。'),
('CNV', '启示录', 66, 22, 13, '我是阿拉法，是俄梅格；我是首先的，也是末后的；我是创始的，也是成终的。”'),
('CNV', '启示录', 66, 22, 14, '那些洗净自己袍子的人是有福的！他们可以有权到生命树那里，也可以从门进到城里。'),
('CNV', '启示录', 66, 22, 15, '在城外，有那些狗，那些行邪术的、淫乱的、杀人的、拜偶像的，以及所有喜爱说谎的和实行说谎的人。'),
('CNV', '启示录', 66, 22, 16, '“差遣了我的使者、为众教会向你们证明这些事的，就是我耶稣。我是大卫的根，又是他的后裔，我是明亮的晨星。”'),
('CNV', '启示录', 66, 22, 17, '圣灵和新娘都说：“来！”听见的人也要说：“来！”口渴的人也要来！愿意的人都要白白接受生命的水！'),
('CNV', '启示录', 66, 22, 18, '我警告所有听见这书上预言的人：如果有人在这些预言上加添什么，神必把写在这书上的灾难加在他身上。'),
('CNV', '启示录', 66, 22, 19, '如果有人从这书上的预言删减什么，神必从这书上所记的生命树和圣城删去他的分。'),
('CNV', '启示录', 66, 22, 20, '证明这些事的那一位说：“是的，我必快来！”阿们！主耶稣啊，请你来吧！'),
('CNV', '启示录', 66, 22, 21, '愿主耶稣的恩惠与所有的圣徒同在！阿们！')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
